class Team(Enum):
    RED = "Red Team"
    BLUE = "Blue Team"
    NEUTRAL = "Neutral"

class CharacterAbility(Enum):
    STRENGTH = "Strength"
    AGILITY = "Agility"
    INTELLIGENCE = "Intelligence"
    STEALTH = "Stealth"

class Environment(Enum):
    FOREST = "Forest"
    CAVE = "Cave"
    ANCIENT_RUINS = "Ancient Ruins"

class GamePhase(Enum):
    START = "Start"
    PLAYING = "Playing"
    FINISH = "Finish"

class Player:
    def __init__(self, name: str, team: Team, ability: CharacterAbility):
        self.name = name
        self.team = team
        self.ability = ability
        self.treasures_collected = 0
        self.state = "Active"

    def use_ability(self) -> str:
        return f"{self.name} used {self.ability.value}"

    def collect_treasure(self):
        self.treasures_collected += 1
        return f"{self.name} collected a treasure!"

class TeamTreasureHuntGame:
    def __init__(self):
        self.teams: Dict[Team, List[Player]] = {
            Team.RED: [],
            Team.BLUE: [],
            Team.NEUTRAL: []
        }
        self.environments: List[Environment] = [Environment.FOREST, Environment.CAVE, Environment.ANCIENT_RUINS]
        self.game_phase = GamePhase.START
        self.final_chamber_reached_by: Optional[Team] = None
        self.treasure_positions = self._initialize_treasure_positions()

    def _initialize_treasure_positions(self) -> Dict[Environment, List[Tuple[int, int]]]:
        return {
            Environment.FOREST: [(1, 2), (3, 5)],
            Environment.CAVE: [(2, 2), (5, 3)],
            Environment.ANCIENT_RUINS: [(4, 5)]
        }

    def add_player_to_team(self, player: Player, team: Team):
        if len(self.teams[team]) >= 4:
            print(f"{team.value} is full!")
        else:
            self.teams[team].append(player)

    def start_game(self):
        self.game_phase = GamePhase.PLAYING
        print("Game has started!")

    def end_game(self):
        self.game_phase = GamePhase.FINISH
        self._determine_winner()

    def _determine_winner(self):
        red_treasure = sum(p.treasures_collected for p in self.teams[Team.RED])
        blue_treasure = sum(p.treasures_collected for p in self.teams[Team.BLUE])
        if red_treasure > blue_treasure:
            print("Red Team wins!")
        elif blue_treasure > red_treasure:
            print("Blue Team wins!")
        else:
            print("It's a tie!")

    def collect_treasure(self, player: Player, environment: Environment, position: Tuple[int, int]) -> bool:
        if position in self.treasure_positions[environment]:
            self.treasure_positions[environment].remove(position)
            player.collect_treasure()
            return True
        return False

    def use_ability_in_puzzle(self, player: Player, puzzle_type: str) -> bool:
        if puzzle_type == "Heavy Object":
            return player.ability == CharacterAbility.STRENGTH
        elif puzzle_type == "Tight Space":
            return player.ability == CharacterAbility.AGILITY
        elif puzzle_type == "Complex Puzzle":
            return player.ability == CharacterAbility.INTELLIGENCE
        elif puzzle_type == "Avoid Traps":
            return player.ability == CharacterAbility.STEALTH
