# Define global constants
MAX_HEALTH = 100
MAX_ENERGY = 50
MAX_PLAYERS = 20
TEAMS = {"Team_1": 0, "Team_2": 1}
WEAPON_TYPES = ["Ranged", "Melee", "Special"]
POWER_UP_TYPES = ["Speed", "Shield", "Heal", "EMP"]
HAZARD_TYPES = ["Lava", "Spikes", "Ice", "ToxicGas"]
OBJECTIVE_TYPES = ["CaptureFlag", "DefendBase", "Escort"]

# Define basic classes for CyberArena

class Position:
    """Represents a position in the arena with x and y coordinates."""

    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    def distance_to(self, other_pos: "Position") -> float:
        """Calculate the Euclidean distance to another position."""
        return ((self.x - other_pos.x)**2 + (self.y - other_pos.y)**2)**0.5

    def __str__(self):
        return f"Position(x={self.x}, y={self.y})"


class Weapon:
    """Base class for all types of weapons in the arena."""

    def __init__(self, name: str, damage: float, energy_cost: float, weapon_type: str):
        self.name = name
        self.damage = damage
        self.energy_cost = energy_cost
        self.weapon_type = weapon_type

    def is_usable(self, energy: float) -> bool:
        """Check if this weapon can be used with the given energy level."""
        return energy >= self.energy_cost

    def use(self, energy: float) -> float:
        """Use this weapon and return the remaining energy."""
        return energy - self.energy_cost

    def __str__(self):
        return f"Weapon(name='{self.name}', damage={self.damage}, energy_cost={self.energy_cost}, type='{self.weapon_type}')"


class PowerUp:
    """Base class for all types of power-ups in the arena."""

    def __init__(self, name: str, effect: str, duration: float):
        self.name = name
        self.effect = effect
        self.duration = duration
        self.expires_at = time.time() + duration

    def is_active(self) -> bool:
        """Check if this power-up is still active."""
        return time.time() < self.expires_at

    def apply_effect(self, robot: "Robot") -> None:
        """Apply the power-up's effect to the robot."""
        if self.effect == "Speed":
            robot.speed_boost = 1.5
        elif self.effect == "Shield":
            robot.shield = 50
        elif self.effect == "Heal":
            robot.health = min(MAX_HEALTH, robot.health + 25)
        elif self.effect == "EMP":
            robot.disable_weapons = True

    def end_effect(self, robot: "Robot") -> None:
        """End the power-up's effect on the robot."""
        if self.effect == "Speed":
            robot.speed_boost = 1.0
        elif self.effect == "Shield":
            robot.shield = 0
        elif self.effect == "EMP":
            robot.disable_weapons = False

    def __str__(self):
        return f"PowerUp(name='{self.name}', effect='{self.effect}', duration={self.duration})"


class Hazard:
    """Base class for all types of environmental hazards in the arena."""

    def __init__(self, name: str, damage: float, radius: float, duration: float):
        self.name = name
        self.damage = damage
        self.radius = radius
        self.expires_at = time.time() + duration
        self.position = Position(random.uniform(0, 100), random.uniform(0, 100))

    def is_active(self) -> bool:
        """Check if this hazard is still active."""
        return time.time() < self.expires_at

    def is_in_range(self, position: Position) -> bool:
        """Check if the given position is within the hazard's radius."""
        return position.distance_to(self.position) <= self.radius

    def apply_effect(self, robot: "Robot") -> None:
        """Apply the hazard's damage to the robot."""
        if robot.health > 0:
            robot.health = max(0, robot.health - self.damage)

    def __str__(self):
        return f"Hazard(name='{self.name}', damage={self.damage}, radius={self.radius}, position={self.position})"


class Objective:
