    def move_towards(self, target_pos: Position, speed_factor: float = 1.0) -> None:
        """Move the robot towards a target position."""
        if self.health <= 0:
            return

        direction_x = target_pos.x - self.position.x
        direction_y = target_pos.y - self.position.y
        distance = self.position.distance_to(target_pos)

        if distance > 0:
            move_x = (direction_x / distance) * (self.speed * self.speed_boost) * speed_factor
            move_y = (direction_y / distance) * (self.speed * self.speed_boost) * speed_factor

            self.position.x += move_x
            self.position.y += move_y

    def attack(self, target: "Robot", weapon_index: int) -> None:
