                        actual_damage = max(0, weapon.damage - (target.shield if target.shield > 0 else 0))
                        target.health = max(0, target.health - actual_damage)

                        # Apply shield damage if shield is present
                        if target.shield > 0:
                            target.shield = max(0, target.shield - (actual_damage * 0.2))
                elif weapon.weapon_type == "Melee":
                    # Simulate a melee attack with 100% accuracy
                    # Apply damage to the target, considering shields
                    actual_damage = max(0, weapon.damage - (target.shield if target.shield > 0 else 0))
                    target.health = max(0, target.health - actual_damage)

                    # Apply shield damage if shield is present
                    if target.shield > 0:
                        target.shield = max(0, target.shield - (actual_damage * 0.2))
                elif weapon.weapon_type == "Special":
                    # Special weapons have unique effects
                    if weapon.name == "EMP Blast":
                        # EMP blast disables all weapons for 3 seconds
                        target.disable_weapons = True
                        target.power_ups.append(PowerUp("EMP", "Disable", 3))

    def collect_power_up(self, power_up: PowerUp) -> None:
        """Collect and apply a power-up."""
        if self.health <= 0:
            return

        power_up.apply_effect(self)
        self.power_ups.append(power_up)

    def update_power_ups(self) -> None:
        """Update the status of all active power-ups."""
        for power_up in self.power_ups:
            if not power_up.is_active():
                power_up.end_effect(self)
                self.power_ups.remove(power_up)

    def take_damage(self, amount: float) -> None:
        """Take damage from an enemy or hazard."""
        if self.health <= 0:
            return

        # Apply damage to shields first, then to health
        if self.shield > 0:
            self.shield = max(0, self.shield - amount)
        else:
            self.health = max(0, self.health - amount)

    def is_dead(self) -> bool:
        """Check if this robot is dead."""
        return self.health <= 0

    def learn_from_battle(self, battle_results: Dict) -> None:
