    def update_objective(self, objectives: List[Objective]) -> None:
        """Update the robot's objective based on the current game state."""
        if self.objective is None or self.objective.is_complete():
            # Find a new objective to pursue
            for obj in objectives:
                if not obj.is_complete() and obj.team == self.team:
