        # Update score based on robot performance
        for robot in self.robots:
            if robot.is_dead():
                self.score -= 20
            else:
                # Add score based on health and energy remaining
                self.score += (robot.health / MAX_HEALTH) * 10
                self.score += (robot.energy / MAX_ENERGY) * 5

        # Update score based on arena's difficulty
        self.score *= (1 + arena.difficulty_level / 100)

    def __str__(self):
