                continue

            # Update power-ups
            robot.update_power_ups()

            # Update objectives
            robot.update_objective(self.objectives)

            # If the robot has an objective
            if robot.objective is not None:
                # Move towards the objective
                robot.move_towards(robot.objective.position, speed_factor=1.2)

                # If close enough to the objective, complete it
                if robot.position.distance_to(robot.objective.position) < 2:
                    robot.objective.complete()

            # Check for power-ups
            for power_up in self.power_ups:
