        """Adjust the difficulty of the match based on team performance."""
        total_health = sum(robot.health for robot in self.robots)
        team_scores = [team.score for team in self.teams]
        avg_score = sum(team_scores) / len(team_scores) if team_scores else 0

        # Increase difficulty if teams are performing well
        if total_health > (MAX_HEALTH * len(self.robots) * 0.7) and avg_score > 100:
            self.difficulty_level += 10
            self.difficulty_level = min(100, self.difficulty_level)

            # Create more hazards to increase difficulty
            if random.random() < 0.5:
                self.create_hazards(num_hazards=2)

        # Decrease difficulty if teams are struggling
        elif total_health < (MAX_HEALTH * len(self.robots) * 0.3) or avg_score < 50:
            self.difficulty_level -= 10
            self.difficulty_level = max(0, self.difficulty_level)

            # Remove some hazards to decrease difficulty
            if random.random() < 0.5 and len(self.hazards) > 2:
                hazards_to_remove = min(len(self.hazards) // 2, len(self.hazards) - 2)
                for _ in range(hazards_to_remove):
