        # Reset difficulty if it's balanced
        else:
            self.difficulty_level = 50

    def check_victory_condition(self) -> Optional[Team]:
        """Check if the match has been won by a team."""
        # Check if any team has won by completing all objectives
        for team in self.teams:
            team_objectives_completed = sum(1 for obj in self.objectives if obj.team == team.team_id and obj.is_complete())
            if team_objectives_completed >= len([obj for obj in self.objectives if obj.team == team.team_id]):
                return team

        # Check if any team has eliminated all robots on an opposing team
        for team in self.teams:
            if all(robot.is_dead() for robot in self.teams[1 - team.team_id].robots):
                return team

        return None

    def end_match(self, winner: Team) -> None:
