        if amount < 0:
            raise ValueError("Expense amount must be non-negative.")
        self.expenses[category] += amount

    def get_total_expenses(self):
        return sum(self.expenses.values())

    def get_expenses_by_category(self):
        return self.expenses

# Class for managing shared budget
class BudgetManager:
    def __init__(self):
        self.users = {}
        self.budget_limits = defaultdict(float)  # {category: limit}

    def add_user(self, user):
        self.users[user.user_id] = user

    def set_budget_limit(self, category, limit):
        if limit < 0:
            raise ValueError("Budget limit must be non-negative.")
        self.budget_limits[category] = limit

    def get_budget_status(self):
        total_expenses_by_category = defaultdict(float)
        for user in self.users.values():
            for category, amount in user.expenses.items():
                total_expenses_by_category[category] += amount

        budget_status = {}
        for category in self.budget_limits:
            spent = total_expenses_by_category.get(category, 0)
            remaining = self.budget_limits[category] - spent
            budget_status[category] = {
                'category': category,
                'budget_limit': self.budget_limits[category],
                'total_spent': spent,
                'remaining': remaining
            }
        return budget_status

    def optimize_budget(self):
        status = self.get_budget_status()
        recommendations = []
        for category, data in status.items():
            if data['remaining'] < 0:
                recommendations.append(
                    f'Overbudget in {category}: Consider reducing expenses by ${abs(data["remaining"])}.'
                )
            elif data['remaining'] > 0:
                recommendations.append(
                    f'Underbudget in {category}: Consider reallocating ${data["remaining"]} to other categories or saving it.'
                )
