        self.score = 0
        self.strategy = None  # AI strategy

    def assign_weapon(self, weapon):
        self.weapon = weapon

    def assign_role(self, role):
        self.role = role

    def assign_strategy(self, strategy):
        self.strategy = strategy

    def take_damage(self, amount):
        self.health -= amount
        if self.health <= 0:
            self.is_alive = False

    def heal(self, amount):
        self.health = min(self.max_health, self.health + amount)

    def update(self, delta_time):
        if not self.is_alive:
            return
        self.strategy.execute(self, delta_time)

    def attack(self, target):
        if self.weapon:
            self.weapon.fire(self, target)

class Weapon:
    """Class for representing weapons with different attack types."""
    def __init__(self, weapon_type: WeaponType, damage: float, range: float, fire_rate: float):
        self.type = weapon_type
        self.damage = damage
        self.range = range
        self.fire_rate = fire_rate  # attacks per second
        self.last_fired = 0  # timestamp of last attack

    def fire(self, attacker: Robot, target: Entity, current_time=None):
        if current_time is None:
            current_time = time.time()
        if current_time - self.last_fired < 1 / self.fire_rate:
            return  # not enough time since last attack
        if attacker.position.distance_to(target.position) > self.range:
            return  # out of range

        # Calculate damage based on type
        if self.type == WeaponType.MELEE:
            # Melee attack has full damage
            target.take_damage(self.damage)
        elif self.type == WeaponType.LASER or self.type == WeaponType.PLASMA:
            # Ranged attack with some spread/accuracy
            accuracy_factor = random.uniform(0.8, 1.0)
            target.take_damage(self.damage * accuracy_factor)
        elif self.type == WeaponType.MISSILE:
            # Homing missile
            target.take_damage(self.damage)

        self.last_fired = current_time

class Strategy:
    """Abstract base class for robot strategies (AI behavior)."""
