class AttackStrategy(Strategy):
    """Strategy for attacking the nearest enemy."""
    def execute(self, robot: Robot, delta_time):
        # Find nearest enemy
        nearest_enemy = None
        min_distance = float('inf')
        for other in robot.arena.entities:
            if isinstance(other, Robot) and other.team != robot.team and other.is_alive:
                distance = robot.position.distance_to(other.position)
                if distance < min_distance:
                    nearest_enemy = other
                    min_distance = distance

        if nearest_enemy:
            # Move towards enemy
            direction = (nearest_enemy.position - robot.position).normalize()
            robot.position = robot.position + direction * robot.speed * delta_time

            # Attack enemy
            robot.attack(nearest_enemy)
        else:
