class Weapon:
    """Base class for different types of weapons that robots can use."""
    def __init__(self, name, weapon_type, damage, range, cooldown):
        self.name = name
        self.weapon_type = weapon_type
        self.base_damage = damage
        self.range = range
        self.cooldown = cooldown
        self.last_used = 0

    def is_ready(self):
        """Check if the weapon is ready to use based on its cooldown."""
        return time.time() - self.last_used >= self.cooldown

    def calculate_damage(self, attacker_robot, target_robot):
        """Calculate the damage based on various factors."""
        base_damage = self.base_damage
        # Apply damage boost if available
        if attacker_robot.has_power_up(PowerUpType.DAMAGE_BOOST):
            base_damage *= 1.5

        # Apply armor reduction
        armor_reduction = target_robot.armor / (target_robot.armor + 100)
        return base_damage * (1 - armor_reduction)

    def use(self, attacker_robot, target_robot):
        """Use the weapon to attack a target robot."""
        if not self.is_ready():
            return False

        if self._can_attack(attacker_robot, target_robot):
            self.last_used = time.time()
            damage = self.calculate_damage(attacker_robot, target_robot)
            target_robot.take_damage(damage)
            attacker_robot.combat_log(f"{attacker_robot.name} used {self.name} and dealt {damage:.1f} damage to {target_robot.name}")
            return True
        return False

    def _can_attack(self, attacker_robot, target_robot):
        """Determine if the weapon can attack the target robot based on range and type."""
        distance = abs(attacker_robot.position - target_robot.position)
        return distance <= self.range and self._is_valid_target(attacker_robot, target_robot)

    def _is_valid_target(self, attacker_robot, target_robot):
        """Determine if the target is valid for this weapon type."""
        return attacker_robot.team != target_robot.team

class RangedWeapon(Weapon):
    """A specific type of weapon for ranged attacks."""
    def __init__(self, name, damage, range, cooldown, accuracy=0.8):
