    """Main simulation class for the CyberArena"""
    def __init__(self, width: float = 100, height: float = 100):
        self.width = width
        self.height = height
        self.robots: List[Robot] = []
        self.teams: List[Team] = []
        self.objective: Optional[Objective] = None
        self.difficulty_level = 1.0
        self.hazards: List['Hazard'] = []
        self.power_ups: List[PowerUp] = []
        self.running = True
        self.last_update = time.time()

    def add_team(self, team: Team):
        """Add a team to the arena"""
        self.teams.append(team)
        for robot in team.robots:
            self.robots.append(robot)

    def set_objective(self, objective: Objective):
        """Set the current objective for the match"""
        self.objective = objective
        for team in self.teams:
            team.objective = objective

    def add_hazard(self, hazard: 'Hazard'):
        """Add a hazard to the arena"""
        self.hazards.append(hazard)

    def add_power_up(self, power_up: PowerUp):
        """Add a power-up to the arena"""
        self.power_ups.append(power_up)

    def update(self):
        """Update the entire arena state"""
        current_time = time.time()
        delta_time = current_time - self.last_update
        self.last_update = current_time

        # Update all robots
        for robot in self.robots:
            if robot.health > 0:
                robot.update(delta_time)
                self._handle_robot_ai(robot, delta_time)
                self._check_power_ups(robot)

        # Update objective
        if self.objective:
            self.objective.update(self.teams, delta_time)

        # Update hazards
        for hazard in self.hazards:
            hazard.update(delta_time)

        # Update power-ups
        for power_up in self.power_ups:
            power_up.update(delta_time)

    def _handle_robot_ai(self, robot: Robot, delta_time: float):
        """Handle basic AI decision making for a robot"""
        # Check if robot is dead
        if robot.health <= 0:
            return

        # Check objective status
        if self.objective and not self.objective.completed:
            # Basic AI: move toward objective location
            direction = (self.objective.location - robot.position).normalize()
            robot.move(direction, delta_time)

            # Simple attack logic
            enemies = [r for r in self.robots if r.team != robot.team and r.health > 0]
            if enemies:
                nearest_enemy = min(enemies, key=lambda e: (e.position - robot.position).length())
                if (nearest_enemy.position - robot.position).length() < 10.0:
                    robot.attack(nearest_enemy, delta_time)

    def _check_power_ups(self, robot: Robot):
        """Check if robot is near a power-up and can pick it up"""
        for power_up in self.power_ups:
            if (power_up.position - robot.position).length() < 2.0 and power_up not in robot.power_ups:
                robot.apply_power_up(power_up)
                self.power_ups.remove(power_up)

    def start_match(self):
        """Start the match simulation"""
        self.running = True
        print(f"Match started in the CyberArena!")
        print(f"Teams: {[team.name for team in self.teams]}")
        print(f"Objective: {self.objective.name if self.objective else 'No objective'}")
        self._match_loop()

    def _match_loop(self):
        """Main simulation loop"""
        while self.running and not (self.objective and self.objective.completed):
            self.update()
            time.sleep(0.01)  # Simulate real-time with 100ms intervals

            # Simple win condition check
            if self.objective and self.objective.completed:
                self._end_match()

    def _end_match(self):
        """Handle match end logic"""
        self.running = False
