# CulturalConnect - Web Application for Cultural Exploration and Sharing

import random
import time
from enum import Enum
from dataclasses import dataclass
from typing import List, Dict, Optional

# -----------------------------
# FRONTEND CONFIGURATION (REACT.JS)
# -----------------------------

class Component(Enum):
    AUTH = 1
    DASHBOARD = 2
    CULTURAL_CONTENT = 3
    CHAT = 4

@dataclass
class User:
    user_id: str
    name: str
    email: str
    team: Optional[Team] = None
    role: Optional[Role] = None
    preferences: Dict[str, float] = None

    def __post_init__(self):
        if self.preferences is None:
            self.preferences = {
                'literature': 0.5,
                'music': 0.5,
                'visual_arts': 0.5,
                'films': 0.5
            }

@dataclass
class CulturalItem:
    item_id: str
    title: str
    type: str  # e.g., 'literature', 'music', 'visual_arts', 'films'
    description: str
    metadata: Dict[str, str] = None

    def __post_init__(self):
        if self.metadata is None:
            self.metadata = {
                'origin': 'Unknown',
                'year': 'Unknown',
                'culture': 'Unknown'
            }

@dataclass
class Recommendation:
    item_id: str
    score: float
    reason: str

# -----------------------------
# BACKEND CONFIGURATION (NODE.JS + EXPRESS)
# -----------------------------

@dataclass
class UserRequest:
    user_id: str
    action: str  # e.g., 'login', 'logout', 'fetch_recommendations', 'chat'
    data: Optional[Dict] = None

@dataclass
class ChatMessage:
    sender_id: str
    receiver_id: str
    message: str
    timestamp: float

@dataclass
class WebSocketEvent:
    event_type: str
    data: Dict

# -----------------------------
# DATABASE CONFIGURATION (MONGODB)
# -----------------------------

class Collection(Enum):
    USERS = 1
    CULTURAL_ITEMS = 2
    MESSAGES = 3

@dataclass
class DBQuery:
    collection: Collection
    filter: Dict
    action: str  # e.g., 'insert', 'find', 'update', 'delete'

# -----------------------------
# RECOMMENDATION SYSTEM
# -----------------------------

class RecommendationEngine:
    def generate_recommendations(self, user: User, cultural_items: List[CulturalItem]) -> List[Recommendation]:
        recommendations = []
        for item in cultural_items:
            score = self._calculate_score(user, item)
            reason = self._generate_reason(user, item)
            recommendations.append(Recommendation(item.item_id, score, reason))
        return recommendations

    def _calculate_score(self, user: User, item: CulturalItem) -> float:
        return random.uniform(0.5, 1.0)

    def _generate_reason(self, user: User, item: CulturalItem) -> str:
        return "This item fits your interests in {} and {}.".format(
            item.type, item.metadata.get('culture', 'global content')
        )

# -----------------------------
# APPLICATION LOGIC
# -----------------------------

class CulturalConnectApp:
    def __init__(self):
        self.users = []
        self.cultural_items = []
        self.recommendation_engine = RecommendationEngine()

    def add_user(self, user: User) -> None:
        self.users.append(user)

    def add_cultural_item(self, item: CulturalItem) -> None:
        self.cultural_items.append(item)

    def get_recommendations(self, user: User) -> List[Recommendation]:
        return self.recommendation_engine.generate_recommendations(user, self.cultural_items)

    def send_message(self, message: ChatMessage) -> None:
        print(f"[Chat] {message.sender_id} -> {message.receiver_id}: {message.message}")

# Example usage
if __name__ == "__main__":
    app = CulturalConnectApp()

    # Add users
    user1 = User("u1", "Alice", "alice@example.com")
    user2 = User("u2", "Bob", "bob@example.com")

    app.add_user(user1)
    app.add_user(user2)

    # Add cultural items
    item1 = CulturalItem("c1", "Poem about the Nile", "literature", "A historical literary piece from ancient Egypt.", {
        "origin": "Egypt",
        "year": "3000 BCE",
        "culture": "Ancient Egyptian"
    })

    item2 = CulturalItem("c2", "Symphony No. 5", "music", "A powerful classical composition.", {
        "origin": "Germany",
        "year": "1808",
        "culture": "Western Classical"
    })

    app.add_cultural_item(item1)
    app.add_cultural_item(item2)

    # Get recommendations for user1
    recommendations = app.get_recommendations(user1)
    print("Recommendations for Alice:")
    for rec in recommendations:
        print(f"- {rec.reason} (Score: {rec.score:.2f})")

    # Simulate chat
    app.send_message(ChatMessage("u1", "u2", "Hey Bob, what do you think of the Egyptian poem?", time.time()))
    app.send_message(ChatMessage("u2", "u1", "It's fascinating! The language is so rich and poetic.", time.time()))"
}
