# Team class
class Team:
    def __init__(self, name: str, color: TeamColor):
        self.name = name
        self.color = color
        self.robots: List[Robot] = []
        self.score = 0  # Team score
        self.objectives_completed = 0  # Number of objectives completed

    def add_robot(self, robot: Robot):
        """Add a robot to the team."""
        robot.team = self.color
        self.robots.append(robot)

    def update_score(self, points: int):
        """Update the team score with given points."""
        self.score += points

    def complete_objective(self):
        """Mark an objective as completed for the team."""
        self.objectives_completed += 1
        self.update_score(100)  # Reward for completing an objective

# Power-up class
class PowerUp:
    def __init__(self, power_type: PowerUpType, position: Tuple[float, float]):
        self.type = power_type
        self.position = position
        self.active = True

    def apply_effect(self, robot: Robot):
        """Apply the power-up effect to the specified robot."""
        robot.use_power_up(self.type)
        self.active = False  # Power-up is consumed

# Environmental Hazard class
class Hazard:
    def __init__(self, hazard_type: HazardType, position: Tuple[float, float]):
        self.type = hazard_type
        self.position = position
        self.active = True

    def affect_robot(self, robot: Robot):
        """Apply the hazard effect to the specified robot."""
        if not self.active:
            return

        if self.type == HazardType.LANDMINE or self.type == HazardType.EXPLOSIVE:
            # Explosive damage
            damage = random.randint(10, 30)
            robot.take_damage(damage)
            self.active = False  # Hazard is destroyed
        elif self.type == HazardType.TRIPWIRE:
            # Slow robot
            robot.move_speed = max(1.0, robot.move_speed * 0.5)
            self.active = False  # Hazard is triggered
        elif self.type == HazardType.LAVA_POOL:
            # Continuous damage over time
            damage = random.randint(2, 5)
            robot.take_damage(damage)
            # Hazard remains active

