# Abstract class for weapons
class Weapon(ABC):
    def __init__(self, name, damage, range, attack_speed):
        self.name = name
        self.damage = damage
        self.range = range  # Range for ranged weapons, None for melee
        self.attack_speed = attack_speed  # Attacks per second

    @abstractmethod
    def attack(self, target):
        """Perform an attack on the target."""
        pass

