# Abstract class for power-ups
class PowerUp(ABC):
    def __init__(self, name, duration):
        self.name = name
        self.duration = duration  # Duration in seconds

    @abstractmethod
    def apply(self, robot):
        """Apply the power-up to the robot."""
        pass

    @abstractmethod
    def remove(self, robot):
        """Remove the power-up from the robot."""
        pass

# Concrete power-up classes
class SpeedBoost(PowerUp):
    def __init__(self):
        super().__init__(name="SpeedBoost", duration=10)
        self.speed_multiplier = 1.5  # 50% speed boost

    def apply(self, robot):
        """Apply the speed boost to the robot."""
        robot.speed *= self.speed_multiplier
        print(f"Applied {self.name} to {robot.name}: Speed increased by {self.speed_multiplier}x for {self.duration} seconds.")

    def remove(self, robot):
        """Remove the speed boost from the robot."""
        robot.speed /= self.speed_multiplier
        print(f"Removed {self.name} from {robot.name}.")

class Shield(PowerUp):
    def __init__(self):
