class Dataset:
    def __init__(self, data: pd.DataFrame, source_path: str = None):
        self.id = str(uuid.uuid4())
        self.data = data
        self.source_path = source_path
        self.history = []
        self.lock = Lock()

    def get_summary(self) -> Dict:
        summary = {
            'shape': self.data.shape,
            'dtypes': self.data.dtypes.to_dict(),
            'missing_values': self.data.isnull().sum().to_dict(),
            'missing_percentage': (self.data.isnull().sum() / len(self.data) * 100).to_dict(),
            'unique_counts': self.data.nunique().to_dict(),
            'descriptive_stats': self.data.describe(include='all').to_dict()
        }
        return summary

    def visualize_missing_values(self) -> None:
        plt.figure(figsize=(10, 6))
        sns.heatmap(self.data.isnull(), cbar=False, cmap='viridis')
        plt.title('Missing Values Heatmap')
        plt.show()

    def visualize_correlation(self, method='pearson') -> None:
        if method not in ['pearson', 'spearman']:
            raise ValueError('Method must be either pearson or spearman')

        numeric_data = self.data.select_dtypes(include=[np.number])
        if numeric_data.empty:
            raise ValueError('No numeric columns for correlation analysis')

        plt.figure(figsize=(12, 10))
        sns.heatmap(numeric_data.corr(method=method), annot=True, cmap='coolwarm', fmt='.2f')
        plt.title(f'Correlation Matrix ({method.capitalize()})')
        plt.show()

    def visualize_scatter(self, x: str, y: str) -> None:
