        plt.title(f'Scatter Plot: {x} vs {y}')
        plt.show()

    def merge(self, other_dataset, on=None, how='inner', axis=0):
        with self.lock:
            if axis == 0:
                merged_data = pd.concat([self.data, other_dataset.data], axis=axis, join=how, keys=[self.id, other_dataset.id])
            else:
                merged_data = pd.merge(self.data, other_dataset.data, on=on, how=how)

            # Handle data type inconsistencies
            for col in merged_data.columns:
                try:
                    merged_data[col] = pd.to_numeric(merged_data[col])
                except:
                    pass

            self.data = merged_data
            self.record_change(f"Merged with dataset {other_dataset.id} (axis={axis}, how={how})")

    def record_change(self, description: str) -> None:
        with self.lock:
            change = {
                'timestamp': str(datetime.datetime.now()),
                'description': description,
                'data_shape': self.data.shape
            }
