    def __init__(self, position, hazard_type, radius):
        self.position = position
        self.hazard_type = hazard_type
        self.radius = radius
        self.active = True

    def check_damage(self, robot):
        """Check if a robot is in the hazard area and apply damage"""
        if self.position.distance_to(robot.position) <= self.radius:
            if self.hazard_type == "Lava":
                robot.health -= 5
            elif self.hazard_type == "Electric":
                robot.health -= 3
                robot.stunned = True
                threading.Timer(2, self.unstun_robot, args=[robot]).start()

    def unstun_robot(self, robot):
        """Unstun a robot affected by electric hazard"""
        robot.stunned = False

class Robot:
    """Class to represent an AI-controlled robot in the arena"""
    def __init__(self, name, team, robot_type, position):
        self.name = name
        self.team = team
        self.robot_type = robot_type
        self.position = position
        self.health = 100
        self.max_health = 100
        self.movement_speed = 2.0
        self.attack_power = 10
        self.weapon = WeaponType.LASER
        self.inventory = []
        self.invisible = False
        self.stunned = False
        self.power_ups = []
        self.objective = None
        self.memory = {
            "last_attack": None,
            "successful_attacks": [],
            "failed_attacks": [],
            "team_actions": [],
            "environment": {}
        }

    def move_to(self, target_position):
        """Move the robot toward a target position"""
        if not self.stunned and not self.invisible:
            # Calculate direction vector
            dx = target_position.x - self.position.x
            dy = target_position.y - self.position.y
            distance = self.position.distance_to(target_position)

            if distance > 1:  # 1 unit threshold for precision
                # Normalize and apply movement
                self.position.x += (dx / distance) * self.movement_speed
                self.position.y += (dy / distance) * self.movement_speed
                return True
        return False

    def attack(self, target_robot):
        """Attack another robot if in range"""
        if not self.stunned and self.weapon in [WeaponType.LASER, WeaponType.PLASMA]:
            if self.position.distance_to(target_robot.position) <= 8:
                damage = self.attack_power
                target_robot.health -= damage
                self.memory["successful_attacks"].append({
                    "target": target_robot.name,
                    "damage": damage,
                    "weapon": self.weapon.value
                })
                return True
        elif self.weapon == WeaponType.ENERGY_SWORD:
            if self.position.distance_to(target_robot.position) <= 1.5:
                damage = self.attack_power * 1.5
                target_robot.health -= damage
                self.memory["successful_attacks"].append({
                    "target": target_robot.name,
                    "damage": damage,
                    "weapon": self.weapon.value
                })
                return True
        elif self.weapon == WeaponType.EMP:
            if self.position.distance_to(target_robot.position) <= 10:
                target_robot.health -= self.attack_power
                target_robot.stunned = True
                threading.Timer(3, self.unstun_robot, args=[target_robot]).start()
                self.memory["successful_attacks"].append({
                    "target": target_robot.name,
                    "weapon": self.weapon.value
                })
                return True
        return False

    def unstun_robot(self, robot):
        """Unstun a robot after EMP attack"""
        robot.stunned = False

    def pick_up_power_up(self, power_up):
        """Pick up a power-up and apply its effect"""
        if power_up.active:
            power_up.activate()
            self.power_ups.append(power_up)
            power_up.apply_effect(self)
            self.inventory.append(power_up.power_up_type)
            return True
        return False

    def analyze_battle(self):
        """Analyze battle data to improve future performance"""
        if len(self.memory["successful_attacks"]) > 0:
            most_effective_weapon = max(
                set([a["weapon"] for a in self.memory["successful_attacks"]]),
                key=lambda w: sum([a["damage"] for a in self.memory["successful_attacks"] if a["weapon"] == w])
            )
            self.weapon = WeaponType(w.replace(" ", "_").upper())

        # Update movement strategy based on environment
        if "obstacles" in self.memory["environment"]:
            self.movement_speed *= 0.9  # Reduce speed in obstacle-dense areas

    def update_objective(self, new_objective):
        """Update the robot's objective and associated behavior"""
        self.objective = new_objective
        self._set_role_based_behavior()

    def _set_role_based_behavior(self):
        """Adjust behavior based on robot role"""
        if self.robot_type == RobotType.TANK:
            # Tanks focus on defense and soaking damage
            self.movement_speed *= 0.8
            self.attack_power *= 1.2
        elif self.robot_type == RobotType.SCOUT:
            # Scouts are fast and agile
            self.movement_speed *= 1.5
            self.attack_power *= 0.8
        elif self.robot_type == RobotType.ASSASSIN:
            # Assassins specialize in stealth attacks
            self.invisibility = True
            self.attack_power *= 1.5
        elif self.robot_type == RobotType.SUPPORT:
            # Support units provide healing and buffs
            self.weapon = WeaponType.SHIELD_PROJECTOR
            self.attack_power = 0
