class Arena:
    """Main class to represent the CyberArena environment"""
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.robots = []
        self.power_ups = []
        self.hazards = []
        self.objectives = []
        self.current_score = {Team.RED: 0, Team.BLUE: 0, Team.NEUTRAL: 0}
        self.round_number = 1
        self.difficulty = "Normal"
