        # Set initial objective based on team
        if robot.team in [Team.RED, Team.BLUE]:
            robot.update_objective(ObjectiveType.CAPTURE_FLAG)

    def add_power_up(self, power_up):
        """Add a power-up to the arena"""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard):
        """Add a hazard to the arena"""
        self.hazards.append(hazard)

    def add_objective(self, objective):
        """Add an objective to the arena"""
        self.objectives.append(objective)

    def update(self):
        """Update the arena state for one time step"""
        # Check for robot collisions and interactions
        for robot in self.robots:
            if robot.health <= 0:
                print(f"{robot.name} has been destroyed!")
                self.robots.remove(robot)
                continue

            # Update robot behavior based on objectives
            if robot.objective == ObjectiveType.CAPTURE_FLAG:
                # Search for the flag
                flag_position = Position(self.width/2, self.height/2)
                robot.move_to(flag_position)
            elif robot.objective == ObjectiveType.ESCORT_PAYLOAD:
                # Follow the payload
                payload_position = Position(self.width/4, self.height/4)
                robot.move_to(payload_position)

            # Check for nearby hazards
            for hazard in self.hazards:
                hazard.check_damage(robot)

            # Try to pick up power-ups
            for power_up in self.power_ups:
                if power_up.active and robot.position.distance_to(power_up.position) <= 2:
                    robot.pick_up_power_up(power_up)

            # Attack nearby enemies if not stunned
            if not robot.stunned:
                for enemy in self.robots:
                    if enemy.team != robot.team and robot.position.distance_to(enemy.position) <= 12:
