        # Check objectives
        self._check_objectives()

        # Update score and difficulty
        self._update_score()
        self._adjust_difficulty()

        # Analyze robot performance for learning
        for robot in self.robots:
            robot.analyze_battle()

    def _check_objectives(self):
        """Check if any objectives have been completed"""
        for objective in self.objectives:
            if objective.type == ObjectiveType.CAPTURE_FLAG:
                # Check if any robot has reached the flag position
                flag_position = Position(self.width/2, self.height/2)
                for robot in self.robots:
                    if robot.position.distance_to(flag_position) <= 1.5:
                        self.current_score[robot.team] += 10
                        print(f"{robot.team.value} has captured the flag!")
                        # Reset flag position
                        objective.reset()
            elif objective.type == ObjectiveType.ESCORT_PAYLOAD:
                # Check if payload has reached destination
                destination = Position(self.width*3/4, self.height*3/4)
                if objective.payload_position.distance_to(destination) <= 1:
                    self.current_score[objective.owning_team] += 20
                    print(f"{objective.owning_team.value} has successfully escorted the payload!")
