    def _adjust_difficulty(self):
        """Adjust difficulty based on team performance"""
        red_performance = self.current_score[Team.RED]
        blue_performance = self.current_score[Team.BLUE]

        if abs(red_performance - blue_performance) > 20:
            # If one team is significantly ahead, increase difficulty for that team
            if red_performance > blue_performance:
                self.difficulty_adjustments.append({
                    "target": Team.RED,
                    "adjustment": "increase"
                })
            else:
                self.difficulty_adjustments.append({
                    "target": Team.BLUE,
                    "adjustment": "increase"
                })
        else:
            # If teams are balanced, maintain or decrease difficulty
            self.difficulty_adjustments.append({
                "target": "both",
                "adjustment": "decrease"
            })

        # Apply difficulty adjustments
        if self.difficulty == "Normal":
            if any(a["adjustment"] == "increase" for a in self.difficulty_adjustments):
                self.difficulty = "Hard"
                print("\nDifficulty increased to Hard!")
        elif self.difficulty == "Hard":
            if all(a["adjustment"] == "decrease" for a in self.difficulty_adjustments):
                self.difficulty = "Normal"
                print("\nDifficulty decreased to Normal!")

    def start_battle(self, duration_minutes):
        """Start the battle for a specified duration"""
        print(f"\nBattle started! Duration: {duration_minutes} minutes")
        end_time = time.time() + duration_minutes * 60

        while time.time() < end_time:
            self.update()
            time.sleep(0.1)  # 100 ms per update step

