            robot.health = 100
            robot.inventory = []
            robot.power_ups = []
            robot.invisible = False
            robot.stunned = False

        # Reset power-ups
        for power_up in self.power_ups:
            power_up.active = True
            power_up.activation_time = None

        # Reset objectives
