import pandas as pd
from typing import Dict, Any, List
from enum import Enum
import os

# ------------------------------ DataFlowCoordinator System ------------------------------

class ModuleStatus(Enum):
    SUCCESS = 0
    FAILURE = 1


class DataFlowStage:
    def __init__(self, name: str, description: str):
        self.name = name
        self.description = description
        self.input_data = None
        self.output_data = None
        self.status = ModuleStatus.FAILURE

    def set_input(self, data: Any):
        self.input_data = data

    def get_output(self) -> Any:
        return self.output_data

    def execute(self) -> ModuleStatus:
        if self.input_data is None:
            return ModuleStatus.FAILURE
        return ModuleStatus.SUCCESS


# 1. Data Ingestion Module
class DataIngestionStage(DataFlowStage):
    def __init__(self):
        super().__init__('Data Ingestion', 'Ingest data from CSV, Excel, or databases.')

    def execute(self) -> ModuleStatus:
        if self.input_data is None:
            print('No input data source provided.')
            return ModuleStatus.FAILURE

        if self.input_data.endswith('.csv'):
            try:
                self.output_data = pd.read_csv(self.input_data)
                self.status = ModuleStatus.SUCCESS
            except Exception as e:
                print(f'Error reading CSV: {e}')
                return ModuleStatus.FAILURE

        elif self.input_data.endswith('.xlsx'):
            try:
                self.output_data = pd.read_excel(self.input_data)
                self.status = ModuleStatus.SUCCESS
            except Exception as e:
                print(f'Error reading Excel: {e}')
                return ModuleStatus.FAILURE

        else:
            print('Unsupported file format.')
            return ModuleStatus.FAILURE

        return ModuleStatus.SUCCESS


# 2. Data Validation Module
class DataValidationStage(DataFlowStage):
    def __init__(self):
        super().__init__('Data Validation', 'Validate data consistency, accuracy, and completeness.')

    def execute(self) -> ModuleStatus:
        if self.input_data is None:
            return ModuleStatus.FAILURE

        df = self.input_data

        # Check for nulls
        if df.isnull().values.any():
            print('Data contains null values. Validating failed.')
            return ModuleStatus.FAILURE

        # Check for invalid formats (e.g., strings in numeric columns)
        for col in df.select_dtypes(include=['object']).columns:
            if df[col].str.isdigit().all() or pd.to_numeric(df[col], errors='coerce').notnull().all():
                continue
            else:
                print(f'Invalid format in column: {col}')
                return ModuleStatus.FAILURE

        self.output_data = df
        self.status = ModuleStatus.SUCCESS
        return ModuleStatus.SUCCESS


# 3. Data Transformation Module
class DataTransformationStage(DataFlowStage):
