        average_performance = sum(team.team_performance for team in self.teams) / len(self.teams)
        if average_performance > 0.8:
            self.difficulty_level = DifficultyLevel.HARD
        elif average_performance < 0.3:
            self.difficulty_level = DifficultyLevel.EASY
