    def set_weapon(self, weapon):
        """Assigns a weapon to the robot."""
        self.weapon = weapon

    def update(self, arena):
        """Updates the robot's state based on the current arena conditions."""
        if self.health <= 0:
            arena.remove_robot(self)
            return

        # Adaptive behavior based on experience
        if self.experience > 100 and random.random() < 0.2:
            self.take_tactical_action(arena)
        else:
