        """Standard behavior for robots to take actions."""
        if self.objective is not None:
            self.move_toward(self.objective.position)
        else:
            # Default behavior: move randomly
            new_x = self.position.x + random.uniform(-self.speed, self.speed)
            new_y = self.position.y + random.uniform(-self.speed, self.speed)
            self.position.x = max(0, min(arena.arena_width, new_x))
            self.position.y = max(0, min(arena.arena_height, new_y))

