    """Power-up item that provides temporary benefits to robots."""
    def __init__(self, name, position, effect, duration=10, strength=1.5):
        self.name = name
        self.position = position
        self.effect = effect
        self.duration = duration
        self.strength = strength
        self.activating_robot = None

    def activate(self, robot):
        """Activates the power-up for a robot."""
        self.activating_robot = robot
        if self.effect == "speed_boost":
            robot.speed *= self.strength
            robot.power_up_timer = self.duration
        elif self.effect == "health_boost":
            robot.health = min(robot.health + 25, 100)
        elif self.effect == "damage_boost":
            robot.attack_power *= self.strength
            robot.power_up_timer = self.duration

    def update(self):
        """Updates the power-up state."""
        if self.activating_robot:
            if self.effect in ["speed_boost", "damage_boost"] and self.activating_robot.power_up_timer > 0:
                self.activating_robot.power_up_timer -= 1
                if self.activating_robot.power_up_timer == 0:
                    # Revert changes
                    if self.effect == "speed_boost":
                        self.activating_robot.speed /= self.strength
                    elif self.effect == "damage_boost":
                        self.activating_robot.attack_power /= self.strength
                    self.activating_robot = None

