    """Main class for the CyberArena simulation."""
    def __init__(self, width=100, height=100, difficulty=DifficultyLevel.MEDIUM):
        self.width = width
        self.height = height
        self.difficulty = difficulty
        self.robots = []
        self.team_objectives = []
        self.power_ups = []
        self.hazards = []
        self.round_time = 0
        self.start_time = time.time()

    def add_robot(self, robot):
        """Adds a robot to the arena."""
        self.robots.append(robot)

    def remove_robot(self, robot):
        """Removes a robot from the arena."""
        self.robots.remove(robot)

    def add_team_objective(self, objective):
        """Adds a team objective to the arena."""
        self.team_objectives.append(objective)

    def add_power_up(self, power_up):
        """Adds a power-up to the arena."""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard):
        """Adds a hazard to the arena."""
        self.hazards.append(hazard)

    def get_opposing_team_robots(self, robot):
        """Returns all robots from the opposing team."""
        return [r for r in self.robots if r.team != robot.team]

    def get_team_robots(self, team):
        """Returns all robots belonging to a specific team."""
        return [r for r in self.robots if r.team == team]

    def update_difficulty(self):
        """Adjusts the difficulty based on robot performance."""
        avg_health = sum(r.health for r in self.robots) / len(self.robots) if self.robots else 100
        avg_score = sum(r.score for r in self.robots) / len(self.robots) if self.robots else 0

        if avg_health > 80 and avg_score < 50:
            # Increase difficulty
            if self.difficulty != DifficultyLevel.LEGENDARY:
                self.difficulty = DifficultyLevel(self.difficulty.value + 1)
                self._increase_ai_aggressiveness()
        elif avg_health < 50 or avg_score > 200:
            # Decrease difficulty
            if self.difficulty != DifficultyLevel.EASY:
                self.difficulty = DifficultyLevel(self.difficulty.value - 1)
                self._decrease_ai_aggressiveness()

    def _increase_ai_aggressiveness(self):
        """Makes AI robots more aggressive and strategic."""
        for robot in self.robots:
            if robot.team == Team.RED or robot.team == Team.BLUE:
                robot.speed += 1
                robot.attack_power += 5
                robot.experience += 10

    def _decrease_ai_aggressiveness(self):
        """Makes AI robots less aggressive and strategic."""
        for robot in self.robots:
            if robot.team == Team.RED or robot.team == Team.BLUE:
                robot.speed = max(2, robot.speed - 1)
                robot.attack_power = max(5, robot.attack_power - 5)
                robot.experience = max(0, robot.experience - 10)

    def is_round_complete(self):
        """Checks if the current round is complete."""
        for objective in self.team_objectives:
            if not objective.is_complete():
                return False
        return True

    def run_simulation(self, duration_minutes=5):
        """Runs the CyberArena simulation for a given duration."""
        print(f"Starting CyberArena battle with {len(self.robots)} robots!")
        print(f"Difficulty: {self.difficulty}")
        print(f"Objectives: {[obj.name for obj in self.team_objectives]}")

        start_time = time.time()
        frame = 0

        while time.time() - start_time < duration_minutes * 60 and not self.is_round_complete():
            frame += 1
            print(f"\nFrame {frame} - {time.time() - start_time:.2f} seconds")

            # Update all robots
            for robot in self.robots:
                robot.update(self)

                # Update power-ups
                for power_up in self.power_ups:
                    power_up.update()

                    # Check if robot can pick up power-up
                    if robot.position.distance(power_up.position) < 2:
                        power_up.activate(robot)
                        self.power_ups.remove(power_up)

            # Update hazards
            for hazard in self.hazards:
                hazard.update(self.robots)

            # Update difficulty based on performance
            self.update_difficulty()

            # Display status
            self.display_status()
            time.sleep(0.5)  # Simulate real-time behavior (2 Hz)

        print("\nSimulation complete!")
        self.display_results()

    def display_status(self):
        """Displays the current status of the arena."""
        print("\nRobot Status:")
        for robot in self.robots:
            print(f"{robot.name} ({robot.team.name}): Health={robot.health}, Position={robot.position}")

        print("\nTeam Objectives:")
        for objective in self.team_objectives:
            print(f"{objective.name} ({objective.team.name}): Complete={objective.is_complete()}")

    def display_results(self):
        """Displays the results of the simulation."""
        print("\nBattle Results:")

        # Display team scores
        red_score = sum(r.score for r in self.get_team_robots(Team.RED))
        blue_score = sum(r.score for r in self.get_team_robots(Team.BLUE))

        print(f"RED Team Score: {red_score}")
        print(f"BLUE Team Score: {blue_score}")

        # Determine winner
        if red_score > blue_score:
            print("RED Team wins the battle!")
        elif blue_score > red_score:
            print("BLUE Team wins the battle!")
        else:
            print("It's a tie!")

        # Display individual scores
        print("\nIndividual Robot Scores:")
        for robot in self.robots:
            print(f"{robot.name} ({robot.team.name}): Score={robot.score}, Experience={robot.experience}")

