    def __init__(self, user: str, content: str, timestamp: float):
        self.user = user
        self.content = content
        self.timestamp = timestamp


class ChatRoom:
    def __init__(self, session_id: str):
        self.session_id = session_id
        self.messages: List[ChatMessage] = []

    def send_message(self, user: str, content: str):
        self.messages.append(ChatMessage(user, content, time.time()))

    def get_messages(self):
        return self.messages

# ==========================
# MAIN SYSTEM
# ==========================
class CodeSquad:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.code_sessions: Dict[str, CodeSnippet] = {}
        self.chat_rooms: Dict[str, ChatRoom] = {}
        self.issues: List[Dict] = []

    def add_user(self, username: str, role: str):
        user = User(username, role)
        self.users[username] = user
        return user

    def create_code_session(self, session_id: str, content: str, author: str):
        snippet = self.users[author].share_code(content)
        self.code_sessions[session_id] = snippet
        self.chat_rooms[session_id] = ChatRoom(session_id)
        return snippet

    def annotate_code(self, session_id: str, user: str, comment: str):
        snippet = self.code_sessions.get(session_id)
        if snippet:
            snippet.add_annotation(user, comment)

    def resolve_issue(self, session_id: str):
        snippet = self.code_sessions.get(session_id)
        if snippet:
            snippet.review_status = CodeReviewStatus.RESOLVED

    def reopen_issue(self, session_id: str):
        snippet = self.code_sessions.get(session_id)
        if snippet:
            snippet.review_status = CodeReviewStatus.REOPENED

    def get_dashboard(self):
        dashboard = {
            'ongoing_sessions': [],
            'resolved_issues': [],
            'open_issues': []
        }
        for session_id, snippet in self.code_sessions.items():
            issue_status = {
                'session_id': session_id,
                'author': snippet.author,
                'status': snippet.review_status.name
            }
            if snippet.review_status == CodeReviewStatus.PENDING:
                dashboard['open_issues'].append(issue_status)
            elif snippet.review_status == CodeReviewStatus.RESOLVED:
                dashboard['resolved_issues'].append(issue_status)
            elif snippet.review_status == CodeReviewStatus.IN_PROGRESS:
                dashboard['ongoing_sessions'].append(issue_status)
        return dashboard

    def filter_issues(self, status: CodeReviewStatus):
        return [session for session in self.code_sessions.values() if session.review_status == status]

# ==========================
# DEMO
# ==========================
def demo():
    # Initialize system
    system = CodeSquad()

    # Add users
    dev1 = system.add_user('dev1', 'developer')
    dev2 = system.add_user('dev2', 'reviewer')

