class Direction(Enum):
    UP = 'up'
    DOWN = 'down'
    LEFT = 'left'
    RIGHT = 'right'

class WeaponType(Enum):
    RANGED = 'ranged'
    MELEE = 'melee'
    AREA_OF_EFFECT = 'aoe'

class Team(Enum):
    RED = 'red'
    BLUE = 'blue'

class RobotState(Enum):
    IDLE = 'idle'
    MOVING = 'moving'
    ATTACKING = 'attacking'
    DEFENDING = 'defending'
    DEAD = 'dead'

class PowerUpType(Enum):
    SHIELD = 'shield'
    SPEED_BOOST = 'speed_boost'
    DAMAGE_BOOST = 'damage_boost'
    REPAIR_KIT = 'repair_kit'

class Weapon:
    def __init__(self, name: str, damage: float, weapon_type: WeaponType, range: float = 0):
        self.name = name
        self.damage = damage
        self.type = weapon_type
        self.range = range  # Range for ranged weapons, radius for AoE

    def use(self, target_distance: float) -> bool:
        """Determine if the attack is successful based on weapon type and distance."""
        if self.type == WeaponType.RANGED:
            return target_distance <= self.range
        elif self.type == WeaponType.MELEE:
            return target_distance <= 1.5
        elif self.type == WeaponType.AREA_OF_EFFECT:
            return True  # AoE weapons affect all nearby
        return False

class PowerUp:
    def __init__(self, power_up_type: PowerUpType, duration: float = 10.0):
        self.type = power_up_type
        self.duration = duration
        self.expires_at = 0.0

    def apply_effect(self, robot):
        """Apply the power-up effect to the robot."""
        if self.type == PowerUpType.SHIELD:
            robot.shield = 50.0
        elif self.type == PowerUpType.SPEED_BOOST:
            robot.movement_speed *= 1.5
        elif self.type == PowerUpType.DAMAGE_BOOST:
            robot.damage_multiplier = 1.5
        elif self.type == PowerUpType.REPAIR_KIT:
            robot.health = min(robot.health + 30.0, robot.max_health)
        self.expires_at = time.time() + self.duration

    def has_expired(self):
        """Check if the power-up has expired."""
        return time.time() > self.expires_at

class Robot:
    def __init__(self, name: str, team: Team, position: Tuple[float, float]):
        self.name = name
        self.team = team
        self.position = position  # x, y
        self.movement_speed = 2.0
        self.health = 100.0
        self.max_health = 100.0
        self.shield = 0.0
        self.state = RobotState.IDLE
        self.weapon = Weapon("Standard Plasma Gun", 10.0, WeaponType.RANGED, 15.0)
        self.inventory: List[PowerUp] = []
        self.damage_multiplier = 1.0
        self.strategy = None  # To be set by the team commander
        self.last_action_time = time.time()
        self.action_cooldown = 1.0  # 1 second between actions

    def move(self, direction: Direction, delta_time: float):
        """Move the robot in the desired direction."""
        if self.state != RobotState.MOVING:
            self.state = RobotState.MOVING
            self.last_action_time = time.time()

        dx, dy = 0, 0
        if direction == Direction.UP:
            dy = self.movement_speed * delta_time
        elif direction == Direction.DOWN:
            dy = -self.movement_speed * delta_time
        elif direction == Direction.LEFT:
            dx = -self.movement_speed * delta_time
        elif direction == Direction.RIGHT:
            dx = self.movement_speed * delta_time

        self.position = (self.position[0] + dx, self.position[1] + dy)

    def attack(self, target):
        """Attempt to attack a target with the current weapon."""
        if self.state != RobotState.ATTACKING and time.time() - self.last_action_time >= self.action_cooldown:
            self.state = RobotState.ATTACKING
            distance = ((self.position[0] - target.position[0]) ** 2 + (self.position[1] - target.position[1]) ** 2) ** 0.5
            if self.weapon.use(distance):
                damage = self.weapon.damage * self.damage_multiplier
                self.inflict_damage(target, damage)
                self.last_action_time = time.time()

    def inflict_damage(self, target, damage: float):
        """Apply damage to a target, considering shields."""
        if self.team == target.team:
            return  # Don't attack teammates

        if target.shield > 0:
            if damage >= target.shield:
                target.shield = 0
                damage -= target.shield
            else:
                target.shield -= damage
                damage = 0

        if damage > 0:
            target.health -= damage
            if target.health <= 0:
                target.state = RobotState.DEAD

    def pick_up_power_up(self, power_up: PowerUp):
        """Pick up a power-up and apply its effect."""
        self.inventory.append(power_up)
        power_up.apply_effect(self)

    def update_power_ups(self):
        """Update active power-ups and remove expired ones."""
        for power_up in self.inventory.copy():
            if power_up.has_expired():
                # Revert effects
                if power_up.type == PowerUpType.SHIELD:
                    self.shield = 0
                elif power_up.type == PowerUpType.SPEED_BOOST:
                    self.movement_speed /= 1.5
                elif power_up.type == PowerUpType.DAMAGE_BOOST:
                    self.damage_multiplier = 1.0
                self.inventory.remove(power_up)

    def is_alive(self):
        """Check if the robot is alive."""
        return self.state != RobotState.DEAD

