        """Assign a strategy to the team."""
        if strategy_name == "flanking":
            self.tactics = ["flank_left", "flank_right", "main_attack"]
        elif strategy_name == "defensive":
            self.tactics = ["defend_base", "ambush", "support"]
        elif strategy_name == "offensive":
            self.tactics = ["push_forward", "capture", "support"]

        # Assign tactics to individual robots
        for i, robot in enumerate(self.robots):
            if i < len(self.tactics):
                robot.strategy = self.tactics[i]
            else:
                robot.strategy = "support"  # Default fallback

    def update_tactics(self):
        """Update tactics based on the team's performance."""
        if self.team_score >= 100:
