        """Evaluate the team's performance and adjust tactics."""
        # Calculate kill/death ratio for the team
        team_kills = sum(robot.health <= 0 for robot in enemies if robot.team != self.team)
        team_deaths = sum(robot.health <= 0 for robot in self.robots)
        if team_deaths == 0:
            kill_death_ratio = float('inf')  # Perfect
        else:
            kill_death_ratio = team_kills / team_deaths

        # Adjust tactics based on performance
