    SUPPORT = {'speed': 1.0, 'health': 150, 'weapon': 'medkit_launcher'}
    ENGINEER = {'speed': 1.2, 'health': 200, 'weapon': 'turret_deployer'}

class WeaponType(Enum):
    """Enum for different weapon types and their properties."""
    LASER = {'damage': 20, 'range': 50, 'cooldown': 1.0}
    PLASMA_CANNON = {'damage': 50, 'range': 100, 'cooldown': 3.0}
    MEDKIT_LAUNCHER = {'damage': 0, 'heal': 30, 'range': 30, 'cooldown': 5.0}
    TURRET_DEPLOYER = {'damage': 0, 'turret_damage': 25, 'range': 40, 'cooldown': 10.0}

class ObjectiveType(Enum):
    """Enum for different objective types in the arena."""
    CAPTURE_FLAG = 1
    DEFEND_BASE = 2
    ESCORT_PAYLOAD = 3

class Team(Enum):
    """Enum for robot teams in the arena."""
    RED = 1
    BLUE = 2

# ==============================
