class Robot(ABC):
    """Abstract base class for all robots in the arena."""
    def __init__(self, robot_id, robot_type, team, position):
        self.robot_id = robot_id
        self.robot_type = RobotType(robot_type)
        self.team = Team(team)
        self.position = position
        self.health = self.robot_type.value['health']
        self.max_health = self.robot_type.value['health']
        self.speed = self.robot_type.value['speed']
        self.weapon = self._initialize_weapon()
        self.objective = None
        self.target = None
        self.weapon_cooldown = 0.0
        self.is_active = True

    def _initialize_weapon(self):
        """Initialize the robot's weapon based on its type."""
        weapon_name = self.robot_type.value['weapon']
        for weapon in WeaponType:
            if weapon_name in weapon.name.lower():
                return weapon.value
        return {}

    def take_damage(self, damage):
        """Reduce robot's health based on damage received."""
        self.health -= damage
        if self.health <= 0:
            self.is_active = False
            if self.objective:
                self.objective.robot_lost(self)

    def heal(self, amount):
        """Heal the robot's health."""
        self.health = min(self.health + amount, self.max_health)

    def move_towards(self, target_position, delta_time):
        """Move the robot towards a target position."""
        if not self.is_active:
            return
        dx = target_position[0] - self.position[0]
        dy = target_position[1] - self.position[1]
        distance = math.hypot(dx, dy)
        if distance > 1e-6:
            self.position = (
                self.position[0] + (dx / distance) * self.speed * delta_time,
                self.position[1] + (dy / distance) * self.speed * delta_time
            )

    def use_weapon(self, target):
        """Use the robot's weapon against a target."""
        if not self.is_active or self.weapon_cooldown > 0:
            return
        if self._is_in_attack_range(target):
            damage = self.weapon.get('damage', 0)
            heal = self.weapon.get('heal', 0)
            if damage > 0:
                target.take_damage(damage)
            elif heal > 0:
                self.heal(heal)
            self.weapon_cooldown = self.weapon.get('cooldown', 0)

    def _is_in_attack_range(self, target):
        """Check if the target is within attack range."""
        dx = target.position[0] - self.position[0]
        dy = target.position[1] - self.position[1]
        distance = math.hypot(dx, dy)
        return distance <= self.weapon.get('range', 0)

    @abstractmethod
    def update(self, arena, delta_time):
        """Update robot's state and behavior in the arena."""
        pass

    def __str__(self):
        return f"Robot {self.robot_id} ({self.robot_type.name}, Team {self.team.name}, Health: {self.health}) at {self.position}"

class TeamObjective:
    """Class representing a team's objective in the arena."""
    def __init__(self, objective_type, position, team):
        self.objective_type = objective_type
        self.position = position
        self.team = team
        self.assigned_robots = []
        self.progress = 0.0

    def assign_robot(self, robot):
        """Assign a robot to this objective."""
        if robot not in self.assigned_robots:
            self.assigned_robots.append(robot)
            robot.objective = self
            if self.objective_type == ObjectiveType.CAPTURE_FLAG:
                # For capture flag, start progress at 0
                self.progress = 0.0
            elif self.objective_type == ObjectiveType.ESCORT_PAYLOAD:
                # For escort, progress is based on distance
                self.progress = 0.0

    def robot_lost(self, robot):
        """Handle when a robot assigned to the objective is lost."""
        if robot in self.assigned_robots:
            self.assigned_robots.remove(robot)
            robot.objective = None
            # Adjust progress if necessary
            if self.objective_type == ObjectiveType.ESCORT_PAYLOAD:
                # If the payload is being escorted, progress is reduced
                self.progress -= 0.1
                self.progress = max(0.0, self.progress)

    def update_progress(self, delta_time):
        """Update the progress of the objective."""
        if self.objective_type == ObjectiveType.CAPTURE_FLAG:
            # Capture flag progress increases over time
            if self.progress < 1.0:
                self.progress += 0.01 * delta_time
                self.progress = min(1.0, self.progress)
        elif self.objective_type == ObjectiveType.ESCORT_PAYLOAD:
            # Escort payload progress increases if all assigned robots are alive
            if len(self.assigned_robots) > 0:
                for robot in self.assigned_robots:
                    if robot.is_active:
                        destination = (1000, 1000)  # Destination point for the payload
                        dx = destination[0] - robot.position[0]
                        dy = destination[1] - robot.position[1]
                        distance = math.hypot(dx, dy)
                        # Progress is based on distance to destination
                        self.progress = 1.0 - (distance / 1000)
                        break
        elif self.objective_type == ObjectiveType.DEFEND_BASE:
            # Defense objective progress decreases if enemies get too close
            for robot in self.assigned_robots:
                if robot.is_active:
                    for enemy in arena.robots:
                        if enemy.team != self.team and enemy.is_active:
                            dx = robot.position[0] - enemy.position[0]
                            dy = robot.position[1] - enemy.position[1]
                            distance = math.hypot(dx, dy)
                            if distance < 50:
                                self.progress -= 0.005 * delta_time
                            else:
                                self.progress += 0.001 * delta_time
            self.progress = max(0.0, min(1.0, self.progress))

    def is_complete(self):
        """Check if the objective is complete."""
        return self.progress >= 1.0

    def __str__(self):
        return f"Objective {self.objective_type.name} for Team {self.team.name} at {self.position}, Progress: {self.progress:.2f}"

class PowerUp:
    """Class representing a power-up item in the arena."""
    def __init__(self, powerup_type, position, duration=10.0):
        self.powerup_type = powerup_type
        self.position = position
        self.duration = duration
        self.remaining_time = duration

    def apply_effect(self, robot):
        """Apply the power-up's effect to a robot."""
        if self.powerup_type == 'speed_boost':
            robot.speed *= 1.5
        elif self.powerup_type == 'invincibility':
            robot.is_invisible = True
        elif self.powerup_type == 'double_damage':
            robot.weapon['damage'] *= 2
        elif self.powerup_type == 'heal':
            robot.heal(50)

    def remove_effect(self, robot):
        """Remove the power-up's effect from a robot."""
        if self.powerup_type == 'speed_boost':
            robot.speed /= 1.5
        elif self.powerup_type == 'invincibility':
            robot.is_invisible = False
        elif self.powerup_type == 'double_damage':
            base_damage = {
                'LASER': 20,
                'PLASMA_CANNON': 50,
                'MEDKIT_LAUNCHER': 0,
                'TURRET_DEPLOYER': 0
            }.get(robot.weapon.get('name', 'LASER'), 20)
            robot.weapon['damage'] = base_damage
        elif self.powerup_type == 'heal':
            pass  # No action needed

    def update(self, delta_time):
        """Update the power-up's remaining time."""
        self.remaining_time -= delta_time
        if self.remaining_time <= 0:
            return False
        return True

class EnvironmentalHazard:
    """Class representing an environmental hazard in the arena."""
    def __init__(self, hazard_type, position, radius, damage_per_tick):
        self.hazard_type = hazard_type
        self.position = position
        self.radius = radius
        self.damage_per_tick = damage_per_tick

    def apply_damage(self, robot):
        """Apply damage to robots in the hazard's area."""
        dx = robot.position[0] - self.position[0]
        dy = robot.position[1] - self.position[1]
        distance = math.hypot(dx, dy)
        if distance <= self.radius:
            robot.take_damage(self.damage_per_tick)

    def __str__(self):
        return f"Hazard {self.hazard_type} at {self.position}, Radius: {self.radius}, Damage: {self.damage_per_tick}/tick"

class CyberArena:
    """Main class for the CyberArena simulation."""
    def __init__(self):
        self.robots = []
        self.objectives = []
        self.powerups = []
        self.hazards = []
        self.time_elapsed = 0.0
        self.team_scores = {Team.RED: 0, Team.BLUE: 0}
        self.running = True
        self.difficulty_level = 1.0  # Adjusts AI difficulty dynamically

    def add_robot(self, robot):
        """Add a robot to the arena."""
        self.robots.append(robot)

    def add_objective(self, objective):
        """Add an objective to the arena."""
        self.objectives.append(objective)

    def add_powerup(self, powerup):
        """Add a power-up to the arena."""
        self.powerups.append(powerup)

    def add_hazard(self, hazard):
        """Add an environmental hazard to the arena."""
        self.hazards.append(hazard)

    def update(self, delta_time):
        """Update the entire arena state."""
        if not self.running:
            return

        self.time_elapsed += delta_time

        # Update all robots
        for robot in self.robots:
            if robot.is_active:
                robot.update(self, delta_time)

        # Update all objectives
        for objective in self.objectives:
            objective.update_progress(delta_time)

        # Update all power-ups
        for powerup in self.powerups:
            if not powerup.update(delta_time):
                self.powerups.remove(powerup)

        # Update environmental hazards
        for hazard in self.hazards:
            for robot in self.robots:
                if robot.is_active:
                    hazard.apply_damage(robot)

