class Robot:
    def __init__(self, name: str, robot_type: RobotType, team: Team, position: Position):
        self.name = name
        self.robot_type = robot_type
        self.team = team
        self.position = position
        self.health = 100
        self.max_health = 100
        self.weapon = self._select_default_weapon()
        self.velocity = Velocity(0, 0, 0)
        self.status_effects: List[StatusEffect] = []
        self.skills_cooldown: Dict[WeaponType, float] = {weapon: 0 for weapon in WeaponType}
        self.score = 0
        self.experience = 0
        self.memory_log: List[Dict] = []  # For learning from previous actions

    def _select_default_weapon(self) -> WeaponType:
        """Select a default weapon based on robot type."""
        weapon_map = {
            RobotType.ASSAULT: WeaponType.LASER_RIFLE,
            RobotType.SUPPORT: WeaponType.HEAL_DRONE,
            RobotType.ENGINEER: WeaponType.SHOCK_WAVE,
            RobotType.RECON: WeaponType.PLASMA_CANNON
        }
        return weapon_map[self.robot_type]

    def move(self, target_position: Position, speed: float = 2.0):
        """Move robot towards a target position with specified speed."""
        dx = target_position.x - self.position.x
        dy = target_position.y - self.position.y
        dz = target_position.z - self.position.z
        distance = (dx**2 + dy**2 + dz**2)**0.5
        if distance > 0:
            self.velocity.x = (dx / distance) * speed
            self.velocity.y = (dy / distance) * speed
            self.velocity.z = (dz / distance) * speed
            self.position.x += self.velocity.x
            self.position.y += self.velocity.y
            self.position.z += self.velocity.z

    def attack(self, target: "Robot", weapon: WeaponType):
        """Attack a target robot with the specified weapon."""
        if self.skills_cooldown[weapon] > 0:
            print(f"{self.name} is on cooldown for {weapon.value}.")
            return
        if self._is_in_attack_range(target):
            damage = self._calculate_damage(weapon)
            print(f"{self.name} attacks {target.name} with {weapon.value}, dealing {damage} damage.")
            target.take_damage(damage)
            self.skills_cooldown[weapon] = self._get_weapon_cooldown(weapon)
            self._log_action("attack", weapon, target.name, damage)

    def take_damage(self, damage: float):
        """Apply damage to the robot."""
        if self.health > 0:
            self.health -= damage
            if self.health < 0:
                self.health = 0
            print(f"{self.name} took {damage} damage. Health: {self.health}")

    def use_ability(self, ability: WeaponType):
        """Use a special ability."""
        if self.skills_cooldown[ability] > 0:
            print(f"{self.name} is on cooldown for {ability.value}.")
            return
        if ability == WeaponType.HEAL_DRONE:
            self.heal(30)
            self.skills_cooldown[ability] = self._get_weapon_cooldown(ability)
            self._log_action("use_ability", ability, "self", 30)
        else:
            print(f"{self.name} used {ability.value} ability.")

    def heal(self, amount: float):
        """Heal the robot by a specified amount."""
        self.health = min(self.health + amount, self.max_health)
        print(f"{self.name} healed for {amount} health. Current health: {self.health}")

    def _is_in_attack_range(self, target: "Robot") -> bool:
        """Check if the target is within attack range."""
        distance = ((self.position.x - target.position.x)**2 +
                    (self.position.y - target.position.y)**2 +
                    (self.position.z - target.position.z)**2)**0.5
        return distance <= 5.0  # 5.0 units is the attack range

    def _calculate_damage(self, weapon: WeaponType) -> float:
        """Calculate damage based on weapon type and robot type."""
        damage_map = {
            WeaponType.LASER_RIFLE: 25,
            WeaponType.PLASMA_CANNON: 35,
            WeaponType.SHOCK_WAVE: 40,
            WeaponType.HEAL_DRONE: 0
        }
        if self.robot_type == RobotType.SUPPORT:
            return damage_map[weapon] * 0.75  # Support robots deal 75% damage
        return damage_map[weapon]

    def _get_weapon_cooldown(self, weapon: WeaponType) -> float:
        """Get cooldown time for each weapon."""
        cooldown_map = {
            WeaponType.LASER_RIFLE: 1.0,
            WeaponType.PLASMA_CANNON: 1.5,
            WeaponType.SHOCK_WAVE: 2.5,
            WeaponType.HEAL_DRONE: 3.0
        }
        return cooldown_map[weapon]

