        """Log actions for learning and strategy adaptation."""
        self.memory_log.append({
            "action": action_type,
            "weapon": weapon.value,
            "target": target,
            "value": value,
            "timestamp": time.time()
        })

    def learn_from_experience(self):
        """Process past experiences to improve future behavior."""
        if len(self.memory_log) < 5:
            return  # Not enough data to learn from
        effective_actions = [log for log in self.memory_log if log["value"] > 20]
        if effective_actions:
            most_used_action = max(set([a["action"] for a in effective_actions]), 
                                  key=lambda x: [a["action"] for a in effective_actions].count(x))
            self._adapt_strategy(most_used_action)

    def _adapt_strategy(self, action_type: str):
        """Adjust strategy based on what's working."""
        if action_type == "attack":
            self.weapon = WeaponType.PLASMA_CANNON  # Switch to a more effective weapon
        elif action_type == "use_ability":
            self.weapon = WeaponType.HEAL_DRONE  # Switch to support role

class PowerUp:
    def __init__(self, name: str, position: Position, effect: StatusEffect, duration: float):
