    def apply_effect(self, robot: Robot):
        """Apply the power-up effect to a robot."""
        print(f"{robot.name} picked up {self.name} power-up.")
        if self.effect == StatusEffect.STUN:
            robot.velocity = Velocity(0, 0, 0)
        elif self.effect == StatusEffect.SLOW:
            robot.velocity.x *= 0.5
            robot.velocity.y *= 0.5
            robot.velocity.z *= 0.5
