                "damage": 10,
                "activation_time": 0
            })

    def add_robot(self, robot: Robot):
        """Add a robot to the arena and set its spawn position."""
        spawn = random.choice(self.spawn_points[robot.team])
        robot.position = spawn
        self.robots.append(robot)

    def update(self, delta_time: float):
        """Update the arena state in real-time."""
        # Update robot cooldowns
        for robot in self.robots:
            for weapon in robot.skills_cooldown:
                if robot.skills_cooldown[weapon] > 0:
                    robot.skills_cooldown[weapon] -= delta_time
                    if robot.skills_cooldown[weapon] < 0:
                        robot.skills_cooldown[weapon] = 0

        # Check for hazards
        for hazard in self.hazards:
            hazard["activation_time"] += delta_time
            if hazard["activation_time"] > 3.0:
                for robot in self.robots:
                    distance = ((robot.position.x - hazard["position"].x)**2 +
                                (robot.position.y - hazard["position"].y)**2 +
                                (robot.position.z - hazard["position"].z)**2)**0.5
                    if distance < 2.0:
                        robot.take_damage(hazard["damage"])
                hazard["activation_time"] = 0

        # Check for power-up collection
        for power_up in self.power_ups:
            for robot in self.robots:
                distance = ((robot.position.x - power_up.position.x)**2 +
                            (robot.position.y - power_up.position.y)**2 +
                            (robot.position.z - power_up.position.z)**2)**0.5
                if distance < 1.0:
                    power_up.apply_effect(robot)
                    self.power_ups.remove(power_up)
                    break

        # Update robot positions
        for robot in self.robots:
            robot.move(
                Position(
                    robot.position.x + random.uniform(-1, 1),
                    robot.position.y,
