                )
            )

        # Check for objective completion
        if self.objective_type == ObjectiveType.CTF:
            self._check_ctf_objective()
        elif self.objective_type == ObjectiveType.BASE_DEFENSE:
            self._check_base_defense()
        elif self.objective_type == ObjectiveType.PAYLOAD_ESCORT:
            self._check_payload_escort()

    def _check_ctf_objective(self):
        """Check if the Capture the Flag objective is completed."""
        flag_positions = {
            Team.RED: Position(45, 0, 0),
            Team.BLUE: Position(15, 0, 0)
        }
        for robot in self.robots:
            if (robot.team == Team.RED and 
