                   (robot.position.z - flag_positions[Team.RED].z)**2)**0.5 < 2.0):
                print(f"{robot.name} captured the Red team's flag!")
                robot.score += 100
                break

    def _check_base_defense(self):
        """Check if the Base Defense objective is completed."""
        base_positions = {
            Team.RED: Position(45, 0, 0),
