        }
        for team, position in base_positions.items():
            for robot in self.robots:
                if robot.team != team and ((robot.position.x - position.x)**2 + 
                                           (robot.position.z - position.z)**2)**0.5 < 3.0:
                    print(f"Enemy {robot.name} is attacking {team.value} base!")
                    for defender in self.robots:
