# solution.py
import json
import datetime
from typing import List, Dict, Optional
import threading
import math

# --------------------------
# Vector2 Class (Reused in UI for Charting)
# --------------------------
class Vector2:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector2(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            raise ValueError("Cannot divide by zero")
        return Vector2(self.x / scalar, self.y / scalar)

    def length(self):
        return math.hypot(self.x, self.y)

    def normalize(self):
        length = self.length()
        if length == 0:
            return Vector2(0, 0)
        return self / length


# --------------------------
# Database Layer
# --------------------------
class Database:
    def __init__(self):
        self.users = {}
        self.transactions = {}
        self.savings_goals = {}
        self.expense_categories = {}

    def add_user(self, user_id: int, name: str, email: str):
        self.users[user_id] = {"name": name, "email": email}

    def add_transaction(self, user_id: int, amount: float, category: str, date: str):
        if user_id not in self.transactions:
            self.transactions[user_id] = []
        self.transactions[user_id].append({
            "amount": amount,
            "category": category,
            "date": date
        })

    def get_transactions(self, user_id: int) -> List[Dict]:
        return self.transactions.get(user_id, [])

    def add_savings_goal(self, user_id: int, goal_name: str, target_amount: float, deadline: str):
        if user_id not in self.savings_goals:
            self.savings_goals[user_id] = []
        self.savings_goals[user_id].append({
            "goal_name": goal_name,
            "target_amount": target_amount,
            "deadline": deadline
        })


# --------------------------
# Backend Layer
# --------------------------
class Backend:
    def __init__(self, database: Database):
        self.db = database

    def register_user(self, user_id: int, name: str, email: str):
        self.db.add_user(user_id, name, email)

    def add_transaction(self, user_id: int, amount: float, category: str, date: str):
        self.db.add_transaction(user_id, amount, category, date)

    def add_savings_goal(self, user_id: int, goal_name: str, target_amount: float, deadline: str):
        self.db.add_savings_goal(user_id, goal_name, target_amount, deadline)

    def get_user_data(self, user_id: int) -> Dict:
        transactions = self.db.get_transactions(user_id)
        savings_goals = self.db.savings_goals.get(user_id, [])
        return {
            "transactions": transactions,
            "savings_goals": savings_goals
        }


# --------------------------
# Frontend Layer (Basic UI and Visualization)
# --------------------------
class Frontend:
    def __init__(self, backend: Backend):
        self.backend = backend

    def register_user(self, user_id: int, name: str, email: str):
        self.backend.register_user(user_id, name, email)

    def track_expense(self, user_id: int, amount: float, category: str, date: str):
        self.backend.add_transaction(user_id, amount, category, date)

    def set_savings_goal(self, user_id: int, goal_name: str, target_amount: float, deadline: str):
        self.backend.add_savings_goal(user_id, goal_name, target_amount, deadline)

    def display_expense_chart(self, user_id: int):
        transactions = self.backend.get_user_data(user_id)["transactions"]
        print("Expense Chart (Category-wise):")
        category_totals = {}

        for t in transactions:
            category = t["category"]
            amount = t["amount"]
            if category not in category_totals:
                category_totals[category] = 0
            category_totals[category] += amount

        for category, total in category_totals.items():
            # Simple bar chart using ASCII
            bar = "#" * int(total / 100)
            print(f"{category}: {total:.2f} -> {bar}")


# --------------------------
# Financial Advisor Module (Data Analyst + Advisor Collaboration)
# --------------------------
class FinancialAdvisor:
    def __init__(self, backend: Backend):
        self.backend = backend

    def analyze_expenses(self, user_id: int):
        data = self.backend.get_user_data(user_id)
        transactions = data["transactions"]
        savings_goals = data["savings_goals"]

        total_spent = sum(t["amount"] for t in transactions)
        average_spent = total_spent / len(transactions) if transactions else 0

        savings_progress = []
        for goal in savings_goals:
            progress = total_spent / goal["target_amount"] if goal["target_amount"] > 0 else 0
            savings_progress.append({
                "goal": goal["goal_name"],
                "progress": progress
            })

        return {
            "total_spent": total_spent,
            "average_spent": average_spent,
            "savings_progress": savings_progress
        }

    def provide_advice(self, user_id: int):
        analysis = self.analyze_expenses(user_id)
        advice = []

        if analysis["total_spent"] > 0:
            advice.append("You are spending a significant amount on average.")
        if analysis["savings_progress"]:
            advice.append("Consider increasing your savings to meet your goals faster.")

        return advice


# --------------------------
# Main Execution and Demo
# --------------------------
def main():
    db = Database()
    backend = Backend(db)
    frontend = Frontend(backend)
    advisor = FinancialAdvisor(backend)

    # Demo user
    frontend.register_user(1, "Alice Johnson", "alice@example.com")

    # Add some sample transactions
    frontend.track_expense(1, 50.0, "Grocery", "2025-04-01")
    frontend.track_expense(1, 200.0, "Transport", "2025-04-02")
    frontend.track_expense(1, 150.0, "Entertainment", "2025-04-03")

    # Set a savings goal
