    frontend.display_expense_chart(1)

    # Advisor analysis
    analysis = advisor.analyze_expenses(1)
    print("\nFinancial Analysis:", json.dumps(analysis, indent=2))
    print("\nFinancial Advice:")
    for advice in advisor.provide_advice(1):
