        self.score = 0  # Player score
        self.shield = 0  # Temporary damage protection
        self.movement_speed = 1.0  # Base movement speed
        self.attack_speed = 1.0  # Base attack speed

    def update(self, delta_time: float):
        # Update robot's state (movement, animation, etc.)
        if self.health <= 0:
            return

        # Update position based on velocity
        new_position = (
            self.position[0] + self.velocity[0] * delta_time,
            self.position[1] + self.velocity[1] * delta_time
        )
        self.position = new_position

        # Update status effects
        for effect in list(self.status_effects.keys()):
            self.status_effects[effect] -= delta_time
            if self.status_effects[effect] <= 0:
                del self.status_effects[effect]

        # Check health status
        if self.health <= 20:
            self.health_status = HealthStatus.CRITICAL
        elif self.health <= 50:
            self.health_status = HealthStatus.LOW
        else:
            self.health_status = HealthStatus.FULL

    def take_damage(self, damage: float):
