# Class representing an ability
class Ability:
    def __init__(self, name: str, cooldown: float, description: str):
        self.name = name
        self.cooldown = cooldown
        self.last_used = 0.0
        self.description = description

    def is_ready(self, current_time: float):
        # Check if ability is ready to use
        return (current_time - self.last_used) >= self.cooldown

    def use(self, owner: Robot, target: Optional[Entity] = None):
        # Use the ability
        if not isinstance(owner, Robot):
            raise ValueError("Ability must be used by a Robot")

        current_time = time.time()
        if not self.is_ready(current_time):
            print(f"Ability '{self.name}' is on cooldown")
            return

        # Implement ability-specific effects
        if self.name == "Healing Pulse":
            if isinstance(owner, Robot):
                owner.heal(20)
                owner.add_score(5)
        elif self.name == "Shield Wave":
            if isinstance(owner, Robot):
                owner.shield += 25
                owner.add_score(3)
        elif self.name == "EMP Blast":
            if target and isinstance(target, Robot):
                target.shield = 0
                target.add_status_effect("Disoriented", 3.0)
                owner.add_score(7)
        elif self.name == "Teleport":
