# Class representing a control point objective
class ControlPoint(Objective):
    def __init__(self, name: str, position: Tuple[float, float], capture_time: float = 10.0):
        super().__init__(name, position, ObjectiveType.CONTROL_POINT)
        self.capture_time = capture_time
        self.capture_progress = 0.0  # Progress towards capture (0-1)

    def update(self, delta_time: float):
        # Check for nearby robots trying to capture
        for robot in self.arena.get_entities():
            if isinstance(robot, Robot) and robot.team != self.owner_team and robot.role == Role.ATTACKER:
                distance = robot.distance_to(self)
                if distance <= 3.0:
                    self.capture_progress += delta_time / self.capture_time
                    if self.capture_progress >= 1.0:
                        self.capture_progress = 1.0
                        self.owner_team = robot.team
                        self.arena.add_event(f"Control Point '{self.name}' captured by {robot.team}")
                        self.arena.broadcast_sound("capture_complete")
                        break

        # Reset if no one is near
        if self.capture_progress < 0.01 and self.owner_team is not None:
            self.capture_progress = 0.0
            self.owner_team = None

    def on_complete(self):
        # Called when objective is completed
        if self.owner_team:
            # Reward team for capturing control point
            for robot in self.arena.get_entities():
                if isinstance(robot, Robot) and robot.team == self.owner_team:
                    robot.add_score(50)
                    robot.update_experience(50)

