import random
import time
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import List, Dict, Tuple, Optional, Any

# -----------------------------
# Base Classes for CyberArena
# -----------------------------
@dataclass
class Position:
    x: float
    y: float
    z: float = 0.0  # Optional for 3D environments

class Robot(ABC):
    def __init__(self, name: str, team: str, position: Position):
        self.name = name
        self.team = team
        self.position = position
        self.health = 100
        self.weapon = None
        self.is_alive = True
        self.score = 0
        self.role = "default"  # e.g., "offense", "defense", "support"
        self.memory = {}  # For storing learned strategies

    def set_weapon(self, weapon: "Weapon"):
        self.weapon = weapon

    def take_damage(self, amount: float):
        self.health -= amount
        if self.health <= 0:
            self.is_alive = False
            self.die()

    def die(self):
        # Trigger any death-related effects
        print(f"{self.name} (Team: {self.team}) has been destroyed.")

    def update(self, arena: "Arena"):
        if self.is_alive:
            self.decide_action(arena)

    @abstractmethod
    def decide_action(self, arena: "Arena"):
        pass  # Each robot type must implement its own behavior

class Player(Robot):
    def __init__(self, name: str, team: str, position: Position, controls: Dict):
        super().__init__(name, team, position)
        self.controls = controls  # Mapping of key/actions or input mappings

    def decide_action(self, arena: "Arena"):
        # Implement player-controlled actions based on input
        pass  # Placeholder for actual control handling

class Enemy(Robot):
    def __init__(self, name: str, team: str, position: Position, difficulty: str):
        super().__init__(name, team, position)
        self.difficulty = difficulty  # e.g., "easy", "medium", "hard"
        self.learning_rate = 0.1  # Rate at which it learns from past actions

    def decide_action(self, arena: "Arena"):
        # Basic AI decision logic for enemies
        target = self.get_target(arena)
        if target:
            if self.position.distance_to(target.position) <= self.weapon.range:
                self.attack(target)
            else:
                self.move_towards(target.position)
        else:
            self.patrol(arena)

    def get_target(self, arena: "Arena"):
        # Select a target based on proximity and team
        for robot in arena.robots:
            if robot.team != self.team and robot.is_alive:
                return robot
        return None

    def attack(self, target: "Robot"):
        damage = self.weapon.use()
        target.take_damage(damage)
        print(f"{self.name} attacks {target.name} for {damage} damage!")

    def move_towards(self, target_position: Position):
        # Basic movement logic
        pass  # Placeholder for actual movement mechanics

    def patrol(self, arena: "Arena"):
        # Patrol logic for enemy when no target is available
        pass

class Weapon:
    def __init__(self, name: str, damage: float, range: float, type: str):
        self.name = name
        self.damage = damage
        self.range = range
        self.type = type  # e.g., "ranged", "melee"

    def use(self) -> float:
        # Apply weapon effects
        return self.damage

class PowerUp:
    def __init__(self, name: str, position: Position, effect: Dict):
        self.name = name
        self.position = position
        self.effect = effect  # e.g., {"health": 20, "speed": 1.5}

    def apply(self, robot: "Robot"):
        # Apply the power-up effect to the robot
        for key, value in self.effect.items():
            if hasattr(robot, key):
                setattr(robot, key, value)

class Objective(ABC):
    def __init__(self, name: str, position: Position):
        self.name = name
        self.position = position
        self.completed = False

    @abstractmethod
    def check_completion(self, arena: "Arena"):
        pass  # Each objective type must define its completion logic

class CaptureFlagObjective(Objective):
    def __init__(self, name: str, position: Position, flag_position: Position):
        super().__init__(name, position)
        self.flag_position = flag_position

    def check_completion(self, arena: "Arena"):
        for robot in arena.robots:
            if robot.position == self.flag_position and robot.team == self.team:
                self.completed = True
                print(f"Team {robot.team} has captured the flag!")

# -----------------------------
# Arena Class
# -----------------------------
class Arena:
    def __init__(self):
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards = []  # List of environmental hazards
        self.difficulty_manager = AdaptiveDifficultyManager()
        self.scoreboard = ScoreBoard()

    def add_robot(self, robot: Robot):
        self.robots.append(robot)

    def add_objective(self, objective: Objective):
        self.objectives.append(objective)

    def add_power_up(self, power_up: PowerUp):
        self.power_ups.append(power_up)

    def update(self):
        # Update all robots, check objectives, and manage difficulty
        for robot in self.robots:
            if robot.is_alive:
                robot.update(self)

        for objective in self.objectives:
            if not objective.completed:
                objective.check_completion(self)

        self.difficulty_manager.update(self)

        self.scoreboard.update_scores(self)

    def find_nearest_power_up(self, position: Position) -> Optional[PowerUp]:
        # Find the nearest power-up to the given position
        if not self.power_ups:
            return None
        return min(self.power_ups, key=lambda pu: position.distance_to(pu.position))

# -----------------------------
# Difficulty and Scoring Systems
# -----------------------------
class AdaptiveDifficultyManager:
    def __init__(self):
        self.difficulty_level = "medium"
        self.difficulty_range = {
            "easy": {"enemy_health": 80, "enemy_damage": 10},
            "medium": {"enemy_health": 100, "enemy_damage": 20},
            "hard": {"enemy_health": 120, "enemy_damage": 30}
        }

    def update(self, arena: "Arena"):
        # Adjust difficulty based on team performance
        total_health = sum(robot.health for robot in arena.robots if robot.is_alive)
        if total_health < 500:
            self.difficulty_level = "easy"
        elif total_health > 800:
            self.difficulty_level = "hard"
        else:
            self.difficulty_level = "medium"

        # Apply difficulty settings to enemies
        for robot in arena.robots:
            if isinstance(robot, Enemy):
                robot.health = self.difficulty_range[self.difficulty_level]["enemy_health"]
                if robot.weapon:
                    robot.weapon.damage = self.difficulty_range[self.difficulty_level]["enemy_damage"]

class ScoreBoard:
    def __init__(self):
        self.scores: Dict[str, int] = {}

    def update_scores(self, arena: "Arena"):
        # Assign scores based on objectives and performance
        for objective in arena.objectives:
            if objective.completed:
                for robot in arena.robots:
                    if robot.team == objective.team:
                        robot.score += 100

        for robot in arena.robots:
            if robot.is_alive:
                robot.score += 10  # Give points for surviving

    def get_rankings(self) -> List[Tuple[str, int]]:
        # Return a sorted list of teams and their scores
        team_scores = {}
        for robot in arena.robots:
            if robot.team not in team_scores:
                team_scores[robot.team] = 0
            team_scores[robot.team] += robot.score

        return sorted(team_scores.items(), key=lambda x: x[1], reverse=True)

