import React, { useState, useEffect } from 'react';
import './App.css';
import io from 'socket.io-client';

const socket = io('http://localhost:3001');

function App() {
  const [canvas, setCanvas] = useState(null);
  const [ctx, setCtx] = useState(null);
  const [color, setColor] = useState('#000000');
  const [brushSize, setBrushSize] = useState(5);
  const [isDrawing, setIsDrawing] = useState(false);

  useEffect(() => {
    const canvasEl = document.getElementById('art-canvas');
    const context = canvasEl.getContext('2d');
    setCanvas(canvasEl);
    setCtx(context);

    // Resize canvas to fit window
    canvasEl.width = window.innerWidth;
    canvasEl.height = window.innerHeight;

    // Listen for real-time drawing events from the server
    socket.on('drawing', (data) => {
      const { x, y, color, brushSize } = data;
      drawAtPosition(x, y, color, brushSize);
    });

    socket.on('clear', () => {
      context.clearRect(0, 0, canvasEl.width, canvasEl.height);
    });

    return () => {
      socket.off('drawing');
      socket.off('clear');
    };
  }, []);

  const drawAtPosition = (x, y, color, brushSize) => {
    if (!ctx) return;

    ctx.beginPath();
    ctx.arc(x, y, brushSize / 2, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();
  };

  const startDrawing = (e) => {
    setIsDrawing(true);
    draw(e.clientX, e.clientY);
  };

  const draw = (x, y) => {
    if (!isDrawing || !ctx) return;

    drawAtPosition(x, y, color, brushSize);

    // Emit event to server with drawing data
    socket.emit('drawing', { x, y, color, brushSize });
  };

  const endDrawing = () => {
    setIsDrawing(false);
  };

  const clearCanvas = () => {
    socket.emit('clear');
  };

  return (
    <div className="App">
      <h1>ArtCollab - Real-Time Digital Art Collaboration</h1>
