import React, { useState, useEffect, useRef } from 'react';
import { io } from 'socket.io-client';

const socket = io('http://localhost:5000');

const App = () => {
  const [color, setColor] = useState('#000000');
  const [brushSize, setBrushSize] = useState(5);
  const canvasRef = useRef(null);
  const [layers, setLayers] = useState([{ id: 'default', visible: true, content: '' }]);
  const [selectedLayer, setSelectedLayer] = useState(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    // Initialize canvas with the selected layer
    if (layers[selectedLayer].content) {
      const img = new Image();
      img.onload = () => {
        ctx.drawImage(img, 0, 0);
      };
      img.src = layers[selectedLayer].content;
    }

    // Handle drawing events from other users
    socket.on('draw', (data) => {
      if (canvas.style.visibility !== 'hidden') {
        const drawData = JSON.parse(data);
        drawToCanvas(drawData, ctx);
      }
    });

    // Handle layer updates from the server
    socket.on('updateLayers', (updatedLayers) => {
      setLayers(updatedLayers);
    });

    return () => {
      socket.off('draw');
      socket.off('updateLayers');
    };
  }, [layers, selectedLayer]);

  const drawToCanvas = (data, ctx) => {
    switch (data.type) {
      case 'line':
        ctx.strokeStyle = data.color;
        ctx.lineWidth = data.brushSize;
        ctx.beginPath();
        ctx.moveTo(data.startX, data.startY);
        ctx.lineTo(data.endX, data.endY);
        ctx.stroke();
        break;
      case 'rect':
        ctx.fillStyle = data.color;
        ctx.fillRect(data.x, data.y, data.width, data.height);
        break;
      case 'circle':
        ctx.fillStyle = data.color;
        ctx.beginPath();
        ctx.arc(data.x, data.y, data.radius, 0, Math.PI * 2);
        ctx.fill();
        break;
      default:
        break;
    }
  };

  const handleMouseDown = (e) => {
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const ctx = canvas.getContext('2d');

    const startX = e.clientX - rect.left;
    const startY = e.clientY - rect.top;

    const mouseMove = (e) => {
      const endX = e.clientX - rect.left;
      const endY = e.clientY - rect.top;

      drawToCanvas({
        type: 'line',
        startX: startX,
        startY: startY,
        endX: endX,
        endY: endY,
        color: color,
        brushSize: brushSize
      }, ctx);

      socket.emit('draw', JSON.stringify({
        type: 'line',
        startX: startX,
        startY: startY,
        endX: endX,
        endY: endY,
        color: color,
        brushSize: brushSize
      }));

      startX = endX;
      startY = endY;
    };

    const mouseUp = () => {
      document.removeEventListener('mousemove', mouseMove);
      document.removeEventListener('mouseup', mouseUp);

      // Convert canvas to image data and update the layer content
      const canvas = canvasRef.current;
      const imageData = canvas.toDataURL();
      const updatedLayers = [...layers];
      updatedLayers[selectedLayer] = { ...updatedLayers[selectedLayer], content: imageData };
      setLayers(updatedLayers);
      socket.emit('updateLayers', updatedLayers);
    };

    document.addEventListener('mousemove', mouseMove);
    document.addEventListener('mouseup', mouseUp);
  };

  const addLayer = () => {
    const newLayer = {
      id: Date.now(),
      visible: true,
      content: ''
    };
    setLayers([...layers, newLayer]);
    setSelectedLayer(layers.length);
  };

  const toggleLayerVisibility = (index) => {
    const updatedLayers = [...layers];
    updatedLayers[index] = { ...updatedLayers[index], visible: !updatedLayers[index].visible };
    setLayers(updatedLayers);
  };

  return (
    <div>
      <h1>ArtCollab - Collaborative Digital Art</h1>
      <div>
        <label>
          Color:
          <input type="color" value={color} onChange={(e) => setColor(e.target.value)} />
        </label>
        <label>
          Brush Size:
          <input type="range" min="1" max="50" value={brushSize} onChange={(e) => setBrushSize(parseInt(e.target.value))} />
        </label>
      </div>
      <div>
        <canvas
          ref={canvasRef}
          width="800"
          height="600"
          onMouseDown={handleMouseDown}
          style={{ border: '1px solid black', cursor: 'crosshair' }}
        >
        </canvas>
        <div>
          <button onClick={addLayer}>Add Layer</button>
          {layers.map((layer, index) => (
            <div key={layer.id}>
              <label>
                <input
                  type="checkbox"
                  checked={layer.visible}
                  onChange={() => toggleLayerVisibility(index)}
                />
                Layer {index + 1}
              </label>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

