        return ((self.x - pos.x) ** 2 + (self.y - pos.y) ** 2 + (self.z - pos.z) ** 2) ** 0.5

    def move_towards(self, target: 'Position', speed: float) -> 'Position':
        """Move position towards a target at a specified speed."""
        dx = target.x - self.x
        dy = target.y - self.y
        dz = target.z - self.z
        dist = (dx**2 + dy**2 + dz**2) ** 0.5
        if dist == 0:
            return self
        scale = min(speed, dist)
        return Position(self.x + (dx / dist) * scale,
                        self.y + (dy / dist) * scale,
                        self.z + (dz / dist) * scale)

    def __str__(self):
        return f"(x={self.x}, y={self.y}, z={self.z})"


class Weapon:
    def __init__(self, weapon_type: WeaponType, damage: int, range: float, reload_time: float):
        self.type = weapon_type
        self.damage = damage
        self.range = range
        self.reload_time = reload_time
        self.cooldown = 0.0

    def is_ready(self) -> bool:
        """Check if the weapon is ready to be fired."""
        return self.cooldown <= 0

    def use(self) -> None:
        """Use the weapon and set its cooldown."""
        if self.is_ready():
            self.cooldown = self.reload_time

    def update(self, delta_time: float) -> None:
        """Update the weapon's cooldown over time."""
        if self.cooldown > 0:
            self.cooldown -= delta_time


class PowerUp:
    def __init__(self, power_up_type: PowerUpType, duration: float):
        self.type = power_up_type
        self.duration = duration
        self.remaining_time = duration
        self.activated = False

    def is_active(self) -> bool:
        """Check if the power-up is active."""
        return self.activated and self.remaining_time > 0

    def activate(self) -> None:
        """Activate the power-up."""
        self.activated = True

    def deactivate(self) -> None:
        """Deactivate the power-up."""
        self.activated = False
        self.remaining_time = self.duration

    def update(self, delta_time: float) -> None:
        """Update the power-up's duration over time."""
        if self.is_active():
            self.remaining_time -= delta_time
            if self.remaining_time <= 0:
                self.deactivate()


class Robot:
    def __init__(self, name: str, team: Team, position: Position, health: int = 100):
        self.name = name
        self.team = team
        self.position = position
        self.health = health
        self.max_health = health
        self.speed = 2.0
        self.weapons: Dict[WeaponType, Weapon] = {
            weapon_type: Weapon(weapon_type, 10, 10.0, 1.0)
            for weapon_type in list(WeaponType)[:3]  # Only assign first three weapons for simplicity
        }
        self.selected_weapon = WeaponType.PISTOL
        self.power_ups: Dict[PowerUpType, PowerUp] = {
            power_up_type: PowerUp(power_up_type, 10.0)
            for power_up_type in list(PowerUpType)
        }
        self.is_dead = False
        self.last_action_time = 0.0
        self.role = "attacker"  # Default role
        self.experience = 0
        self.skills = {
            "shooting": 0.5,
            "movement": 0.5,
            "teamwork": 0.5
        }

    def take_damage(self, damage: int) -> None:
        """Take damage and check if the robot is dead."""
        if not self.is_dead:
            self.health -= damage
            if self.health <= 0:
                self.is_dead = True
                self.health = 0

    def heal(self, amount: int) -> None:
        """Heal the robot by a specified amount."""
        if not self.is_dead:
            self.health = min(self.max_health, self.health + amount)

    def get_weapon(self) -> Weapon:
        """Get the currently selected weapon."""
        return self.weapons[self.selected_weapon]

    def select_weapon(self, weapon_type: WeaponType) -> None:
        """Select a different weapon."""
        if weapon_type in self.weapons:
            self.selected_weapon = weapon_type

    def attack(self, target: 'Robot') -> None:
        """Attack a target robot with the selected weapon."""
        weapon = self.get_weapon()
        if not weapon.is_ready():
            return

        distance = self.position.distance_to(target.position)
        if distance <= weapon.range:
            # Calculate hit chance based on distance and skill level
            hit_chance = max(0.1, 1 - (distance / weapon.range) * (1 - weapon.type.value / WeaponType.RIFLE.value))
            if random.random() < hit_chance:
                target.take_damage(weapon.damage)
                weapon.use()
                print(f"{self.name} hit {target.name} for {weapon.damage} damage!")
            else:
                print(f"{self.name} missed {target.name}!")
        else:
            print(f"{self.name} is out of range to attack {target.name}!")

    def move(self, target_position: Position) -> None:
        """Move the robot towards a target position."""
        self.position = self.position.move_towards(target_position, self.speed)

    def use_power_up(self, power_up_type: PowerUpType) -> None:
        """Use a power-up."""
        power_up = self.power_ups.get(power_up_type)
        if power_up and not power_up.is_active():
            power_up.activate()
            print(f"{self.name} activated {power_up_type.name} power-up!")

    def update(self, delta_time: float, game: 'Game') -> None:
        """Update the robot's state and behavior."""
        current_time = time.time()
        for weapon in self.weapons.values():
            weapon.update(delta_time)
        for power_up in self.power_ups.values():
            power_up.update(delta_time)

        # Simple AI behavior: move randomly if not dead
        if not self.is_dead:
            if current_time - self.last_action_time > 5.0:  # Take action every 5 seconds
                self.last_action_time = current_time
                self.take_action(game)

    def take_action(self, game: 'Game') -> None:
        """Take a random action based on the robot's role."""
        if random.random() < 0.3:  # 30% chance to move
            self.move_to_random_position(game)
        elif random.random() < 0.5:  # 50% chance to attack
            self.attack_random_opponent(game)
        else:  # 20% chance to use power-up
            self.use_random_power_up()

    def move_to_random_position(self, game: 'Game') -> None:
        """Move to a random position within the arena."""
        new_pos = Position(
            x=random.uniform(0, game.arena_size),
            y=random.uniform(0, game.arena_size),
            z=0
        )
        self.move(new_pos)
        print(f"{self.name} is moving to {new_pos}")

    def attack_random_opponent(self, game: 'Game') -> None:
        """Attack a random opponent robot."""
        opponents = [r for r in game.robots if r.team != self.team and not r.is_dead]
        if opponents:
            target = random.choice(opponents)
            self.attack(target)

    def use_random_power_up(self) -> None:
        """Use a random power-up."""
        available_power_ups = [p for p in self.power_ups.values() if not p.is_active()]
        if available_power_ups:
            power_up = random.choice(available_power_ups)
            power_up.activate()
            print(f"{self.name} activated {power_up.type.name} power-up!")

    def gain_experience(self, amount: int) -> None:
        """Gain experience and potentially improve skills."""
        self.experience += amount
        # Simplified skill improvement based on experience
        for skill, value in self.skills.items():
            if random.random() < 0.2:  # 20% chance to improve a skill
                self.skills[skill] = min(1.0, value + 0.05)


