class AdaptiveDifficulty:
    def __init__(self, game: 'Game'):
        self.game = game
        self.last_performance_check = time.time()
        self.performance_threshold = 0.5  # 50% win rate

    def update(self, delta_time: float) -> None:
        """Update the adaptive difficulty system."""
        current_time = time.time()
        if current_time - self.last_performance_check > 60.0:  # Check performance every 60 seconds
            self.last_performance_check = current_time
            self.adjust_difficulty()

    def adjust_difficulty(self) -> None:
        """Adjust the difficulty based on robot performance."""
        total_battles = self.game.num_battles
        if total_battles == 0:
            return

        # Calculate win rate
        win_rate = self.game.num_wins / total_battles

        if win_rate > self.performance_threshold:
            self.increase_difficulty()
        else:
            self.decrease_difficulty()

    def increase_difficulty(self) -> None:
        """Increase the difficulty of the game."""
        print("Increasing game difficulty...")
        for robot in self.game.robots:
            if random.random() < 0.5:  # 50% chance to upgrade an enemy robot's stats
                robot.health += 20
                robot.speed += 0.5
                for weapon in robot.weapons.values():
                    weapon.damage += 5

    def decrease_difficulty(self) -> None:
        """Decrease the difficulty of the game."""
        print("Decreasing game difficulty...")
        for robot in self.game.robots:
            if random.random() < 0.5:  # 50% chance to downgrade an enemy robot's stats
                robot.health -= 20
                robot.speed -= 0.5
                if robot.health < 10:
                    robot.health = 10
                for weapon in robot.weapons.values():
                    weapon.damage -= 5
                    if weapon.damage < 5:
                        weapon.damage = 5


