    def __init__(self, arena_size: float = 100.0):
        self.arena_size = arena_size
        self.robots: List[Robot] = []
        self.objective_system = ObjectiveSystem(self)
        self.adaptive_difficulty = AdaptiveDifficulty(self)
        self.feedback_loop = FeedbackLoop(self)
        self.running = True
        self.start_time = time.time()
        self.num_battles = 0
        self.num_wins = 0
        self.winner_team = None

    def add_robot(self, robot: Robot) -> None:
        """Add a robot to the game."""
        self.robots.append(robot)

    def start_game(self) -> None:
        """Start the game."""
        print("CyberArena game started!")
        self.running = True
        self.start_time = time.time()

    def update(self) -> None:
        """Update the game state."""
        if not self.running:
            return

        current_time = time.time()
        delta_time = current_time - self.start_time
        self.start_time = current_time

        for robot in self.robots:
            robot.update(delta_time, self)

        self.objective_system.update(delta_time)
        self.adaptive_difficulty.update(delta_time)
        self.feedback_loop.update(delta_time)

    def end_game(self, winner_team: Team) -> None:
        """End the game and declare a winner."""
        self.running = False
        self.winner_team = winner_team
        self.num_battles += 1
        if winner_team in [Team.RED, Team.BLUE]:
            self.num_wins += 1
        print(f"Game ended! Winner: Team {winner_team.name}")
        for robot in self.robots:
            if robot.team == winner_team:
                robot.gain_experience(50)  # Reward winning robots
            else:
                robot.gain_experience(10)  # Give some experience to all robots

    def run(self, duration: float = 600.0) -> None:
        """Run the game for a specified duration in seconds."""
        self.start_game()
        end_time = time.time() + duration
        while time.time() < end_time and self.running:
            self.update()
            time.sleep(GAME_TICK_RATE)
        if self.running:
            print("Game ended by time limit!")
            self.end_game(winner_team=Team.NEUTRAL)


def create_robots(num_robots: int, arena_size: float) -> List[Robot]:
