# solution.py
# CollaborativeDesignSuite - A Multi-Agent Collaborative Graphics Design Tool

import uuid
from datetime import datetime
from typing import Dict, List, Optional, Tuple
import json
import threading

# -----------------------------
# 1. User Registration and Authentication
# -----------------------------

class User:
    def __init__(self, user_id: str, username: str, password: str):
        self.user_id = user_id
        self.username = username
        self.password = password  # In real app, store hashed passwords
        self.session_token: Optional[str] = None
        self.last_active = datetime.now()

class AuthenticationService:
    def __init__(self):
        self.users: Dict[str, User] = {}  # username -> User
        self.sessions: Dict[str, str] = {}  # session_token -> user_id

    def register_user(self, username: str, password: str) -> bool:
        if username in self.users:
            return False
        user_id = str(uuid.uuid4())
        self.users[username] = User(user_id, username, password)
        return True

    def login_user(self, username: str, password: str) -> Optional[str]:
        user = self.users.get(username)
        if user and user.password == password:
            session_token = str(uuid.uuid4())
            user.session_token = session_token
            self.sessions[session_token] = user.user_id
            return session_token
        return None

    def is_authenticated(self, session_token: str) -> bool:
        return session_token in self.sessions

# -----------------------------
# 2. Real-Time Collaboration Canvas
# -----------------------------

class DesignElement:
    def __init__(self, element_id: str, type: str, data: dict):
        self.element_id = element_id
        self.type = type
        self.data = data

class Canvas:
    def __init__(self, project_id: str, name: str):
        self.project_id = project_id
        self.name = name
        self.elements: Dict[str, DesignElement] = {}
        self.lock = threading.Lock()
        self.collaborators: Dict[str, str] = {}  # user_id -> username

    def add_element(self, element: DesignElement):
        with self.lock:
            self.elements[element.element_id] = element

    def remove_element(self, element_id: str):
        with self.lock:
            if element_id in self.elements:
                del self.elements[element_id]

    def add_collaborator(self, user_id: str, username: str):
        with self.lock:
            self.collaborators[user_id] = username

    def get_state(self) -> Dict:
        return {
            "project_id": self.project_id,
            "name": self.name,
            "elements": {k: v.__dict__ for k, v in self.elements.items()},
            "collaborators": self.collaborators
        }

# -----------------------------
# 3. Shape and Texture Tools
# -----------------------------

class ShapeTool:
    def create_shape(self, canvas: Canvas, shape_type: str, position: Tuple[float, float], size: Tuple[float, float]) -> str:
        element_id = str(uuid.uuid4())
        canvas.add_element(DesignElement(
            element_id,
            "SHAPE",
            {
                "type": shape_type,
                "position": position,
                "size": size
            }
        ))
