            elif isinstance(objective, BaseDefenseObjective):
                objective.base_health = 100
            elif isinstance(objective, PayloadEscortObjective):
                objective.payload_position = objective.start_position
                objective.payload_carrier = None

    def remove_objective(self, objective):
        """Remove a completed objective from the arena."""
        if objective in self.objectives:
            self.objectives.remove(objective)


