# LanguageCollaborator - Web application for collaborative language learning

class UserRole(Enum):
    """Represents user roles in the language learning application"""
    LEARNER = 1
    TEACHER = 2

@dataclass
class User:
    """Represents a user in the LanguageCollaborator application"""
    user_id: str
    username: str
    role: UserRole
    exercises: list = field(default_factory=list)
    reviews: dict = field(default_factory=dict)

    def create_exercise(self, exercise_type: str, content: str, correct_answer: str = None):
        """Create a new language exercise"""
        exercise_id = f"EX_{random.randint(100000, 999999)}"
        exercise = {
            'exercise_id': exercise_id,
            'type': exercise_type,
            'content': content,
            'correct_answer': correct_answer,
            'created_by': self.user_id,
            'timestamp': time.time()
        }
        self.exercises.append(exercise)
        return exercise

    def provide_feedback(self, exercise_id: str, feedback: str):
        """Provide peer feedback for an exercise"""
        if exercise_id in self.reviews:
            raise ValueError("Already provided feedback for this exercise")
        self.reviews[exercise_id] = feedback

    def get_feedback(self, exercise_id: str):
        """Get feedback given to others for an exercise"""
        if exercise_id not in self.reviews:
            return "No feedback available for this exercise"
        return self.reviews[exercise_id]

class Exercise:
    """Base class for language exercises"""
    def __init__(self, exercise_id: str, exercise_type: str, content: str, correct_answer: str = None):
        self.exercise_id = exercise_id
        self.type = exercise_type
        self.content = content
        self.correct_answer = correct_answer
        self.submissions = []

    def submit_answer(self, user_id: str, answer: str):
        """Submit an answer to this exercise"""
        submission = {
            'user_id': user_id,
            'answer': answer,
            'timestamp': time.time()
        }
        self.submissions.append(submission)
        return self.evaluate_answer(answer)

    @abstractmethod
    def evaluate_answer(self, answer: str) -> dict:
        pass

class GrammarQuiz(Exercise):
    """Represents a grammar quiz exercise"""
    def evaluate_answer(self, answer: str) -> dict:
        """Evaluate the submitted answer for a grammar quiz"""
        is_correct = answer.strip().lower() == self.correct_answer.strip().lower()
        feedback = {
            'is_correct': is_correct,
            'feedback': self.correct_answer if not is_correct else "Correct! Great job!"
        }
        return feedback

class VocabularyTest(Exercise):
    """Represents a vocabulary test exercise"""
    def evaluate_answer(self, answer: str) -> dict:
        """Evaluate the submitted answer for a vocabulary test"""
        is_correct = answer.strip().lower() == self.correct_answer.strip().lower()
        feedback = {
            'is_correct': is_correct,
            'feedback': f"The correct answer is: {self.correct_answer}" if not is_correct else "Correct! Well done!"
        }
        return feedback

class WritingPrompt(Exercise):
    """Represents a writing prompt exercise"""
    def __init__(self, exercise_id: str, content: str):
        super().__init__(exercise_id, 'writing', content)
        self.peer_feedback = []

    def evaluate_answer(self, answer: str) -> dict:
        """Provide general feedback for writing prompts (no correct answer)"""
        feedback = {
