import random
import time
from enum import Enum
from abc import ABC, abstractmethod
from dataclasses import dataclass

class Team(Enum):
    RED = 1
    BLUE = 2
    NEUTRAL = 3

class WeaponType(Enum):
    RANGED = 1
    MELEE = 2
    SUPPORT = 3

class Role(Enum):
    TANK = 1
    ATTACKER = 2
    SUPPORTER = 3
    SCOUT = 4

class StatusEffect(Enum):
    BURNING = 1
    FROZEN = 2
    STUNNED = 3
    SHIELDED = 4

class PowerUpType(Enum):
    HEALTH = 1
    DAMAGE_BOOST = 2
    SPEED_BOOST = 3
    SHIELD = 4

class ObjectiveType(Enum):
    CAPTURE_FLAG = 1
    DEFEND_BASE = 2
    ESCORT_PAYLOAD = 3
    DESTROY_OBJECTIVE = 4

@dataclass
class Position:
    x: float
    y: float
    z: float = 0.0

class Weapon(ABC):
    def __init__(self, name: str, damage: float, weapon_type: WeaponType, range: float):
        self.name = name
        self.damage = damage
        self.weapon_type = weapon_type
        self.range = range
        self.cooldown = 0.0
        self.last_used = 0.0

    @abstractmethod
    def fire(self, target_position: Position, current_time: float) -> bool:
        pass

class RangedWeapon(Weapon):
    def __init__(self, name: str, damage: float, range: float, accuracy: float):
        super().__init__(name, damage, WeaponType.RANGED, range)
        self.accuracy = accuracy  # 0.0 to 1.0

    def fire(self, target_position: Position, current_time: float) -> bool:
        if current_time - self.last_used < self.cooldown:
            return False
        # Calculate hit probability based on distance and accuracy
        hit_probability = self.accuracy * (1 - (target_position.distance(self.robot_position) / self.range))
        hit = random.random() < hit_probability
        if hit:
            self.last_used = current_time
            return True
        return False

class MeleeWeapon(Weapon):
    def __init__(self, name: str, damage: float, range: float, crit_chance: float):
