@dataclass
class Position:
    x: float
    y: float
    z: float = 0.0  # For 3D environments

    def distance_to(self, other: 'Position') -> float:
        dx = self.x - other.x
        dy = self.y - other.y
        dz = self.z - other.z
        return math.sqrt(dx*dx + dy*dy + dz*dz)

    def direction_to(self, other: 'Position') -> Tuple[float, float, float]:
        dist = self.distance_to(other)
        if dist == 0:
            return (0, 0, 0)
        return ((other.x - self.x)/dist, (other.y - self.y)/dist, (other.z - self.z)/dist)

