        self.power_ups.append(power_up)

    def add_hazard(self, hazard: Hazard):
        self.hazards.append(hazard)

    def add_objective(self, objective: Objective):
        self.objectives.append(objective)

    def update(self, delta_time: float):
        current_time = time.time()

        for robot in self.robots:
            if robot.health > 0:
                robot.update(self, delta_time)
            else:
                # Robot is dead, check if they should respawn
                if random.random() < 0.01:  # 1% chance to respawn per second
                    robot.health = robot.max_health
                    robot.position = Position(random.uniform(-50, 50), random.uniform(-50, 50))

