        for power_up in self.power_ups:
            if not power_up.active:
                continue
            for robot in self.robots:
                if robot.health > 0 and robot.position.distance_to(power_up.position) < 2.0:
                    robot.apply_status_effect(power_up.effect, power_up.duration, power_up.strength)
                    power_up.active = False
                    break

