        for hazard in self.hazards:
            if not hazard.active:
                continue
            for robot in self.robots:
                if robot.health > 0 and robot.position.distance_to(hazard.position) < hazard.radius:
                    robot.take_damage(hazard.damage)

        # Check objectives
        for objective in self.objectives:
            if objective.owner is None and objective.is_capturing(self.robots):
                objective.remaining_time = objective.capture_time
            elif objective.owner is None:
                objective.remaining_time = 0

        # Adaptive difficulty
        self.update_difficulty(delta_time)

        # Check for end conditions
        if self.is_game_over():
            self.running = False

    def update_difficulty(self, delta_time: float):
        # Check team performance
        red_score = self.scores[Team.RED]
        blue_score = self.scores[Team.BLUE]

