        if red_score > blue_score + 50:
            # Blue team is weaker, make them stronger
            for robot in self.robots:
                if robot.team == Team.BLUE:
                    robot.speed = min(3.0, robot.speed + 0.1)
                    for weapon in robot.weapons:
                        weapon.damage = min(25.0, weapon.damage + 1.0)
