            # Red team is weaker, make them stronger
            for robot in self.robots:
                if robot.team == Team.RED:
                    robot.speed = min(3.0, robot.speed + 0.1)
                    for weapon in robot.weapons:
                        weapon.damage = min(25.0, weapon.damage + 1.0)

        # Adjust based on time
        if current_time - self.start_time > 300:  # After 5 minutes
            for robot in self.robots:
                if robot.health > 0:
                    robot.max_health = max(120.0, robot.max_health * 1.1)
                    robot.health = robot.max_health

    def add_score(self, team: Team, points: int):
