            distance = math.sqrt((target.position[0] - self.position[0])**2 + (target.position[1] - self.position[1])**2)
            if distance <= weapon["range"]:
                target.health -= weapon["damage"]
                print(f"{self.name} attacks {target.name} with {weapon_name}, causing {weapon['damage']} damage!")
                self.weapon_cooldowns[weapon_name] = weapon["cooldown"]
