# Import necessary libraries
import random
import time
import threading
from abc import ABC, abstractmethod
from enum import Enum
from typing import List, Dict, Tuple, Optional, Any

# Define constants for the CyberArena
MAX_ROBOTS = 40  # Maximum number of robots in the arena
TEAM_COUNT = 2  # Number of teams
ARENA_WIDTH = 1000  # Arena dimensions
ARENA_HEIGHT = 1000
OBJECTIVE_RADIUS = 100  # Radius for objectives like flags or payloads
WEAPON_COOLDOWN = 0.5  # Time in seconds between attacks
ADAPTIVE_DIFFICULTY_INTERVAL = 30  # Interval for difficulty adjustments in seconds
POWERUP_SPAWN_TIME = 15  # Time between powerup spawns


# Define types and enums for the system
class RobotStatus(Enum):
    ACTIVE = "Active"
    INACTIVE = "Inactive"
    RECHARGING = "Recharging"
    DESTROYED = "Destroyed"


class WeaponType(Enum):
    RANGED = "Ranged"
    MELEE = "Melee"
    SUPPORT = "Support"


class ObjectiveType(Enum):
    CAPTURE_FLAG = "Capture Flag"
    DEFEND_BASE = "Defend Base"
    ESCORT_PAYLOAD = "Escort Payload"


class PowerupType(Enum):
    SPEED_BOOST = "Speed Boost"
    SHIELD = "Shield"
    DAMAGE_AMPLIFIER = "Damage Amplifier"
    SLOW_FIELD = "Slow Field"


class RobotRole(Enum):
    ATTACKER = "Attacker"
    DEFENDER = "Defender"
    SUPPORT = "Support"
    SCOUT = "Scout"


# Abstract class for all robots in the arena
class Robot(ABC):
    def __init__(self, name: str, team: int, x: float, y: float):
        self.name = name
        self.team = team  # Team identifier (0-indexed)
        self.x = x  # Position on the x-axis
        self.y = y  # Position on the y-axis
        self.health = 100  # Health points
        self.status = RobotStatus.ACTIVE
        self.weapon = None  # Current weapon
        self.role = RobotRole.ATTACKER  # Default role
        self.speed = 10  # Movement speed
        self.powerup_effect = None  # Current powerup effect
        self.attack_cooldown = 0  # Time until next attack
        self.objective = None  # Current objective
        self.team_robots = []  # List of robots in the same team

    @abstractmethod
    def select_action(self, arena: 'CyberArena') -> None:
        """Abstract method for robots to select their next action."""
        pass

    def move_to(self, x: float, y: float) -> None:
        """Move the robot towards the target coordinates."""
        self.x = x
        self.y = y

    def attack(self, target: 'Robot', arena: 'CyberArena') -> None:
        """Attack a target robot if within range and not on cooldown."""
        if self.attack_cooldown <= 0 and self.weapon is not None:
            if self.weapon.weapon_type == WeaponType.RANGED:
                # Check if in range for ranged attack
                if self.distance_to(target) <= self.weapon.range:
                    damage = self.weapon.damage + self.get_powerup_effect(
                        PowerupType.DAMAGE_AMPLIFIER, 0
                    )
                    target.take_damage(damage)
                    self.attack_cooldown = WEAPON_COOLDOWN
                    print(f"{self.name} attacked {target.name} for {damage} damage.")
            elif self.weapon.weapon_type == WeaponType.MELEE:
                # Check if in range for melee attack (closer range)
                if self.distance_to(target) <= 50:
                    damage = self.weapon.damage + self.get_powerup_effect(
                        PowerupType.DAMAGE_AMPLIFIER, 0
                    )
                    target.take_damage(damage)
                    self.attack_cooldown = WEAPON_COOLDOWN
                    print(f"{self.name} attacked {target.name} for {damage} damage.")
            elif self.weapon.weapon_type == WeaponType.SUPPORT:
                # Support weapon provides healing to self or allies
                if self.team == target.team:
                    heal_amount = self.weapon.heal_amount + self.get_powerup_effect(
                        PowerupType.SPEED_BOOST, 0
                    )
                    target.heal(heal_amount)
                    self.attack_cooldown = WEAPON_COOLDOWN
                    print(
                        f"{self.name} healed {target.name} for {heal_amount} health."
                    )

    def take_damage(self, damage: int) -> None:
        """Reduce robot's health when attacked."""
        self.health -= damage
        if self.health <= 0:
            self.status = RobotStatus.DESTROYED
            print(f"{self.name} was destroyed!")

    def heal(self, amount: int) -> None:
        """Increase robot's health if not at max."""
        self.health = min(100, self.health + amount)

    def distance_to(self, other: 'Robot') -> float:
        """Calculate the distance between this robot and another."""
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5

    def get_powerup_effect(self, powerup_type: PowerupType, default_effect: int) -> int:
        """Return the current powerup effect value for a specific type."""
        if self.powerup_effect and self.powerup_effect["type"] == powerup_type:
            return self.powerup_effect["value"]
        return default_effect


# Abstract class for weapons
class Weapon(ABC):
    def __init__(self, name: str, weapon_type: WeaponType, damage: int = 0):
        self.name = name
        self.weapon_type = weapon_type
        self.damage = damage
        if weapon_type == WeaponType.SUPPORT:
            self.heal_amount = 20  # Default healing for support weapons
        else:
            self.range = 200  # Default range for ranged weapons


# Concrete weapon implementations
class PlasmaRifle(Weapon):
