# Concrete robot implementations with different roles and behaviors
class AttackerRobot(Robot):
    def __init__(self, name: str, team: int, x: float, y: float):
        super().__init__(name, team, x, y)
        self.weapon = PlasmaRifle()
        self.role = RobotRole.ATTACKER

    def select_action(self, arena: 'CyberArena') -> None:
        if self.status != RobotStatus.ACTIVE:
            return

        # Apply attack cooldown
        if self.attack_cooldown > 0:
            self.attack_cooldown -= 0.1

        # Attack closest enemy robot
        closest_enemy = self.find_closest_enemy(arena)
        if closest_enemy and self.distance_to(closest_enemy) <= self.weapon.range:
            self.attack(closest_enemy, arena)
        else:
            # Move towards the nearest enemy or objective
            target = self.find_closest_target(arena)
            if target:
                self.move_towards(target)
            elif self.objective:
                self.move_towards_objective(arena)

    def find_closest_enemy(self, arena: 'CyberArena') -> Optional['Robot']:
        """Find the closest enemy robot to this robot."""
        enemies = [r for r in arena.robots if r.team != self.team and r.status == RobotStatus.ACTIVE]
        if not enemies:
            return None
        return min(enemies, key=lambda r: self.distance_to(r))

    def find_closest_target(self, arena: 'CyberArena') -> Optional['Robot']:
        """Find the closest robot to this robot (friend or foe)."""
        all_robots = [r for r in arena.robots if r.status == RobotStatus.ACTIVE]
        if not all_robots:
            return None
        return min(all_robots, key=lambda r: self.distance_to(r))

    def move_towards(self, target: 'Robot') -> None:
        """Move the robot towards the target."""
        dx = target.x - self.x
        dy = target.y - self.y
        distance = (dx ** 2 + dy ** 2) ** 0.5
