# Define constants for the LanguageSkillEnhancer
SUPPORTED_LANGUAGES = ['English', 'Spanish', 'French', 'German', 'Chinese', 'Japanese']
SKILL_LEVELS = ['Beginner', 'Intermediate', 'Advanced']

# Enums and base classes
class Language(Enum):
    ENGLISH = 'English'
    SPANISH = 'Spanish'
    FRENCH = 'French'
    GERMAN = 'German'
    CHINESE = 'Chinese'
    JAPANESE = 'Japanese'

class SkillLevel(Enum):
    BEGINNER = 'Beginner'
    INTERMEDIATE = 'Intermediate'
    ADVANCED = 'Advanced'

class ModuleType(Enum):
    VOCABULARY = 'Vocabulary'
    GRAMMAR = 'Grammar'
    COMPREHENSION = 'Comprehension'

class User:
    def __init__(self, name: str, target_language: Language, skill_level: SkillLevel):
        self.name = name
        self.target_language = target_language
        self.skill_level = skill_level
        self.progress = ProgressTracker()

    def update_progress(self, module_type: ModuleType, score: int):
        self.progress.record_score(module_type, score)

class ProgressTracker:
    def __init__(self):
        self.scores = {}  # ModuleType -> List[score]

    def record_score(self, module_type: ModuleType, score: int):
        if module_type not in self.scores:
            self.scores[module_type] = []
        self.scores[module_type].append(score)

    def get_average_score(self, module_type: ModuleType) -> Optional[float]:
        if module_type in self.scores and len(self.scores[module_type]) > 0:
            return sum(self.scores[module_type]) / len(self.scores[module_type])
        return None

class Exercise(ABC):
    @abstractmethod
    def get_question(self) -> str:
        pass

    @abstractmethod
    def get_correct_answer(self) -> str:
        pass

    @abstractmethod
    def check_answer(self, user_answer: str) -> bool:
        pass

class FlashcardExercise(Exercise):
    def __init__(self, word: str, translation: str):
        self.word = word
        self.translation = translation

    def get_question(self) -> str:
        return f"What is the translation of '{self.word}'?"

    def get_correct_answer(self) -> str:
        return self.translation

    def check_answer(self, user_answer: str) -> bool:
        return user_answer.lower() == self.translation.lower()

class MCQExercise(Exercise):
    def __init__(self, question: str, options: List[str], correct_answer: str):
        self.question = question
        self.options = options
        self.correct_answer = correct_answer

    def get_question(self) -> str:
        options_str = '\n'.join([f"{i+1}. {opt}" for i, opt in enumerate(self.options)])
        return f"{self.question}\n{options_str}"

    def get_correct_answer(self) -> str:
        return self.correct_answer

    def check_answer(self, user_answer: str) -> bool:
        return user_answer.lower() == self.correct_answer.lower()

class FillInTheBlankExercise(Exercise):
    def __init__(self, sentence: str, blank_index: int, correct_word: str):
        self.sentence = sentence
        self.blank_index = blank_index
        self.correct_word = correct_word

    def get_question(self) -> str:
        words = self.sentence.split()
        words[self.blank_index] = "____"
        return " ".join(words)

    def get_correct_answer(self) -> str:
        return self.correct_word

    def check_answer(self, user_answer: str) -> bool:
        return user_answer.lower() == self.correct_word.lower()

