# ProjectSynergy - A Management Game for Simulating Software Development Projects

import random
from collections import defaultdict

class Task:
    def __init__(self, task_id, name, duration, dependencies=None):
        self.task_id = task_id
        self.name = name
        self.duration = duration
        self.dependencies = dependencies if dependencies else []
        self.completed = False

    def mark_complete(self):
        self.completed = True

    def is_ready_to_start(self, completed_tasks):
        return all(task in completed_tasks for task in self.dependencies)

class TeamMember:
    def __init__(self, member_id, name, skill_set, availability=True):
        self.member_id = member_id
        self.name = name
        self.skill_set = skill_set
        self.availability = availability
        self.assigned_tasks = []

    def assign_task(self, task):
        if self.availability:
            self.assigned_tasks.append(task)
            self.availability = False
            task.dependencies = [dep for dep in task.dependencies if dep not in [t.task_id for t in self.assigned_tasks]]

    def complete_task(self):
        for task in self.assigned_tasks:
            task.mark_complete()
        self.assigned_tasks = []

    def is_available(self):
        return self.availability

class Project:
    def __init__(self, name, scope, budget, timeline):
        self.name = name
        self.scope = scope
        self.budget = budget
        self.timeline = timeline
        self.tasks = []
        self.team_members = []
        self.completed_tasks = set()
        self.current_budget = budget
        self.current_time = 0

    def setup_project(self, tasks):
        self.tasks = [Task(t['id'], t['name'], t['duration'], t.get('dependencies', [])) for t in tasks]

    def add_team_member(self, member):
        self.team_members.append(member)

    def assign_tasks_to_team(self):
        for task in self.tasks:
            for member in self.team_members:
                if member.is_available() and task.is_ready_to_start(self.completed_tasks):
                    member.assign_task(task)
                    break

    def execute_tasks(self):
        for member in self.team_members:
            if not member.is_available():
                member.complete_task()
                for task in member.assigned_tasks:
                    self.completed_tasks.add(task.task_id)

    def resolve_issues(self):
        # Simulate issue resolution
        if random.random() < 0.2:  # 20% chance of issue
            issue = random.choice(['budget', 'time', 'skill_gap'])
            if issue == 'budget':
                self.current_budget -= 100
            elif issue == 'time':
                self.current_time += 1
            elif issue == 'skill_gap':
                for member in self.team_members:
                    if 'specialist' not in member.skill_set:
                        member.skill_set.append('specialist')
                        break

