import time
from enum import Enum
from typing import List, Dict, Tuple, Optional

class Direction(Enum):
    UP = (0, -1)
    DOWN = (0, 1)
    LEFT = (-1, 0)
    RIGHT = (1, 0)

    def get_delta(self):
        return self.value

class WeaponType(Enum):
    LASER = 1
    PLASMA = 2
    MELEE = 3
    SHIELD = 4

class Weapon:
    def __init__(self, weapon_type: WeaponType, damage: int, range: int, cooldown: float):
        self.type = weapon_type
        self.damage = damage
        self.range = range
        self.cooldown = cooldown
        self.last_used = 0.0  # Time when the weapon was last used

    def can_use(self, current_time: float) -> bool:
        return current_time - self.last_used >= self.cooldown

    def use(self, current_time: float):
        self.last_used = current_time

class Robot:
    def __init__(self, name: str, team: str, x: int, y: int):
        self.name = name
        self.team = team
        self.x = x
        self.y = y
        self.health = 100
        self.speed = 2
        self.weapons = []
        self.role = "Soldier"
        self.experience = 0
        self.score = 0
        self.last_position_update = 0.0

    def add_weapon(self, weapon: Weapon):
        self.weapons.append(weapon)

    def move(self, direction: Direction, time_elapsed: float):
        dx, dy = direction.get_delta()
        self.x += dx * self.speed * time_elapsed
        self.y += dy * self.speed * time_elapsed
        self.last_position_update = time.time()

    def attack(self, target: 'Robot', current_time: float) -> bool:
        # Try to use the best available weapon against the target
        for weapon in self.weapons:
            if weapon.can_use(current_time) and self._is_in_attack_range(target):
                weapon.use(current_time)
                target.health -= weapon.damage
                return True
        return False

    def _is_in_attack_range(self, target: 'Robot') -> bool:
        # Check if target is within attack range of any weapon
        distance = math.sqrt((self.x - target.x)**2 + (self.y - target.y)**2)
        return any(weapon.range >= distance for weapon in self.weapons)

    def update_role(self, new_role: str):
        self.role = new_role

    def learn_from_battle(self, battle_results: Dict):
        # Update robot's experience and adapt its strategy
        self.experience += int(battle_results.get('effectiveness', 0) * 10)
        if self.experience > 1000:
            self.update_role("Commander")
        elif self.experience > 500:
            self.update_role("Scout")

