    def update_difficulty(self):
        # Calculate team performance
        team_performance = {}
        for team in self.teams:
            alive_robots = sum(1 for r in team.members if r.is_alive())
            team_score = team.score
            performance = (alive_robots / len(team.members)) * 0.5 + (team_score / 100) * 0.5
            team_performance[team.name] = performance

        # Adjust difficulty based on average performance
        average_performance = sum(team_performance.values()) / len(team_performance)

        if average_performance < 0.4 and self.difficulty_level > 1:
            # Teams are underperforming - increase difficulty
            self.difficulty_level -= 1
            self._increase_difficulty()
        elif average_performance > 0.7 and self.difficulty_level < self.max_difficulty:
            # Teams are overperforming - decrease difficulty
            self.difficulty_level += 1
            self._decrease_difficulty()

    def _increase_difficulty(self):
        # Add more enemies or make them stronger
        for team in self.teams:
            for robot in team.members:
                if robot.is_alive():
                    robot.movement_speed += 0.2
                    robot.weapon.attack_speed += 0.5

        # Add more obstacles
        if len(self.arena.obstacles) < 5:
