                self.arena.add_obstacle(Obstacle(obstacle_position, size=1.0, damage_per_second=2))

    def _decrease_difficulty(self):
        # Make enemies weaker
        for team in self.teams:
            for robot in team.members:
                if robot.is_alive():
                    robot.movement_speed = max(1.0, robot.movement_speed - 0.2)
                    if robot.weapon.attack_speed > 1.0:
