class Robot:
    def __init__(self, robot_id, team, position, weapon):
        self.id = robot_id
        self.team = team
        self.position = position
        self.target = position
        self.health = 100
        self.max_health = 100
        self.shield = 0
        self.movement_speed = 2
        self.max_speed = 2
        self.weapon = weapon
        self.alive = True
        self.last_attack_time = 0
        self.memory = {}  # for strategy learning
        self.experience = 0

    def move_towards(self, target, speed, delta_time):
        if not self.alive:
            return
        direction = (target - self.position).normalize()
        movement = direction * speed * delta_time
        self.position = self.position + movement

    def take_damage(self, amount):
        if not self.alive:
            return
        if self.shield > 0:
            if self.shield >= amount:
                self.shield -= amount
            else:
                remaining_damage = amount - self.shield
                self.shield = 0
                self.health -= remaining_damage
        else:
            self.health -= amount

        if self.health <= 0:
            self.alive = False

    def is_alive(self):
        return self.alive

    def update(self, delta_time):
        if not self.alive:
            return

        # Update position based on target
        if self.position != self.target:
            distance = (self.target - self.position).magnitude()
            if distance > 0.1:
                self.move_towards(self.target, self.movement_speed, delta_time)
            else:
                self.position = self.target

        # Update weapon state
        current_time = time.time()
        if current_time - self.last_attack_time >= 1 / self.weapon.attack_speed:
            self.last_attack_time = current_time

    def attack(self, target, current_time):
        if self.weapon.can_attack(current_time):
            return self.weapon.attack(current_time)
        return 0

    def learn_strategy(self, situation, action, outcome):
        # Store experience for strategy adaptation
        self.memory[situation] = {"action": action, "outcome": outcome}
        self.experience += 1

    def get_strategy(self, situation):
        # Retrieve best strategy for a given situation
        if situation in self.memory:
            return self.memory[situation]["action"]
        return None

    def apply_power_up(self, power_up):
        power_up.apply_effect(self)

    def collect_health_pack(self, health_pack):
        health_pack.collect(self)


class CombatSystem:
    def __init__(self):
