    def register_enemy(self, robot, enemy):
        if robot.id not in self.enemies:
            self.enemies[robot.id] = []
        if enemy not in self.enemies[robot.id]:
            self.enemies[robot.id].append(enemy)

    def update_combat(self, robots, delta_time):
        for robot in robots:
            if not robot.is_alive():
                continue

            # Find nearest enemy
            nearest_enemy = None
            min_distance = float('inf')
            current_time = time.time()

            for enemy in self.enemies.get(robot.id, []):
                if not enemy.is_alive():
                    continue
                distance = robot.position.distance(enemy.position)
                if (distance < min_distance and 
                    robot.weapon.is_ranged or 
                    distance < robot.weapon.range):
                    min_distance = distance
                    nearest_enemy = enemy

            if nearest_enemy:
                # Move towards enemy if within range
                if robot.weapon.is_ranged:
                    if min_distance > robot.weapon.range:
                        robot.target = nearest_enemy.position
                    else:
                        # Attack
                        damage = robot.attack(nearest_enemy, current_time)
                        nearest_enemy.take_damage(damage)
                else:
                    # Melee - move towards enemy
                    robot.target = nearest_enemy.position

    def check_collisions(self, robots, obstacles):
        for robot in robots:
            if not robot.is_alive():
                continue

            for obstacle in obstacles:
                if obstacle.is_active() and robot.position.distance(obstacle.position) < obstacle.size:
                    robot.take_damage(obstacle.damage_per_second)


