            self._defend()
        elif action == CombatAction.RETREAT:
            self._retreat()
        elif action == CombatAction.CHARGE:
            self._charge(target)

    def _attack(self, target):
        """Use the current weapon to attack the target."""
        current_weapon = self.weapons[self.current_weapon_index]
        if current_weapon.is_ready():
            if self._can_attack(target):
                if current_weapon.weapon_type == WeaponType.RANGED:
                    damage = self.base_damage * 0.8
                else:
