                print(f"{self.name} attacked {target.name} for {damage} damage.")
                target.take_damage(damage)
                current_weapon.cooldown = current_weapon.reload_time
            else:
                print(f"{self.name} cannot attack {target.name}: out of range.")
        else:
            print(f"{self.name} needs to reload {current_weapon.name} before attacking.")

    def _can_attack(self, target):
        """Check if the robot is in range and not reloading."""
        current_weapon = self.weapons[self.current_weapon_index]
        distance = ((self.position[0] - target.position[0]) ** 2 + (self.position[1] - target.position[1]) ** 2) ** 0.5
        return distance <= current_weapon.range

