        self.radius = radius
        self.active = True

class Weapon:
    def __init__(self, weapon_type: WeaponType, damage: float, range: float, reload_time: float):
        self.weapon_type = weapon_type
        self.damage = damage
        self.range = range
        self.reload_time = reload_time
        self.current_reload = 0.0

    def fire(self):
        if self.current_reload > 0:
            return False  # Weapon not ready
        self.current_reload = self.reload_time
        return True

    def update_reload(self, delta_time: float):
        self.current_reload = max(0.0, self.current_reload - delta_time)

    def can_fire(self) -> bool:
        return self.current_reload <= 0

class Robot:
