            "symptoms": symptoms
        })

    def track_progress(self, progress: Dict[str, Any]):
        self.progress.update(progress)

    def get_feedback(self) -> List[Dict]:
        return self.feedback

class MedicalAgent:
    def __init__(self, role: AgentRole):
