class Team:
    """Base class for teams in CyberArena"""
    def __init__(self, team_id: Team, objective_type: ObjectiveType):
        self.team_id = team_id
        self.robots: List[Robot] = []
        self.objective_type = objective_type
        self.objectives: List[Objective] = []
        self.score = 0
        self.adaptation_level = 0.5  # AI adaptation level (0-1)
        self.difficulty = "medium"  # AI difficulty level
        self.performance_history = []

    def add_robot(self, robot: Robot) -> None:
        """Add a robot to the team"""
        self.robots.append(robot)
        robot.team = self.team_id

    def remove_robot(self, robot: Robot) -> None:
        """Remove a robot from the team"""
        self.robots.remove(robot)

    def get_next_objective(self) -> "Objective":
        """Get the next objective for the team"""
        if self.objectives:
            return self.objectives.pop(0)
        else:
            # Generate new objective if none remaining
            return Objective(self.objective_type, 
                             Position(SCREEN_WIDTH/2 + random.uniform(-200, 200),
                                      SCREEN_HEIGHT/2 + random.uniform(-150, 150)))

    def update_ai_difficulty(self, team_performance: float) -> None:
        """Adjust AI difficulty based on team performance"""
        self.performance_history.append(team_performance)

        # Calculate difficulty adjustment
        if len(self.performance_history) > 5:
            avg_performance = sum(self.performance_history[-5:]) / 5
            if avg_performance < 0.3:  # Team is underperforming
                self.adaptation_level = min(1.0, self.adaptation_level + 0.1)
                self.difficulty = "hard"
            elif avg_performance > 0.7:  # Team is overperforming
                self.adaptation_level = max(0.0, self.adaptation_level - 0.1)
                self.difficulty = "easy"
            else:
                self.difficulty = "medium"

    def calculate_team_performance(self) -> float:
        """Calculate team performance based on battle stats"""
        total_kills = sum(robot.battle_stats["kills"] for robot in self.robots)
        total_deaths = sum(robot.battle_stats["deaths"] for robot in self.robots)
        total_assists = sum(robot.battle_stats["assists"] for robot in self.robots)

        if total_deaths == 0:
            kd_ratio = float('inf')
        else:
            kd_ratio = total_kills / total_deaths

        performance = 0.5 * kd_ratio + 0.3 * (total_assists / len(self.robots)) + 0.2
        return min(1.0, performance)

    def update(self, delta_time: float) -> None:
        """Update team state each frame"""
        # Update AI difficulty based on recent performance
        performance = self.calculate_team_performance()
        self.update_ai_difficulty(performance)

        # Update all robots
        for robot in self.robots:
            robot.update(delta_time)
            robot.perform_role_actions(self)

