            speed = self.speed * self.speed_multiplier
        else:
            speed = self.speed

        if direction == Direction.UP:
            self.position.y -= speed * delta_time
        elif direction == Direction.DOWN:
            self.position.y += speed * delta_time
        elif direction == Direction.LEFT:
            self.position.x -= speed * delta_time
        elif direction == Direction.RIGHT:
            self.position.x += speed * delta_time

    def attack(self, target: "Robot", weapon: Weapon, current_time: float) -> None:
        """Attack a target with the specified weapon"""
        if not self.combat_ready:
            return

        weapon.fire(current_time)
        distance = ((self.position.x - target.position.x)**2 + 
                   (self.position.y - target.position.y)**2)**0.5

        if distance <= weapon.range:
            # Calculate hit chance based on weapon accuracy
            if random.random() < (weapon.accuracy / 100):
                damage = weapon.damage
                target.take_damage(damage)
                self.battle_stats["damage_dealt"] += damage
                self.battle_stats["kills"] += 1
                target.battle_stats["deaths"] += 1

    def take_damage(self, damage: float) -> None:
        """Apply damage to robot and reduce health"""
        if not self.combat_ready:
            return

        self.health -= damage
        self.battle_stats["damage_received"] += damage

        if self.health <= 0:
            self.die()

    def die(self) -> None:
        """Handle robot death"""
        self.combat_ready = False
        self.health = 0
        self.energy = 0
        self.status_effects.clear()

    def apply_status_effect(self, effect: StatusEffect, 
