        """Apply a status effect to the robot"""
        self.status_effects[effect] = {
            "intensity": intensity,
            "duration": duration,
            "time_applied": time.time()
        }

    def teleport(self) -> None:
        """Teleport robot to random position"""
        if self.combat_ready:
            self.position.x = random.uniform(0, SCREEN_WIDTH)
            self.position.y = random.uniform(0, SCREEN_HEIGHT)

    def pick_up_power_up(self, power_up: PowerUp) -> None:
        """Pick up a power-up and apply its effect"""
        power_up.apply_effect(self)
        self.inventory[power_up.power_up_type] = self.inventory.get(
            power_up.power_up_type, 0) + 1

    def update(self, delta_time: float) -> None:
        """Update robot state each frame"""
        # Update status effects
        current_time = time.time()
        expired_effects = []

        for effect, data in self.status_effects.items():
            data["duration"] -= delta_time
            if data["duration"] <= 0:
                expired_effects.append(effect)

        for effect in expired_effects:
            del self.status_effects[effect]

        # Apply effects if still active
        for effect, data in self.status_effects.items():
            if data["duration"] > 0:
                # Apply the effect (this is just a placeholder - actual effects 
