class Team:
    """Base class for teams in CyberArena"""
    def __init__(self, team_id: Team, objective_type: ObjectiveType):
        self.team_id = team_id
        self.robots: List[Robot] = []
        self.objective_type = objective_type
        self.objectives: List[Objective] = []
        self.score = 0
        self.adaptation_level = 0.5  # AI adaptation level (0-1)
        self.difficulty = "medium"  # AI difficulty level
        self.performance_history = []

    def add_robot(self, robot: Robot) -> None:
        """Add a robot to the team"""
        self.robots.append(robot)
        robot.team = self.team_id

    def remove_robot(self, robot: Robot) -> None:
        """Remove a robot from the team"""
        self.robots.remove(robot)

    def get_next_objective(self) -> "Objective":
        """Get the next objective for the team"""
        if self.objectives:
            return self.objectives.pop(0)
        else:
            # Generate new objective if none remaining
            return Objective(self.objective_type, 
                             Position(SCREEN_WIDTH/2 + random.uniform(-200, 200),
                                      SCREEN_HEIGHT/2 + random.uniform(-150, 150)))

    def update_ai_difficulty(self, team_performance: float) -> None:
        """Adjust AI difficulty based on team performance"""
        self.performance_history.append(team_performance)

        # Calculate difficulty adjustment
        if len(self.performance_history) > 5:
            avg_performance = sum(self.performance_history[-5:]) / 5
            if avg_performance < 0.3:  # Team is underperforming
                self.adaptation_level = min(1.0, self.adaptation_level + 0.1)
                self.difficulty = "hard"
            elif avg_performance > 0.7:  # Team is overperforming
                self.adaptation_level = max(0.0, self.adaptation_level - 0.1)
                self.difficulty = "easy"
            else:
                self.difficulty = "medium"

    def calculate_team_performance(self) -> float:
        """Calculate team performance based on battle stats"""
        total_kills = sum(robot.battle_stats["kills"] for robot in self.robots)
        total_deaths = sum(robot.battle_stats["deaths"] for robot in self.robots)
        total_assists = sum(robot.battle_stats["assists"] for robot in self.robots)

        if total_deaths == 0:
            kd_ratio = float('inf')
        else:
            kd_ratio = total_kills / total_deaths

        performance = 0.5 * kd_ratio + 0.3 * (total_assists / len(self.robots)) + 0.2
        return min(1.0, performance)

    def update(self, delta_time: float) -> None:
        """Update team state each frame"""
        # Update AI difficulty based on recent performance
        performance = self.calculate_team_performance()
        self.update_ai_difficulty(performance)

        # Update all robots
        for robot in self.robots:
            robot.update(delta_time)
            robot.perform_role_actions(self)

class Objective:
    """Base class for team objectives in CyberArena"""
    def __init__(self, objective_type: ObjectiveType, position: Position):
        self.objective_type = objective_type
        self.position = position
        self.is_complete = False
        self.completion_time = 0
        self.team = None  # Which team owns this objective

    def complete(self) -> None:
        """Mark objective as complete"""
        self.is_complete = True
        self.completion_time = time.time()

class CyberArena:
    """Main class for the CyberArena simulation"""
    def __init__(self, arena_width: int = SCREEN_WIDTH, 
                 arena_height: int = SCREEN_HEIGHT):
        self.arena_width = arena_width
        self.arena_height = arena_height
        self.teams: Dict[Team, Team] = {
            Team.RED: Team(Team.RED, ObjectiveType.CAPTURE_FLAG),
            Team.BLUE: Team(Team.BLUE, ObjectiveType.ESCORT_PAYLOAD)
        }
        self.robots: List[Robot] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []
        self.current_time = time.time()
        self.battle_log: List[Dict[str, Any]] = []
        self.scoreboard: Dict[Team, int] = {
            Team.RED: 0,
            Team.BLUE: 0
        }
        self.difficulty_level = "medium"  # Overall difficulty level of the arena

    def add_robot(self, robot: Robot) -> None:
        """Add a robot to the arena"""
        self.robots.append(robot)
        self.teams[robot.team].add_robot(robot)

    def remove_robot(self, robot: Robot) -> None:
        """Remove a robot from the arena"""
        self.robots.remove(robot)
        self.teams[robot.team].remove_robot(robot)

    def add_power_up(self, power_up: PowerUp) -> None:
        """Add a power-up to the arena"""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard: Hazard) -> None:
        """Add a hazard to the arena"""
        self.hazards.append(hazard)

    def update(self, delta_time: float) -> None:
        """Update the entire arena state"""
        self.current_time = time.time()

        # Update teams and their robots
        for team in self.teams.values():
            team.update(delta_time)

        # Update power-ups
        for power_up in self.power_ups:
            power_up.time_applied += delta_time

        # Update hazards
        for hazard in self.hazards:
            if not hazard.is_active(self.current_time):
                self.hazards.remove(hazard)
            else:
                # Check if any robots are in hazard area
                for robot in self.robots:
                    distance = ((robot.position.x - hazard.position.x)**2 + 
                               (robot.position.y - hazard.position.y)**2)**0.5
                    if distance < hazard.radius:
                        robot.take_damage(hazard.damage * delta_time)

        # Check for power-up pickups
        for robot in self.robots:
            for power_up in self.power_ups:
                distance = ((robot.position.x - power_up.position.x)**2 + 
                          (robot.position.y - power_up.position.y)**2)**0.5
                if distance < 20:
                    robot.pick_up_power_up(power_up)
                    self.power_ups.remove(power_up)

        # Update battle log
        self._update_battle_log()

        # Update score based on objectives
        self._update_score()

    def _update_battle_log(self) -> None:
        """Update the battle log with recent events"""
        # This would normally be filled with actual battle events
        pass

    def _update_score(self) -> None:
        """Update scores based on objectives and performance"""
        for team in self.teams.values():
            # Add points for completed objectives
            if team.objectives:
                for objective in team.objectives:
                    if objective.is_complete:
                        self.scoreboard[team.team_id] += 1000
                        team.objectives.remove(objective)

            # Add points for kills
            for robot in team.robots:
                self.scoreboard[team.team_id] += robot.battle_stats["kills"] * 50

    def get_winner(self) -> Optional[Team]:
        """Determine if there's a winner based on game conditions"""
        # Simple win condition: first team to 5000 points wins
        if self.scoreboard[Team.RED] >= 5000:
            return Team.RED
        elif self.scoreboard[Team.BLUE] >= 5000:
            return Team.BLUE
        else:
            return None

    def simulate(self, duration: float = 60.0) -> None:
        """Run the simulation for the specified duration"""
        start_time = time.time()
        last_update = start_time

        while time.time() - start_time < duration:
            current_time = time.time()
            delta_time = current_time - last_update
            last_update = current_time

            self.update(delta_time)

            # Check for winner
            winner = self.get_winner()
            if winner:
                self._announce_victory(winner)
                break

    def _announce_victory(self, winner: Team) -> None:
        """Announce the winner to the simulation"""
        print(f"Simulation Complete! Team {winner.name} Wins!")
        print(f"Final Score: Red - {self.scoreboard[Team.RED]}, Blue - {self.scoreboard[Team.BLUE]}")
        print(f"Battle Log: {self.battle_log[-5:]}")  # Show last 5 battle events

    def generate_report(self) -> None:
        """Generate a detailed report of the simulation"""
        print("CyberArena Simulation Report:")
        print("==============================")

        for team in self.teams.values():
            print(f"\nTeam {team.team_id.name}:")
            print(f"  Score: {self.scoreboard[team.team_id]}")
            print(f"  Team Difficulty: {team.difficulty}")
            print(f"  Adaptation Level: {team.adaptation_level:.2f}")

            for robot in team.robots:
                print(f"\n    Robot {robot.name}:")
                print(f"      Role: {robot.role.name}")
                print(f"      Health: {robot.health:.1f}/{robot.max_health}")
                print(f"      Energy: {robot.energy:.1f}/{robot.max_energy}")
                print(f"      Battle Stats:")
                for stat, value in robot.battle_stats.items():
                    print(f"        - {stat}: {value}")

        print(f"\nFinal Scoreboard: {self.scoreboard}")
        print(f"\nSimulation Duration: {time.time() - self.current_time:.2f} seconds")
        print(f"Winner: {self.get_winner().name if self.get_winner() else 'No winner'}")

