        elif self.weapon_type == WeaponType.PLASMA:
            damage = random.randint(15, 30)
        elif self.weapon_type == WeaponType.SHOCK_BLADE:
            damage = random.randint(20, 35)
        elif self.weapon_type == WeaponType.HEAVY_MISSILE:
            damage = random.randint(25, 40)

        armor_reduction = min(target.armor, damage // 2)
        final_damage = damage - armor_reduction
        target.health -= final_damage
        print(f"{self.name} attacks {target.name} for {final_damage} damage!")

        if target.health <= 0:
            print(f"{target.name} has been destroyed!")

    def apply_status_effect(self, effect):
        if effect not in self.status_effects:
            self.status_effects.append(effect)

    def remove_status_effect(self, effect):
        if effect in self.status_effects:
