    def __init__(self, red_robots, blue_robots, rounds=5):
        self.red_team = red_robots
        self.blue_team = blue_robots
        self.rounds = rounds

    def start_match(self):
        for round_num in range(1, self.rounds + 1):
            print(f'\n--- Round {round_num} ---')
            for robot in self.red_team:
                if robot.health <= 0:
                    continue
                target = random.choice(self.blue_team)
                if target.health <= 0:
                    continue
                robot.attack(target)
            for robot in self.blue_team:
