        if distance > 0:
            self.x += dx / distance * speed
            self.y += dy / distance * speed

    def distance_to(self, other: "Position") -> float:
        """Calculates the Euclidean distance to another position."""
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5

