class Objective:
    """Represents a team-based objective in the arena."""
    def __init__(self, objective_type: ObjectiveType, position: Position):
        self.objective_type = objective_type
        self.position = position
        self.completed = False
        self.team = None  # The team that has captured/achieved this objective

    def check_completion(self, robots: List["Robot"]) -> bool:
        """Checks if the objective has been completed."""
        if self.objective_type == ObjectiveType.CAPTURE_FLAG:
            # A robot must be within 50 units of the objective and from the opposing team
            for robot in robots:
                if robot.team != self.team and robot.position.distance_to(self.position) < 50.0:
                    self.completed = True
                    self.team = robot.team
                    print(f"Objective {self.objective_type.value} completed by team {self.team.value}!")
                    return True
        elif self.objective_type == ObjectiveType.DEFEND_BASE:
            # The base must not be destroyed for a certain period
            pass
        elif self.objective_type == ObjectiveType.ESCORT_PAYLOAD:
            # The payload must reach the destination
            pass
        elif self.objective_type == ObjectiveType.DESTROY_ENEMY_HQ:
            # The enemy HQ must be destroyed
            pass
        return self.completed

    def __str__(self):
        return f"Objective({self.objective_type.value} at {self.position}, completed={self.completed}, team={self.team.value if self.team else 'None'})"

class Robot:
    """Represents a robot in the CyberArena battle."""
    def __init__(self, name: str, team: Team, position: Position):
        self.name = name
        self.team = team
        self.position = position
        self.health = 100
        self.max_health = 100
        self.speed = 2.0
        self.shield = 0
        self.damage_multiplier = 1.0
        self.invisible = False
        self.weapon: Weapon = RangedWeapon(WeaponType.RIFLE, 20, 300.0, 1.0, 0.8)
        self.abilities: List[str] = ["Heal", "Teleport"]
        self.score = 0
        self.objective: Objective = None
        self.memory: Dict[str, float] = {}  # Learning from previous actions
        self.role: str = "Support"  # Could be "Offense", "Defense", "Support", etc.

    def take_damage(self, amount: int) -> None:
        """Handles damage taken by the robot."""
        if self.invisible:
            return  # Invisibility protects from damage
        if self.shield > 0:
            shield_damage = min(self.shield, amount)
            self.shield -= shield_damage
            amount -= shield_damage
        if amount > 0:
            self.health = max(0, self.health - amount)
            print(f"Robot {self.name} took {amount} damage. Health: {self.health}/{self.max_health}")
            if self.health <= 0:
                self.on_death()

    def on_death(self) -> None:
        """Actions to take when the robot dies."""
        print(f"Robot {self.name} has died!")
        self.health = self.max_health  # Respawn
        self.shield = 0
        self.invisible = False
        self.score -= 5  # Penalties for death
        # Reset position to team base
        if self.team == Team.RED:
            self.position = Position(100, 100)
        elif self.team == Team.BLUE:
            self.position = Position(800, 100)
        elif self.team == Team.GREEN:
            self.position = Position(100, 600)
        elif self.team == Team.YELLOW:
            self.position = Position(800, 600)

    def move(self, target: Position) -> None:
        """Moves the robot towards a target position."""
        move_speed = self.speed
        self.position.move_towards(target, move_speed)

    def attack(self, target: "Robot") -> None:
        """Attempts to attack another robot."""
        distance = self.position.distance_to(target.position)
        if distance <= self.weapon.range:
            if self.weapon.can_fire():
                damage = self.weapon.calculate_damage(distance) * self.damage_multiplier
                target.take_damage(damage)
                print(f"Robot {self.name} attacked {target.name} for {damage} damage")
                self.score += 1  # Reward for successful attack

    def use_ability(self, ability_name: str) -> None:
        """Uses a specific ability."""
        if ability_name in self.abilities:
            if ability_name == "Heal":
                self.heal()
            elif ability_name == "Teleport":
                self.teleport()

    def heal(self) -> None:
        """Heals the robot using the Heal ability."""
        heal_amount = 30
        self.health = min(self.max_health, self.health + heal_amount)
        self.score += 2  # Reward for healing
        print(f"Robot {self.name} used Heal ability. Health: {self.health}/{self.max_health}")

    def teleport(self) -> None:
        """Teleports the robot to a random position in the arena."""
        # Simple teleport to a random position in a safe zone
        safe_x = random.uniform(100, 700)
        safe_y = random.uniform(100, 500)
        self.position = Position(safe_x, safe_y)
        self.score += 3  # Reward for teleport
        print(f"Robot {self.name} used Teleport ability. New position: {self.position}")

    def update_objective(self, objective: Objective) -> None:
        """Updates the robot's current objective."""
        self.objective = objective

    def learn(self, action: str, reward: float) -> None:
        """Stores information about actions and their outcomes for future use."""
        if action in self.memory:
            self.memory[action] = (self.memory[action] + reward) / 2  # Average the reward
        else:
            self.memory[action] = reward
        # Adjust role based on performance
        if reward > 0:
            if self.role == "Support" and self.memory.get("attack", 0) > self.memory.get("heal", 0):
                self.role = "Offense"
            elif self.role == "Offense" and self.memory.get("heal", 0) > self.memory.get("attack", 0):
                self.role = "Support"

    def __str__(self):
        return f"Robot(name={self.name}, team={self.team.value}, position={self.position}, health={self.health}, score={self.score}, role={self.role})"

class TeamManager:
    """Manages team-based objectives and strategies."""
    def __init__(self, team: Team, robots: List[Robot]):
        self.team = team
        self.robots = robots
        self.objectives: List[Objective] = []
        self.strategy = "Offense"  # Could be "Offense", "Defense", "Balanced", etc.

    def assign_objectives(self, objectives: List[Objective]) -> None:
        """Assigns objectives to robots in the team."""
        self.objectives = objectives
        for i, robot in enumerate(self.robots):
            if i < len(objectives):
                robot.update_objective(objectives[i])
            else:
                robot.update_objective(None)  # No objective for this robot

    def update_team_strategy(self, game_state: Dict) -> None:
        """Updates the team's strategy based on game state and performance."""
        # Simple adaptive difficulty: if team is losing, switch to defense
        team_score = sum(robot.score for robot in self.robots)
        enemy = next(t for t in [Team.RED, Team.BLUE, Team.GREEN, Team.YELLOW] if t != self.team)
        enemy_score = sum(robot.score for robot in [r for r in all_robots if r.team == enemy])

        if team_score < enemy_score * 0.7:
            self.strategy = "Defense"
        elif team_score > enemy_score * 1.3:
            self.strategy = "Offense"
        else:
            self.strategy = "Balanced"

        print(f"Team {self.team.value} strategy updated to: {self.strategy}")
