        self.damage = damage
        self.cooldown = cooldown
        self.last_used = 0

    def can_use(self) -> bool:
        return time.time() - self.last_used >= self.cooldown

    def use(self) -> int:
        if self.can_use():
            self.last_used = time.time()
            return self.damage
        return 0

class Robot:
    def __init__(self, name: str, team: Team, health: int = 100, speed: float = 1.0):
        self.name = name
        self.team = team
        self.health = health
        self.speed = speed
        self.weapon = self._choose_weapon()
        self.status_effects: Dict[StatusEffect, float] = {}
        self.role = None  # Will be assigned by the team during objective setup
        self.experience = 0  # Experience for learning from battles

