        """Randomly assign a weapon to the robot."""
        weapons = [
            Weapon(WeaponType.LASER_GUN, 20, 2.0),
            Weapon(WeaponType.PLASMA_RIFLE, 30, 3.0),
            Weapon(WeaponType.TESLA_SWORD, 40, 1.5),
            Weapon(WeaponType.SHOCK_BOMB, 50, 4.0)
        ]
        return random.choice(weapons)

    def is_alive(self) -> bool:
        return self.health > 0

    def take_damage(self, damage: int) -> None:
        """Apply damage to the robot, considering any status effects."""
        if self.status_effects.get(StatusEffect.ENERGIZED):
            damage = int(damage * 0.5)  # Energized reduces damage by 50%
        self.health -= damage
        if self.health < 0:
            self.health = 0

    def attack(self, target: 'Robot') -> int:
        """Attack another robot with the weapon."""
        if self.weapon.can_use():
            damage = self.weapon.use()
            target.take_damage(damage)
            return damage
        return 0

    def apply_status_effect(self, effect: StatusEffect, duration: float) -> None:
        """Apply a status effect to the robot."""
        self.status_effects[effect] = time.time() + duration

    def update_status_effects(self) -> None:
        """Update and remove expired status effects."""
        now = time.time()
        for effect in list(self.status_effects.keys()):
            if now >= self.status_effects[effect]:
                del self.status_effects[effect]

    def learn_from_battle(self, outcome: str) -> None:
        """Update the robot's experience based on the battle outcome."""
        if outcome == "win":
            self.experience += 10
        elif outcome == "loss":
            self.experience += 1
        elif outcome == "draw":
            self.experience += 5
        # Adjust the robot's strategy based on accumulated experience
        if self.experience >= 50:
