        if self.is_active:
            robot.apply_status_effect(self.effect, self.duration)
            self.is_active = False

class Hazard:
    def __init__(self, position: Tuple[float, float], damage: int, radius: float):
        self.position = position
        self.damage = damage
        self.radius = radius
        self.is_active = True

    def activate(self, robot: Robot) -> None:
        """Deal damage to the robot if it enters the hazard area."""
        if self.is_active and self._is_in_hazard_area(robot.position):
            robot.take_damage(self.damage)

    def _is_in_hazard_area(self, position: Tuple[float, float]) -> bool:
        # Simple distance check to see if the robot is in the hazard's area of effect
        distance = ((position[0] - self.position[0]) ** 2 + (position[1] - self.position[1]) ** 2) ** 0.5
