@dataclass
class Position:
    x: float
    y: float
    z: float

    def distance_to(self, other: "Position") -> float:
        # Calculate Euclidean distance between two positions
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2 + (self.z - other.z)**2)


class Weapon:
    def __init__(self, name: str, weapon_type: WeaponType, damage: float, range: float = 0.0):
        self.name = name
        self.type = weapon_type
        self.base_damage = damage
        self.range = range  # For ranged weapons only

    def calculate_damage(self, distance: float, multiplier: float = 1.0) -> float:
        # Ranged weapons lose effectiveness with distance
        if self.type == WeaponType.RANGED:
            distance_factor = max(0, 1 - (distance / self.range))
            return self.base_damage * distance_factor * multiplier
        # Melee weapons have consistent damage
        return self.base_damage * multiplier


