    def __init__(self, name: str, team: Team, position: Position, health: float = 100.0):
        self.name = name
        self.team = team
        self.position = position
        self.health = health
        self.max_health = health
        self.weapon = None
        self.status_effects: Dict[StatusEffect, float] = {}  # {effect: time_remaining}
        self.role = None  # Will be set in TeamObjectiveSystem
        self.experience = 0
        self.last_battle_stats = {}

    def assign_weapon(self, weapon: Weapon):
        self.weapon = weapon

    def take_damage(self, damage: float):
        # Apply damage to health with a minimum threshold
        self.health = max(0, self.health - damage)
        if self.health == 0:
            print(f"{self.name} has been destroyed!")

    def apply_status_effect(self, effect: StatusEffect, duration: float, strength: float = 1.0):
        # Apply a temporary status effect
        if effect not in self.status_effects:
            self.status_effects[effect] = duration
        else:
            self.status_effects[effect] = max(self.status_effects[effect], duration)

    def update_status_effects(self, delta_time: float):
        # Update all active status effects
        for effect in list(self.status_effects.keys()):
            self.status_effects[effect] -= delta_time
            if self.status_effects[effect] <= 0:
                del self.status_effects[effect]

    def move_towards(self, target_position: Position, speed: float, delta_time: float):
        # Move robot towards a target position
        direction = (target_position.x - self.position.x, 
                    target_position.y - self.position.y, 
                    target_position.z - self.position.z)
        distance = math.sqrt(sum(d**2 for d in direction))

        if distance > 0:
            move_vector = (d / distance * speed * delta_time for d in direction)
            self.position = Position(
                self.position.x + next(move_vector),
                self.position.y + next(move_vector),
                self.position.z + next(move_vector)
            )

    def attack(self, target: "Robot", delta_time: float) -> float:
        # Calculate and apply damage to a target robot
        if not self.weapon:
            return 0

        distance = self.position.distance_to(target.position)

        # Check if weapon range is appropriate
        if self.weapon.type == WeaponType.RANGED and distance > self.weapon.range:
            return 0  # Out of range
        elif self.weapon.type == WeaponType.MELEE and distance > 2.0:
            return 0  # Too far for melee

        # Calculate damage based on weapon and status effects
        damage_multiplier = 1.0
        if StatusEffect.SPEED_BOOST in self.status_effects:
            damage_multiplier *= 1.2  # Speed boost increases damage
        if StatusEffect.SLOW in target.status_effects:
            damage_multiplier *= 1.3  # Slow target takes more damage

        damage = self.weapon.calculate_damage(distance, damage_multiplier)
        target.take_damage(damage)
        return damage


