        self.max_health = health
        self.weapon = None
        self.status_effects: Dict[StatusEffect, float] = {}  # {effect: time_remaining}
        self.role = None  # Will be set in TeamObjectiveSystem
        self.experience = 0
        self.last_battle_stats = {}

    def assign_weapon(self, weapon: Weapon):
