class BasicBrain(RobotBrain):
    """Simple AI brain for basic robot behavior"""
    def think(self) -> None:
        """Make decisions for basic robot behavior"""
        # Find nearby targets
        nearby_targets = [r for r in self.robot.arena.robots if 
                         r.team != self.robot.team and 
                         abs(self.robot.position - r.position) <= 10]

        # Find nearby teammates
        nearby_teammates = [r for r in self.robot.arena.robots if 
                           r.team == self.robot.team and 
                           abs(self.robot.position - r.position) <= 10]

        # Find nearby power-ups
        nearby_power_ups = [p for p in self.robot.arena.environment.power_ups if 
                           abs(self.robot.position - p.position) <= 5 and not p.is_active]

        # Decide on action
        if nearby_targets:
            self._attack(nearby_targets[0])
        elif nearby_power_ups:
            self._collect_power_up(nearby_power_ups[0])
        elif self.robot.arena.objective and not self.robot.arena.objective.is_complete:
            self._move_towards(self.robot.arena.objective.position)
        else:
            self._roam_randomly()

    def _attack(self, target: 'Robot') -> None:
        """Handle attacking another robot"""
        # Try to get into optimal attack position
        if self.robot.position < target.position:
            self.robot.move(1)  # Move right
        else:
            self.robot.move(-1)  # Move left

        # Attack if in range
        if abs(self.robot.position - target.position) <= self.robot.active_weapon.range:
            self.robot.active_weapon.fire(self.robot, target)

    def _collect_power_up(self, power_up: PowerUp) -> None:
        """Handle collecting a power-up"""
        if abs(self.robot.position - power_up.position) <= 1:
            power_up.is_active = True
            power_up.remaining_duration = power_up.duration
            self.robot.apply_power_up_effect(power_up)

        # Move towards the power-up
        if self.robot.position < power_up.position[0]:
            self.robot.move(1)
        else:
            self.robot.move(-1)

    def _move_towards(self, position: int) -> None:
        """Move towards a specific position"""
        if self.robot.position < position:
            self.robot.move(1)
        else:
            self.robot.move(-1)

    def _roam_randomly(self) -> None:
        """Random movement when no specific target"""
        if random.random() > 0.5:
            self.robot.move(1)
        else:
            self.robot.move(-1)

    def learn(self, battle_results: Dict) -> None:
        """Learn from battle outcomes"""
        # In a basic brain, this would be more sophisticated
        # For our example, we just print the results
        print(f"{self.robot.name} learned from the battle: {battle_results}")

class ObjectiveType(Enum):
    """Enum class for different objective types"""
