        """Set the arena the robot belongs to"""
        self.arena = arena

    def move(self, distance: int) -> None:
        """Move the robot by a certain distance"""
        new_position = self.position + distance
        # Keep the robot within arena boundaries
        self.position = max(0, min(new_position, self.arena.width))

    def select_weapon(self, weapon_name: str) -> None:
        """Select a weapon to use"""
        for weapon in self.weapons:
            if weapon.name == weapon_name:
                self.active_weapon = weapon
                print(f"{self.name} selected {weapon.name}")
                return
        print(f"{self.name} doesn't have a weapon named {weapon_name}!")

    def update(self) -> None:
        """Update the robot's state for one game tick"""
        # Apply power-up effects
        for power_up in self.power_ups:
            if power_up.is_active and power_up.remaining_duration > 0:
                # Apply the power-up effect
                if power_up.effect == "energy_boost":
                    self.energy = min(100, self.energy + 20)
                elif power_up.effect == "health_boost":
                    self.health = min(100, self.health + 20)
                elif power_up.effect == "shield":
                    self.shield = min(50, self.shield + 10)

        # Make a decision
        if self.brain:
            self.brain.think()

        # Apply environmental effects
        # Check for hazards at the robot's position
        for hazard in self.arena.environment.hazards:
            if hazard.position == self.position and hazard.remaining_duration > 0:
                effective_damage = hazard.damage
                if self.shield > 0:
                    # Apply shield first
                    if self.shield >= effective_damage:
                        self.shield -= effective_damage
                        effective_damage = 0
                    else:
                        effective_damage -= self.shield
                        self.shield = 0

                self.health -= effective_damage
                print(f"{self.name} took {effective_damage} damage from {hazard.effect}!")

        # Check for power-up effects at the robot's position
        for power_up in self.arena.environment.power_ups:
            if power_up.position == self.position and not power_up.is_active:
                # Robot could collect this power-up
                pass

        # Regenerate health and energy over time
        self.health = min(100, self.health + 1)
        self.energy = min(100, self.energy + 2)

        # Update the brain's knowledge of the current state
        if self.brain:
            self.brain.robot = self

    def apply_power_up_effect(self, power_up: PowerUp) -> None:
        """Apply the effect of a power-up"""
        self.power_ups.append(power_up)
        print(f"{self.name} activated {power_up.name} power-up!")

    def report_status(self) -> None:
        """Report the robot's current status"""
        print(f"{self.name} (Team {self.team.value if self.team else 'None'}):")
        print(f"  Position: {self.position}")
        print(f"  Health: {self.health}")
        print(f"  Energy: {self.energy}")
        print(f"  Shield: {self.shield}")
        print(f"  Active weapon: {self.active_weapon.name if self.active_weapon else 'None'}")
        print(f"  Power-ups: {[p.name for p in self.power_ups]}")

