        """Attack a target if the weapon is ready."""
        if self.weapon and self.weapon.can_fire(current_time):
            if self.weapon.fire(current_time, target.position):
                # Check if the attack hits the target
                if self.position.distance_to(target.position) <= self.weapon.get_range():
                    damage = self.weapon.get_damage()
