                    target.take_damage(damage)
                    return True
        return False

    def take_damage(self, damage):
        """Take damage from an attack."""
        armor = self.status_effects.get("ARMOR", 0)
        actual_damage = max(0, damage - armor)
        self.health -= actual_damage
        if self.health <= 0:
            self.die()

    def die(self):
        """Handle robot death."""
        self.is_active = False
        self.velocity = Vector2(0, 0)
        self.health = 0
        self.team.update_score(-10)  # Penalize the team for losing a robot

    def apply_status_effect(self, effect, amount, duration):
