        """Heal the robot and restore health"""
        if self.is_active:
            self.health = min(self.max_health, self.health + amount)
            return amount
        return 0

    def move_towards(self, target_position):
        """Move the robot towards a target position"""
        if self.is_active:
            dx = target_position[0] - self.position[0]
            dy = target_position[1] - self.position[1]
            distance = (dx**2 + dy**2)**0.5
            if distance > 0:
                self.position = (
                    self.position[0] + (dx/distance) * self.speed,
                    self.position[1] + (dy/distance) * self.speed
                )
            return distance
        return 0

    def attack(self, target):
        """Attack a target with a randomly selected weapon"""
        if self.is_active and target.is_active:
            if random.random() < self.accuracy:
                selected_weapon = random.choice(self.weapons)
                damage = selected_weapon.use()
                damage_dealt = target.take_damage(damage)
