            'science': ['science', 'research', 'study', 'lab', 'experiment', 'physics'],
            'entertainment': ['entertainment', 'movie', 'music', 'celebrity', 'tv', 'show']
        }
        for category in ArticleType:
            if any(keyword.lower() in self.content.lower() for keyword in keywords[category.name.lower()]):
                return category
        return ArticleType.ENTERTAINMENT

    def _summarize(self):
        # Simplified article summarizer (e.g., extract first 100 words)
