# Collaborative Workspace and Recommendation Module

class CollaborativeWorkspace:
    """\n    A module to manage collaborative sharing and discussion of news articles.\n    """
    def __init__(self):
        self.articles = []  # List of shared articles
        self.users = []     # List of active users

    def add_user(self, user):
        self.users.append(user)
        print(f"{user.username} has joined the collaborative workspace.")

    def share_article(self, user, article):
        if user.is_logged_in:
            article.share(user)
            self.articles.append(article)
            print(f"{user.username} shared article '{article.title}' in the collaborative workspace.")
        else:
            print(f"{user.username} must be logged in to share articles.")

    def get_user_feed(self, user):
        # Return articles based on user preferences and interactions
        if not user.is_logged_in:
            return []
        relevant_articles = [article for article in self.articles if any(pref in article.category.name.lower() for pref in user.preferences)]
        return sorted(relevant_articles, key=lambda x: (x.shares, len(x.comments)), reverse=True)

    def calculate_insights(self):
        # Provide analytics on popularity, sentiment, and emerging topics
        insights = {
            'popular_articles': self._get_popular_articles(),
            'emerging_topics': self._get_emerging_topics(),
            'sentiment_trend': self._get_sentiment_trend()
        }
        return insights

    def _get_popular_articles(self):
        # Sort articles by shares and comments
        return sorted(self.articles, key=lambda x: (x.shares, len(x.comments)), reverse=True)

    def _get_emerging_topics(self):
        # Count how many articles fall into each category
        topic_counts = defaultdict(int)
        for article in self.articles:
            topic_counts[article.category.name] += 1
        return dict(sorted(topic_counts.items(), key=lambda x: x[1], reverse=True))

    def _get_sentiment_trend(self):
        # Simplified sentiment analysis based on article content
        positive_keywords = ['positive', 'good', 'great', 'improving', 'success', 'increase']
        negative_keywords = ['negative', 'bad', 'worse', 'decline', 'fail', 'loss']
        neutral_keywords = ['neutral', 'stable', 'unchanged', 'current', 'same']

        sentiment_count = {'positive': 0, 'negative': 0, 'neutral': 0}
        for article in self.articles:
            content_lower = article.content.lower()
            if any(word in content_lower for word in positive_keywords):
                sentiment_count['positive'] += 1
            elif any(word in content_lower for word in negative_keywords):
                sentiment_count['negative'] += 1
            elif any(word in content_lower for word in neutral_keywords):
                sentiment_count['neutral'] += 1
            else:
                sentiment_count['neutral'] += 1
        return sentiment_count

