        position = Position(random.randint(0, SCREEN_WIDTH), random.randint(0, SCREEN_HEIGHT), Direction.RIGHT)
        duration = 10.0  # Power-up lasts 10 seconds
        powerup_stats = PowerupStats(duration, powerup_type.name, powerup_type, position)
        self.powerups.append(powerup_stats)

    def update_terrain(self):
        # Add terrain effects based on position
        for i in range(SCREEN_WIDTH):
            for j in range(SCREEN_HEIGHT):
                # Add random terrain features
                if random.random() < 0.01:
                    self.terrain[i][j] = 1.0  # Ice patch

    def get_terrain_effect(self, position: Position) -> Optional[HazardStats]:
        # Check if the position is on a special terrain
        if position.x < 0 or position.x >= SCREEN_WIDTH or position.y < 0 or position.y >= SCREEN_HEIGHT:
            return None

        terrain_value = self.terrain[int(position.x)][int(position.y)]
        if terrain_value == 1.0:  # Ice patch
            return HazardStats(1.0, "Slippery ice", HazardType.ICE_PATCH, position)
        return None

# AI Controller for robots
class RobotAI:
    def __init__(self, robot_stats: RobotStats):
        self.robot = robot_stats
        self.memory = []  # Robot's memory of past actions and results
        self.learning_rate = 0.1  # Rate at which the robot learns from experience

    def make_decision(self, game_state: Dict, environment: Environment):
        # Make a decision based on the current game state and robot's role
        if self.robot.role == RobotRole.ATTACKER:
            return self._attack_decision(game_state)
        elif self.robot.role == RobotRole.DEFENDER:
            return self._defend_decision(game_state)
        elif self.robot.role == RobotRole.SUPPORT:
            return self._support_decision(game_state)
        elif self.robot.role == RobotRole.SCOUT:
            return self._scout_decision(game_state)

    def _attack_decision(self, game_state: Dict):
        # Attack decision logic for an attacker robot
        # Find the nearest enemy
        nearest_enemy = self._find_nearest_enemy(game_state)

        if nearest_enemy:
            # Calculate direction to enemy
            direction = self._calculate_direction_to_position(nearest_enemy.position)
            if self._is_in_attack_range(nearest_enemy):
                # Attack the enemy
                return {
                    "action": "attack",
                    "target": nearest_enemy.name,
                    "direction": direction
                }
            else:
                # Move towards the enemy
                return {
                    "action": "move",
                    "direction": direction
                }
        else:
            # No enemies found, move randomly
            return {
                "action": "move",
                "direction": random.choice(list(Direction))
            }

    def _defend_decision(self, game_state: Dict):
        # Defend decision logic for a defender robot
        # Stay near the objective and attack any approaching enemies
        if self.robot.objective:
            # Check if anyone is near the objective
            for robot in game_state["robots"]:
                if (robot.team != self.robot.team and 
                    self._distance_to_position(robot.position, self.robot.objective.position) < 100):
                    # Attack the intruder
                    direction = self._calculate_direction_to_position(robot.position)
                    return {
                        "action": "attack",
                        "target": robot.name,
                        "direction": direction
                    }

            # Move to the objective if not already there
            if self._distance_to_position(self.robot.position, self.robot.objective.position) > 20:
                direction = self._calculate_direction_to_position(self.robot.objective.position)
                return {
                    "action": "move",
                    "direction": direction
                }

        # If no immediate threat, move randomly near the objective
        return {
            "action": "move",
            "direction": random.choice(list(Direction))
        }

    def _support_decision(self, game_state: Dict):
        # Support decision logic for a support robot
        # Help teammates and provide healing or buffs
        # Check for injured teammates
        for robot in game_state["robots"]:
            if robot.team == self.robot.team and robot.health < MAX_HEALTH * 0.7:
                # Heal the teammate
                direction = self._calculate_direction_to_position(robot.position)
                return {
                    "action": "use_ability",
                    "target": robot.name,
                    "ability": "heal",
                    "direction": direction
                }

        # If no injured teammates, assist attackers by providing buffs
        for robot in game_state["robots"]:
            if (robot.team == self.robot.team and 
                robot.role == RobotRole.ATTACKER and 
                robot.health > MAX_HEALTH * 0.9):
                # Buff the attacker
                direction = self._calculate_direction_to_position(robot.position)
                return {
                    "action": "use_ability",
                    "target": robot.name,
                    "ability": "buff",
                    "direction": direction
                }

        # If no specific action, move randomly
        return {
            "action": "move",
            "direction": random.choice(list(Direction))
        }

    def _scout_decision(self, game_state: Dict):
        # Scout decision logic for a scout robot
        # Gather information about the environment and enemy positions
        # Look for power-ups
        for powerup in game_state["environment"].powerups:
            if self._distance_to_position(self.robot.position, powerup.position) < 200:
                # Move to the power-up
                direction = self._calculate_direction_to_position(powerup.position)
                return {
                    "action": "move",
                    "direction": direction
                }

        # Check for enemies in the area
        for robot in game_state["robots"]:
            if robot.team != self.robot.team:
                # Gather information about the enemy
                direction = self._calculate_direction_to_position(robot.position)
                return {
                    "action": "scan",
                    "target": robot.name,
                    "direction": direction
                }

        # If no specific action, move randomly
        return {
            "action": "move",
            "direction": random.choice(list(Direction))
        }

    def _find_nearest_enemy(self, game_state: Dict) -> Optional[RobotStats]:
        # Find the nearest enemy robot
        nearest_enemy = None
        min_distance = float('inf')

        for robot in game_state["robots"]:
            if robot.team != self.robot.team:
                distance = self._distance_to_position(self.robot.position, robot.position)
                if distance < min_distance:
                    min_distance = distance
                    nearest_enemy = robot

        return nearest_enemy

    def _calculate_direction_to_position(self, target_position: Position) -> Direction:
        # Calculate the direction to a target position
        dx = target_position.x - self.robot.position.x
        dy = target_position.y - self.robot.position.y

        if abs(dx) > abs(dy):
            return Direction.RIGHT if dx > 0 else Direction.LEFT
        else:
            return Direction.DOWN if dy > 0 else Direction.UP

    def _distance_to_position(self, pos1: Position, pos2: Position) -> float:
        # Calculate the distance between two positions
        return ((pos1.x - pos2.x)**2 + (pos1.y - pos2.y)**2)**0.5

    def _is_in_attack_range(self, target: RobotStats) -> bool:
        # Check if a target is within attack range
        return self._distance_to_position(self.robot.position, target.position) <= self.robot.weapon.range

# Combat system for handling attacks
class CombatSystem:
    def __init__(self):
        self.attack_cooldowns = {}  # Track attack cooldowns for each robot

    def handle_attack(self, attacker: RobotStats, target: RobotStats, environment: Environment) -> Tuple[bool, float]:
        """
        Handle an attack from one robot to another

        Args:
            attacker: The robot making the attack
            target: The robot being attacked
            environment: The game environment

        Returns:
            A tuple (success, damage_dealt)
        """
        # Check if the attacker can attack (cooldown)
        if attacker.name in self.attack_cooldowns:
            if time.time() < self.attack_cooldowns[attacker.name]:
                return (False, 0.0)

        # Check if the target is in range
        distance = self._distance_between(attacker.position, target.position)
        if distance > attacker.weapon.range:
            return (False, 0.0)

        # Apply weapon damage
        base_damage = attacker.weapon.damage

        # Apply armor reduction
        armor_reduction = min(target.armor / (target.armor + attacker.weapon.damage), 0.7)
        effective_damage = base_damage * (1 - armor_reduction)

        # Apply environment effects
        terrain_effect = environment.get_terrain_effect(attacker.position)
        if terrain_effect and terrain_effect.hazard_type == HazardType.ELECTRIC_FIELD:
            effective_damage *= 1.2  # Electric field increases damage

        # Apply to target
        target.health -= effective_damage
        target.score += int(effective_damage)

        # Set attack cooldown
        self.attack_cooldowns[attacker.name] = time.time() + attacker.weapon.recharge_time

        return (True, effective_damage)

    def _distance_between(self, pos1: Position, pos2: Position) -> float:
        return ((pos1.x - pos2.x)**2 + (pos1.y - pos2.y)**2)**0.5

# Team-based objective system
class ObjectiveSystem:
    def __init__(self, num_teams: int):
        self.objectives = []
        self.team_scores = {}
        self.current_round = 1
        self.num_teams = num_teams

        # Initialize team scores
        for team in TEAM_COLORS:
            self.team_scores[team] = 0

    def create_objective(self, objective_type: ObjectiveType, team: str):
        # Create a new objective for a team
        if objective_type == ObjectiveType.CAPTURE_FLAG:
            flag_position = Position(random.randint(100, SCREEN_WIDTH-100), 
                                random.randint(100, SCREEN_HEIGHT-100), Direction.RIGHT)
            self.objectives.append(ObjectiveStats(flag_position, objective_type))
        elif objective_type == ObjectiveType.DEFEND_BASE:
            base_position = Position(random.randint(50, 100), 
                              random.randint(50, 100), Direction.RIGHT)
            self.objectives.append(ObjectiveStats(base_position, objective_type))
        elif objective_type == ObjectiveType.ESCORT_PAYLOAD:
            payload_position = Position(random.randint(SCREEN_WIDTH-100, SCREEN_WIDTH), 
                                 random.randint(SCREEN_HEIGHT-100, SCREEN_HEIGHT), Direction.RIGHT)
            target_position = Position(random.randint(SCREEN_WIDTH-200, SCREEN_WIDTH), 
                                random.randint(SCREEN_HEIGHT-200, SCREEN_HEIGHT), Direction.RIGHT)
            self.objectives.append(ObjectiveStats(payload_position, objective_type, target_position))
        elif objective_type == ObjectiveType.DESTROY_ENEMY:
            # For this objective, the target is the opposing team
            pass

    def update_objectives(self, game_state: Dict, environment: Environment):
        # Update the progress of all objectives
        for objective in self.objectives:
            # Update based on objective type
            if objective.objective_type == ObjectiveType.CAPTURE_FLAG:
                self._update_capture_flag(objective, game_state)
            elif objective.objective_type == ObjectiveType.DEFEND_BASE:
                self._update_defend_base(objective, game_state)
            elif objective.objective_type == ObjectiveType.ESCORT_PAYLOAD:
                self._update_escort_payload(objective, game_state)
            elif objective.objective_type == ObjectiveType.DESTROY_ENEMY:
                self._update_destroy_enemy(objective, game_state)

    def _update_capture_flag(self, objective: ObjectiveStats, game_state: Dict):
        # Check if a robot has captured the flag
        for robot in game_state["robots"]:
            if (robot.role != RobotRole.SCOUT and  # Scouts don't carry flags
                self._distance_between(robot.position, objective.position) < 20 and
                robot.team != "Neutral"):  # Assuming flags are for team-based play
                # Robot has captured the flag
                objective.progress = 1.0
                robot.objective = objective
                # Add score for the robot's team
                self.team_scores[robot.team] += 100
                break

    def _update_defend_base(self, objective: ObjectiveStats, game_state: Dict):
        # Check if the base is under attack
        for robot in game_state["robots"]:
            if robot.team != "Neutral" and  # Assuming Neutral team doesn't attack
               self._distance_between(robot.position, objective.position) < 50 and
               robot.team != objective.team:  # Assuming objective has a team attribute
                # Base is under attack
                objective.progress = 1.0
                break

    def _update_escort_payload(self, objective: ObjectiveStats, game_state: Dict):
        # Check if a robot is carrying the payload and making progress
        for robot in game_state["robots"]:
            if robot.objective == objective and robot.role == RobotRole.ATTACKER:
                distance_to_target = self._distance_between(robot.position, objective.target_position)
                objective.progress = 1 - (distance_to_target / self._distance_between(objective.position, objective.target_position))
                if distance_to_target < 20:
                    # Payload has reached the destination
                    objective.progress = 1.0
                    robot.objective = None
                    # Add score for the robot's team
                    self.team_scores[robot.team] += 200
                    break

    def _update_destroy_enemy(self, objective: ObjectiveStats, game_state: Dict):
        # Check if all enemies have been destroyed
        for robot in game_state["robots"]:
            if robot.team == objective.enemy_team and robot.health > 0:
                return  # Not all enemies destroyed yet

        # All enemies destroyed
        objective.progress = 1.0
        # Add score to the winning team
        for robot in game_state["robots"]:
            if robot.team == objective.team:
                self.team_scores[robot.team] += 300
                break

    def _distance_between(self, pos1: Position, pos2: Position) -> float:
        return ((pos1.x - pos2.x)**2 + (pos1.y - pos2.y)**2)**0.5

