# Feedback and learning system for AI robots
class LearningSystem:
    def __init__(self):
        self.robot_experiences = {}  # Store experiences for each robot
        self.team_strategies = {}  # Store team strategies

    def record_experience(self, robot: RobotStats, action: str, result: Dict):
        """
        Record an experience for a robot

        Args:
            robot: The robot that performed the action
            action: The action taken
            result: A dictionary with the outcome of the action (e.g., damage done, health lost)
        """
        if robot.name not in self.robot_experiences:
            self.robot_experiences[robot.name] = []

        experience = {
            "action": action,
            "result": result,
            "timestamp": time.time()
        }

        self.robot_experiences[robot.name].append(experience)

        # Update robot's experience score
        robot.experience += self._calculate_experience_value(result)

    def _calculate_experience_value(self, result: Dict) -> float:
        """Calculate the value of an experience for learning"""
        # This is a simple calculation based on the result
        # In a real implementation, this would be more complex
        value = 0.0

        # Positive outcomes increase experience
        if "damage_dealt" in result:
            value += result["damage_dealt"] * 0.1
        if "heal_amount" in result:
            value += result["heal_amount"] * 0.05

        # Negative outcomes decrease experience
        if "health_lost" in result:
            value -= result["health_lost"] * 0.05

        return value

    def update_robot_strategies(self):
        """Update strategies for all robots based on their experiences"""
        for robot_name, experiences in self.robot_experiences.items():
            # Analyze experiences to find patterns
            best_actions = self._analyze_experiences(experiences)

            # Update the robot's strategy
            # In a more advanced system, this would modify the AI decision-making process
            self.robot_experiences[robot_name] = best_actions

    def _analyze_experiences(self, experiences: List[Dict]) -> Dict:
        """Analyze a robot's experiences to find the best actions"""
        # This is a simplified analysis
        best_actions = {}

        for experience in experiences:
            action = experience["action"]
            result = experience["result"]

            if action not in best_actions:
                best_actions[action] = 0.0

            # Score the action based on the result
            best_actions[action] += self._calculate_experience_value(result)

        return best_actions

# Main game simulation
class CyberArena:
    def __init__(self, num_teams: int = 2):
        # Initialize game systems
        self.state = GameState.WAITING
        self.objective_system = ObjectiveSystem(num_teams)
        self.environment = Environment()
        self.combat_system = CombatSystem()
        self.difficulty_system = DifficultySystem()
        self.learning_system = LearningSystem()

        # Initialize game entities
        self.robots = []
        self.teams = list(TEAM_COLORS.keys())[:num_teams]

        # Create robots for each team
        self._create_robots()

        # Create objectives for the game
        self._create_objectives()

    def _create_robots(self):
        """Create robots for each team with different roles"""
        for team in self.teams:
            # Create several robots per team with different roles
            for i in range(5):
                role = random.choice(list(RobotRole))
                robot_stats = RobotStats(
                    name=f"{team} Robot {i}",
                    team=team,
                    role=role
                )
                self.robots.append(robot_stats)

    def _create_objectives(self):
        """Create objectives for the game"""
        # Create one objective for each team
        for team in self.teams:
            objective_type = random.choice([ObjectiveType.CAPTURE_FLAG, ObjectiveType.DEFEND_BASE])
            self.objective_system.create_objective(objective_type, team)

    def start_game(self):
        """Start the game simulation"""
        self.state = GameState.STARTING
        self._initialize_game()

        while self.state != GameState.GAME_END:
            self.run_round()

        self._end_game()

    def run_round(self):
        """Run a single round of the game"""
        self.state = GameState.RUNNING
        print(f"Starting round {self.objective_system.current_round}")

        # Run the round until it ends
        while self.state == GameState.RUNNING:
            self.update_game_state()
            time.sleep(0.1)  # Simple simulation of real-time

        # Handle round end
        self._end_round()

    def update_game_state(self):
        """Update the game state for all entities"""
        # Update all systems
        self.objective_system.update_objectives(self._get_game_state(), self.environment)
        self.environment.update(0.1)

        # Update all robots
        for robot in self.robots:
            if robot.health <= 0:
                continue  # Skip dead robots

            # Get current game state for this robot
            game_state = self._get_game_state(robot.name)

            # Make decisions for the robot
            ai = RobotAI(robot)
            decision = ai.make_decision(game_state, self.environment)

            # Process the decision
            self._process_robot_decision(robot, decision)

            # Check if the robot has any power-up effects
            if robot.powerup:
                self._apply_powerup_effect(robot)

    def _get_game_state(self, robot_name: Optional[str] = None) -> Dict:
        """Get the current game state"""
        game_state = {
            "robots": [robot for robot in self.robots if robot.health > 0],
            "objectives": self.objective_system.objectives,
            "environment": self.environment,
            "teams": self.teams
        }

        # If a specific robot is requested, return a filtered game state
        if robot_name:
            filtered_game_state = {
                "robots": [robot for robot in game_state["robots"] if robot.name != robot_name],
                "objectives": self.objective_system.objectives,
                "environment": self.environment
            }
            return filtered_game_state

        return game_state

    def _process_robot_decision(self, robot: RobotStats, decision: Dict):
        """Process a robot's decision and update its state"""
        action = decision["action"]

        if action == "move":
            self._move_robot(robot, decision["direction"])
        elif action == "attack":
            self._attack_with_robot(robot, decision["target"], decision["direction"])
        elif action == "use_ability":
            self._use_ability(robot, decision["target"], decision["ability"], decision["direction"])
        elif action == "scan":
            self._scan_environment(robot, decision["target"], decision["direction"])

    def _move_robot(self, robot: RobotStats, direction: Direction):
        """Move a robot in the specified direction"""
        # Simple movement logic
        move_distance = robot.speed * 0.1  # 0.1 is the time step

        if direction == Direction.UP:
            robot.position.y -= move_distance
        elif direction == Direction.DOWN:
            robot.position.y += move_distance
        elif direction == Direction.LEFT:
            robot.position.x -= move_distance
        elif direction == Direction.RIGHT:
            robot.position.x += move_distance

        # Check for terrain effects
        terrain_effect = self.environment.get_terrain_effect(robot.position)
        if terrain_effect:
            self._apply_terrain_effect(robot, terrain_effect)

    def _attack_with_robot(self, robot: RobotStats, target_name: str, direction: Direction):
        """Make a robot attack another robot"""
        # Find the target
        for target in self.robots:
            if target.name == target_name and target.health > 0:
                # Perform the attack
                success, damage = self.combat_system.handle_attack(robot, target, self.environment)

                # Update scores and experience
                if success:
                    robot.score += int(damage)
                    self.learning_system.record_experience(robot, "attack", {"damage_dealt": damage})
                    self.learning_system.record_experience(target, "defend", {"damage_received": damage})

                    # Update difficulty based on the outcome
                    self._update_difficulty_based_on_attack(robot, target, damage)
                break

    def _use_ability(self, robot: RobotStats, target_name: str, ability: str, direction: Direction):
        """Make a robot use a special ability"""
        # This is a simplified implementation
        # In a real game, this would handle various abilities like healing, shielding, etc.
        if ability == "heal":
            for target in self.robots:
                if target.name == target_name and target.health > 0 and target.team == robot.team:
                    heal_amount = 20.0
                    target.health = min(target.health + heal_amount, MAX_HEALTH)

                    # Record the experience
                    robot.experience += 5.0
                    self.learning_system.record_experience(robot, "heal", {"heal_amount": heal_amount})
                    break
        elif ability == "buff":
            for target in self.robots:
                if target.name == target_name and target.health > 0 and target.team == robot.team:
                    # Buff the target's armor
                    target.armor = min(target.armor + 10.0, 100.0)

                    # Record the experience
                    robot.experience += 3.0
                    self.learning_system.record_experience(robot, "buff", {"buff_amount": 10.0})
                    break
        elif ability == "shield":
            # Apply a shield to the robot
            if not any(se.effect == StatusEffect.SHIELDED for se in robot.status_effects):
                robot.status_effects.append(StatusEffectStats(
                    duration=5.0, 
                    effect=StatusEffect.SHIELDED, 
                    source="shield_projector"
                ))

                # Record the experience
                robot.experience += 2.0
                self.learning_system.record_experience(robot, "shield", {"duration": 5.0})

    def _scan_environment(self, robot: RobotStats, target_name: str, direction: Direction):
        """Make a robot scan the environment"""
        # This is a simplified implementation
        # In a real game, this would provide information about the environment
        # For now, just record that the robot scanned
        self.learning_system.record_experience(robot, "scan", {"scan_direction": direction.name})

    def _apply_powerup_effect(self, robot: RobotStats):
        """Apply the effect of a power-up to a robot"""
        if robot.powerup is None:
            return

        # Apply the power-up effect
        if robot.powerup.powerup_type == PowerupType.HEALTH_BOOST:
            robot.health = min(robot.health + 30.0, MAX_HEALTH)
        elif robot.powerup.powerup_type == PowerupType.SHIELD_ENHANCE:
            robot.armor = min(robot.armor + 20.0, 100.0)
        elif robot.powerup.powerup_type == PowerupType.SPEED_BOOST:
            robot.speed = min(robot.speed * 1.5, 5.0)
        elif robot.powerup.powerup_type == PowerupType.DAMAGE_AMPLIFIER:
            robot.weapon.damage = min(robot.weapon.damage * 1.5, 100.0)
        elif robot.powerup.powerup_type == PowerupType.TELEPORT:
            # Teleport to a random location
            robot.position.x = random.randint(0, SCREEN_WIDTH)
            robot.position.y = random.randint(0, SCREEN_HEIGHT)

        # Decrease the power-up duration
