    def handle_attack(self, attacker: RobotStats, target: RobotStats, environment: Environment) -> Tuple[bool, float]:
        """
        Handle an attack from one robot to another

        Args:
            attacker: The robot making the attack
            target: The robot being attacked
            environment: The game environment

        Returns:
            A tuple (success, damage_dealt)
        """
        # Check if the attacker can attack (cooldown)
        if attacker.name in self.attack_cooldowns:
            if time.time() < self.attack_cooldowns[attacker.name]:
                return (False, 0.0)

        # Check if the target is in range
        distance = self._distance_between(attacker.position, target.position)
        if distance > attacker.weapon.range:
            return (False, 0.0)

        # Apply weapon damage
        base_damage = attacker.weapon.damage

        # Apply armor reduction
        armor_reduction = min(target.armor / (target.armor + attacker.weapon.damage), 0.7)
        effective_damage = base_damage * (1 - armor_reduction)

        # Apply environment effects
        terrain_effect = environment.get_terrain_effect(attacker.position)
        if terrain_effect and terrain_effect.hazard_type == HazardType.ELECTRIC_FIELD:
            effective_damage *= 1.2  # Electric field increases damage

        # Apply to target
        target.health -= effective_damage
        target.score += int(effective_damage)

        # Set attack cooldown
        self.attack_cooldowns[attacker.name] = time.time() + attacker.weapon.recharge_time

        return (True, effective_damage)

