        self.performance_thresholds = {
            1: 0.4,  # 40% win threshold to increase difficulty
            2: 0.5,
            3: 0.6,
            4: 0.7,
            5: 0.8
        }

    def adjust_difficulty(self, win_percentage):
        """Adjust the difficulty level based on win percentage."""
        for level, threshold in sorted(self.performance_thresholds.items()):
            if win_percentage >= threshold and level < self.max_difficulty:
                self.difficulty_level += 1
                return True
            elif win_percentage < threshold and level > 1:
                self.difficulty_level -= 1
                return True
        return False  # No change needed

    def get_difficulty_factor(self):
        """Get a factor to scale difficulty-related parameters."""
        return self.difficulty_level / self.max_difficulty

