class Position:
    """A class to represent a 2D position in the arena."""

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def move_towards(self, target, speed):
        """Move towards a target position at a given speed."""
        dx = target.x - self.x
        dy = target.y - self.y
        distance = (dx**2 + dy**2)**0.5
        if distance > 0:
            self.x += (dx / distance) * speed
            self.y += (dy / distance) * speed

    def __str__(self):
        return f"Position(x={self.x:.2f}, y={self.y:.2f})"


class Weapon:
    """A class to represent a weapon used by a robot."""

    def __init__(self, weapon_type, damage, range, fire_rate, ammo_capacity):
