            return False  # Out of range

        # Simulate hit probability based on distance
        hit_chance = max(0, 1 - (distance / self.range))
        if random.random() < hit_chance:
            self.current_ammo -= 1
            return True  # Hit
        else:
            self.current_ammo -= 1
            return False  # Miss

