        # Update movement
        self.move_towards_target()

        # Update weapon cooldowns
        self.update_weapon_cooldowns()

        # Update state
        self.update_state()

    def handle_power_ups(self) -> None:
        """Handle active power-ups"""
        for power_up in self.power_ups:
            if power_up.type == PowerUpType.SPEED_BOOST:
                # Duration for speed boost
                if time.time() - power_up.activation_time > power_up.duration:
                    self.speed = self.base_speed
                    self.power_ups.remove(power_up)
            elif power_up.type == PowerUpType.DAMAGE_BOOST:
                # Duration for damage boost
                if time.time() - power_up.activation_time > power_up.duration:
                    self.damage_multiplier = 1.0
                    self.power_ups.remove(power_up)

    def handle_hazards(self) -> None:
        """Handle effects of hazards on the robot"""
        for hazard in self.hazards:
            hazard.damage_robot(self)

    def handle_objective(self) -> None:
        """Handle robot behavior based on current objective"""
        if self.objective:
            if self.objective.completed:
                self.objective = None
                self.state = RobotState.IDLE
                return

            if isinstance(self.objective, FlagCapture):
                self.handle_flag_capture()
            elif isinstance(self.objective, BaseDefense):
                self.handle_base_defense()
            elif isinstance(self.objective, PayloadEscort):
                self.handle_payload_escort()
            elif isinstance(self.objective, ZoneControl):
                self.handle_zone_control()

    def handle_combat(self, arena: 'CyberArena') -> None:
        """Handle combat behavior when no objective is active"""
        # Check for nearby enemies
        enemies = [r for r in arena.robots if r.team != self.team and not r.is_dead]

        if enemies:
            self.select_target(enemies)
            if self.target:
                # Attack if in range
                if self.position.distance_to(self.target.position) <= self.weapons[self.current_weapon_index].range:
                    self.attack()
                else:
                    # Move towards target
                    self.state = RobotState.MOVING
                    target_direction = (self.target.position - self.position).normalize()
                    self.position += target_direction * self.speed * (time.time() - self.last_move_time)
        else:
            # No enemies found, check for objectives
            if arena.active_objectives:
                self.select_objective(arena.active_objectives)
            else:
                # Patrol or random movement
                self.state = RobotState.IDLE
                self.position += Vector2(random.uniform(-1, 1), random.uniform(-1, 1)) * self.speed

    def handle_flag_capture(self) -> None:
        """Handle behavior for flag capture objective"""
        # Implementation for flag capture behavior
        if self.position.distance_to(self.objective.flag_position) <= 5:
            self.objective.complete(self.team)
            self.state = RobotState.IDLE
        else:
            self.state = RobotState.CAPTURING
            direction = (self.objective.flag_position - self.position).normalize()
            self.position += direction * self.speed * (time.time() - self.last_move_time)

    def handle_base_defense(self) -> None:
        """Handle behavior for base defense objective"""
        # Implementation for base defense behavior
        if self.position.distance_to(self.objective.base_position) > 50:
            # Return to base
            direction = (self.objective.base_position - self.position).normalize()
            self.position += direction * self.speed * (time.time() - self.last_move_time)
        else:
            # Look for enemies near the base
            enemies = [r for r in self.objective.arena.robots if r.team != self.team and 
                      r.position.distance_to(self.objective.base_position) <= 100 and not r.is_dead]
            if enemies:
                self.select_target(enemies)
                if self.target:
                    # Attack if in range
                    if self.position.distance_to(self.target.position) <= self.weapons[self.current_weapon_index].range:
                        self.attack()
                    else:
                        # Move towards target
                        self.state = RobotState.MOVING
                        target_direction = (self.target.position - self.position).normalize()
                        self.position += target_direction * self.speed * (time.time() - self.last_move_time)
            else:
                # Patrol around base
                self.state = RobotState.DEFENDING
                patrol_point = Vector2(
                    self.objective.base_position.x + random.uniform(-10, 10),
                    self.objective.base_position.y + random.uniform(-10, 10)
                )
                direction = (patrol_point - self.position).normalize()
                self.position += direction * self.speed * (time.time() - self.last_move_time)

    def handle_payload_escort(self) -> None:
        """Handle behavior for payload escort objective"""
        # Implementation for payload escort behavior
        payload = self.objective.payload
        if payload is None:
            return

        if self.position.distance_to(payload.position) > 10:
            # Move towards payload
            direction = (payload.position - self.position).normalize()
            self.position += direction * self.speed * (time.time() - self.last_move_time)
        else:
            # Stay near payload and guard it
            self.state = RobotState.ESCORTING
            # Look for enemies near the payload
            enemies = [r for r in self.objective.arena.robots if r.team != self.team and 
                      r.position.distance_to(payload.position) <= 100 and not r.is_dead]
            if enemies:
                self.select_target(enemies)
                if self.target:
                    # Attack if in range
                    if self.position.distance_to(self.target.position) <= self.weapons[self.current_weapon_index].range:
                        self.attack()
                    else:
                        # Move towards target
                        self.state = RobotState.MOVING
                        target_direction = (self.target.position - self.position).normalize()
                        self.position += target_direction * self.speed * (time.time() - self.last_move_time)
            else:
                # Patrol around payload
                patrol_point = Vector2(
                    payload.position.x + random.uniform(-10, 10),
                    payload.position.y + random.uniform(-10, 10)
                )
                direction = (patrol_point - self.position).normalize()
                self.position += direction * self.speed * (time.time() - self.last_move_time)

    def handle_zone_control(self) -> None:
        """Handle behavior for zone control objective"""
        # Implementation for zone control behavior
        if self.position.distance_to(self.objective.zone_center) > 50:
            # Move towards control zone
            direction = (self.objective.zone_center - self.position).normalize()
            self.position += direction * self.speed * (time.time() - self.last_move_time)
        else:
            # Stay in control zone and look for enemies
            self.state = RobotState.SUPPORTING
            enemies = [r for r in self.objective.arena.robots if r.team != self.team and 
                      r.position.distance_to(self.objective.zone_center) <= 100 and not r.is_dead]
            if enemies:
                self.select_target(enemies)
                if self.target:
                    # Attack if in range
                    if self.position.distance_to(self.target.position) <= self.weapons[self.current_weapon_index].range:
                        self.attack()
                    else:
                        # Move towards target
                        self.state = RobotState.MOVING
                        target_direction = (self.target.position - self.position).normalize()
                        self.position += target_direction * self.speed * (time.time() - self.last_move_time)
            else:
                # Patrol within control zone
                patrol_point = Vector2(
                    self.objective.zone_center.x + random.uniform(-30, 30),
                    self.objective.zone_center.y + random.uniform(-30, 30)
                )
                direction = (patrol_point - self.position).normalize()
                self.position += direction * self.speed * (time.time() - self.last_move_time)

    def select_objective(self, objectives: List['Objective']) -> None:
        """Select the best objective based on strategy"""
        # Simple selection based on proximity and team needs
        if not objectives:
            return

        best_objective = min(objectives, key=lambda obj: self.position.distance_to(obj.position))
        self.objective = best_objective
        self.state = self.determine_state_for_objective(best_objective)

    def determine_state_for_objective(self, objective: 'Objective') -> RobotState:
        """Determine appropriate state for the given objective"""
        if isinstance(objective, FlagCapture):
            return RobotState.CAPTURING
        elif isinstance(objective, BaseDefense):
            return RobotState.DEFENDING
        elif isinstance(objective, PayloadEscort):
            return RobotState.ESCORTING
        elif isinstance(objective, ZoneControl):
            return RobotState.SUPPORTING
        return RobotState.IDLE

    def select_target(self, enemies: List['Robot']) -> None:
        """Select the best target based on strategy"""
        if not enemies:
            self.target = None
            return

        # Simple selection based on proximity and vulnerability
        best_target = min(enemies, key=lambda e: self.position.distance_to(e.position))
        self.target = best_target
        self.state = RobotState.ATTACKING

    def move_towards_target(self) -> None:
        """Move towards the current target if not attacking"""
        if self.target and self.state != RobotState.ATTACKING:
            direction = (self.target.position - self.position).normalize()
            self.position += direction * self.speed * (time.time() - self.last_move_time)
            self.last_move_time = time.time()

    def attack(self) -> None:
        """Execute an attack with the current weapon"""
        if self.target and self.weapons[self.current_weapon_index].is_ready(self.last_attack_time):
            # Calculate damage with multiplier
            damage = self.weapons[self.current_weapon_index].damage * self.damage_multiplier
            self.target.take_damage(damage, self.weapons[self.current_weapon_index].weapon_type)
            self.last_attack_time = time.time()
            self.state = RobotState.ATTACKING

    def update_weapon_cooldowns(self) -> None:
        """Update all weapon cooldowns"""
        for weapon in self.weapons:
            if time.time() - self.last_attack_time > (1 / weapon.fire_rate):
                weapon.ready = True
            else:
                weapon.ready = False

    def update_state(self) -> None:
        """Update the robot's state based on current actions"""
        if self.is_dead:
            self.state = RobotState.DEAD
            return

        if self.objective and self.objective.completed:
            self.state = RobotState.IDLE
            self.objective = None
            return

        # Set state based on current actions
        if self.target and self.state == RobotState.ATTACKING:
            self.state = RobotState.ATTACKING
        elif self.objective:
            self.state = self.determine_state_for_objective(self.objective)
        else:
            self.state = RobotState.IDLE

    def take_damage(self, amount: float, damage_type: WeaponType) -> None:
        """Take damage from an attack"""
        if self.is_dead:
            return
        if self.shield > 0:
            if amount <= self.shield:
                self.shield -= amount
                amount = 0
            else:
                amount -= self.shield
                self.shield = 0
        if amount > 0:
            self.health -= amount
            # Check if dead
            if self.health <= 0:
                self.die()

    def die(self) -> None:
        """Handle robot death"""
        self.is_dead = True
        self.state = RobotState.DEAD
        self.health = 0
        self.shield = 0
        self.target = None
        self.objective = None
        self.speed = 0
        self.damage_multiplier = 1.0

        # Reset power-ups
        self.power_ups = []

    def collect_power_up(self, power_up: PowerUp) -> None:
        """Collect a power-up and apply its effects"""
        power_up.active = False
        power_up.activation_time = time.time()
        self.power_ups.append(power_up)
        power_up.apply_effect(self)

    @abstractmethod
    def get_strategy_value(self, key: str) -> float:
        """Get value from the robot's strategy"""
        pass

    @abstractmethod
    def set_strategy_value(self, key: str, value: float) -> None:
        """Set value in the robot's strategy"""
        pass

    def __str__(self):
        return f"{Color.GREEN if self.team == Team.RED else Color.RED if self.team == Team.BLUE else Color.CYAN}{self.team.value} {self.__class__.__name__} at {self.position.to_tuple()}, HP: {self.health} SH: {self.shield}{Color.RESET}"

class CombatRobot(Robot):
    """Specialized robot for combat roles"""
    def __init__(self, team: Team, position: Vector2):
        super().__init__(team, position, speed=6.0, health=120.0, shield=60.0)
        self.name = "Combat Unit"
        # Initialize weapons
        self.weapons = [
            Weapon("Laser Cannon", 20, 80, 1.5, 100, WeaponType.LASER),
            Weapon("Plasma Gun", 15, 100, 2.0, 50, WeaponType.PLASMA),
            Weapon("Shock Rod", 30, 5, 0.5, 5, WeaponType.SHOCK)
        ]
        self.current_weapon_index = 0

    def get_strategy_value(self, key: str) -> float:
        """Get value from the robot's strategy"""
        return self.strategy.get(key, 1.0)

    def set_strategy_value(self, key: str, value: float) -> None:
        """Set value in the robot's strategy"""
        self.strategy[key] = value

    def switch_weapon(self):
        """Switch to the next weapon"""
        self.current_weapon_index = (self.current_weapon_index + 1) % len(self.weapons)

class SupportRobot(Robot):
    """Specialized robot for support roles"""
    def __init__(self, team: Team, position: Vector2):
        super().__init__(team, position, speed=4.0, health=80.0, shield=40.0)
        self.name = "Support Unit"
        # Initialize weapons
        self.weapons = [
            Weapon("Heal Beam", 10, 50, 1.0, 10, WeaponType.NONE),
            Weapon("Shield Generator", 20, 60, 0.5, 5, WeaponType.NONE)
        ]
        self.current_weapon_index = 0

    def get_strategy_value(self, key: str) -> float:
        """Get value from the robot's strategy"""
        return self.strategy.get(key, 1.0)

    def set_strategy_value(self, key: str, value: float) -> None:
        """Set value in the robot's strategy"""
        self.strategy[key] = value

    def use_heal(self, target: 'Robot') -> None:
        """Heal a target robot"""
        if self.weapons[self.current_weapon_index].is_ready(self.last_attack_time):
            if target.team == self.team:
                # Healing effect
                heal_amount = self.weapons[self.current_weapon_index].damage
                target.health = min(target.max_health, target.health + heal_amount)
                self.last_attack_time = time.time()
                self.state = RobotState.SUPPORTING

    def use_shield(self, target: 'Robot') -> None:
        """Apply shield to a target robot"""
        if self.weapons[self.current_weapon_index].is_ready(self.last_attack_time):
            if target.team == self.team:
                # Shield effect
                shield_amount = self.weapons[self.current_weapon_index].damage
                target.shield = min(target.max_shield, target.shield + shield_amount)
                self.last_attack_time = time.time()
                self.state = RobotState.SUPPORTING

class ObjectiveType(Enum):
    """Enum for different objective types"""
    FLAG_CAPTURE = "flag_capture"
    BASE_DEFENSE = "base_defense"
    PAYLOAD_ESCORT = "payload_escort"
    ZONE_CONTROL = "zone_control"

class Objective:
    """Base class for all objectives in the arena"""
    def __init__(self, objective_type: ObjectiveType, position: Vector2, team: Team):
        self.type = objective_type
        self.position = position
        self.team = team
        self.completed = False
        self.arena = None  # Will be set by the arena

    def complete(self, team: Team) -> None:
        """Mark the objective as completed by the specified team"""
        self.completed = True
        self.team = team
        # Add score to the team
        if self.arena:
            self.arena.add_team_score(team, 100)

    def __str__(self):
        return f"{self.type.value} Objective at {self.position.to_tuple()} for {self.team.value}"

class FlagCapture(Objective):
    """Objective for capturing flags"""
    def __init__(self, position: Vector2, team: Team):
        super().__init__(ObjectiveType.FLAG_CAPTURE, position, team)
        self.flag_position = position

class BaseDefense(Objective):
    """Objective for defending bases"""
    def __init__(self, position: Vector2, team: Team):
        super().__init__(ObjectiveType.BASE_DEFENSE, position, team)
        self.base_position = position

class PayloadEscort(Objective):
    """Objective for escorting payloads"""
    def __init__(self, payload_position: Vector2, team: Team):
        super().__init__(ObjectiveType.PAYLOAD_ESCORT, payload_position, team)
        self.payload_position = payload_position
        self.payload = None  # Will be created by the arena

class ZoneControl(Objective):
    """Objective for controlling zones"""
    def __init__(self, zone_center: Vector2, team: Team):
        super().__init__(ObjectiveType.ZONE_CONTROL, zone_center, team)
        self.zone_center = zone_center

class CyberArena:
    """Main class for the CyberArena simulation"""
    def __init__(self, width: int = 100, height: int = 100):
        self.width = width
        self.height = height
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.active_objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []
        self.teams: Dict[Team, List[Robot]] = {team: [] for team in Team}
        self.scores: Dict[Team, float] = {team: 0 for team in Team}
        self.total_time = 0
        self.running = True
        self.difficulty_multiplier = 1.0
        self.max_robots = 0
        self.robot_count = 0
        self.last_difficulty_check = time.time()
        self.difficulty_check_interval = 60  # every 60 seconds
        self.feedback_loop_data = {}
        self.feedback_loop_active = False

    def add_robot(self, robot: Robot) -> None:
        """Add a robot to the arena"""
        if self.robot_count >= self.max_robots:
            return

        self.robots.append(robot)
        self.teams[robot.team].append(robot)
        self.robot_count += 1
        robot.arena = self

    def add_objective(self, objective: Objective) -> None:
        """Add an objective to the arena"""
        self.objectives.append(objective)
        self.active_objectives.append(objective)
        objective.arena = self

    def add_power_up(self, power_up: PowerUp) -> None:
        """Add a power-up to the arena"""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard: Hazard) -> None:
        """Add a hazard to the arena"""
        self.hazards.append(hazard)

    def add_team_score(self, team: Team, amount: float) -> None:
        """Add score to a team"""
        if team in self.scores:
            self.scores[team] += amount
            self._display_score(team, amount)

    def _display_score(self, team: Team, amount: float) -> None:
        """Display score change with appropriate color"""
        team_colors = {
            Team.RED: Color.RED,
            Team.BLUE: Color.BLUE,
            Team.GREEN: Color.GREEN,
            Team.YELLOW: Color.YELLOW
        }

        color = team_colors.get(team, Color.WHITE)
        print(f"{color}{team.value} team scored {amount} points! Total: {self.scores[team]}{Color.RESET}")

    def update(self) -> None:
        """Update the entire arena state"""
        if not self.running:
            return

        current_time = time.time()
        self.total_time += current_time - self.last_difficulty_check

        # Update all robots
        for robot in self.robots:
            robot.update(self)

        # Update all power-ups
        for power_up in self.power_ups:
            if power_up.active:
                # Check if any robot is near the power-up
                for robot in self.robots:
                    if robot.position.distance_to(power_up.position) <= 5:
                        robot.collect_power_up(power_up)
                        break

        # Update all hazards
        for hazard in self.hazards:
            if hazard.active:
                for robot in self.robots:
                    hazard.damage_robot(robot)

        # Check for completed objectives
        for objective in self.active_objectives[:]:
            if objective.completed:
                self.active_objectives.remove(objective)
                self._display_objective_completion(objective)

        # Check if all robots are dead
        if all(robot.is_dead for robot in self.robots):
            self._end_match()

        # Check for difficulty adjustment
        if current_time - self.last_difficulty_check > self.difficulty_check_interval:
            self._adjust_difficulty()
            self.last_difficulty_check = current_time

        # Check for feedback loop
        if self.feedback_loop_active:
            self._run_feedback_loop()

        # Display status
        self._display_status()

    def _display_objective_completion(self, objective: Objective) -> None:
        """Display message when an objective is completed"""
        team_colors = {
            Team.RED: Color.RED,
            Team.BLUE: Color.BLUE,
            Team.GREEN: Color.GREEN,
            Team.YELLOW: Color.YELLOW
        }

        color = team_colors.get(objective.team, Color.WHITE)
        print(f"{color}{objective.team.value} team completed the {objective.type.value} objective!{Color.RESET}")

    def _end_match(self) -> None:
        """End the match and display final results"""
        self.running = False
        self._display_results()

    def _display_results(self) -> None:
        """Display match results including scores and performance metrics"""
        print("\n" + Color.YELLOW + "=== Match Results ===" + Color.RESET)
        for team, score in self.scores.items():
            team_colors = {
                Team.RED: Color.RED,
                Team.BLUE: Color.BLUE,
                Team.GREEN: Color.GREEN,
                Team.YELLOW: Color.YELLOW
            }
            color = team_colors.get(team, Color.WHITE)
            print(f"{color}{team.value} Team Final Score: {score}{Color.RESET}")

        # Display performance metrics
        print("\n" + Color.CYAN + "=== Performance Metrics ===" + Color.RESET)
        for team in Team:
            if team != Team.NONE:
                team_robots = [r for r in self.robots if r.team == team]
                if team_robots:
                    avg_health = sum(r.health for r in team_robots) / len(team_robots)
                    avg_shield = sum(r.shield for r in team_robots) / len(team_robots)
                    survival_rate = len([r for r in team_robots if not r.is_dead]) / len(team_robots)
                    team_colors = {
                        Team.RED: Color.RED,
                        Team.BLUE: Color.BLUE,
                        Team.GREEN: Color.GREEN,
                        Team.YELLOW: Color.YELLOW
                    }
                    color = team_colors.get(team, Color.WHITE)
                    print(f"{color}{team.value} Team - Avg HP: {avg_health:.1f}, Avg SH: {avg_shield:.1f}, Survival Rate: {survival_rate:.2%}{Color.RESET}")

        # Display feedback loop data if active
        if self.feedback_loop_active and self.feedback_loop_data:
            print("\n" + Color.MAGENTA + "=== Feedback Loop Data ===" + Color.RESET)
            for key, value in self.feedback_loop_data.items():
                print(f"{Color.CYAN}{key}{Color.RESET}: {value}")

    def _display_status(self) -> None:
        """Display current status of the arena"""
        print("\n" + Color.MAGENTA + "=== CyberArena Status ===" + Color.RESET)

        # Display team status
        for team in Team:
            if team != Team.NONE:
                team_robots = [r for r in self.robots if r.team == team]
                alive_robots = [r for r in team_robots if not r.is_dead]
                team_colors = {
                    Team.RED: Color.RED,
                    Team.BLUE: Color.BLUE,
                    Team.GREEN: Color.GREEN,
                    Team.YELLOW: Color.YELLOW
                }
                color = team_colors.get(team, Color.WHITE)
                print(f"{color}{team.value} Team - {len(alive_robots)} of {len(team_robots)} robots alive{Color.RESET}")

        # Display active objectives
        if self.active_objectives:
            print("\n" + Color.BLUE + "Active Objectives:" + Color.RESET)
            for objective in self.active_objectives:
                print(f" - {objective}")
        else:
            print(Color.BLUE + "No active objectives" + Color.RESET)

        # Display power-ups
        if self.power_ups:
            print("\n" + Color.GREEN + "Available Power-Ups:" + Color.RESET)
            for power_up in self.power_ups:
                if power_up.active:
                    print(f" - {power_up}")
        else:
            print(Color.GREEN + "No active power-ups" + Color.RESET)

        # Display hazards
        if self.hazards:
            print("\n" + Color.RED + "Active Hazards:" + Color.RESET)
            for hazard in self.hazards:
                if hazard.active:
                    print(f" - {hazard}")
        else:
            print(Color.RED + "No active hazards" + Color.RESET)

    def _adjust_difficulty(self) -> None:
        """Adjust the difficulty based on team performance"""
        # Calculate average scores and performance metrics
        total_score = sum(self.scores.values())
        if total_score > 0:
            team_performance = {team: self.scores[team]/total_score for team in Team if team != Team.NONE}
        else:
            team_performance = {team: 0.0 for team in Team if team != Team.NONE}

        # Calculate average robot performance
        avg_health = sum(robot.health for robot in self.robots if not robot.is_dead) / max(1, self.robot_count)
        avg_shield = sum(robot.shield for robot in self.robots if not robot.is_dead) / max(1, self.robot_count)
