import datetime
import json
from enum import Enum
import threading
import time

# Enum for Task Status

class TaskStatus(Enum):
    NOT_STARTED = 1
    IN_PROGRESS = 2
    COMPLETED = 3

# Enum for User Roles
class UserRole(Enum):
    ADMIN = 1
    MANAGER = 2
    EMPLOYEE = 3

# Base User class
class User:
    def __init__(self, user_id, name, role):
        self.user_id = user_id
        self.name = name
        self.role = role

    def can_assign_task(self):
        return self.role in [UserRole.ADMIN, UserRole.MANAGER]

    def can_view_task(self):
        return True

    def can_edit_task(self):
        return self.role in [UserRole.ADMIN, UserRole.MANAGER]

class Task:
    def __init__(self, task_id, title, description, assignee, deadline, priority=1):
        self.task_id = task_id
        self.title = title
        self.description = description
        self.assignee = assignee
        self.status = TaskStatus.NOT_STARTED
        self.deadline = deadline
        self.priority = priority
        self.comments = []
        self.attachments = []
        self.history = []  # Task status history

    def update_status(self, new_status):
        self.status = new_status
        self.history.append({
            'timestamp': datetime.datetime.now(),
            'status': new_status.name
        })

    def add_comment(self, user, comment):
        self.comments.append({
            'user': user.name,
            'comment': comment,
            'timestamp': datetime.datetime.now()
        })

    def add_attachment(self, file_name):
        self.attachments.append(file_name)

    def is_overdue(self):
        return self.status != TaskStatus.COMPLETED and datetime.datetime.now() > self.deadline

class TaskManager:
    def __init__(self):
        self.tasks = {}
        self.users = {}
        self.notifications = []
        self.lock = threading.Lock()

    def create_user(self, user_id, name, role):
        if user_id in self.users:
            return False, "User already exists"
        self.users[user_id] = User(user_id, name, role)
        return True, "User created successfully"

    def authenticate_user(self, user_id):
        return user_id in self.users

    def get_user(self, user_id):
        return self.users.get(user_id)

    def create_task(self, creator, title, description, assignee, deadline, priority=1):
        if not creator.can_assign_task():
            return False, "Only admins or managers can assign tasks"
        if assignee not in self.users:
            return False, "Assignee does not exist"

        task_id = len(self.tasks) + 1
        deadline_dt = datetime.datetime.strptime(deadline, "%Y-%m-%d %H:%M")

        self.tasks[task_id] = Task(task_id, title, description, assignee, deadline_dt, priority)
        self.notify_user(assignee, f"You have been assigned a new task: {title}")
        return True, f"Task {task_id} created and assigned to {assignee}"

    def update_task_status(self, user_id, task_id, new_status):
        if task_id not in self.tasks:
            return False, "Task does not exist"
        task = self.tasks[task_id]
        user = self.get_user(user_id)

        if not user.can_edit_task():
            return False, "You do not have permission to edit this task"

        if task.assignee != user_id and user.role != UserRole.ADMIN:
            return False, "You are not the assignee"

        task.update_status(new_status)
        self.notify_users(f"Task {task_id}: status updated to {new_status.name}")
        return True, f"Task {task_id} status updated to {new_status.name}"

    def add_comment(self, user_id, task_id, comment):
        if task_id not in self.tasks:
            return False, "Task does not exist"
        task = self.tasks[task_id]
        user = self.get_user(user_id)

        if not user.can_view_task():
            return False, "You do not have permission to view this task"

        task.add_comment(user, comment)
        self.notify_users(f"Task {task_id}: new comment added by {user.name}")
        return True, f"Comment added to task {task_id}"

    def add_attachment(self, user_id, task_id, file_name):
        if task_id not in self.tasks:
            return False, "Task does not exist"
        task = self.tasks[task_id]
        user = self.get_user(user_id)

        if not user.can_view_task():
            return False, "You do not have permission to view this task"

        task.add_attachment(file_name)
        self.notify_users(f"Task {task_id}: new attachment added by {user.name}")
        return True, f"Attachment added to task {task_id}"

    def generate_report(self):
        report = {
            'completed_tasks': [],
            'pending_tasks': [],
            'overdue_tasks': []
        }

        for task in self.tasks.values():
            if task.status == TaskStatus.COMPLETED:
                report['completed_tasks'].append(task.task_id)
            elif task.status == TaskStatus.NOT_STARTED:
                report['pending_tasks'].append(task.task_id)
            elif task.is_overdue():
                report['overdue_tasks'].append(task.task_id)
            else:
                report['pending_tasks'].append(task.task_id)
        return report

    def notify_user(self, user_id, message):
        with self.lock:
            self.notifications.append({
                'user_id': user_id,
                'message': message,
                'timestamp': datetime.datetime.now()
            })

    def notify_users(self, message):
        for user_id in self.users:
            self.notify_user(user_id, message)

    def get_user_notifications(self, user_id):
        return [n for n in self.notifications if n['user_id'] == user_id]

