class Vector2:
    """Class to represent a 2D vector for position and movement."""
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector2(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.hypot(self.x, self.y)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2(0, 0)
        return Vector2(self.x / mag, self.y / mag)

    def distance_to(self, other):
        return math.hypot(self.x - other.x, self.y - other.y)

    def __repr__(self):
        return f"Vector2({self.x}, {self.y})"

class Weapon:
    """Base class representing a weapon that a robot can use."""
    def __init__(self, name, damage, range, ammo, fire_rate, weapon_type):
        self.name = name
        self.damage = damage
        self.range = range
        self.ammo = ammo
        self.fire_rate = fire_rate  # attacks per second
        self.weapon_type = weapon_type

    def fire(self, target):
        """Simulate firing at a target."""
        if self.weapon_type in [WeaponType.LASER_GUN, WeaponType.PLASMA_RIFLE]:
            # Ranged weapon
            if self.range >= self.distance_to(target.position):
                return self._ranged_attack(target)
        elif self.weapon_type in [WeaponType.SHOCK_SWORD]:
            # Melee weapon
            if self.range >= self.distance_to(target.position):
                return self._melee_attack(target)
        return False  # out of range or failed to attack

    def _ranged_attack(self, target):
        """Perform a ranged attack on the target."""
        # Simulating ranged attack
        damage = self.damage * (1 - (self.distance_to(target.position) / self.range))
        if random.random() < 0.8:  # 80% accuracy
            target.take_damage(damage)
            return True
        return False

    def _melee_attack(self, target):
        """Perform a melee attack on the target."""
        # Simulating melee attack
        if random.random() < 0.95:  # 95% accuracy
            target.take_damage(self.damage)
            return True
        return False

    def distance_to(self, position):
        """Helper method to calculate distance to a position."""
        if not isinstance(position, Vector2):
            raise ValueError("Position must be a Vector2 instance")
        return self.range - position.magnitude()

class PowerUp:
    """Class representing a power-up in the arena."""
    def __init__(self, power_type, duration=10, effect=None):
        self.power_type = power_type
        self.duration = duration
        self.effect = effect or self._default_effect

    def _default_effect(self, robot):
        """Default effect for power-ups."""
        if self.power_type == PowerUpType.BOOST:
