        elif self.power_type == PowerUpType.INVISIBLE:
            robot.status_effects[StatusEffect.INVISIBLE] = self.duration
        elif self.power_type == PowerUpType.SLOW_DOWN:
            robot.status_effects[StatusEffect.SLOWED] = self.duration

    def apply(self, robot):
        """Apply the power-up effect to a robot."""
        self.effect(robot)

    def expire(self, robot):
