class Robot(ABC):
    """Abstract base class for a robot in CyberArena."""
    def __init__(self, name, robot_type, team, position, health=100, shield=0, speed=1.0, weapons=None):
        self.name = name
        self.robot_type = robot_type
        self.team = team
        self.position = position
        self.health = health
        self.max_health = health
        self.shield = shield
        self.speed = speed
        self.weapons = weapons or []
        self.status_effects = {}  # {StatusEffect: duration}
        self.objective = None
        self.combat_log = []

    def take_damage(self, damage):
        """Handle damage intake, applying shield and health reduction."""
        # Apply shield first
        if self.shield > 0:
            if self.shield >= damage:
                self.shield -= damage
                return
            else:
                damage -= self.shield
                self.shield = 0
        # Then apply to health
        self.health -= damage
        self.combat_log.append(f"{self.name} took {damage} damage. Health: {self.health}")
        if self.health <= 0:
            self.die()

    def die(self):
        """Handle robot death."""
        self.combat_log.append(f"{self.name} has been destroyed!")
        # Notify team
        self.team.robots.remove(self)

    def apply_status_effect(self, effect, duration):
        """Apply a status effect to the robot."""
        if effect in self.status_effects:
            self.status_effects[effect] = max(self.status_effects[effect], duration)
        else:
            self.status_effects[effect] = duration

    def update_status_effects(self, delta_time):
        """Update active status effects."""
        to_remove = []
        for effect, duration in self.status_effects.items():
            duration -= delta_time
            if duration <= 0:
                to_remove.append(effect)
            else:
                self.status_effects[effect] = duration
        for effect in to_remove:
            del self.status_effects[effect]

    def use_power_up(self, power_up):
        """Use a power-up if available."""
        power_up.apply(self)
        self.combat_log.append(f"{self.name} used {power_up.power_type} power-up.")
        return True

    def move_towards(self, target_position, delta_time):
        """Move the robot towards a target position."""
        direction = (target_position - self.position).normalize()
        movement = direction * self.speed * delta_time
        self.position = self.position + movement

    @abstractmethod
    def update(self, delta_time):
        """Abstract method to update robot behavior each frame."""
        pass

    def select_weapon(self, target):
        """Select the best weapon for the current target."""
        for weapon in self.weapons:
            if weapon.fire(target):
                self.combat_log.append(f"{self.name} used {weapon.name} on {target.name}.")
                return True
        return False

    def log_combat(self):
        """Return the combat log for this robot."""
        return self.combat_log

