        self.fire_rate = fire_rate  # attacks per second
        self.weapon_type = weapon_type

    def fire(self, target):
        """Simulate firing at a target."""
        if self.weapon_type in [WeaponType.LASER_GUN, WeaponType.PLASMA_RIFLE]:
            # Ranged weapon
            if self.range >= self.distance_to(target.position):
                return self._ranged_attack(target)
        elif self.weapon_type in [WeaponType.SHOCK_SWORD]:
            # Melee weapon
            if self.range >= self.distance_to(target.position):
                return self._melee_attack(target)
        return False  # out of range or failed to attack

    def _ranged_attack(self, target):
        """Perform a ranged attack on the target."""
        # Simulating ranged attack
        damage = self.damage * (1 - (self.distance_to(target.position) / self.range))
        if random.random() < 0.8:  # 80% accuracy
            target.take_damage(damage)
            return True
        return False

    def _melee_attack(self, target):
        """Perform a melee attack on the target."""
        # Simulating melee attack
        if random.random() < 0.95:  # 95% accuracy
            target.take_damage(self.damage)
            return True
        return False

    def distance_to(self, position):
        """Helper method to calculate distance to a position."""
        if not isinstance(position, Vector2):
            raise ValueError("Position must be a Vector2 instance")
        return self.range - position.magnitude()

