class Arena:
    """Main class representing the CyberArena environment."""
    def __init__(self):
        self.teams = []
        self.robots = []
        self.power_ups = []
        self.objectives = []
        self.combat_log = []
        self.running = False
        self.frame_rate = 60
        self.time = 0
        self.scoreboard = {}

    def add_team(self, team):
        """Add a team to the arena."""
        self.teams.append(team)
        self.robots.extend(team.robots)

    def spawn_power_up(self, power_type, position):
        """Spawn a power-up at a specific position."""
        duration = 10 if power_type == PowerUpType.INVISIBLE else 5
        self.power_ups.append((position, PowerUp(power_type, duration)))

    def update(self, delta_time):
        """Update the entire arena state."""
        # Update all teams
        for team in self.teams:
            team.update(delta_time)
            self.combat_log.extend(team.log_combat())

        # Update power-ups
        for i, (position, power_up) in enumerate(self.power_ups):
            # For simplicity, we'll assume robots collect power-ups automatically if within range
            for robot in self.robots:
                if robot.position.distance_to(position) < 10:
                    power_up.apply(robot)
                    self.combat_log.append(f"{robot.name} collected a {power_up.power_type.value} power-up.")
                    del self.power_ups[i]
                    break

        # Update time
        self.time += delta_time

        # Check for objective completions
        for objective in self.objectives:
            if objective.is_complete():
                self.scoreboard[objective.team.name] = objective.team.score
                self.combat_log.append(f"{objective.team.name} completed their objective! Score: {objective.team.score}")

    def start(self):
        """Start the simulation."""
        self.running = True
        self.time = 0
        try:
            while self.running and self.time < 300:  # 5 minutes max
                start_time = time.time()
                self.update(1 / self.frame_rate)  # 60 FPS
                elapsed_time = time.time() - start_time
                if elapsed_time < 1 / self.frame_rate:
                    time.sleep(1 / self.frame_rate - elapsed_time)
                self.time = time.time() - start_time
        except KeyboardInterrupt:
            print("Simulation stopped by user.")
        finally:
            self.running = False
            self.print_summary()

    def print_summary(self):
        """Print a summary of the simulation."""
        print("\n=== CyberArena Simulation Summary ===")
        print(f"Total simulation time: {self.time:.2f} seconds")
        print("\nScoreboard:")
        for team_name, score in self.scoreboard.items():
            print(f"{team_name}: {score} points")

        print("\nCombat Log:")
        for log in self.combat_log:
            print(log)

        print("\n=== End of Simulation ===")

    def get_team_by_name(self, name):
        """Get a team by name."""
        for team in self.teams:
            if team.name == name:
                return team
        return None

