        """Update active power-ups"""
        to_remove = []
        for power_up in self.active_power_ups:
            power_up.duration -= delta_time
            if power_up.duration <= 0:
                to_remove.append(power_up)
        for power_up in to_remove:
            self.active_power_ups.remove(power_up)

