import copy

class VersionControl:
    def __init__(self):
        self.project_management = ProjectManagement()
        self.history = {}

    def save_version(self, project_id, state):
        if project_id not in self.history:
            self.history[project_id] = []
        self.history[project_id].append(copy.deepcopy(state))
        return {'success': True, 'message': 'Version saved'}

    def get_history(self, project_id):
        return self.history.get(project_id, [])

    def revert_to_version(self, project_id, version_index):
        if project_id not in self.history or version_index < 0 or version_index >= len(self.history[project_id]):
