            self.robot.target_position = self.robot.position + random.choice(list(Direction))
            return

        # Choose target based on role
        if self.robot.role == RobotRole.TANK:
            # Tanks target the strongest enemy
            strongest_enemy = max(attackable_enemies, key=lambda r: r.health)
        elif self.robot.role == RobotRole.DAMAGE_DEALER:
            # Damage dealers target the weakest enemy
            weakest_enemy = min(attackable_enemies, key=lambda r: r.health)
        elif self.robot.role == RobotRole.SUPPORT:
            # Supporters target enemies closest to their team
            closest_to_ally = min(attackable_enemies, 
                                key=lambda r: min(self.robot.position.distance_to(ally.position) 
                                                for ally in self.robot.team.robots if ally != r))
        else:  # SCOUT
            # Scouts target random enemies
            target = random.choice(attackable_enemies)

        # Move toward target if not already in range
        if self.robot.position.distance_to(target.position) > max(weapon.range for weapon in self.robot.weapons.values()):
            self._move_towards_position(target.position)
        else:
            # Attack the target
            self._attack(target)

    def _defending_behavior(self, arena):
        """Behavior when robot is defending"""
        # Stay near the objective and attack enemies that come too close
        if self.robot.team.objective:
            # Stay near the objective
            if self.robot.position.distance_to(self.robot.team.objective.position) > 3:
                self._move_towards_position(self.robot.team.objective.position)
            else:
                # Attack any enemies within range
                enemies_in_range = [enemy for team in arena.teams for enemy in team.robots 
                                  if enemy.team != self.robot.team and 
                                  self.robot.position.distance_to(enemy.position) <= max(weapon.range for weapon in self.robot.weapons.values())]

                if enemies_in_range:
                    self._attack(random.choice(enemies_in_range))
                else:
                    # Patrol around the objective
                    self.robot.state = RobotState.MOVING
                    self.robot.target_position = self.robot.position + random.choice(list(Direction))
        else:
            # If no objective, switch to idle behavior
            self.robot.state = RobotState.IDLE

    def _retreating_behavior(self, arena):
        """Behavior when robot is retreating"""
        # Find the nearest ally to retreat to
        if len(self.robot.team.robots) > 1:
            nearest_ally = min([ally for ally in self.robot.team.robots if ally != self.robot],
                             key=lambda r: self.robot.position.distance_to(r.position))

            if self.robot.position.distance_to(nearest_ally.position) > 3:
                self._move_towards_position(nearest_ally.position)
            else:
                # Stay with the ally and wait for health to recover
                self.robot.state = RobotState.IDLE
        else:
            # If alone, just wait for health to recover
            self.robot.state = RobotState.IDLE

    def _capturing_behavior(self, arena):
        """Behavior when robot is capturing an objective"""
        # Stay at the objective and help capture it
        if self.robot.objective:
            # Attack any enemies that try to stop the capture
            enemies_in_range = [enemy for team in arena.teams for enemy in team.robots 
                              if enemy.team != self.robot.team and 
                              self.robot.position.distance_to(enemy.position) <= max(weapon.range for weapon in self.robot.weapons.values())]

            if enemies_in_range:
                self._attack(random.choice(enemies_in_range))
            else:
                # Help capture the objective
                self.robot.team.objective.progress += 1

                # If another robot is already capturing, stand by
                if any(ally.state == RobotState.CAPTURING for ally in self.robot.team.robots if ally != self.robot):
                    self.robot.state = RobotState.IDLE
        else:
            # If no objective, switch to idle behavior
            self.robot.state = RobotState.IDLE

    def _move_towards_position(self, target_position: Position):
        """Move the robot toward a target position"""
        # Calculate direction to target
        dx = target_position.x - self.robot.position.x
        dy = target_position.y - self.robot.position.y

        # Choose movement direction based on the strongest component
        if abs(dx) > abs(dy):
            direction = Direction.RIGHT if dx > 0 else Direction.LEFT
        else:
            direction = Direction.DOWN if dy > 0 else Direction.UP

        # Move in the chosen direction
        self.robot.position = self.robot.position + direction

    def _attack(self, target):
        """Attack a target with the most suitable weapon"""
        # Choose best weapon for the situation
        if self.robot.position.distance_to(target.position) <= 1:
            # Use melee weapon if very close
            weapon = self.robot.weapons.get(WeaponType.SABER)
        else:
            # Use ranged weapon otherwise
            weapon = self.robot.weapons.get(WeaponType.LASER)

        if weapon and weapon.can_use(time.time()):
            # Apply damage to target
            damage = weapon.damage

            # Apply shield protection if available
            if target.shield > 0:
                target.shield -= damage
                if target.shield < 0:
                    damage = -target.shield
                    target.shield = 0
            else:
                target.health -= damage
                if target.health < 0:
                    target.health = 0

            # Mark the weapon as used
            weapon.use(time.time())

            # Add to memory for learning
            self.memory.append({
                "situation": {
                    "distance": self.robot.position.distance_to(target.position),
                    "weapon": str(weapon),
                    "target_health": target.health,
                },
                "result": {
                    "damage_dealt": damage,
                    "target_alive": target.health > 0
                }
            })

            # Update strategy based on success
            if target.health <= 0:
                self.strategy["kill_" + str(target)] = {
                    "distance": self.robot.position.distance_to(target.position),
                    "weapon": str(weapon)
                }

    def learn_from_experience(self):
        """Process past experiences to improve strategy"""
        # Analyze memory to find patterns
        successful_attacks = [exp for exp in self.memory if exp["result"]["target_alive"] is False]

        if successful_attacks:
            # Find most successful attack pattern
            best_pattern = max(successful_attacks, key=lambda x: x["situation"]["damage_dealt"])

            # Update strategy based on this pattern
            self.strategy["best_attack"] = {
                "distance": best_pattern["situation"]["distance"],
                "weapon": best_pattern["situation"]["weapon"]
            }

            # Clear memory to make room for new experiences
            self.memory = []

    def adapt_difficulty(self, performance: float):
        """Adjust AI difficulty based on robot performance"""
        # For simplicity, just change aggression level based on performance
        if performance > 0.8:
            # High performance = reduce difficulty
            self.robot.attack_speed *= 0.9
            self.robot.movement_speed *= 0.9
        elif performance < 0.3:
            # Low performance = increase difficulty
            self.robot.attack_speed *= 1.1
            self.robot.movement_speed *= 1.1

class Robot:
    """Represents a robot in the arena"""
    def __init__(self, name: str, team: "Team", role: RobotRole):
        self.name = name
        self.team = team
        self.role = role
        self.position = Position(0, 0)
        self.target_position: Optional[Position] = None
        self.state: RobotState = RobotState.IDLE
        self.health: int = 100
        self.max_health: int = 100
        self.shield: int = 0
        self.movement_speed: float = 1.0
        self.attack_speed: float = 1.0
        self.objective: Optional["Objective"] = None
        self.ai = RobotAI(self)
        self.weapons: Dict[WeaponType, Weapon] = {
            WeaponType.LASER: Laser(),
            WeaponType.PLASMA: Plasma(),
            WeaponType.SABER: Saber(),
            WeaponType.MISSILE: Missile()
        }
        self.power_up_effects: List[PowerUp] = []

    def update(self, arena):
        """Update the robot's state and position"""
        self.ai.update(arena)

        # Apply power-up effects
        for power_up in self.power_up_effects:
            power_up.apply_effect(self)

        # Remove expired power-ups
        self.power_up_effects = [p for p in self.power_up_effects if not p.is_expired()]

    def is_alive(self) -> bool:
        """Check if the robot is still alive"""
        return self.health > 0

# --- Game Environment Components ---

class ObjectiveType(Enum):
    """Enum representing different types of objectives"""
    FLAG_CAPTURE = 0
    BASE_DEFENSE = 1
    PAYLOAD_ESCORT = 2
    TERRAIN_CONTROL = 3

class Objective:
    """Represents a game objective that teams need to achieve"""
    def __init__(self, position: Position, objective_type: ObjectiveType):
        self.position = position
        self.objective_type = objective_type
        self.owned_by: Optional["Team"] = None
        self.progress: int = 0
        self.max_progress: int = 100

    def update(self, arena):
        """Update the objective's state"""
        if self.objective_type == ObjectiveType.FLAG_CAPTURE:
            # Check if any robot is at the flag position
            if any(robot.position == self.position and robot.team != self.owned_by for team in arena.teams for robot in team.robots):
                # Change ownership
                self.owned_by = None
                for team in arena.teams:
                    if any(robot.position == self.position for robot in team.robots):
                        self.owned_by = team
                        break
        elif self.objective_type == ObjectiveType.BASE_DEFENSE:
            # Check if the base is under attack
            if any(robot.team != self.owned_by and robot.position.distance_to(self.position) < 3 for team in arena.teams for robot in team.robots):
                # Base is under attack
                self.progress -= 1
                if self.progress <= 0:
                    # Base has been destroyed
                    self.owned_by = None
        elif self.objective_type == ObjectiveType.PAYLOAD_ESCORT:
            # Check if the payload has reached its destination
            if self.owned_by and self.owned_by.objective == self and self.owned_by.objective.progress >= self.max_progress:
                # Payload has reached destination
                self.owned_by.score += 100
                self.owned_by = None
        elif self.objective_type == ObjectiveType.TERRAIN_CONTROL:
            # Check if any team controls this terrain
            if any(robot.position.distance_to(self.position) < 5 for team in arena.teams for robot in team.robots):
                # Determine which team has the most units near this objective
                teams_near = {}
                for team in arena.teams:
                    teams_near[team] = sum(1 for robot in team.robots if robot.position.distance_to(self.position) < 5)

                # Find the team with the most units near this objective
                best_team = max(teams_near, key=teams_near.get)
                if teams_near[best_team] > len(arena.teams) // 2:
                    # This team controls the terrain
                    self.owned_by = best_team
                    self.owned_by.score += 1

class Team:
    """Represents a team of robots"""
    def __init__(self, name: str):
        self.name = name
        self.score = 0
        self.robots: List[Robot] = []
        self.objective: Optional[Objective] = None
        self.power_up_effects: List[PowerUp] = []

    def add_robot(self, robot: Robot):
        """Add a robot to the team"""
        self.robots.append(robot)
        robot.team = self

    def update(self, arena):
        """Update the team's state"""
        # Update all robots in the team
        for robot in self.robots:
            robot.update(arena)

        # Remove dead robots
        self.robots = [robot for robot in self.robots if robot.is_alive()]

        # Update power-up effects
        for power_up in self.power_up_effects:
            power_up.apply_effect(self)

        # Remove expired power-ups
        self.power_up_effects = [p for p in self.power_up_effects if not p.is_expired()]

        # Update team objective
        if self.objective:
            self.objective.update(arena)

class Arena:
    """Main class representing the CyberArena battlefield"""
    def __init__(self, size: Tuple[int, int] = (20, 20)):
        self.size = size
        self.teams: List[Team] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List["Hazard"] = []
        self.running = True
        self.game_time = 0

    def add_team(self, team: Team):
        """Add a team to the arena"""
        self.teams.append(team)

    def add_objective(self, objective: Objective):
        """Add an objective to the arena"""
        self.objectives.append(objective)

    def add_power_up(self, power_up: PowerUp):
        """Add a power-up to the arena"""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard: "Hazard"):
        """Add a hazard to the arena"""
        self.hazards.append(hazard)

    def update(self):
        """Main update loop for the arena"""
        if not self.running:
            return

        # Update game time
        self.game_time += 1

        # Update all teams
        for team in self.teams:
            team.update(self)

        # Update all objectives
        for objective in self.objectives:
            objective.update(self)

        # Update all power-ups
        for power_up in self.power_ups:
            power_up.update(self)

        # Update all hazards
        for hazard in self.hazards:
            hazard.update(self)

        # Check if any team has won
        if self._check_for_winner():
            self.running = False

    def _check_for_winner(self) -> bool:
        """Check if any team has won the game"""
        # Check if any team has reached the win condition
        for team in self.teams:
            if team.score >= 500:  # Winning score threshold
                print(f"{team.name} has won the battle!")
                return True

        return False

    def spawn_power_ups(self):
        """Randomly spawn power-ups in the arena"""
        # For demonstration, just spawn one power-up every 10 seconds
        if self.game_time % 10 == 0:
            power_up_type = random.choice(list(PowerUpType))

            # Choose a random position not occupied by an objective
            while True:
                x = random.randint(0, self.size[0] - 1)
                y = random.randint(0, self.size[1] - 1)
                position = Position(x, y)

                # Check if this position is already an objective
                if not any(obj.position == position for obj in self.objectives):
                    break

            # Create and add the power-up
            if power_up_type == PowerUpType.SPEED_BOOST:
                self.add_power_up(SpeedBoost(position))
            elif power_up_type == PowerUpType.SHIELD:
                self.add_power_up(Shield(position))
            elif power_up_type == PowerUpType.DAMAGE_BOOST:
                self.add_power_up(DamageBoost(position))
            elif power_up_type == PowerUpType.REPAIR:
                self.add_power_up(Repair(position))
            elif power_up_type == PowerUpType.TEAM_BUFF:
                self.add_power_up(TeamBuff(position))

    def spawn_hazards(self):
        """Randomly spawn hazards in the arena"""
        # For demonstration, just spawn one hazard every 20 seconds
        if self.game_time % 20 == 0:
            # Choose a random position not occupied by an objective or power-up
            while True:
                x = random.randint(0, self.size[0] - 1)
                y = random.randint(0, self.size[1] - 1)
                position = Position(x, y)

                # Check if this position is already occupied
                if not any(obj.position == position for obj in self.objectives + self.power_ups):
                    break

            # Create and add a hazard
            self.add_hazard(Hazard(position, hazard_type=HazardType.EXPLOSION))

class HazardType(Enum):
    """Enum representing different types of hazards"""
    EXPLOSION = 0
    ACID = 1
    ELECUTICAL = 2
    MAGNETIC = 3

class Hazard:
    """Represents a hazard in the arena that can affect robots"""
    def __init__(self, position: Position, hazard_type: HazardType, duration: float = 10.0):
        self.position = position
        self.hazard_type = hazard_type
        self.duration = duration
        self.created_at = time.time()
        self.effects: List["HazardEffect"] = []

    def update(self, arena):
        """Update the hazard's state"""
        # Apply effects to nearby robots
        for robot in [robot for team in arena.teams for robot in team.robots]:
            if robot.position.distance_to(self.position) <= 2:
                self._apply_effect(robot)

        # Remove expired hazard
        if time.time() - self.created_at > self.duration:
            arena.hazards.remove(self)

    def _apply_effect(self, robot):
        """Apply the hazard's effect to a robot"""
        if self.hazard_type == HazardType.EXPLOSION:
            # Explosion deals damage to nearby robots
            robot.health -= 15
        elif self.hazard_type == HazardType.ACID:
            # Acid gradually damages robots over time
            robot.health -= 5
            # Add effect if it doesn't already exist
            if not any(isinstance(e, AcidEffect) for e in robot.power_up_effects):
                robot.power_up_effects.append(AcidEffect(self.position))
        elif self.hazard_type == HazardType.ELECUTICAL:
            # Electrical hazard stuns robots for a short duration
            robot.movement_speed *= 0.5
            robot.attack_speed *= 0.5
            # Add effect if it doesn't already exist
            if not any(isinstance(e, ElectricalEffect) for e in robot.power_up_effects):
                robot.power_up_effects.append(ElectricalEffect(self.position))
        elif self.hazard_type == HazardType.MAGNETIC:
            # Magnetic hazard pulls robots toward it
            robot.position = self.position + (robot.position - self.position).normalized()
            # Add effect if it doesn't already exist
            if not any(isinstance(e, MagneticEffect) for e in robot.power_up_effects):
                robot.power_up_effects.append(MagneticEffect(self.position))

class HazardEffect:
    """Base class for hazard effects"""
    def __init__(self, position: Position):
        self.position = position
        self.duration = 5.0
        self.created_at = time.time()

    def update(self, robot):
        """Update the effect on the robot"""
        if time.time() - self.created_at > self.duration:
            self._remove_effect(robot)

    @abstractmethod
    def _remove_effect(self, robot):
        """Remove the effect from the robot"""
        pass

class AcidEffect(HazardEffect):
    """Effect for the acid hazard"""
    def _remove_effect(self, robot):
        # Restore normal movement and attack speed
        robot.movement_speed = 1.0
        robot.attack_speed = 1.0
        # Remove from robot's effects list
        if self in robot.power_up_effects:
            robot.power_up_effects.remove(self)

class ElectricalEffect(HazardEffect):
    """Effect for the electrical hazard"""
    def _remove_effect(self, robot):
        # Restore normal movement and attack speed
        robot.movement_speed = 1.0
        robot.attack_speed = 1.0
        # Remove from robot's effects list
        if self in robot.power_up_effects:
            robot.power_up_effects.remove(self)

class MagneticEffect(HazardEffect):
    """Effect for the magnetic hazard"""
    def _remove_effect(self, robot):
        # Restore normal movement and attack speed
        robot.movement_speed = 1.0
        robot.attack_speed = 1.0
        # Remove from robot's effects list
        if self in robot.power_up_effects:
            robot.power_up_effects.remove(self)

