def initialize_arena() -> Arena:
    """Initialize and return a configured CyberArena instance"""
    arena = Arena(size=(20, 20))

    # Create and add teams
    team_blue = Team("Blue Team")
    team_red = Team("Red Team")

    arena.add_team(team_blue)
    arena.add_team(team_red)

    # Create and add robots to teams
    # Blue Team - Balanced composition
    team_blue.add_robot(Robot("Blue Tank", team_blue, RobotRole.TANK))
    team_blue.add_robot(Robot("Blue Damage", team_blue, RobotRole.DAMAGE_DEALER))
    team_blue.add_robot(Robot("Blue Support", team_blue, RobotRole.SUPPORT))
    team_blue.add_robot(Robot("Blue Scout", team_blue, RobotRole.SCOUT))

    # Red Team - Balanced composition
    team_red.add_robot(Robot("Red Tank", team_red, RobotRole.TANK))
    team_red.add_robot(Robot("Red Damage", team_red, RobotRole.DAMAGE_DEALER))
    team_red.add_robot(Robot("Red Support", team_red, RobotRole.SUPPORT))
    team_red.add_robot(Robot("Red Scout", team_red, RobotRole.SCOUT))

    # Set starting positions for robots
    for i, robot in enumerate(team_blue.robots):
        robot.position = Position(2, i*2)

    for i, robot in enumerate(team_red.robots):
        robot.position = Position(17, i*2)

    # Create and add objectives
    flag_capture = Objective(Position(10, 10), ObjectiveType.FLAG_CAPTURE)
    base_defense = Objective(Position(5, 15), ObjectiveType.BASE_DEFENSE)
    payload_escort = Objective(Position(15, 5), ObjectiveType.PAYLOAD_ESCORT)

    arena.add_objective(flag_capture)
    arena.add_objective(base_defense)
    arena.add_objective(payload_escort)

    # Assign objectives to teams
    team_blue.objective = flag_capture
    team_red.objective = base_defense

    return arena

def run_arena(arena: Arena):
    """Main loop for running the CyberArena simulation"""
    print("Starting CyberArena battle!")
    print(f"Teams: {[team.name for team in arena.teams]}")
    print(f"Objectives: {[obj.objective_type.name for obj in arena.objectives]}")
    print(f"Size: {arena.size[0]}x{arena.size[1]}")

    try:
        while arena.running:
            # Update the arena
            arena.update()

            # Spawn power-ups and hazards
            arena.spawn_power_ups()
            arena.spawn_hazards()

            # Print game state for demonstration
            if arena.game_time % 5 == 0:
                print(f"\nTime: {arena.game_time}s")
                print("Team scores:")
                for team in arena.teams:
                    print(f"  {team.name}: {team.score}")

                print("Objectives:")
                for objective in arena.objectives:
                    print(f"  {objective.objective_type.name} at ({objective.position.x}, {objective.position.y}): {objective.owned_by.name if objective.owned_by else 'Unowned'}")

                print("Alive robots:")
                for team in arena.teams:
                    alive_robots = [robot.name for robot in team.robots if robot.is_alive()]
                    print(f"  {team.name}: {len(alive_robots)}/{len(team.robots)} robots alive - {alive_robots}")

                # Add a small delay for more readable output
                time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nSimulation stopped by user")
    finally:
        print("Final scores:")
        for team in arena.teams:
            print(f"  {team.name}: {team.score}")

        if not arena.running:
            for team in arena.teams:
                if team.score >= 500:
                    print(f"\n{team.name} has won the battle!")

