# Chain Reaction - Multi-Agent Collaborative Puzzle Game

import random
import json
import time
from collections import defaultdict

# ========== [1] CORE GAME COMPONENTS ==========

class Node:
    """
    Represents a node in the Chain Reaction grid.
    Each node has an activation requirement and dependencies.
    """
    def __init__(self, position, activation_count=1, requires=None):
        self.position = position
        self.activation_count = activation_count
        self.requires = requires if requires is not None else []
        self.activated = False

    def activate(self, activated_nodes):
        if all(node in activated_nodes for node in self.requires) and self.activation_count > 0:
            self.activated = True
            self.activation_count -= 1
            return True
        return False

class Player:
    """
    Represents a player in the game, responsible for a specific area of the grid.
    """
    def __init__(self, name, area):
        self.name = name
        self.area = area  # List of (x, y) positions assigned to this player

    def can_activate(self, node):
        return node.position in self.area and not node.activated

class Level:
    """
    Represents a level in the game with a grid, nodes, and dependencies.
    """
    def __init__(self, size=(10, 10), difficulty=1):
        self.size = size
        self.nodes = self._generate_nodes(difficulty)
        self.players = []  # List of Player objects
        self.timer = 0
        self.start_time = None
        self.save_path = "game_save.json"
        self.is_solved = False

    def _generate_nodes(self, difficulty):
        """
        Generates a grid of nodes with increasing complexity as difficulty increases.
        Each node has dependencies and activation requirements.
        """
        nodes = {}
        for x in range(self.size[0]):
            for y in range(self.size[1]):
                activation_count = random.randint(1, difficulty + 1)
                # Randomly assign dependencies based on difficulty
                requires = []
                if difficulty >= 2:
                    for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nx, ny = x + dx, y + dy
                        if (nx, ny) in nodes:
                            requires.append(nodes[(nx, ny)])
                nodes[(x, y)] = Node((x, y), activation_count, requires)
        return nodes

    def assign_players(self, player_areas):
        self.players = [
            Player(name=f"Player {i+1}", area=area) for i, area in enumerate(player_areas)
        ]

    def get_player_for_position(self, position):
        for player in self.players:
            if position in player.area:
                return player
        return None

    def activate_node(self, position):
        node = self.nodes.get(position)
        if node and node.can_activate(self.nodes):
            node.activate(self.nodes)
            return True
        return False

    def check_solved(self):
        return all(node.activated for node in self.nodes.values())

    def start_timer(self):
        self.start_time = time.time()

    def stop_timer(self):
        self.timer = round(time.time() - self.start_time, 2)

    def save_progress(self):
        save_data = {
            "nodes": {
                (x, y): {
                    "activated": node.activated,
                    "activation_count": node.activation_count
                } for (x, y), node in self.nodes.items()
            },
            "timer": self.timer
        }
        with open(self.save_path, "w") as f:
            json.dump(save_data, f)

    def load_progress(self):
        try:
            with open(self.save_path, "r") as f:
                save_data = json.load(f)
            self.timer = save_data.get("timer", 0)
            for (x, y), data in save_data["nodes"].items():
                node = self.nodes.get((x, y))
                if node:
                    node.activated = data["activated"]
                    node.activation_count = data["activation_count"]
        except Exception as e:
            print(f"Error loading progress: {e}")

    def get_hint(self):
        for node in self.nodes.values():
            if not node.activated and node.can_activate(self.nodes):
                return f"Try activating node at position {node.position} first."
        return "No hint available. All nodes are already activated or cannot be activated yet."

# ========== [2] GAME INITIALIZATION AND UTILITIES ==========

class Game:
    """
    Main game class to manage level progression, players, and game state.
    """
    def __init__(self):
        self.levels = []
        self.current_level_index = 0

    def add_level(self, level):
        self.levels.append(level)

    def start(self):
        if not self.levels:
            print("No levels defined.")
            return
        self.current_level_index = 0
        self.play_level()

    def play_level(self):
        if self.current_level_index >= len(self.levels):
            print("All levels completed!")
            return

        level = self.levels[self.current_level_index]
        level.start_timer()
        print(f"\n--- Starting Level {self.current_level_index + 1} ---")
        print(f"Grid Size: {level.size}, Difficulty: {self.current_level_index + 1}")
        print(f"Players: {[p.name for p in level.players]}")
        print("Use 'activate (x, y)' to activate a node.")
        print("Type 'hint' for assistance.")
        print("Type 'save' to save progress.")
        print("Type 'quit' to exit the level.")

        while not level.is_solved:
            try:
                cmd = input("\n> ").strip()
                if cmd.lower() == "quit":
                    break
                elif cmd.lower() == "hint":
                    print(level.get_hint())
                elif cmd.lower() == "save":
                    level.save_progress()
                    print("Progress saved.")
                elif cmd.startswith("activate "):
                    pos = eval(cmd.split(" ")[1])
                    if level.activate_node(pos):
                        print(f"Node at {pos} activated.")
                        if level.check_solved():
                            level.stop_timer()
                            print(f"Level {self.current_level_index + 1} solved in {level.timer:.2f} seconds!")
                            self.current_level_index += 1
                            level.is_solved = True
                            break
                    else:
                        print(f"Node at {pos} could not be activated.")
                else:
                    print("Invalid command.")
            except Exception as e:
                print(f"Error: {e}")

        if level.is_solved:
            self.play_level()

# ========== [3] DEMO SETUP ==========

def setup_game():
    game = Game()

    # Level 1: Simple grid with 2 players
    level1 = Level(size=(4, 4), difficulty=1)
    player1_area = [(0, 0), (1, 0), (0, 1), (0, 2)]
    player2_area = [(1, 1), (1, 2), (2, 1), (2, 2)]
    level1.assign_players([player1_area, player2_area])
    game.add_level(level1)

    # Level 2: Larger grid with more complex dependencies
    level2 = Level(size=(5, 5), difficulty=2)
    player1_area = [(0, 0), (1, 0), (0, 1), (0, 2), (0, 3)]
    player2_area = [(1, 1), (1, 2), (1, 3), (2, 2), (2, 3)]
    player3_area = [(2, 0), (3, 0), (3, 1), (3, 2), (3, 3)]
    level2.assign_players([player1_area, player2_area, player3_area])
    game.add_level(level2)

    return game

if __name__ == "__main__":
    game = setup_game()
    game.start()"
}
