        # Check for objective progress
        if objective_status != "complete":
            decision = self.decision_tree["objective_progress"][objective_status]
            if decision == "continue":
                self.continue_objective(arena)
            elif decision == "search":
                self.search_objective(arena)

    def apply_power_ups(self, delta_time):
        """Apply active power-up effects to the robot."""
        for power_up in self.power_ups[:]:  # Iterate over a copy to allow removal
            power_up.apply_effect(self, delta_time)
            power_up.duration -= delta_time
            if power_up.duration <= 0:
                self.power_ups.remove(power_up)

    def update_position(self, delta_time):
        """Update the robot's position based on movement vector and terrain."""
        # Simple movement logic with terrain consideration
        self.velocity += self.movement_vector * delta_time
        # Apply friction
        self.velocity *= 0.95
        # Update position
        self.x += self.velocity[0] * delta_time
        self.y += self.velocity[1] * delta_time

        # Store last position for pathing
        self.last_position = (self.x, self.y)

    def attack(self, arena):
        """Handle attack behavior based on the robot's weapon type."""
        if self.attack_cooldown <= 0:
            if self.weapon == WeaponType.LASER:
                self.laser_attack(arena)
            elif self.weapon == WeaponType.MISSILE:
                self.missile_attack(arena)
            elif self.weapon == WeaponType.PLASMA:
                self.plasma_attack(arena)
            elif self.weapon == WeaponType.WRENCH:
                self.wrench_attack(arena)
            elif self.weapon == WeaponType.SWORD:
                self.sword_attack(arena)
            self.attack_cooldown = 1.0  # Reset cooldown

    def laser_attack(self, arena):
        """Perform a laser attack on the nearest enemy."""
        target = self.find_closest_enemy(arena)
        if target:
            # Calculate damage based on distance
            distance = np.hypot(target.x - self.x, target.y - self.y)
            damage = max(10, 50 - distance/5)
            target.take_damage(damage, self)

    def missile_attack(self, arena):
        """Launch a missile at a random enemy."""
        targets = [obj for obj in arena.objects if isinstance(obj, Robot) and obj.team != self.team]
        if targets:
            target = random.choice(targets)
            missile = Missile(self.x, self.y, target)
            arena.add_object(missile)

    def plasma_attack(self, arena):
        """Release a plasma wave that affects all nearby enemies."""
        affected_robots = []
        for obj in arena.objects:
            if isinstance(obj, Robot) and obj.team != self.team:
                distance = np.hypot(obj.x - self.x, obj.y - self.y)
                if distance < 200:
                    affected_robots.append(obj)

        if affected_robots:
            damage = 15
            for robot in affected_robots:
                robot.take_damage(damage, self)
            # Create visual effects for plasma attack
            plasma_wave = ParticleEffect(self.x, self.y, "plasma", 200, 20)
            arena.add_object(plasma_wave)

    def wrench_attack(self, arena):
        """Perform a melee attack with a wrench."""
        for obj in arena.objects:
            if isinstance(obj, Robot) and obj.team != self.team:
                distance = np.hypot(obj.x - self.x, obj.y - self.y)
                if distance < 50:
                    # Calculate damage based on robot's strength
                    damage = random.randint(15, 30)
                    obj.take_damage(damage, self)
                    # Create visual effects for wrench attack
                    wrench_effect = ParticleEffect(obj.x, obj.y, "wrench", 50, 10)
                    arena.add_object(wrench_effect)
                    break

    def sword_attack(self, arena):
        """Perform a melee sword attack on nearby enemies."""
        for obj in arena.objects:
            if isinstance(obj, Robot) and obj.team != self.team:
                distance = np.hypot(obj.x - self.x, obj.y - self.y)
                if distance < 40:
                    # Calculate damage based on robot's strength
                    damage = random.randint(20, 40)
                    obj.take_damage(damage, self)
                    # Create visual effects for sword attack
                    sword_effect = ParticleEffect(obj.x, obj.y, "sword", 40, 15)
                    arena.add_object(sword_effect)
                    break

    def take_damage(self, amount, attacker):
        """Handle taking damage from an attack."""
        # Calculate damage reduction from armor
        reduced_damage = max(0, amount - self.armor)
        self.armor = max(0, self.armor - amount)
        self.health -= reduced_damage

        # Check if robot is destroyed
        if self.health <= 0:
            self.die(attacker)

        # Create visual effects for damage
        damage_effect = ParticleEffect(self.x, self.y, "damage", 30, 10)
        arena.add_object(damage_effect)

        # Play sound effect for damage
        play_sound("damage")

    def die(self, attacker):
        """Handle robot death and scoring."""
        self.active = False
        # Give kill credit to attacker
        if attacker:
            attacker.score += 10
            attacker.experience += 15

        # Play death sound effect
        play_sound("death")

        # Create explosion visual
        explosion = ParticleEffect(self.x, self.y, "explosion", 150, 30)
        arena.add_object(explosion)

    def retreat(self):
        """Handle retreating behavior."""
        # Move towards team base
        self.movement_vector = np.array([
            arena.team_bases[self.team]["x"] - self.x,
            arena.team_bases[self.team]["y"] - self.y
        ])
        self.movement_vector = normalize_vector(self.movement_vector)

    def defend(self):
        """Handle defending behavior."""
        # Stay near team base
        base_position = arena.team_bases[self.team]
        distance = np.hypot(base_position["x"] - self.x, base_position["y"] - self.y)
        if distance > 100:
            self.movement_vector = np.array([
                base_position["x"] - self.x,
                base_position["y"] - self.y
            ])
            self.movement_vector = normalize_vector(self.movement_vector)
        else:
            self.movement_vector = np.array([0.0, 0.0])

    def fight(self, arena):
        """Handle fighting behavior."""
        target = self.find_closest_enemy(arena)
        if target:
            # Move towards the enemy
            vector_to_target = np.array([target.x - self.x, target.y - self.y])
            distance = np.linalg.norm(vector_to_target)
            if distance > 100:
                self.movement_vector = normalize_vector(vector_to_target)
            else:
                self.movement_vector = np.array([0.0, 0.0])
                self.attack(arena)

    def continue_objective(self, arena):
        """Handle continuing with the objective."""
        # Simple pathing towards objective
        objective_position = arena.objective_position
        vector_to_objective = np.array([objective_position[0] - self.x, objective_position[1] - self.y])
        self.movement_vector = normalize_vector(vector_to_objective)

    def search_objective(self, arena):
        """Handle searching for the objective."""
        # Random movement in search of objective
        self.movement_vector = np.array([random.uniform(-1, 1), random.uniform(-1, 1)])

    def find_closest_enemy(self, arena):
        """Find the closest enemy robot."""
        closest_distance = float('inf')
        closest_enemy = None

        for obj in arena.objects:
            if isinstance(obj, Robot) and obj.team != self.team:
                distance = np.hypot(obj.x - self.x, obj.y - self.y)
                if distance < closest_distance:
                    closest_distance = distance
                    closest_enemy = obj

        return closest_enemy

    def check_for_enemies(self, arena):
        """Check if any enemies are nearby."""
        for obj in arena.objects:
            if isinstance(obj, Robot) and obj.team != self.team:
                distance = np.hypot(obj.x - self.x, obj.y - self.y)
                if distance < 200:
                    return True
        return False

    def collect_power_up(self, power_up):
        """Collect a power-up and add it to the robot's inventory."""
        self.power_ups.append(power_up)
        # Play power-up collection sound
        play_sound("powerup")

    def update_experience(self):
        """Update robot's experience and potentially improve skills."""
        if self.experience >= 100:
            self.experience = 0
            # Improve random skill
            skill_to_improve = random.choice(list(self.skills.keys()))
            self.skills[skill_to_improve] += 1

# Power-up class representing temporary boost items
class PowerUp(ArenaObject):
    def __init__(self, x, y, power_type):
        super().__init__(x, y, 30)
        self.power_type = power_type
        self.duration = 10  # Duration in seconds
        self.collected = False

    def apply_effect(self, robot, delta_time):
        """Apply the power-up's effect to the robot."""
        if self.power_type == PowerUpType.SHIELD:
            robot.armor = min(robot.max_armor, robot.armor + 10)
        elif self.power_type == PowerUpType.SPEED:
            robot.movement_vector *= 1.5
        elif self.power_type == PowerUpType.DAMAGE:
            robot.skills["damage"] += 0.5
        elif self.power_type == PowerUpType.HEAL:
            robot.health = min(robot.max_health, robot.health + 20)
        elif self.power_type == PowerUpType.JUMP:
            robot.velocity[1] = 15  # Apply upward force for jump
        elif self.power_type == PowerUpType.TEAM_BUFF:
            # Apply to all teammates
            for obj in arena.objects:
                if isinstance(obj, Robot) and obj.team == robot.team:
                    obj.skills["damage"] += 0.3
                    obj.skills["heal"] += 0.2

    def update(self, delta_time):
        """Update the power-up's state."""
        super().update(delta_time)

        # If collected, remove it from the arena
        if self.collected:
            self.active = False

# Weapon class representing different types of attacks
class Weapon:
