                if isinstance(obj, Robot) and obj.team != self.target.team:
                    distance = np.hypot(obj.x - self.x, obj.y - self.y)
                    if distance < closest_distance:
                        closest_distance = distance
                        new_target = obj

            if new_target:
                self.target = new_target
            else:
                self.active = False
                return

