    SWORD = "Sword"        # Close-range melee

# Enum for different power-up types
class PowerUpType(Enum):
    SHIELD = "Shield"      # Temporarily increases armor
    SPEED = "Speed"        # Temporarily increases movement speed
    DAMAGE = "Damage"      # Temporarily increases attack power
    HEAL = "Heal"          # Restores health
    JUMP = "Jump"          # Increases jump height
    TEAM_BUFF = "Team Buff" # Benefits entire team

# Enum for different environmental hazards
class HazardType(Enum):
    LAVA = "Lava"          # Continuous damage
