# Base class for all objects in the arena
class ArenaObject:
    def __init__(self, x, y, size):
        self.x = x
        self.y = y
        self.size = size
        self.velocity = np.array([0.0, 0.0])
        self.rotation = 0.0
        self.active = True

    def update(self, delta_time):
        """Update the object's position based on velocity and time."""
        self.x += self.velocity[0] * delta_time
        self.y += self.velocity[1] * delta_time

    def is_active(self):
        """Check if the object is still active in the arena."""
        return self.active

    def destroy(self):
        """Mark the object as inactive."""
        self.active = False

# Robot class representing AI-controlled agents
class Robot(ArenaObject):
