# Missile class for projectile weapons
class Missile(ArenaObject):
    def __init__(self, x, y, target):
        super().__init__(x, y, 10)
        self.target = target
        self.velocity = np.array([0.0, 0.0])
        self.speed = 200  # Speed in pixels per second
        self.explosion_radius = 50
        self.damage = 40
        self.lifetime = 3.0  # Seconds before missile disappears
        self.remaining_time = self.lifetime

    def update(self, delta_time):
        """Update the missile's position and behavior."""
        super().update(delta_time)
        self.remaining_time -= delta_time

        # Calculate direction towards target
        if self.target.is_active():
            direction = np.array([self.target.x - self.x, self.target.y - self.y])
            direction = normalize_vector(direction)
            self.velocity = direction * self.speed
        else:
            # If target is destroyed, find new target
            new_target = None
            closest_distance = float('inf')

            for obj in arena.objects:
                if isinstance(obj, Robot) and obj.team != self.target.team:
                    distance = np.hypot(obj.x - self.x, obj.y - self.y)
                    if distance < closest_distance:
                        closest_distance = distance
                        new_target = obj

            if new_target:
                self.target = new_target
            else:
                self.active = False
                return

        # Check for collisions
        if self.check_collisions():
            self.explode()
            self.active = False
        elif self.remaining_time <= 0:
            self.active = False

    def check_collisions(self):
        """Check if the missile has hit anything."""
        # Check for collision with robots
        for obj in arena.objects:
            if obj != self and obj.is_active():
                distance = np.hypot(obj.x - self.x, obj.y - self.y)
                if distance < (obj.size + self.size):
                    return True
        # Check if missile is out of bounds
        if not (0 < self.x < SCREEN_WIDTH and 0 < self.y < SCREEN_HEIGHT):
            return True
        return False

    def explode(self):
        """Handle missile explosion."""
        # Deal damage to nearby robots
        for obj in arena.objects:
            if isinstance(obj, Robot) and obj.team != self.target.team:
                distance = np.hypot(obj.x - self.x, obj.y - self.y)
                if distance < self.explosion_radius:
                    damage = max(0, self.damage - distance/2)
                    obj.take_damage(damage, self)

        # Create explosion visual effect
        explosion = ParticleEffect(self.x, self.y, "explosion", 100, 20)
        arena.add_object(explosion)

        # Play explosion sound
        play_sound("explosion")

# Particle effect class for visual effects
class ParticleEffect(ArenaObject):
    def __init__(self, x, y, effect_type, size, duration):
        super().__init__(x, y, size)
        self.effect_type = effect_type
        self.lifetime = duration
        self.remaining_time = duration
        self.particles = []
        self.create_particles()

    def create_particles(self):
        """Create particles for the effect based on type."""
        if self.effect_type == "plasma":
            num_particles = 100
            for _ in range(num_particles):
                angle = random.uniform(0, 2 * np.pi)
                radius = random.uniform(0, 20)
                speed = random.uniform(0.5, 2.0)
                self.particles.append({
                    "x": self.x + radius * np.cos(angle),
                    "y": self.y + radius * np.sin(angle),
                    "vx": speed * np.cos(angle),
                    "vy": speed * np.sin(angle),
                    "life": random.uniform(0.5, 1.5)
                })
        elif self.effect_type == "wrench":
            num_particles = 20
            for _ in range(num_particles):
                self.particles.append({
                    "x": self.x + random.uniform(-10, 10),
                    "y": self.y + random.uniform(-10, 10),
                    "vx": random.uniform(-3, 3),
                    "vy": random.uniform(-3, 3),
                    "life": random.uniform(0.3, 0.8)
                })
        elif self.effect_type == "sword":
            num_particles = 30
            for _ in range(num_particles):
                angle = random.uniform(0, np.pi/2)
                self.particles.append({
                    "x": self.x + random.uniform(-10, 10),
                    "y": self.y + random.uniform(-10, 10),
                    "vx": random.uniform(-2, 2),
                    "vy": random.uniform(-2, 2),
                    "life": random.uniform(0.4, 1.0)
                })
        elif self.effect_type == "damage":
            num_particles = 10
            for _ in range(num_particles):
                self.particles.append({
                    "x": self.x + random.uniform(-5, 5),
                    "y": self.y + random.uniform(-5, 5),
                    "vx": random.uniform(-1, 1),
                    "vy": random.uniform(-1, 1),
                    "life": random.uniform(0.2, 0.6)
                })
        elif self.effect_type == "explosion":
            num_particles = 150
            for _ in range(num_particles):
                angle = random.uniform(0, 2 * np.pi)
                speed = random.uniform(1.0, 3.0)
                self.particles.append({
                    "x": self.x,
                    "y": self.y,
                    "vx": speed * np.cos(angle),
                    "vy": speed * np.sin(angle),
                    "life": random.uniform(0.5, 1.5)
                })

    def update(self, delta_time):
        """Update the particle effect."""
        super().update(delta_time)
        self.remaining_time -= delta_time

        # Update all particles
        for particle in self.particles:
            particle["x"] += particle["vx"] * delta_time
            particle["y"] += particle["vy"] * delta_time
            particle["life"] -= delta_time

        # Remove particles that have expired
        self.particles = [p for p in self.particles if p["life"] > 0]

        # If all particles are gone, destroy the effect
        if not self.particles or self.remaining_time <= 0:
            self.active = False

# Arena class representing the battlefield
class Arena:
    def __init__(self):
        self.objects = []
        self.teams = {}
        self.team_bases = {}
        self.objective = random.choice(list(Objective))
        self.objective_position = self.set_objective_position()
        self.power_ups = []
        self.hazards = []
        self.difficulty_level = 1
        self.time_elapsed = 0
        self.scores = defaultdict(int)
        self.winning_team = None

        # Initialize teams
        for i in range(MAX_TEAMS):
            team_name = f"Team {chr(65+i)}"
            self.teams[team_name] = {
                "score": 0,
                "robots": [],
                "base": None
            }
            self.team_bases[team_name] = self.set_team_base(team_name)

        # Create initial objects
        self.create_robots()
        self.create_power_ups()
        self.create_hazards()

        # Start the update loop in a separate thread
        self.update_thread = threading.Thread(target=self.run_simulation)
        self.update_thread.start()

    def set_team_base(self, team_name):
        """Set a random base position for each team."""
        # For simplicity, place teams in corners
        if team_name == "Team A":
            return {"x": 100, "y": 100}
        elif team_name == "Team B":
            return {"x": 900, "y": 100}
        elif team_name == "Team C":
            return {"x": 100, "y": 700}
        else:  # Team D
            return {"x": 900, "y": 700}

    def set_objective_position(self):
        """Set the position of the objective based on its type."""
        if self.objective == Objective.CTF:
            # Place objective in the center
            return (SCREEN_WIDTH//2, SCREEN_HEIGHT//2)
        elif self.objective == Objective.DEFEND:
            # Place objective randomly near a team base
            team = random.choice(list(self.team_bases.values()))
            return (team["x"] + random.randint(-100, 100), team["y"] + random.randint(-100, 100))
        elif self.objective == Objective.ESCORT:
            # Place objective at a team's base
            team = random.choice(list(self.team_bases.values()))
            return (team["x"], team["y"])
        else:  # KING
            # Place objective randomly in the center area
            return (SCREEN_WIDTH//2 + random.randint(-150, 150), SCREEN_HEIGHT//2 + random.randint(-150, 150))

    def create_robots(self):
        """Create and add robots to the arena."""
        for team_name in self.teams:
            team = self.teams[team_name]
            team_base = self.team_bases[team_name]

            # Create 5 robots per team
            for i in range(5):
                robot_id = f"{team_name}R{i+1}"
                robot = Robot(team_base["x"], team_base["y"], team_name, robot_id)
                self.objects.append(robot)
                team["robots"].append(robot)

    def create_power_ups(self):
        """Create and add power-ups to the arena."""
        power_up_types = list(PowerUpType)
        for i in range(MAX_POWERUPS):
            power_type = power_up_types[i % len(power_up_types)]
            x = random.randint(0, SCREEN_WIDTH)
            y = random.randint(0, SCREEN_HEIGHT)
            power_up = PowerUp(x, y, power_type)
            self.objects.append(power_up)
            self.power_ups.append(power_up)

    def create_hazards(self):
        """Create and add hazards to the arena."""
        hazard_types = list(HazardType)
        for i in range(MAX_HAZARDS):
            hazard_type = hazard_types[i % len(hazard_types)]
            x = random.randint(0, SCREEN_WIDTH)
            y = random.randint(0, SCREEN_HEIGHT)
            self.add_hazard(x, y, hazard_type)

    def add_hazard(self, x, y, hazard_type):
        """Add a hazard to the arena."""
        if hazard_type == HazardType.LAVA:
            hazard = Lava(x, y)
        elif hazard_type == HazardType.ICE:
            hazard = Ice(x, y)
        elif hazard_type == HazardType.ELECTRIC:
            hazard = Electric(x, y)
        elif hazard_type == HazardType.TOXIC:
            hazard = Toxic(x, y)
        elif hazard_type == HazardType.TRAP:
            hazard = Trap(x, y)
        else:
            # Default to lava if type is unknown
            hazard = Lava(x, y)

        self.objects.append(hazard)
        self.hazards.append(hazard)

    def run_simulation(self):
        """Main simulation loop that updates the arena state."""
        start_time = time.time()
        while self.time_elapsed < SIMULATION_DURATION and not self.is_game_over():
            delta_time = min(UPDATE_INTERVAL, time.time() - start_time)
            start_time = time.time()

            # Update all objects
            for obj in self.objects[:]:  # Iterate over a copy to allow removal
                if obj.is_active():
                    obj.update(delta_time)
                else:
                    self.objects.remove(obj)

            # Check for collisions and power-up pickups
            self.check_collisions()

            # Update time
            self.time_elapsed += delta_time

            # Update difficulty based on performance
            self.update_difficulty()

            # Update scores and check for objective progress
            self.update_scores()

            # Add some randomness to keep the simulation dynamic
            if random.random() < 0.05:
                self.add_random_event()

            # Small delay to prevent CPU overuse
            time.sleep(max(0, UPDATE_INTERVAL - (time.time() - start_time)))

        self.end_game()

    def check_collisions(self):
        """Check for collisions between objects, including power-up pickups."""
        # Robot-robot collisions
        for i, robot1 in enumerate(self.objects):
            if not isinstance(robot1, Robot) or not robot1.is_active():
                continue

            for j, robot2 in enumerate(self.objects[i+1:], i+1):
                if not isinstance(robot2, Robot) or not robot2.is_active():
                    continue

                distance = np.hypot(robot2.x - robot1.x, robot2.y - robot1.y)
