class Vector3:
    """Represents a 3D vector for position and movement in the arena."""
    def __init__(self, x: float, y: float, z: float):
        self.x = x
        self.y = y
        self.z = z

    def distance(self, other: 'Vector3') -> float:
        """Calculates the Euclidean distance between two points."""
        return ((self.x - other.x)**2 + (self.y - other.y)**2 + (self.z - other.z)**2)**0.5


class Player:
    """Represents a player in the game."""
    def __init__(self, name: str, role: str):
        self.name = name
        self.role = role
        self.score = 0


class Block:
    """Represents a movable block in the maze."""
    def __init__(self, position: Vector3, block_id: int):
        self.position = position
        self.block_id = block_id
        self.is_movable = True


class Maze:
    """Represents the game maze with blocks and players."""
    def __init__(self, size: Tuple[int, int, int], block_density: float = 0.3):
        self.size = size  # (width, height, depth)
        self.blocks: List[Block] = []
        self.players: List[Player] = []
        self.goal_position = Vector3(size[0] - 1, 0, 0)
        self._initialize_maze(block_density)

    def _initialize_maze(self, block_density: float):
        """Initialize maze with random blocks."""
        num_blocks = int(self.size[0] * self.size[1] * self.size[2] * block_density)
        for i in range(num_blocks):
            x = random.randint(0, self.size[0] - 1)
            y = random.randint(0, self.size[1] - 1)
            z = random.randint(0, self.size[2] - 1)
            block = Block(Vector3(x, y, z), i)
            self.blocks.append(block)

    def add_player(self, player: Player, position: Vector3):
        player.position = position
        self.players.append(player)

    def move_block(self, block_id: int, new_position: Vector3):
        """Move a block to a new position if valid."""
        for block in self.blocks:
            if block.block_id == block_id:
                block.position = new_position

    def is_path_clear(self, start: Vector3, end: Vector3) -> bool:
        """Check if a path is clear between two points."""
        # Placeholder for pathfinding logic
        return True

    def check_goal(self) -> bool:
        """Check if any player has reached the goal."""
        for player in self.players:
            if player.position.distance(self.goal_position) < 1e-5:
                return True
        return False


class GameEngine:
    """Manages the game state and logic."""
    def __init__(self):
        self.maze = Maze((10, 10, 3))  # Example maze
        self.running = False
        self.lock = threading.Lock()

    def start_game(self):
        self.running = True
        print("Game started!")
        # Start game loop in a thread
        game_thread = threading.Thread(target=self._game_loop)
        game_thread.start()

    def _game_loop(self):
        while self.running:
            # Update game state and check for win condition
            if self.maze.check_goal():
                self._end_game()
            time.sleep(0.5)  # Update every 0.5 seconds

    def _end_game(self):
        print("Game over! Team reached the goal!")
        self.running = False

    def player_action(self, player_name: str, action: str, data: Dict[str, Any]):
        """Handle player actions."""
        # Example: 'move_block', 'swap_block', etc.
        with self.lock:
            if action == 'move_block':
