class Arena:
    """Represents the CyberArena environment where the battle takes place."""

    def __init__(self, width=1000, height=800, time_step=0.1):
        self.width = width
        self.height = height
        self.time_step = time_step
        self.robots = []
        self.power_ups = []
        self.hazards = []
        self.objectives = []
        self.score = defaultdict(int)
        self.winning_team = None
        self.game_over = False

        # Set up the environment
        self.setup_arena()

    def setup_arena(self):
        """Initialize the arena with robots, power-ups, hazards, and objectives."""
        # Create robots for each team
        red_team = self.create_team(Team.RED, 5)
        blue_team = self.create_team(Team.BLUE, 5)
        self.robots = red_team + blue_team

        # Assign roles to robots
        self.assign_roles()

        # Add power-ups to the arena
        self.add_power_ups()

        # Add hazards to the arena
        self.add_hazards()

        # Add objectives to the arena
        self.add_objectives()

    def create_team(self, team, num_robots):
        """Create a team of robots with different types."""
        robots = []
        robot_types = [RobotType.TANK, RobotType.ASSAULT, RobotType.SUPPORT, RobotType.SCOUT]

        for i in range(num_robots):
            robot_type = robot_types[i % len(robot_types)]
            # Randomly place robots in their team's spawn area
            if team == Team.RED:
                x = random.randint(100, 300)
                y = random.randint(100, 700)
            else:  # Team.BLUE
                x = random.randint(700, 900)
                y = random.randint(100, 700)

            robot = Robot(f"{team.name}_{robot_type.value}_{i}", team, robot_type, Position(x, y))
            robots.append(robot)

        return robots

    def assign_roles(self):
        """Assign roles to robots based on their type and capabilities."""
        roles = [
            TeamRole("Flag Carrier", "Carry flag to enemy base", ["Speed Boost", "Double Shot"]),
            TeamRole("Base Defender", "Protect base from enemy attacks", ["Heal", "Shield"]),
            TeamRole("Payload Escort", "Escort payload to destination", ["Speed Boost", "Damage Boost"]),
            TeamRole("Scout", "Gather intel and map exploration", ["Double Shot"]),
            TeamRole("Support", "Heal and assist teammates", ["Heal", "Shield"]),
            TeamRole("Offense", "Attack enemy robots and objectives", ["Double Shot", "Damage Boost"]),
            TeamRole("Tactical", "Coordinate team strategy", ["Heal", "Double Shot"]),
        ]

        for role in roles:
            # Find suitable robots for this role based on their type and skills
            suitable_robots = [
                robot for robot in self.robots 
                if all(skill in robot.skills for skill in role.required_skills)
            ]

            if suitable_robots:
                role.assign_robot(random.choice(suitable_robots))
                role.set_objective(self.get_objective_for_role(role))
                suitable_robots[0].objective_role = role

    def get_objective_for_role(self, role):
        """Get an objective that matches the role."""
        if role.role_name == "Flag Carrier":
            return CaptureFlagObjective(Position(500, 400), role.assigned_robot.team)
        elif role.role_name == "Base Defender":
            if role.assigned_robot.team == Team.RED:
                return DefendBaseObjective(Position(150, 400), Team.RED)
            else:
                return DefendBaseObjective(Position(850, 400), Team.BLUE)
        elif role.role_name == "Payload Escort":
            if role.assigned_robot.team == Team.RED:
                return EscortPayloadObjective(Position(150, 400), Position(850, 400), Team.RED)
            else:
                return EscortPayloadObjective(Position(850, 400), Position(150, 400), Team.BLUE)
        else:
            return None

    def add_power_ups(self):
        """Add power-ups to the arena at random positions."""
        power_up_types = [
            PowerUpType.SHIELD,
            PowerUpType.SPEED_BOOST,
            PowerUpType.DAMAGE_BOOST,
            PowerUpType.HEAL,
        ]

        for _ in range(5):  # Add 5 power-ups
            power_up_type = random.choice(power_up_types)
            x = random.randint(100, 900)
            y = random.randint(100, 700)
            power_up = PowerUp(power_up_type)
            power_up.position = Position(x, y)
            self.power_ups.append(power_up)

    def add_hazards(self):
        """Add hazards to the arena at random positions."""
        hazard_types = [
            HazardType.FIRE,
            HazardType.ICE,
            HazardType.ELECTRICITY,
            HazardType.ACID,
        ]

        for _ in range(3):  # Add 3 hazards
            hazard_type = random.choice(hazard_types)
            x = random.randint(100, 900)
            y = random.randint(100, 700)
            hazard = Hazard(hazard_type, Position(x, y), 30)
            self.hazards.append(hazard)

    def add_objectives(self):
        """Add objectives to the arena."""
        # Add flag capture objective
        self.objectives.append(CaptureFlagObjective(Position(500, 400), Team.RED))

        # Add base defense objective for each team
        self.objectives.append(DefendBaseObjective(Position(150, 400), Team.RED))
        self.objectives.append(DefendBaseObjective(Position(850, 400), Team.BLUE))

        # Add payload escort objective
        self.objectives.append(EscortPayloadObjective(Position(150, 400), Position(850, 400), Team.RED))
        self.objectives.append(EscortPayloadObjective(Position(850, 400), Position(150, 400), Team.BLUE))

    def update(self):
        """Update the state of the arena and its robots."""
        # Update all robots
        for robot in self.robots:
            robot.update(self)

            # Check for power-up collection
            collected_power_ups = []
            for power_up in self.power_ups:
                if power_up.position.distance_to(robot.position) <= 15 and not power_up.is_active():
                    robot.apply_power_up(power_up)
                    collected_power_ups.append(power_up)

            # Remove collected power-ups
            for power_up in collected_power_ups:
                if power_up in self.power_ups:
                    self.power_ups.remove(power_up)

            # Check for hazards
            for hazard in self.hazards:
                if hazard.is_active() and hazard.position.distance_to(robot.position) <= hazard.radius:
                    hazard.apply_effect(robot)

        # Update objectives
        for objective in self.objectives:
            if not objective.completed:
                objective.check_completion(self.robots)
            if objective.completed:
                # Update score
                if objective.type == ObjectiveType.CAPTURE_FLAG and isinstance(objective, CaptureFlagObjective):
                    self.score[objective.capturing_team.name] += 100
                elif objective.type == ObjectiveType.DEFEND_BASE and isinstance(objective, DefendBaseObjective):
                    if objective.base_health <= 0:
                        self.score[objective.defending_team.name] -= 50
                        self.score[Team.RED.name if objective.defending_team == Team.BLUE else Team.BLUE.name] += 50
                elif objective.type == ObjectiveType.ESCORT_PAYLOAD and isinstance(objective, EscortPayloadObjective):
                    self.score[objective.escorting_team.name] += 75

        # Check for game over condition
        if all(robot.is_dead for robot in self.robots if robot.team == Team.RED):
            self.winning_team = Team.BLUE
            self.game_over = True
        elif all(robot.is_dead for robot in self.robots if robot.team == Team.BLUE):
            self.winning_team = Team.RED
            self.game_over = True

        # Adaptive difficulty system
        self.adjust_difficulty()

        # Learning and adaptation
        self.robot_learning()

    def adjust_difficulty(self):
        """Adjust the difficulty of the game based on robot performance."""
        red_score = self.score.get("RED", 0)
        blue_score = self.score.get("BLUE", 0)

        # If one team is significantly ahead, increase the AI difficulty for that team
        if abs(red_score - blue_score) > 150:
            if red_score > blue_score:
                # Make blue team robots more aggressive
                for robot in self.robots:
                    if robot.team == Team.BLUE:
                        # Increase blue team AI aggression
                        robot.speed += 0.5
                        robot.weapon.damage += 5
            else:
                # Make red team robots more aggressive
                for robot in self.robots:
                    if robot.team == Team.RED:
                        # Increase red team AI aggression
                        robot.speed += 0.5
                        robot.weapon.damage += 5

    def robot_learning(self):
        """Implement learning and adaptation for the robots."""
        # Update robot experience based on performance
        for robot in self.robots:
            if not robot.is_dead:
                robot.experience += 1

                # Adjust AI behavior based on experience
                if robot.experience > 100:
                    # More experienced robots become more aggressive
                    robot.weapon.damage += 1
                    robot.speed += 0.1

                # Adapt movement based on environment
                if self.is_area_safe(robot):
                    # If current area is safe, explore new areas
                    robot.move(random.choice(list(Direction)), self)

    def is_area_safe(self, robot):
        """Check if the area around the robot is safe from enemies and hazards."""
        # Check for nearby enemies
        for other_robot in self.robots:
            if other_robot.team != robot.team and other_robot.is_dead:
                if robot.position.distance_to(other_robot.position) <= 50:
                    return False

        # Check for nearby hazards
        for hazard in self.hazards:
            if hazard.is_active() and hazard.position.distance_to(robot.position) <= hazard.radius + 30:
                return False

        return True

    def draw(self):
        """Draw the arena and all its elements on the screen."""
        screen.fill(BLACK)

        # Draw grid lines for reference
        for x in range(0, self.width, 50):
            pygame.draw.line(screen, GREY, (x, 0), (x, self.height))
        for y in range(0, self.height, 50):
            pygame.draw.line(screen, GREY, (0, y), (self.width, y))

        # Draw objectives
        for objective in self.objectives:
            if not objective.completed:
                objective.draw(screen)

        # Draw power-ups
        for power_up in self.power_ups:
            if not power_up.is_active():
                # Draw power-up
                pygame.draw.circle(screen, WHITE, 
                                  (int(power_up.position.x), int(power_up.position.y)), 10)
                # Draw power-up icon
                if power_up.type == PowerUpType.SHIELD:
                    pygame.draw.circle(screen, BLUE, 
                                      (int(power_up.position.x), int(power_up.position.y)), 6)
                elif power_up.type == PowerUpType.SPEED_BOOST:
                    pygame.draw.circle(screen, GREEN, 
                                      (int(power_up.position.x), int(power_up.position.y)), 6)
                elif power_up.type == PowerUpType.DAMAGE_BOOST:
                    pygame.draw.circle(screen, RED, 
                                      (int(power_up.position.x), int(power_up.position.y)), 6)
                elif power_up.type == PowerUpType.HEAL:
                    pygame.draw.circle(screen, YELLOW, 
                                      (int(power_up.position.x), int(power_up.position.y)), 6)

        # Draw hazards
        for hazard in self.hazards:
            if hazard.is_active():
                if hazard.type == HazardType.FIRE:
                    pygame.draw.circle(screen, RED, 
                                    (int(hazard.position.x), int(hazard.position.y)), hazard.radius, 2)
                elif hazard.type == HazardType.ICE:
                    pygame.draw.circle(screen, BLUE, 
                                    (int(hazard.position.x), int(hazard.position.y)), hazard.radius, 2)
                elif hazard.type == HazardType.ELECTRICITY:
                    pygame.draw.circle(screen, YELLOW, 
                                    (int(hazard.position.x), int(hazard.position.y)), hazard.radius, 2)
                elif hazard.type == HazardType.ACID:
                    pygame.draw.circle(screen, GREEN, 
                                    (int(hazard.position.x), int(hazard.position.y)), hazard.radius, 2)

        # Draw robots
        for robot in self.robots:
            robot.draw(screen)

        # Draw score
        font = pygame.font.SysFont(None, 36)
        score_text = font.render(f"Score: {self.score}", True, WHITE)
        screen.blit(score_text, (10, 10))

        # Draw game over message
        if self.game_over:
            font = pygame.font.SysFont(None, 72)
            winner_text = font.render(f"{self.winning_team.name} Team Wins!", True, self.winning_team.value)
            screen.blit(winner_text, (self.width//2 - 150, self.height//2))

        pygame.display.flip()

