def main():
    """Main function to run the CyberArena simulation."""
    arena = Arena()

    # Set up the game clock
    clock = pygame.time.Clock()

    # Main game loop
    running = True
    while running:
        # Handle events
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False

        # Update game state
        arena.update()

        # Draw the arena
        arena.draw()

        # Control the frame rate
        clock.tick(60)  # 60 FPS

        # Check for game over condition
        if arena.game_over:
            # Wait for a few seconds before exiting
            time.sleep(5)
            running = False

    pygame.quit()

