    def move_to(self, target_position: Position, time_step: float):
        """Move the robot towards a target position."""
        dx = target_position.x - self.position.x
        dy = target_position.y - self.position.y
        distance = (dx**2 + dy**2)**0.5
        if distance > 0:
            if distance < self.speed * time_step:
                self.position = target_position
            else:
                self.position.x += dx / distance * self.speed * time_step
                self.position.y += dy / distance * self.speed * time_step
            self.last_position = self.position

