        if time_now - weapon.last_used >= weapon.cooldown:
            if weapon.weapon_type == WeaponType.RANGED:
                if abs(self.position.x - target.position.x) <= weapon.range:
                    self._perform_attack(target, weapon, time_now)
            elif weapon.weapon_type == WeaponType.MELEE:
