            "type": objective_type,
            "details": details,
            "complete": False
        })

    def update(self, dt: float):
        """Update the game state by the given time step"""
        self.game_time += dt

        # Update difficulty if time has passed
        if self.game_time - self.last_difficulty_adjustment > self.difficulty_adjustment_frequency:
            self._adjust_difficulty()
            self.last_difficulty_adjustment = self.game_time

