    def _adjust_difficulty(self):
        """Adjust the difficulty level based on game performance"""
        # Calculate average team performance
        total_score = sum(self.score.values())
        average_score = total_score / len(self.score) if len(self.score) > 0 else 0

        # Adjust difficulty based on performance
        if average_score < 50:
            # Teams are underperforming, decrease difficulty
            self.difficulty = max(0.5, self.difficulty - 0.1)
        elif average_score > 150:
            # Teams are overperforming, increase difficulty
            self.difficulty = min(2.0, self.difficulty + 0.1)
        else:
            # Teams are performing at normal level, maintain difficulty
            self.difficulty = max(0.5, min(2.0, self.difficulty))

        # Update all robots based on new difficulty
        for robot in self.robots:
            # Adjust robot attributes based on difficulty
            robot.attack_power *= self.difficulty
            robot.defense *= self.difficulty
            robot.speed *= self.difficulty

