class Arena:
    def __init__(self, width: float = 100.0, height: float = 100.0):
        self.width = width
        self.height = height
        self.robots: List[Robot] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []
        self.objectives = []
        self.log = []
        self.running = False
        self.match_timer = 0.0
        self.difficulty = 1.0  # Base difficulty level
        self._last_difficulty_update = time.time()

    def add_robot(self, robot: Robot):
        """Add a robot to the arena."""
        self.robots.append(robot)

    def add_power_up(self, power_up: PowerUp):
        """Add a power-up to the arena."""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard: Hazard):
        """Add a hazard to the arena."""
        self.hazards.append(hazard)

    def add_objective(self, objective: Dict):
        """Add an objective to the arena."""
        self.objectives.append(objective)

    def start_match(self):
        """Start the arena match."""
        self.running = True
        self.match_timer = 0.0
        self.log_event("Match started")
        self._run_match()

    def stop_match(self):
        """Stop the arena match."""
        self.running = False
        self.log_event("Match stopped")

    def log_event(self, message: str):
        """Log an event in the arena."""
        self.log.append(f"{time.time():.2f}: {message}")

    def update(self):
        """Update the state of the arena."""
        if not self.running:
            return

        self.match_timer += 0.1  # 10 updates per second

        # Update all active robots
        for robot in self.robots:
            if robot.is_alive():
                robot.update(self)

        # Handle power-up interactions
        self._handle_power_ups()

        # Handle hazard interactions
        self._handle_hazards()

        # Check for objectives
        self._check_objectives()

        # Update difficulty
        self._update_difficulty()

    def _handle_power_ups(self):
        """Handle power-up interactions with robots."""
        for power_up in self.power_ups:
            if not power_up.active:
                continue
            for robot in self.robots:
                if robot.is_alive() and self._is_robot_in_radius(robot, power_up):
                    robot.apply_power_up(power_up)
                    power_up.active = False
                    self.log_event(f"{robot.name} picked up {power_up.name}")

    def _handle_hazards(self):
        """Handle hazard interactions with robots."""
        for hazard in self.hazards:
            if not hazard.active:
                continue
            for robot in self.robots:
                if robot.is_alive() and self._is_robot_in_radius(robot, hazard):
                    robot.receive_damage(hazard.damage)
                    self.log_event(f"{robot.name} took damage from {hazard.name}")

    def _is_robot_in_radius(self, robot: Robot, area: PowerUp | Hazard) -> bool:
        """Check if a robot is within the radius of a power-up or hazard."""
        distance = ((robot.position.x - area.position.x)**2 + 
                   (robot.position.y - area.position.y)**2)**0.5
        return distance <= area.radius

    def _check_objectives(self):
        """Check if any objectives have been completed."""
        # Example objective: Capture the flag
        for objective in self.objectives:
            if objective["type"] == "capture_flag" and objective["captured"]:
                # Award points to the successful team
                for robot in self.robots:
                    if robot.team == objective["capturing_team"]:
                        robot.score += 50
                self.log_event(f"Team {objective['capturing_team']} captured the flag")
                # Reset the objective for the next round
                objective["captured"] = False
                objective["capturing_team"] = None

    def _update_difficulty(self):
        """Update the difficulty level based on the match progress."""
        if time.time() - self._last_difficulty_update > 30:  # Update every 30 seconds
            # Simple difficulty scaling based on team performance
            red_score = sum(robot.score for robot in self.robots if robot.team == Team.RED)
            blue_score = sum(robot.score for robot in self.robots if robot.team == Team.BLUE)

            if red_score > blue_score:
