                self.log_event("Increasing difficulty for Red team")
                self._adjust_ai_behavior(Team.RED, self.difficulty)
            elif blue_score > red_score:
                self.difficulty = min(2.0, self.difficulty + 0.1)
                self.log_event("Increasing difficulty for Blue team")
                self._adjust_ai_behavior(Team.BLUE, self.difficulty)
            else:
                self.difficulty = max(0.5, self.difficulty - 0.05)
                self.log_event("Balancing difficulty")
                self._adjust_ai_behavior(Team.RED, self.difficulty)
                self._adjust_ai_behavior(Team.BLUE, self.difficulty)

            self._last_difficulty_update = time.time()

    def _adjust_ai_behavior(self, team: Team, difficulty: float):
        """Adjust AI behavior based on difficulty level."""
        # For simplicity, we'll just adjust the speed of robots in the specified team
        for robot in self.robots:
            if robot.team == team:
                robot.speed = 2.0 * difficulty

    def _run_match(self):
        """Run the match in a separate thread."""
        def match_thread():
            while self.running:
                self.update()
                time.sleep(0.1)  # 10 updates per second
            self.log_event("Match ended")

        thread = threading.Thread(target=match_thread)
        thread.start()

