        hazard.position = (random.randint(0, self.width), random.randint(0, self.height))
        self.hazards.append(hazard)

    def update(self):
        """Update the arena state in a game tick"""
        self.time_elapsed += 1  # Increment time

        # Update all robots
        for robot in self.robots:
            if robot.is_alive():
                # Check for power-ups
                for power_up in self.power_ups:
                    if power_up.active and self.distance(robot.position, power_up.position) < 10:
                        power_up.apply(robot)

                # Check for hazards
                for hazard in self.hazards:
                    if hazard.active and self.distance(robot.position, hazard.position) < hazard.trigger_range:
                        robot.health -= hazard.damage

                # Decide and execute action
                action = robot.decide_action(self.get_state(robot))
                self.execute_action(robot, action)

        # Update objectives
        for objective in self.objectives:
            if not objective.is_complete:
                # Check if any robot is at the objective position
                for robot in self.robots:
                    if robot.is_alive() and self.distance(robot.position, objective.position) < 5:
