        elif action == "move_down":
            new_pos = (robot.position[0], robot.position[1] + 5)
        elif action == "move_left":
            new_pos = (robot.position[0] - 5, robot.position[1])
        elif action == "move_right":
            new_pos = (robot.position[0] + 5, robot.position[1])
        elif action == "attack":
            # Find nearest enemy robot to attack
            nearest_enemy = self.get_nearest_enemy(robot)
            if nearest_enemy and self.distance(robot.position, nearest_enemy.position) < robot.weapon.range:
