class LearningRobot(Robot):
    """A robot that can learn and adapt its strategies over time"""
    def __init__(self, name, team, position, learning_rate=0.1):
        super().__init__(name, team, position)
        self.learning_rate = learning_rate  # Learning rate for skill adaptation
        self.previous_state = None  # Previous state for learning
        self.previous_action = None  # Previous action for learning
        self.experience = []  # List of experiences for training

    def decide_action(self, arena_state):
        """Decide action based on learning and current state"""
        # Simplified decision-making for demonstration
        # In a real implementation, this would use reinforcement learning algorithms

        # Use a basic strategy based on the robot's role
        if self.role == "commander":
            # Commanders should focus on objectives
            nearest_objective = self.find_nearest_objective(arena_state)
            if nearest_objective:
                if self.distance(self.position, nearest_objective["position"]) > 5:
                    action = self.get_direction_to_position(self.position, nearest_objective["position"])
                else:
                    action = "idle"
            else:
                action = "idle"

        elif self.role == "defender":
            # Defenders should stay near their base and attack enemies
            if self.distance(self.position, self.team.base_position) > 10:
                action = self.get_direction_to_position(self.position, self.team.base_position)
            else:
                nearest_enemy = self.find_nearest_enemy(arena_state)
                if nearest_enemy and self.distance(self.position, nearest_enemy["position"]) < 20:
                    action = "attack"
                else:
                    action = "idle"

        elif self.role == "attacker":
            # Attackers should seek out enemies
            nearest_enemy = self.find_nearest_enemy(arena_state)
            if nearest_enemy and self.distance(self.position, nearest_enemy["position"]) < 30:
                if self.distance(self.position, nearest_enemy["position"]) > 5:
                    action = self.get_direction_to_position(self.position, nearest_enemy["position"])
                else:
                    action = "attack"
            else:
                random_action = random.choice(["move_up", "move_down", "move_left", "move_right"])
                action = random_action

        # Store experience for learning
        if self.previous_state and self.previous_action:
            self.experience.append((self.previous_state, self.previous_action, arena_state))

        self.previous_state = arena_state
        self.previous_action = action

        return action

    def find_nearest_objective(self, arena_state):
        """Find the nearest objective to the robot"""
        if not arena_state["objectives"]:
            return None

        nearest_distance = float("inf")
        nearest_objective = None

        for obj in arena_state["objectives"]:
            distance = self.distance(self.position, obj["position"])
            if distance < nearest_distance:
                nearest_distance = distance
                nearest_objective = obj

        return nearest_objective

    def find_nearest_enemy(self, arena_state):
        """Find the nearest enemy robot to the robot"""
        if not arena_state["nearby_robots"]:
            return None

        nearest_distance = float("inf")
        nearest_enemy = None

        for robot in arena_state["nearby_robots"]:
            if robot["team"] != self.team.name:
                distance = self.distance(self.position, robot["position"])
                if distance < nearest_distance:
                    nearest_distance = distance
                    nearest_enemy = robot

        return nearest_enemy

    def get_direction_to_position(self, current_pos, target_pos):
        """Determine the direction to move toward a target position"""
        dx = target_pos[0] - current_pos[0]
        dy = target_pos[1] - current_pos[1]

        if dx > abs(dy):
            return "move_right" if dx > 0 else "move_left"
        elif dy > abs(dx):
            return "move_up" if dy > 0 else "move_down"
        else:
            # Randomly choose between x and y direction if they are similar
            return random.choice(["move_right" if dx > 0 else "move_left", "move_up" if dy > 0 else "move_down"])

    def learn(self):
        """Process and learn from experiences"""
        if not self.experience:
            return

        # Simple learning rule: update skills based on the difference between expected and actual outcomes
        for state, action, next_state in self.experience:
            reward = self.get_reward(state, next_state, action)

            # Update skills based on reward and learning rate
            for skill, _ in self.skills.items():
                self.skills[skill] += self.learning_rate * reward

            # Reset experience after learning
            self.experience = []

    def get_reward(self, state, next_state, action):
        """Calculate a reward based on the transition from state to next_state"""
        # This is a simplified reward function for demonstration
        # In a real implementation, this would be more sophisticated

        reward = 0

        # Reward for getting closer to an objective
        if next_state["objectives"]:
            nearest_objective = self.find_nearest_objective(next_state)
            if nearest_objective:
                reward += 1 / (self.distance(self.position, nearest_objective["position"]) + 1)

        # Reward for damaging an enemy
        if action == "attack":
            reward += 0.5

        # Reward for remaining alive
        if next_state["health"] > state["health"]:
            reward += 0.1 * (next_state["health"] - state["health"])

        # Penalty for taking damage
        if next_state["health"] < state["health"]:
            reward -= 0.1 * (state["health"] - next_state["health"])

        return reward


