# ==============================

class Direction(Enum):
    UP = 0
    DOWN = 1
    LEFT = 2
    RIGHT = 3

class WeaponType(Enum):
    RANGED = 0
    MELEE = 1
    SUPPORT = 2

@dataclass
class Position:
    x: float
    y: float

@dataclass
class Velocity:
    x: float
    y: float

class Team(Enum):
    RED = 0
    BLUE = 1
    NEUTRAL = 2

# ==============================
# Game Entities
# ==============================

class Robot:
    def __init__(self, name: str, team: Team, position: Position):
