        self.team = team
        self.position = position
        self.health = 100
        self.weapon = self.choose_weapon()
        self.velocity = Velocity(0, 0)
        self.score = 0
        self.experience = 0
        self.role = self.assign_role()

    def choose_weapon(self):
        """Randomly assign a weapon type to the robot based on its role."""
        if self.role in [Role.SHOOTER, Role.TANK]:
            return RangedWeapon("Plasma Rifle", 30, 10)
        elif self.role == Role.MELEE:
            return MeleeWeapon("Energy Axe", 40)
        else:  # Support
            return SupportItem("Medkit", 30, 15)

    def assign_role(self):
        """Assign a dynamic role based on team balance and robot characteristics."""
        return random.choice([Role.SHOOTER, Role.TANK, Role.MELEE, Role.SUPPORT])

    def move(self, direction: Direction, speed: float):
        """Move the robot in the specified direction."""
        if direction == Direction.UP:
            self.position.y -= speed
        elif direction == Direction.DOWN:
            self.position.y += speed
        elif direction == Direction.LEFT:
            self.position.x -= speed
        elif direction == Direction.RIGHT:
            self.position.x += speed

    def attack(self, target):
        """Use the robot's weapon to attack a target."""
        if self.weapon:
            self.weapon.use(self, target)

    def receive_damage(self, amount: int):
        """Reduce the robot's health when attacked."""
        self.health -= amount
        if self.health <= 0:
            self.die()

    def die(self):
        """Handle the death of a robot."""
        self.health = 0
        self.respawn_timer = time.time() + 10  # Respawns after 10 seconds
        self.spawn_location = Position(0, 0)  # Placeholder for actual spawn points

    def is_alive(self):
        """Check if the robot is alive."""
        return self.health > 0

    def learn_from_battle(self, outcome: str):
        """Implement a basic feedback loop for learning from battles."""
        if outcome == "victory":
            self.experience += 10
        elif outcome == "defeat":
            self.experience += 5
        self.improve_skills()

    def improve_skills(self):
        """Improve robot's skills based on experience."""
        if self.experience >= 20:
            self.experience = 0
            if isinstance(self.weapon, RangedWeapon):
                self.weapon.damage += 5
            elif isinstance(self.weapon, MeleeWeapon):
                self.weapon.damage += 10

class Weapon(ABC):
    def __init__(self, name: str, damage: int):
        self.name = name
        self.damage = damage

    @abstractmethod
    def use(self, user: Robot, target: Robot):
        pass

class RangedWeapon(Weapon):
    def __init__(self, name: str, damage: int, range: int):
        super().__init__(name, damage)
        self.range = range

    def use(self, user: Robot, target: Robot):
        """Fire a ranged weapon at a target."""
        distance = ((user.position.x - target.position.x)**2 + 
                   (user.position.y - target.position.y)**2)**0.5
        if distance <= self.range:
            target.receive_damage(self.damage)
            print(f"{user.name} shot {target.name} for {self.damage} damage!")

class MeleeWeapon(Weapon):
    def __init__(self, name: str, damage: int):
