        """Use a melee weapon to attack a target."""
        distance = ((user.position.x - target.position.x)**2 + 
                   (user.position.y - target.position.y)**2)**0.5
        if distance <= 1:
            target.receive_damage(self.damage)
            print(f"{user.name} slashed {target.name} for {self.damage} damage!")

class SupportItem(Weapon):
    def __init__(self, name: str, heal_amount: int, range: int):
        super().__init__(name, 0)
        self.heal_amount = heal_amount
        self.range = range

    def use(self, user: Robot, target: Robot):
        """Use a support item to heal a target."""
        distance = ((user.position.x - target.position.x)**2 + 
                   (user.position.y - target.position.y)**2)**0.5
        if distance <= self.range and target.team == user.team:
            target.health = min(target.health + self.heal_amount, 100)
            print(f"{user.name} healed {target.name} for {self.heal_amount} health!")

