        """Add a robot to the battle arena."""
        self.robots.append(robot)

    def start_game(self):
        """Start the CyberArena battle."""
        print("CyberArena Battle Started!")
        self.match_start_time = time.time()

    def update_game(self):
        """Update the game state in real-time."""
        if time.time() - self.match_start_time > self.round_time:
            self.end_game()
            return

        # Update robot positions and behaviors
        for robot in self.robots:
            if robot.is_alive():
                # Simple AI for demonstration
                target = self.find_closest_opponent(robot)
                if target:
                    self.attack(robot, target)
                else:
                    self.move(robot)

        # Check for objective completion
        for team, objective in self.teams.items():
            if objective.get_status():
                self.announce_victory(team)

        # Adjust difficulty based on performance
        self.adjust_difficulty()

    def find_closest_opponent(self, robot: Robot):
        """Find the closest opponent robot to the given robot."""
        min_distance = float('inf')
        closest_opponent = None
        for other_robot in self.robots:
            if other_robot.team != robot.team and other_robot.is_alive():
                distance = ((robot.position.x - other_robot.position.x)**2 + 
                           (robot.position.y - other_robot.position.y)**2)**0.5
                if distance < min_distance:
                    min_distance = distance
                    closest_opponent = other_robot
        return closest_opponent

    def attack(self, attacker: Robot, defender: Robot):
        """Handle an attack between two robots."""
        attacker.attack(defender)
        defender.learn_from_battle("defeat" if defender.health <= 0 else "survival")
        attacker.learn_from_battle("victory" if defender.health <= 0 else "partial success")

    def move(self, robot: Robot):
        """Simple movement AI for the robot."""
        direction = random.choice(list(Direction))
        robot.move(direction, 0.5)  # Move at 0.5 units per update

    def adjust_difficulty(self):
        """Adjust the difficulty based on the performance of the robots."""
        alive_robots = [robot for robot in self.robots if robot.is_alive()]
        if len(alive_robots) < 5:
            self.difficulty_level += 1
            print(f"Difficulty increased to level {self.difficulty_level}")
        elif len(alive_robots) > 10:
            self.difficulty_level = max(1, self.difficulty_level - 1)
            print(f"Difficulty decreased to level {self.difficulty_level}")

    def end_game(self):
        """End the current game round."""
        print("CyberArena Battle Ended!")
        self.declare_winner()
        self.reset_game()

    def declare_winner(self):
        """Determine and declare the winning team."""
        red_score = sum(robot.score for robot in self.robots if robot.team == Team.RED)
        blue_score = sum(robot.score for robot in self.robots if robot.team == Team.BLUE)
        if red_score > blue_score:
            print("Red Team Wins!")
        elif blue_score > red_score:
            print("Blue Team Wins!")
        else:
            print("It's a Draw!")

    def announce_victory(self, winning_team: Team):
        """Announce when an objective is completed."""
        print(f"{winning_team.name} Team has completed their objective!")

    def reset_game(self):
        """Reset the game for a new round."""
        for robot in self.robots:
            robot.health = 100
