    def distance_to(self, other_position):
        return math.hypot(self.x - other_position.x, self.y - other_position.y)

    def __str__(self):
        return f"Position({self.x}, {self.y})"

class Weapon(ABC):
    def __init__(self, name, damage, range, cooldown):
        self.name = name
        self.damage = damage
        self.range = range  # For ranged weapons; melee uses 0
        self.cooldown = cooldown
        self.last_fired = 0

    @abstractmethod
    def fire(self, attacker, target):
        pass

    def is_ready(self):
        return time.time() - self.last_fired >= self.cooldown

class RangedWeapon(Weapon):
    def fire(self, attacker, target):
        if self.is_ready() and attacker.position.distance_to(target.position) <= self.range:
            print(f"{attacker.name} fires {self.name} at {target.name} for {self.damage} damage!")
            target.take_damage(self.damage)
            self.last_fired = time.time()

class MeleeWeapon(Weapon):
    def fire(self, attacker, target):
        if self.is_ready() and attacker.position.distance_to(target.position) <= 1.5:
            print(f"{attacker.name} attacks {target.name} with {self.name} for {self.damage} damage!")
            target.take_damage(self.damage)
            self.last_fired = time.time()

# ==================== ROBOT CLASS ====================

class Robot:
    def __init__(self, name, team, position, weapons, role):
        self.name = name
        self.team = team
        self.position = position
        self.weapons = weapons
        self.role = role
        self.health = 100
        self.experience = 0
        self.strategy = Strategy()

    def take_damage(self, amount):
        self.health -= amount
        if self.health <= 0:
            print(f"{self.name} has been destroyed!")

    def move_towards(self, target_position, speed=1):
        if self.position.distance_to(target_position) > 1e-5:
            direction_x = (target_position.x - self.position.x) / self.position.distance_to(target_position)
            direction_y = (target_position.y - self.position.y) / self.position.distance_to(target_position)
            self.position.x += direction_x * speed
            self.position.y += direction_y * speed

    def select_weapon(self):
        # Simple selection: use the first weapon that is ready
        for weapon in self.weapons:
            if weapon.is_ready():
                return weapon
        return None

    def attack(self, target):
        weapon = self.select_weapon()
        if weapon:
            weapon.fire(self, target)

    def update(self, arena):
        # Basic AI for movement and attacking
        self.strategy.evaluate(self, arena)

    def report(self):
        return f"{self.name} (Team {self.team}): Health={self.health}, Position={self.position}, Role={self.role}"

    def learn(self, battle_summary):
        # Simple learning mechanism based on battle outcome
        if battle_summary["my_team_score"] > battle_summary["opponent_team_score"]:
            self.experience += 10
        else:
            self.experience += 5
        self.strategy.update_strategy(battle_summary)

# ==================== STRATEGY CLASS ====================

class Strategy:
    def __init__(self):
        self.aggression = 0.5  # 0 = passive, 1 = aggressive
        self.role_specialization = {}  # e.g., {"Support": 0.8, "Offense": 0.2}

    def evaluate(self, robot, arena):
        # Basic AI decision logic
        if robot.health < 30:
            self.retreat(robot)
        else:
            if random.random() < self.aggression:
                self.attack(robot, arena)
            else:
                self.support(robot, arena)

    def retreat(self, robot):
        # Move to a safe position
        safe_position = Position(robot.position.x + 10, robot.position.y + 10)
        robot.move_towards(safe_position)

    def attack(self, robot, arena):
        # Attack the nearest enemy
        target = self.find_nearest_enemy(robot, arena)
        if target:
            robot.attack(target)

    def support(self, robot, arena):
        # Support teammates
        teammate = self.find_teammate_needing_help(robot, arena)
        if teammate:
            # Move towards teammate
            robot.move_towards(teammate.position)

    def find_nearest_enemy(self, robot, arena):
        enemies = [r for r in arena.robots if r.team != robot.team]
        if not enemies:
            return None
        return min(enemies, key=lambda r: robot.position.distance_to(r.position))

    def find_teammate_needing_help(self, robot, arena):
        teammates = [r for r in arena.robots if r.team == robot.team and r.health < 50]
        if not teammates:
