        if self.robot_type == RobotType.TANK:
            return {
                ObjectiveType.CAPTURE_FLAG: 0.3,
                ObjectiveType.DEFEND_BASE: 0.4,
                ObjectiveType.ESCORT_PAYLOAD: 0.2,
                ObjectiveType.DESTROY_TURRET: 0.1
            }
        elif self.robot_type == RobotType.SCOUT:
            return {
                ObjectiveType.CAPTURE_FLAG: 0.5,
                ObjectiveType.DEFEND_BASE: 0.1,
                ObjectiveType.ESCORT_PAYLOAD: 0.3,
