        if 0 <= weapon_index < len(self.weapons):
            self.equipped_weapon = self.weapons[weapon_index]

    def fire(self):
        if self.equipped_weapon.can_fire():
            if self.ammo > 0:
                self.ammo -= 1
                return self.equipped_weapon.fire()
