        else:
            print(f"{self.name} is waiting to fire...")
        return None

    def take_damage(self, amount: int):
        if self.shield > 0:
            if self.shield >= amount:
                self.shield -= amount
                return
            else:
                amount -= self.shield
                self.shield = 0

        self.health -= amount
        if self.health <= 0:
            print(f"{self.name} has been destroyed!")
            self.health = 0

    def heal(self, amount: int):
        self.health = min(self.max_health, self.health + amount)

