        # Calculate weighted scores for each objective
        objective_scores = {}
        for objective in objectives:
            if objective.team != self.team:
                continue

            distance = self.position.distance_to(objective.position)
            base_score = 1.0 / (distance + 1)
            weighted_score = base_score * self.objective_weighting[objective.type]
            objective_scores[objective] = weighted_score

        # Choose the best objective based on score
        if objective_scores:
            self.current_objective = max(objective_scores, key=objective_scores.get)
            self.move_towards(self.current_objective.position)
        else:
            # If no objectives, move randomly
            random_x = random.uniform(self.position.x - 10, self.position.x + 10)
            random_y = random.uniform(self.position.y - 10, self.position.y + 10)
            self.move_towards(Position(random_x, random_y))

