                ObjectiveType.ESCORT_PAYLOAD: 0.1,
                ObjectiveType.DESTROY_TURRET: 0.6
            }
        return {obj_type: 1.0/len(ObjectiveType) for obj_type in ObjectiveType}

    def move_towards(self, target_position: Position, speed: Optional[float] = None):
        if speed is None:
            speed = self.speed * self.speed_multiplier

        direction_x = target_position.x - self.position.x
        direction_y = target_position.y - self.position.y
        distance = math.sqrt(direction_x**2 + direction_y**2)

        if distance > 0:
            self.position.x += (direction_x / distance) * speed * 0.1
            self.position.y += (direction_y / distance) * speed * 0.1

    def update_status_effects(self):
        current_time = time.time()
        to_remove = []
        for effect, duration in self.status_effects.items():
            if (current_time - duration) > 3:
                to_remove.append(effect)

        for effect in to_remove:
            del self.status_effects[effect]

        # Apply effects
        if StatusEffect.STUN in self.status_effects:
            self.speed_multiplier = 0
        elif StatusEffect.SLOW in self.status_effects:
            self.speed_multiplier = 0.5
        else:
            self.speed_multiplier = 1.0

        if self.speed_boost_duration > 0:
            self.speed_multiplier = max(1.5, self.speed_multiplier)
            self.speed_boost_duration -= 0.1
            if self.speed_boost_duration <= 0:
                self.speed_multiplier = 1.0

    def apply_status_effect(self, effect: StatusEffect, duration: float):
