                self.objective_weighting[obj_type] = max(0.001, 
                                                      self.objective_weighting[obj_type] + performance)

        # Normalize weights
        total = sum(self.objective_weighting.values())
        for obj_type in self.objective_weighting:
            self.objective_weighting[obj_type] /= total

