    def can_fire(self):
        return time.time() - self.last_used >= self.cooldown

    def fire(self):
        if self.can_fire():
            self.last_used = time.time()
            return self.damage
        return 0

class PowerUp:
    def __init__(self, name, effect_duration, effect_type):
        self.name = name
        self.effect_duration = effect_duration  # in seconds
