class TankStrategy(Strategy):
    def execute(self, game_state):
        # Tank strategy: stay in front of teammates and protect them
        if self.robot.team.goal is not None:
            direction = self.robot.position.move_towards(self.robot.team.goal)
            self.robot.position.move(direction, self.robot.speed)
