        if self.robot.weapon and self.robot.weapon.can_fire():
            self.robot.weapon.fire()

class DamageStrategy(Strategy):
    def execute(self, game_state):
        # Damage strategy: seek and destroy enemy robots
        nearest_enemy = self.find_nearest_enemy(game_state)
        if nearest_enemy:
            direction = self.robot.position.move_towards(nearest_enemy.position)
            self.robot.position.move(direction, self.robot.speed)
            if self.robot.weapon.can_fire():
                self.robot.weapon.fire()

    def find_nearest_enemy(self, game_state):
        enemies = [r for r in game_state.robots if r.team != self.robot.team]
        if not enemies:
            return None
        return min(enemies, key=lambda e: self.robot.position.distance(e.position))

