        if target.health <= 0:
            target.is_alive = False
            print(f"{target.name} has been defeated!")

    def update_role(self):
        """Update the robot's role based on experience and performance"""
        if self.experience >= 100:
            self.role = Role.FIGHTER
        elif self.experience >= 50:
            self.role = Role.SUPPORT
        else:
            self.role = Role.SCOUT

