    @abstractmethod
    def update(self, arena: 'CyberArena'):
        """Update the robot's state based on the current arena state"""
        pass

    def take_damage(self, amount: float):
        """Take damage, first from shield then from health"""
        if self.shield > 0:
            if amount >= self.shield:
                amount -= self.shield
                self.shield = 0
            else:
                self.shield -= amount
                amount = 0

        if amount > 0:
            self.health -= amount
            if self.health <= 0:
                self.health = 0
                self.active = False

    def has_weapon_ready(self, weapon_type: WeaponType) -> bool:
        """Check if a weapon of the specified type is ready to use"""
        for weapon in self.weapons:
            if weapon.__class__.__name__.startswith(weapon_type.value) and weapon.is_ready():
                return True
        return False

    def use_weapon(self, target: 'Robot', weapon_type: WeaponType):
        """Use a weapon of the specified type against a target"""
        for weapon in self.weapons:
            if weapon.__class__.__name__.startswith(weapon_type.value) and weapon.is_ready():
                distance = self.position.distance_to(target.position)
                if distance <= weapon.range:
                    damage = weapon.damage * self.damage_multiplier
                    target.take_damage(damage)
                    weapon.use()
                    self.last_action_time = time.time()
                    return True
        return False

    def move_towards(self, target_position: Position, arena: 'CyberArena'):
        """Move towards a target position"""
        if not self.active:
            return

        if self.position.distance_to(target_position) > 0.1:
            direction_x = (target_position.x - self.position.x) / self.position.distance_to(target_position)
            direction_y = (target_position.y - self.position.y) / self.position.distance_to(target_position)
            self.position.x += direction_x * self.speed * (time.time() - self.last_action_time)
            self.position.y += direction_y * self.speed * (time.time() - self.last_action_time)
            self.last_action_time = time.time()

