# -----------------------------
# Enums for system modeling
# -----------------------------

class Team(Enum):
    RED = 0
    BLUE = 1

class TaskPriority(Enum):
    LOW = 1
    MEDIUM = 2
    HIGH = 3

class TaskDependencyType(Enum):
    PREREQUISITE = 0
    COORDINATED = 1

# -----------------------------
# Core Data Models
# -----------------------------

class Position:
    """Represents a position in a 2D space (used for spatial scheduling if needed)."""
    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

class Task:
    """Represents an individual task with name, duration, priority, and optional dependencies."""
    def __init__(self, task_id: int, name: str, duration: float, priority: TaskPriority):
        self.task_id = task_id
        self.name = name
        self.duration = duration
        self.priority = priority
        self.dependencies: List[Tuple[int, TaskDependencyType]] = []
        self.assigned_to: Optional[int] = None  # User ID of assigned member
        self.start_time: Optional[float] = None
        self.end_time: Optional[float] = None

    def add_dependency(self, task_id: int, dependency_type: TaskDependencyType):
        self.dependencies.append((task_id, dependency_type))

class User:
    """Represents a team member with their availability and assigned tasks."""
    def __init__(self, user_id: int, name: str, availability: Dict[str, bool]):
        self.user_id = user_id
        self.name = name
        self.availability = availability  # e.g., {"Mon 9-12": True, "Wed 14-17": False}
        self.assigned_tasks: List[Task] = []

    def is_available(self, time_slot: str) -> bool:
        return self.availability.get(time_slot, False)

# -----------------------------
# Collaborative Schedule Planner Core
# -----------------------------

class CollaborativeSchedulePlanner:
    """Main system class to manage and optimize schedules for a team."""
    def __init__(self):
        self.tasks: Dict[int, Task] = {}
        self.users: Dict[int, User] = {}
        self.schedules: Dict[int, List[Task]] = {}  # Task schedule per user
        self.feedback_log: List[Tuple[int, str, Dict]] = []

    def add_task(self, task: Task):
        self.tasks[task.task_id] = task

    def add_user(self, user: User):
        self.users[user.user_id] = user
        self.schedules[user.user_id] = []

    def assign_task(self, task_id: int, user_id: int):
        task = self.tasks[task_id]
        user = self.users[user_id]
        if task and user and user.is_available(f"Task {task_id} slot"):
            task.assigned_to = user_id
            user.assigned_tasks.append(task)
            self.schedules[user_id].append(task)
            self._notify_users(f"Task {task.name} assigned to {user.name}")
        else:
            raise ValueError(f"User {user_id} is not available or task {task_id} does not exist.")

    def _notify_users(self, message: str):
        # Simulate real-time notification for users
        print(f"Notification: {message}")

    def optimize_schedule(self):
        # Placeholder for ML-based scheduling logic
        # For now, sort tasks by priority and assign to available users
        sorted_tasks = sorted(self.tasks.values(), key=lambda t: t.priority.value, reverse=True)
        for task in sorted_tasks:
            for user_id, user in self.users.items():
                if user.is_available(f"Task {task.task_id} slot") and task.assigned_to is None:
                    self.assign_task(task.task_id, user_id)
                    break

    def collect_feedback(self, user_id: int, feedback: Dict):
        self.feedback_log.append((user_id, "feedback", feedback))
        self.optimize_schedule()  # Re-optimize based on feedback

    def generate_report(self, user_id: Optional[int] = None) -> Dict:
        report = {
            "tasks": {},
            "users": {},
            "summary": {},
        }
        if user_id is not None:
            user = self.users[user_id]
            report["tasks"] = {task.task_id: task.name for task in user.assigned_tasks}
            report["users"] = {user_id: user.name}
        else:
            report["tasks"] = {t.task_id: t.name for t in self.tasks.values()}
            report["users"] = {u.user_id: u.name for u in self.users.values()}
        report["summary"] = {
            "total_tasks": len(self.tasks),
            "assigned_tasks": sum(len(s) for s in self.schedules.values()),
            "users_involved": len(self.users),
        }
        # Gantt chart placeholder logic
        report["gantt_chart"] = {task.task_id: task.duration for task in self.tasks.values()}
        return report

# -----------------------------
# Example Usage
# -----------------------------

if __name__ == "__main__":
