import json
import datetime
from collections import defaultdict
from threading import Lock

class Task:
    def __init__(self, name, duration, priority, dependencies=None):
        self.name = name
        self.duration = duration
        self.priority = priority
        self.dependencies = dependencies if dependencies else []
        self.assigned_user = None
        self.start_time = None
        self.end_time = None

    def assign_to_user(self, user):
        self.assigned_user = user

    def schedule(self, start_time):
        self.start_time = start_time
        self.end_time = start_time + datetime.timedelta(minutes=self.duration)

    def to_dict(self):
        return {
            'name': self.name,
            'duration': self.duration,
            'priority': self.priority,
            'dependencies': self.dependencies,
            'assigned_user': self.assigned_user.name if self.assigned_user else None,
            'start_time': self.start_time.isoformat() if self.start_time else None,
            'end_time': self.end_time.isoformat() if self.end_time else None
        }

class User:
    def __init__(self, name, availability):
        self.name = name
        self.tasks = []
        self.availability = availability  # List of (start, end) time slots

    def add_task(self, task):
        self.tasks.append(task)

    def get_available_slots(self):
        return self.availability

    def to_dict(self):
        return {
            'name': self.name,
            'availability': [(s.isoformat(), e.isoformat()) for s, e in self.availability],
            'tasks': [t.to_dict() for t in self.tasks]
        }

class CollaborativeSchedulePlanner:
    def __init__(self):
        self.users = {}
        self.tasks = []
        self.lock = Lock()

    def add_user(self, user):
        with self.lock:
            self.users[user.name] = user

    def add_task(self, task):
        with self.lock:
            self.tasks.append(task)

    def assign_task_to_user(self, task_name, user_name):
        with self.lock:
            task = next((t for t in self.tasks if t.name == task_name), None)
            user = self.users.get(user_name)
            if task and user:
                task.assign_to_user(user)
                user.add_task(task)

    def optimize_schedule(self):
        # A simple greedy approach for demonstration
        tasks_by_priority = sorted(self.tasks, key=lambda t: t.priority, reverse=True)
        for task in tasks_by_priority:
            # Find the first available user with sufficient time
            for user in self.users.values():
                if user.get_available_slots():
                    # Assign task to the first available user
                    self.assign_task_to_user(task.name, user.name)
                    break

    def generate_gantt_chart(self):
        schedule = []
        for task in self.tasks:
            if task.assigned_user:
                schedule.append({
                    'name': task.name,
                    'start': task.start_time.isoformat() if task.start_time else None,
                    'end': task.end_time.isoformat() if task.end_time else None,
                    'assigned_to': task.assigned_user.name if task.assigned_user else None
                })
        return schedule

    def to_dict(self):
        return {
            'users': [user.to_dict() for user in self.users.values()],
            'tasks': [task.to_dict() for task in self.tasks]
        }

    def save_schedule(self, filename='schedule.json'):
        with open(filename, 'w') as f:
            json.dump(self.to_dict(), f, indent=2)

    def load_schedule(self, filename='schedule.json'):
        with open(filename, 'r') as f:
            data = json.load(f)
            for user_data in data['users']:
                user = User(
                    name=user_data['name'],
                    availability=[(datetime.datetime.fromisoformat(s), datetime.datetime.fromisoformat(e)) 
                                 for s, e in user_data['availability']]
                )
                self.add_user(user)
                for task_data in user_data['tasks']:
                    task = Task(
                        name=task_data['name'],
                        duration=task_data['duration'],
                        priority=task_data['priority'],
                        dependencies=task_data['dependencies']
                    )
                    task.assigned_user = self.users.get(task_data['assigned_user']) if task_data['assigned_user'] else None
                    task.start_time = datetime.datetime.fromisoformat(task_data['start_time']) if task_data['start_time'] else None
                    task.end_time = datetime.datetime.fromisoformat(task_data['end_time']) if task_data['end_time'] else None
                    self.add_task(task)

# Sample usage
