import pygame
import numpy as np
from enum import Enum
import json

# Constants for simulation
SCREEN_WIDTH = 1200
SCREEN_HEIGHT = 800
FPS = 60

# Celestial Body Parameters
class CelestialBody:
    def __init__(self, name, mass, radius, position, velocity, color):
        self.name = name
        self.mass = mass
        self.radius = radius
        self.position = np.array(position, dtype=float)
        self.velocity = np.array(velocity, dtype=float)
        self.color = color

# Physics Engine for Celestial Mechanics
class PhysicsEngine:
    G = 6.67430e-11  # Gravitational Constant

    def compute_gravitational_force(self, body1, body2):
        # Calculate gravitational force between two bodies
        r = body2.position - body1.position
        distance = np.linalg.norm(r)
        if distance == 0:
            return np.array([0, 0, 0])  # Avoid division by zero
        force_magnitude = (self.G * body1.mass * body2.mass) / (distance ** 2)
        force_direction = r / distance
        return force_magnitude * force_direction

    def update_positions(self, bodies, dt):
        for body in bodies:
            # Apply force from all other bodies
            total_force = np.array([0, 0, 0])
            for other in bodies:
                if other != body:
                    total_force += self.compute_gravitational_force(body, other)

            # Newton's second law: F = ma => a = F/m
            acceleration = total_force / body.mass
            body.velocity += acceleration * dt
            body.position += body.velocity * dt

# Visualization Module
class VisualizationEngine:
    def __init__(self, screen):
        self.screen = screen
        self.camera_position = np.array([0, 0, 0])
        self.zoom_level = 1.0

    def draw_celestial_bodies(self, bodies):
        for body in bodies:
            # Convert 3D position to 2D screen position
            x = int(body.position[0] * self.zoom_level + SCREEN_WIDTH // 2)
            y = int(body.position[1] * self.zoom_level + SCREEN_HEIGHT // 2)
            pygame.draw.circle(self.screen, body.color, (x, y), int(body.radius * self.zoom_level))

    def handle_camera_controls(self, event):
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_UP:
                self.camera_position[1] -= 10
            elif event.key == pygame.K_DOWN:
                self.camera_position[1] += 10
            elif event.key == pygame.K_LEFT:
                self.camera_position[0] -= 10
            elif event.key == pygame.K_RIGHT:
                self.camera_position[0] += 10
            elif event.key == pygame.K_EQUALS:
                self.zoom_level += 0.1
            elif event.key == pygame.K_MINUS:
                self.zoom_level -= 0.1

# Educational Module
