    sun = CelestialBody("Sun", 1.989e30, 696340000, [0, 0, 0], [0, 0, 0], (255, 255, 0))
    earth = CelestialBody("Earth", 5.972e24, 6371000, [1.496e11, 0, 0], [0, 29780, 0], (0, 0, 255))

    bodies = [sun, earth]

    physics_engine = PhysicsEngine()
    visualization_engine = VisualizationEngine(screen)
    educational_module = EducationalModule()

    running = True
    dt = 1.0 / FPS  # Time step

    while running:
        clock.tick(FPS)
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False
            visualization_engine.handle_camera_controls(event)

        physics_engine.update_positions(bodies, dt)
        screen.fill((0, 0, 0))  # Clear screen with black background
        visualization_engine.draw_celestial_bodies(bodies)
        pygame.display.flip()

        # Educational content example
        if pygame.key.get_pressed()[pygame.K_e]:
            educational_module.display_lesson(1)  # Display lesson 1

    pygame.quit()

if __name__ == "__main__":
    main()"
