class CelestialBody:
    def __init__(self, name: str, mass: float, radius: float, position: tuple, velocity: tuple):
        self.name = name
        self.mass = mass
        self.radius = radius
        self.position = pygame.Vector2(position)  # x, y
        self.velocity = pygame.Vector2(velocity)  # vx, vy

    def __str__(self):
        return f"{self.name} (Mass: {self.mass}, Radius: {self.radius}, Pos: {self.position}, Vel: {self.velocity})"


class CelestialInput:
    def __init__(self):
        self.bodies = []

    def add_body(self, name, mass, radius, position, velocity):
        self.bodies.append(CelestialBody(name, mass, radius, position, velocity))

    def get_bodies(self):
        return self.bodies

# === Simulation Engine ===

class GravityEngine:
    def __init__(self, bodies: List['CelestialBody']):
        self.bodies = bodies
        self.G = 6.67430e-11  # Gravitational constant (scaled for simulation)

    def compute_gravity(self):
        for i, body_i in enumerate(self.bodies):
            for j, body_j in enumerate(self.bodies):
                if i != j:
                    dx = body_j.position.x - body_i.position.x
                    dy = body_j.position.y - body_i.position.y
                    distance = math.hypot(dx, dy)
                    if distance == 0:
                        continue  # Prevent division by zero
                    force = (self.G * body_i.mass * body_j.mass) / (distance ** 2)
                    fx = force * dx / distance
                    fy = force * dy / distance
                    body_i.velocity.x += fx / body_i.mass * 0.01  # time step
                    body_i.velocity.y += fy / body_i.mass * 0.01

    def update_positions(self):
        for body in self.bodies:
            body.position += body.velocity * 0.01  # time step

    def detect_collisions(self):
        for i, body_i in enumerate(self.bodies):
            for j, body_j in enumerate(self.bodies):
                if i < j:
                    dx = body_j.position.x - body_i.position.x
                    dy = body_j.position.y - body_i.position.y
                    distance = math.hypot(dx, dy)
                    if distance < body_i.radius + body_j.radius:
                        print(f"Collision detected between {body_i.name} and {body_j.name}")

