# ------------------------------
# Position Class
# ------------------------------

class Position:
    def __init__(self, x, y, z=0):
        self.x = x
        self.y = y
        self.z = z

    def distance_to(self, other):
        return ((self.x - other.x)**2 + (self.y - other.y)**2 + (self.z - other.z)**2)**0.5

    def __str__(self):
        return f"({self.x}, {self.y}, {self.z})"

# ------------------------------
# Simulation Engine Module
# ------------------------------

GRAVITATIONAL_CONSTANT = 6.67430e-11  # N·m²/kg²

class SimulationEngine:
    def __init__(self, celestial_bodies):
        self.bodies = celestial_bodies

    def calculate_gravitational_force(self, body1, body2):
        distance = body1.position.distance_to(body2.position)
        force_magnitude = (GRAVITATIONAL_CONSTANT * body1.mass * body2.mass) / (distance ** 2)

        # Calculate direction vector
        dx = body2.position.x - body1.position.x
        dy = body2.position.y - body1.position.y
        dz = body2.position.z - body1.position.z

        magnitude = (dx**2 + dy**2 + dz**2) ** 0.5
        if magnitude == 0:
            return Position(0, 0, 0)

        # Normalize and apply the force
        return Position(
            force_magnitude * dx / magnitude,
            force_magnitude * dy / magnitude,
            force_magnitude * dz / magnitude
        )

    def update_velocities(self, delta_time):
        for i in range(len(self.bodies)):
            for j in range(len(self.bodies)):
                if i != j:
                    force = self.calculate_gravitational_force(self.bodies[i], self.bodies[j])
                    self.bodies[i].velocity.x += (force.x / self.bodies[i].mass) * delta_time
                    self.bodies[i].velocity.y += (force.y / self.bodies[i].mass) * delta_time
                    self.bodies[i].velocity.z += (force.z / self.bodies[i].mass) * delta_time

    def update_positions(self, delta_time):
        for body in self.bodies:
            body.position.x += body.velocity.x * delta_time
            body.position.y += body.velocity.y * delta_time
            body.position.z += body.velocity.z * delta_time

    def run_simulation(self, duration, time_step):
        steps = int(duration / time_step)
        for _ in range(steps):
            self.update_velocities(time_step)
            self.update_positions(time_step)
            self._visualize_step()

    def _visualize_step(self):
        for body in self.bodies:
            print(f"{body.name} at {body.position}")

