        """Move robot towards a target position."""
        if self.position.distance_to(target_pos) > step:
            dx = target_pos.x - self.position.x
            dy = target_pos.y - self.position.y
            self.position.x += (dx / max(1, self.position.distance_to(target_pos))) * self.speed
            self.position.y += (dy / max(1, self.position.distance_to(target_pos))) * self.speed
