        self.phishing_keywords = ['login', 'password', 'verify', 'urgent']
        self.allowed_ips = ['127.0.0.1']

    def detect(self, data, source_ip):
        # Check for known malware hashes in the data
        if any(hash in data for hash in self.known_malware_hashes):
            return ThreatType.MALWARE

        # Check for phishing-related keywords
        for keyword in self.phishing_keywords:
            if keyword in data.decode('utf-8', errors='ignore').lower():
                return ThreatType.PHISHING

        # Check for unauthorized access (e.g., not in allowed IPs)
