        """Reduce health when damaged."""
        self.health -= amount
        if self.health <= 0:
            self.is_alive = False

    def heal(self, amount):
        """Heal the robot up to max health."""
        self.health = min(self.health + amount, self.max_health)

    def use_weapon(self, target):
        """Use the equipped weapon on a target."""
        if self.weapon and self.is_alive:
            self.weapon.use(self, target)

    def use_skill(self, skill_name, target):
        """Use a specific skill on a target."""
        for skill in self.skills:
            if skill.name == skill_name:
                skill.use(self, target)
                return

    def pick_up_power_up(self, power_up):
        """Collect a power-up."""
        self.power_ups.append(power_up)

    def __str__(self):
