        elif self.power_type == "Speed":
            robot.speed_boost = min(2, robot.speed_boost + 0.5)
            robot.speed_boost_duration = self.duration


class Hazard:
    """Environmental hazard class for obstacles and dangers."""
    def __init__(self, hazard_type, position, radius):
        self.hazard_type = hazard_type
        self.position = position
        self.radius = radius
        self.damage_interval = 2  # seconds
        self.last_damage_time = time.time()

    def is_in_hazard(self, robot):
        return robot.position.distance_to(self.position) <= self.radius

    def apply_damage(self, robot):
        if self.hazard_type == "Toxic":
            damage = 5
        elif self.hazard_type == "Lava":
            damage = 10
        elif self.hazard_type == "Spikes":
            damage = 15
        elif self.hazard_type == "Electric":
            damage = 20
        robot.take_damage(damage)


class Objective:
    """Base class for team objectives in CyberArena."""
    def __init__(self, objective_type, position, team):
        self.objective_type = objective_type
        self.position = position
        self.team = team
        self.is_complete = False
        self.progress = 0  # 0-100% completion
        self.id = str(uuid.uuid4())

    def update(self, robots):
        """Update objective status based on robot actions."""
        if self.is_complete:
            return
        if self.objective_type == "CaptureFlag":
            # Find if any enemy team robot has the flag
            for robot in robots:
                if robot.team != self.team and robot.has_flag:
                    self.progress = 100
                    self.is_complete = True
                    break
            else:
                # Check if flag is at the correct position
                if self.position.distance_to(self.team.flag_position) <= 2:
                    self.progress = 100
                    self.is_complete = True
        elif self.objective_type == "DefendBase":
            # Check if base is under attack
            for robot in robots:
                if robot.team != self.team and robot.position.distance_to(self.position) <= 5:
                    self.progress = max(0, self.progress - 5)
                else:
                    self.progress = min(100, self.progress + 2)
        elif self.objective_type == "EscortPayload":
            # Check if payload is at destination
            if self.position.distance_to(self.team.payload_position) <= 2:
                self.progress = 100
                self.is_complete = True
        elif self.objective_type == "DestroyTarget":
            # Check if target is destroyed
            if self.team.target_health <= 0:
                self.progress = 100
                self.is_complete = True


class Team:
    """Team class for managing groups of robots and their objectives."""
    def __init__(self, name, color):
        self.name = name
        self.color = color
        self.robots = []
        self.score = 0
        self.objectives = []
        self.base_position = Vector3(0, 0)
        self.flag_position = Vector3(0, 0)
        self.payload_position = Vector3(0, 0)
        self.target_health = 100

    def add_robot(self, robot):
        self.robots.append(robot)
        robot.team = self
        robot.team_color = self.color

    def add_objective(self, objective):
        self.objectives.append(objective)

    def calculate_team_score(self):
        # Calculate team score based on all robots' performance
        total_score = 0
        for robot in self.robots:
            if robot.is_active:
                robot_score = 0
                # Score for health
                robot_score += (robot.health / Config.MAX_HEALTH) * Config.SCORE_WEIGHTS["health"] * 100
                # Score for energy
                robot_score += (robot.energy / Config.MAX_ENERGY) * Config.SCORE_WEIGHTS["energy"] * 100
                # Score for proximity to objectives
                min_distance = float('inf')
                for objective in self.objectives:
                    if not objective.is_complete:
                        dist = robot.position.distance_to(objective.position)
                        min_distance = min(min_distance, dist)
                robot_score += (1 - min_distance / (Config.VISION_RADIUS * 2)) * Config.SCORE_WEIGHTS["distance_to_objective"] * 100
                # Score for team success
                robot_score += (self.score / Config.MAX_ROUNDS) * Config.SCORE_WEIGHTS["team_success"] * 100
                total_score += robot_score
        return total_score / len(self.robots) if self.robots else 0

    def update(self, arena):
        # Update team objectives and calculate team progress
        for objective in self.objectives:
            objective.update(arena.robots)
            if objective.is_complete:
                self.score += 10
        # Apply team-based rewards
        if self.score > 0 and time.time() - self.last_reward_time > 10:
            for robot in self.robots:
                if robot.is_active:
                    robot.energy = min(Config.MAX_ENERGY, robot.energy + 20)
            self.last_reward_time = time.time()


class Robot:
    """AI-controlled robot class for CyberArena."""
    def __init__(self, name, team):
        self.id = str(uuid.uuid4())
        self.name = name
        self.team = team
        self.team_color = team.color
        self.position = Vector3(0, 0)
        self.velocity = Vector3(0, 0)
        self.health = Config.MAX_HEALTH
        self.max_health = Config.MAX_HEALTH
        self.energy = Config.MAX_ENERGY
        self.max_energy = Config.MAX_ENERGY
        self.shield = 0
        self.speed_boost = 0
        self.speed_boost_duration = 0
        self.is_active = True
        self.has_flag = False
        self.weapon = Weapon("Plasma Gun", "Ranged", Config.ATTACK_DAMAGE, Config.ATTACK_ENERGY_COST, Config.RANGED_RANGE)
        self.role = "Assault"  # Can be "Assault", "Support", "Defender", "Scout"
        self.behavior_tree = {}  # Will be initialized with AI behavior
        self.decision_memory = []  # Stores recent decisions for learning
        self.experience = 0
        self.strategy_preferences = {
            "aggression": 0.5,
            "caution": 0.5,
            "teamwork": 0.5
        }

    def move_towards(self, target_position, speed=None):
        """Move towards a target position with optional speed override."""
        if not self.is_active:
            return
        if speed is None:
            speed = Config.MOVEMENT_SPEED * (1 + self.speed_boost)
        direction = (target_position - self.position).normalize()
        self.velocity = direction * speed
        self.position += self.velocity

    def take_damage(self, damage):
        """Handle damage with shield absorption and health reduction."""
        if not self.is_active:
            return
        # Apply shield first
        if self.shield > 0:
            absorbed = min(damage, self.shield)
            self.shield -= absorbed
            damage -= absorbed
        # Then apply to health
        if damage > 0:
            self.health -= damage
        if self.health <= 0:
            self.health = 0
            self.is_active = False
            # Notify team
            if self.team:
                self.team.score = max(0, self.team.score - 5)

    def heal(self, amount):
        """Restore health with a cap at max health."""
        if not self.is_active:
            return
        self.health = min(self.max_health, self.health + amount)

    def recharge_energy(self, delta_time):
        """Recharge energy over time."""
        if not self.is_active:
            return
        self.energy = min(self.max_energy, self.energy + Config.RECHARGE_RATE * delta_time)

    def use_power_up(self, power_up):
        """Apply the effects of a power up to the robot."""
        if not self.is_active:
            return
        power_up.apply_effect(self)

    def update(self, arena):
        """Main update function for the robot's behavior."""
        if not self.is_active:
            return

        # Recharge energy
        self.recharge_energy(arena.delta_time)

        # Apply speed boost decay
        if self.speed_boost > 0 and self.speed_boost_duration > 0:
            self.speed_boost_duration -= arena.delta_time
            if self.speed_boost_duration <= 0:
                self.speed_boost = 0

        # Process AI behavior
        self.process_ai(arena)

        # Update position based on velocity
        self.position += self.velocity * arena.delta_time

        # Apply environmental effects
        self.apply_environment_effects(arena)

        # Track decisions for learning
        self.decision_memory.append({
            "time": time.time(),
            "action": self.current_action,
            "result": self.evaluate_action_result(arena),
            "position": self.position
        })

        # Update experience
        self.experience += self.evaluate_experience_gain(arena)

    def process_ai(self, arena):
        """Process the robot's AI decision-making for the current frame."""
        self.current_action = None

        # Check if we need to retreat
        if self.health < 30 or self.energy < 50:
            self.current_action = "Retreat"
            self.retreat_behavior(arena)
            return

        # Check for immediate threats
        nearest_enemy = self.find_nearest_enemy(arena)
        if nearest_enemy and self.position.distance_to(nearest_enemy.position) <= 10:
            self.current_action = "Attack"
            self.attack_behavior(arena, nearest_enemy)
            return

        # Check for objectives
        objective = self.select_objective(arena)
        if objective:
            self.current_action = "Objective"
            self.objective_behavior(arena, objective)
            return

        # Default to patrolling
        self.current_action = "Patrol"
        self.patrol_behavior(arena)

    def retreat_behavior(self, arena):
        """Behavior for when the robot needs to retreat."""
        # Find the nearest teammate
        nearest_teammate = min((r for r in arena.robots if r.team == self.team and r != self), 
                              key=lambda r: self.position.distance_to(r.position),
                              default=None)
        if nearest_teammate:
            # Retreat towards the nearest teammate
            self.move_towards(nearest_teammate.position)
        else:
            # Retreat to team base
            self.move_towards(self.team.base_position)

    def attack_behavior(self, arena, target):
        """Behavior for attacking enemies."""
        # Try to attack with the current weapon
        if self.weapon.attack(self, target):
            return
        # If not in range, move closer
        if self.position.distance_to(target.position) > Config.MELEE_RANGE:
            self.move_towards(target.position)
        else:
            # If in range but weapon is on cooldown, wait
            if not self.weapon.can_attack():
                self.velocity = Vector3(0, 0)

    def objective_behavior(self, arena, objective):
        """Behavior for working on team objectives."""
        # Move towards the objective
        self.move_towards(objective.position)
        # Check if we can interact with the objective
        if self.position.distance_to(objective.position) <= 3:
            if objective.objective_type == "CaptureFlag":
                self.pick_up_flag(arena)
            elif objective.objective_type == "DefendBase":
                # Defend the base by attacking enemies
                self.defend_base(arena)
            elif objective.objective_type == "EscortPayload":
                self.escort_payload(arena)
            elif objective.objective_type == "DestroyTarget":
                self.attack_target(arena)

    def patrol_behavior(self, arena):
        """Default behavior for patrolling the arena."""
        # Find the nearest objective
        nearest_objective = min(arena.objectives, 
                                key=lambda o: self.position.distance_to(o.position),
                                default=None)
        if nearest_objective:
            self.move_towards(nearest_objective.position)
        else:
            # Roam randomly if no objectives are nearby
            random_direction = Vector3(random.uniform(-1, 1), random.uniform(-1, 1)).normalize()
            self.move_towards(self.position + random_direction * 5)

    def find_nearest_enemy(self, arena):
        """Find the nearest enemy robot."""
        return min((r for r in arena.robots if r.team != self.team and r.is_active),
                  key=lambda r: self.position.distance_to(r.position),
                  default=None)

    def select_objective(self, arena):
        """Select the most appropriate objective based on team needs."""
        # Prioritize objectives with the lowest progress
        return min((o for o in self.team.objectives if not o.is_complete),
                  key=lambda o: o.progress,
                  default=None)

    def pick_up_flag(self, arena):
        """Pick up the flag for the CaptureFlag objective."""
        if not self.has_flag:
            self.has_flag = True
            # Notify the team
            self.team.flag_position = self.position
            self.team.score += 1

    def defend_base(self, arena):
        """Defend the team base by attacking enemies."""
        # Attack enemies that get too close to the base
        for robot in arena.robots:
            if robot.team != self.team and robot.is_active and robot.position.distance_to(self.team.base_position) <= 5:
                self.attack_behavior(arena, robot)
                return

    def escort_payload(self, arena):
        """Help escort the payload to its destination."""
        # Move towards the payload position
        self.move_towards(self.team.payload_position)
        # If we're close enough, help defend the payload
        if self.position.distance_to(self.team.payload_position) <= 3:
            # Attack any enemies near the payload
            for robot in arena.robots:
                if robot.team != self.team and robot.is_active and robot.position.distance_to(self.team.payload_position) <= 5:
                    self.attack_behavior(arena, robot)
                    return

    def attack_target(self, arena):
        """Attack the team's target objective."""
        if self.position.distance_to(self.team.payload_position) <= 5:
            # Attack the target
            self.team.target_health -= self.weapon.damage
            self.weapon.reset_cooldown()

    def apply_environment_effects(self, arena):
        """Apply environmental hazards and power-ups."""
        # Check for hazards
        for hazard in arena.hazards:
            if hazard.is_in_hazard(self):
                hazard.apply_damage(self)

        # Check for power-ups
        for power_up in arena.power_ups:
            if power_up.is_active and self.position.distance_to(power_up.position) <= 1.5:
                self.use_power_up(power_up)
                power_up.is_active = False

    def evaluate_action_result(self, arena):
        """Evaluate the result of the robot's current action."""
        result = {
            "success": 0,
            "energy_efficiency": 1,
            "team_contribution": 0
        }

        # Check if we completed an objective
        for objective in self.team.objectives:
            if objective.is_complete and objective not in self.completed_objectives:
                result["success"] = 1
                self.completed_objectives.append(objective)
                result["team_contribution"] = 0.5

        # Check if we survived the round
        if self.is_active:
            result["survival"] = 1
        else:
            result["survival"] = 0

        # Calculate energy efficiency
        result["energy_efficiency"] = self.energy / Config.MAX_ENERGY

        # Check if we helped our team
        result["team_contribution"] += self.team.score_change / Config.MAX_ROUNDS

        return result

    def evaluate_experience_gain(self, arena):
        """Calculate how much experience the robot gains from the current situation."""
        # Calculate based on action results and environment
        gain = 0

        # Success in objectives gives significant experience
        if self.current_action == "Objective" and self.evaluate_action_result(arena)["success"] > 0:
            gain += 5

        # Survival gives moderate experience
        if self.is_active:
            gain += 1

        # Effective energy use gives small experience
        gain += min(1, self.energy / Config.MAX_ENERGY) * 0.5

        # Team contribution
        if self.team.score > 0:
            gain += self.team.score / Config.MAX_ROUNDS * 0.5

        return gain

    def adapt_strategy(self, arena):
        """Adapt the robot's strategy based on experience and previous results."""
        # Update strategy preferences based on what worked well
        for decision in self.decision_memory[-5:]:  # Look at the last 5 decisions
            if decision["result"]["success"] > 0.5:
                # This action was successful, reinforce the related preference
                if decision["action"] == "Attack":
                    self.strategy_preferences["aggression"] += 0.05
                elif decision["action"] == "Defend":
                    self.strategy_preferences["caution"] += 0.05
                elif decision["action"] == "Objective":
                    self.strategy_preferences["teamwork"] += 0.05
            elif decision["result"]["success"] < 0.2:
                # This action was unsuccessful, adjust by reducing preference
                if decision["action"] == "Attack":
                    self.strategy_preferences["aggression"] = max(0.1, self.strategy_preferences["aggression"] - 0.05)
                elif decision["action"] == "Defend":
                    self.strategy_preferences["caution"] = max(0.1, self.strategy_preferences["caution"] - 0.05)
                elif decision["action"] == "Objective":
                    self.strategy_preferences["teamwork"] = max(0.1, self.strategy_preferences["teamwork"] - 0.05)

        # Normalize preferences to keep them balanced
        total = sum(self.strategy_preferences.values())
        for key in self.strategy_preferences:
            self.strategy_preferences[key] /= total


class Arena:
    """Main class for the CyberArena simulation."""
    def __init__(self, width, height, difficulty="medium"):
        self.width = width
        self.height = height
        self.time = 0
        self.delta_time = 0.1  # seconds
        self.robots = []
        self.objectives = []
        self.power_ups = []
        self.hazards = []
        self.teams = []
        self.round_number = 1
        self.game_over = False
        self.winning_team = None
        self.difficulty = difficulty
        self.difficulty_factor = Config.DIFFICULTY_FACTORS[difficulty]
        self.last_round_time = time.time()
        self.current_round_time = time.time()
        self.round_duration = 120  # seconds
        self.spawn_objects()

    def start(self):
        """Start the CyberArena simulation."""
        print("CyberArena Simulation Started")
        self.spawn_objects()
        self.run_game_loop()

    def add_robot(self, robot):
        """Add a robot to the arena."""
        self.robots.append(robot)
        if robot.team not in self.teams:
            self.teams.append(robot.team)

    def add_objective(self, objective):
        """Add an objective to the arena."""
        self.objectives.append(objective)
        objective.team.add_objective(objective)

    def add_power_up(self, power_up):
        """Add a power-up to the arena."""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard):
        """Add a hazard to the arena."""
        self.hazards.append(hazard)

    def spawn_objects(self):
        """Randomly spawn power-ups and hazards in the arena."""
        # Spawn power-ups
        for _ in range(5):
            power_type = random.choice(Config.POWER_UP_TYPES)
            x = random.uniform(0, self.width)
            y = random.uniform(0, self.height)
            self.add_power_up(PowerUp(power_type, Vector3(x, y)))

        # Spawn hazards
        for _ in range(3):
            hazard_type = random.choice(Config.HAZARD_TYPES)
            x = random.uniform(0, self.width)
            y = random.uniform(0, self.height)
            radius = random.uniform(2, 5)
            self.add_hazard(Hazard(hazard_type, Vector3(x, y), radius))

        # Spawn objectives
        for team in self.teams:
            objective_type = random.choice(Config.OBJECTIVE_TYPES)
            x = random.uniform(0, self.width)
            y = random.uniform(0, self.height)
            self.add_objective(Objective(objective_type, Vector3(x, y), team))

    def update(self):
        """Update all game objects for the current time step."""
        self.delta_time = time.time() - self.time
        self.time = time.time()

        # Update all robots
        for robot in self.robots:
            robot.update(self)
            # Apply adaptive difficulty based on team performance
            if robot.team and robot.is_active:
                team_score = robot.team.calculate_team_score()
                # Adjust robot's abilities based on team performance
                if team_score < 50:  # Underperforming team
                    robot.weapon.damage = int(Config.ATTACK_DAMAGE * 0.8 * self.difficulty_factor)
                    robot.weapon.energy_cost = int(Config.ATTACK_ENERGY_COST * 0.8 * self.difficulty_factor)
                elif team_score > 80:  # High-performing team
                    robot.weapon.damage = int(Config.ATTACK_DAMAGE * 1.2 * self.difficulty_factor)
                    robot.weapon.energy_cost = int(Config.ATTACK_ENERGY_COST * 1.2 * self.difficulty_factor)
                else:  # Average performance
                    robot.weapon.damage = int(Config.ATTACK_DAMAGE * self.difficulty_factor)
                    robot.weapon.energy_cost = int(Config.ATTACK_ENERGY_COST * self.difficulty_factor)

        # Update all objectives
        for objective in self.objectives:
            objective.update(self.robots)

        # Update all power-ups
        for power_up in self.power_ups:
            if power_up.is_active:
                power_up.remaining_time -= self.delta_time
                if power_up.remaining_time <= 0:
                    power_up.is_active = False

        # Update all hazards
        for hazard in self.hazards:
            # Apply damage at intervals
            if time.time() - hazard.last_damage_time > hazard.damage_interval:
                for robot in self.robots:
                    if hazard.is_in_hazard(robot):
                        hazard.apply_damage(robot)
                hazard.last_damage_time = time.time()

        # Update teams
        for team in self.teams:
            team.update(self)

        # Check for round completion
        self.check_round_completion()

    def check_round_completion(self):
        """Check if the round is complete and handle the next round."""
        # Check if all objectives are complete
        all_objectives_complete = all(obj.is_complete for obj in self.objectives)

        # Check if the round duration has elapsed
        if self.current_round_time + self.round_duration < time.time():
            all_objectives_complete = True

        if all_objectives_complete or self.round_number > Config.MAX_ROUNDS:
            self.game_over = True
            # Determine the winning team
            self.winning_team = max(self.teams, key=lambda t: t.score)
            print(f"Game Over! {self.winning_team.name} team wins with a score of {self.winning_team.score}!")
            return

        # Update round time
        self.current_round_time = time.time()

        # Reset the arena for the next round
        self.reset_round()

    def reset_round(self):
        """Reset the arena for a new round."""
        print(f"Round {self.round_number} over. Starting round {self.round_number + 1}...")

        # Reset all robots
        for robot in self.robots:
            if not robot.is_active:
                robot.health = Config.MAX_HEALTH
                robot.energy = Config.MAX_ENERGY
                robot.shield = 0
                robot.speed_boost = 0
                robot.is_active = True
            # Reset robot position to base
            robot.position = Vector3(random.uniform(0, self.width), random.uniform(0, self.height))

        # Reset all objectives
        for objective in self.objectives:
            objective.is_complete = False
            objective.progress = 0

        # Reset power-ups
        for power_up in self.power_ups:
            power_up.is_active = True
            power_up.remaining_time = power_up.duration

        # Reset hazards
        for hazard in self.hazards:
            hazard.last_damage_time = time.time()

        # Reset team scores
        for team in self.teams:
            team.score = 0

        self.round_number += 1

    def run_game_loop(self):
        """Main game loop that runs the simulation."""
        print("Starting CyberArena game loop...")
        while not self.game_over:
            self.update()
            self.render()
            time.sleep(self.delta_time)

    def render(self):
        """Render the current state of the arena (basic text-based visualization)."""
        print(f"\nTime: {self.time:.2f}s | Round: {self.round_number}/{Config.MAX_ROUNDS}")
        print(f"Teams: {', '.join(t.name for t in self.teams)}")
        print(f"Current score:")
        for team in self.teams:
            print(f"  {team.name}: {team.score} points")

        print("\nRobot Status:")
        for robot in self.robots:
            status = f"{robot.name}({robot.team.color})" if robot.is_active else f"{robot.name}({robot.team.color}) [DEAD]"
            print(f"  {status}: Health-{robot.health:.0f}, Energy-{robot.energy:.0f}, Position-{robot.position}")

        print("\nObjectives:")
        for objective in self.objectives:
            obj_status = "Complete" if objective.is_complete else f"{objective.progress:.0f}%"
            print(f"  {objective.objective_type} for {objective.team.name}: {obj_status} at {objective.position}")

        print("\nPower-ups:")
        for power_up in self.power_ups:
            if power_up.is_active:
                print(f"  {power_up.power_type} at {power_up.position} (Duration: {power_up.remaining_time:.1f}s)")

        print("\nHazards:")
        for hazard in self.hazards:
            print(f"  {hazard.hazard_type} at {hazard.position} (Radius: {hazard.radius:.1f}m)")

    def save_game_state(self, filename):
        """Save the current game state to a file."""
        game_state = {
            "time": self.time,
            "round_number": self.round_number,
            "robots": [
                {
                    "id": r.id,
                    "name": r.name,
                    "team": r.team.name,
                    "position": (r.position.x, r.position.y),
                    "health": r.health,
                    "energy": r.energy,
                    "shield": r.shield,
                    "speed_boost": r.speed_boost,
                    "speed_boost_duration": r.speed_boost_duration,
                    "is_active": r.is_active,
                    "has_flag": r.has_flag,
                    "weapon": {
                        "name": r.weapon.name,
                        "attack_type": r.weapon.attack_type,
                        "damage": r.weapon.damage,
                        "energy_cost": r.weapon.energy_cost,
