# Base classes for CyberArena
class Vector3:
    """3D vector class for handling positions, directions, and velocities."""
    def __init__(self, x, y, z=0):
        self.x = x
        self.y = y
        self.z = z

    def __add__(self, other):
        return Vector3(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other):
        return Vector3(self.x - other.x, self.y - other.y, self.z - other.z)

    def __mul__(self, scalar):
        return Vector3(self.x * scalar, self.y * scalar, self.z * scalar)

    def __truediv__(self, scalar):
        return Vector3(self.x / scalar, self.y / scalar, self.z / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2 + self.z**2)

    def normalize(self):
        mag = self.magnitude()
        if mag > 0:
            return Vector3(self.x / mag, self.y / mag, self.z / mag)
        return Vector3(0, 0, 0)

    def distance_to(self, other):
        return (self - other).magnitude()

    def dot(self, other):
        return self.x * other.x + self.y * other.y + self.z * other.z

    def __str__(self):
        return f"({self.x:.2f}, {self.y:.2f}, {self.z:.2f})"


class Weapon:
    """Base class for all weapon types in CyberArena."""
    def __init__(self, name, attack_type, damage, energy_cost, range):
        self.name = name
        self.attack_type = attack_type  # "Ranged" or "Melee"
        self.damage = damage
        self.energy_cost = energy_cost
        self.range = range
        self.cooldown = 0  # seconds

    def can_attack(self):
        return self.cooldown <= 0

    def reset_cooldown(self):
        # Cooldown is 1/3 of the time it takes to recharge energy
        self.cooldown = max(0, self.energy_cost / Config.RECHARGE_RATE * 0.33)

    def attack(self, attacker, target):
        if not self.can_attack():
            return False
        if attacker.energy < self.energy_cost:
            return False
        distance = attacker.position.distance_to(target.position)
        if distance > self.range:
            return False
        if self.attack_type == "Ranged":
            if random.random() < 0.8:  # 80% accuracy
                target.take_damage(self.damage)
                attacker.energy -= self.energy_cost
                self.reset_cooldown()
                return True
        elif self.attack_type == "Melee":
            if distance <= Config.MELEE_RANGE:
                target.take_damage(self.damage)
                attacker.energy -= self.energy_cost
                self.reset_cooldown()
                return True
        return False


class PowerUp:
