    def apply_effect(self, robot):
        if not self.is_active:
            return
        if self.power_type == "Healing":
            robot.heal(30)
        elif self.power_type == "Shield":
            robot.shield = min(Config.MAX_HEALTH, robot.shield + 30)
        elif self.power_type == "Energy":
            robot.energy = min(Config.MAX_ENERGY, robot.energy + 50)
        elif self.power_type == "Speed":
            robot.speed_boost = min(2, robot.speed_boost + 0.5)
            robot.speed_boost_duration = self.duration


class Hazard:
    """Environmental hazard class for obstacles and dangers."""
    def __init__(self, hazard_type, position, radius):
