class Objective:
    """Base class for team objectives in CyberArena."""
    def __init__(self, objective_type, position, team):
        self.objective_type = objective_type
        self.position = position
        self.team = team
        self.is_complete = False
        self.progress = 0  # 0-100% completion
        self.id = str(uuid.uuid4())

    def update(self, robots):
        """Update objective status based on robot actions."""
        if self.is_complete:
            return
        if self.objective_type == "CaptureFlag":
            # Find if any enemy team robot has the flag
            for robot in robots:
                if robot.team != self.team and robot.has_flag:
