class PowerUp:
    def __init__(self, power_type, duration):
        self.power_type = power_type
        self.duration = duration
        self.remaining_time = duration

    def apply_effect(self, robot):
        if self.power_type == PowerUpType.SHIELD:
            robot.shield = 100
        elif self.power_type == PowerUpType.SPEED_BOOST:
            robot.speed += 1.5
        elif self.power_type == PowerUpType.DAMAGE_BOOST:
            robot.damage_multiplier += 0.5
        elif self.power_type == PowerUpType.RELOAD_BOOST:
            robot.reload_speed_multiplier += 0.5

    def update(self, robot):
        if self.remaining_time > 0:
            self.remaining_time -= 1
            if self.remaining_time == 0:
                self.remove_effect(robot)
                return True
        return False

    def remove_effect(self, robot):
        if self.power_type == PowerUpType.SPEED_BOOST:
            robot.speed -= 1.5
        elif self.power_type == PowerUpType.DAMAGE_BOOST:
            robot.damage_multiplier -= 0.5
        elif self.power_type == PowerUpType.RELOAD_BOOST:
            robot.reload_speed_multiplier -= 0.5

