        self.name = name
        self.weapon_type = weapon_type
        self.damage = damage
        self.reload_time = reload_time
        self.is_reloading = False
        self.reload_timer = 0

    def can_fire(self):
        return not self.is_reloading

    def start_reload(self):
        self.is_reloading = True
        self.reload_timer = self.reload_time

    def update(self):
        if self.is_reloading and self.reload_timer > 0:
            self.reload_timer -= 1
            if self.reload_timer == 0:
                self.is_reloading = False

# Player Character Class
class Character:
    def __init__(self, name, team, weapon):
        self.name = name
        self.team = team
        self.weapon = weapon
        self.health = 100
        self.score = 0

    def attack(self, target):
        if self.weapon.can_fire():
            target.health -= self.weapon.damage
            self.weapon.start_reload()
            print(f"{self.name} attacked {target.name} for {self.weapon.damage} damage.")

# AI System for Controlling Enemy Characters
