class Weapon:
    """Base class for all weapons with common properties and behaviors."""

    def __init__(self, name, weapon_type, damage, range, cooldown):
        self.name = name
        self.weapon_type = weapon_type
        self.damage = damage
        self.range = range  # in meters
        self.cooldown = cooldown  # in seconds
        self.last_used = 0  # timestamp of last use

    def is_ready(self):
        """Check if the weapon is ready for use based on cooldown."""
        return time.time() - self.last_used >= self.cooldown

    def use(self):
        """Use the weapon and record the time of use."""
        if self.is_ready():
            self.last_used = time.time()
            return True
        return False

