# CyberArena: A Multi-Agent System for a Futuristic Battle Arena

import random
import time
import threading
from enum import Enum
from typing import List, Dict, Tuple, Optional, Union, Set

# === ENUMS AND TYPES ===
class Team(Enum):
    ALIEN = "Alien"
    MECH = "Mech"
    CYBER = "Cyber"

class WeaponType(Enum):
    RANGED = "Ranged"
    MELEE = "Melee"
    SUPPORT = "Support"

class ObjectiveType(Enum):
    CAPTURE_FLAG = "Capture Flag"
    DEFEND_BASE = "Defend Base"
    ESCORT_PAYLOAD = "Escort Payload"

class Status(Enum):
    ACTIVE = "Active"
    INACTIVE = "Inactive"
    ELIMINATED = "Eliminated"

class PowerUpType(Enum):
    SHIELD = "Shield"
    SPEED_BOOST = "Speed Boost"
    DAMAGE_AMPLIFIER = "Damage Amplifier"

class HazardType(Enum):
    LAVA_ZONE = "Lava Zone"
    ELECTRIC_FIELD = "Electric Field"
    ICE_PATCH = "Ice Patch"

class Role(Enum):
    SCOUT = "Scout"
    TANK = "Tank"
    SUPPORT = "Support"
    COMMANDER = "Commander"

Point2D = Tuple[float, float]
Point3D = Tuple[float, float, float]

# === BASE CLASSES ===
class Entity:
    def __init__(self, name: str, position: Point3D, health: float = 100.0):
        self.name = name
        self.position = position
        self.health = health
        self.status = Status.ACTIVE

    def take_damage(self, amount: float):
        self.health -= amount
        if self.health <= 0:
            self.status = Status.ELIMINATED
            self.on_eliminate()

    def on_eliminate(self):
        pass  # To be overridden in derived classes

    def is_active(self):
        return self.status == Status.ACTIVE

class Robot(Entity):
    def __init__(self, name: str, team: Team, position: Point3D, health: float = 100.0):
        super().__init__(name, position, health)
        self.team = team
        self.weapon = None
        self.role = Role.SUPPORT  # Default role
        self.skills = {}  # Dictionary of skills: {skill_name: skill_object}
        self.experience = 0
        self.memory = []  # Battle memory for learning

    def assign_role(self, role: Role):
        self.role = role

    def assign_weapon(self, weapon):
        self.weapon = weapon

    def attack(self, target: Entity):
        if self.weapon:
            self.weapon.fire(target)

    def learn(self, battle_data: Dict):
        self.memory.append(battle_data)
        self.update_skills()

    def update_skills(self):
        # This is a placeholder for machine learning logic
        # In a real implementation, this would analyze memory and improve skills
        self.experience += 1
        if self.experience % 5 == 0:
            self.role = random.choice([r for r in Role if r != self.role])  # Change role periodically for variety

    def on_eliminate(self):
        self.status = Status.ELIMINATED
        self.weapon = None  # Reset weapon

class Weapon:
    def __init__(self, name: str, weapon_type: WeaponType, damage: float, range: float = 0.0, is_charged: bool = False):
        self.name = name
        self.type = weapon_type
        self.base_damage = damage
        self.range = range
        self.is_charged = is_charged

    def fire(self, target: Entity):
        if self.type == WeaponType.RANGED:
            self._fire_ranged(target)
        elif self.type == WeaponType.MELEE:
            self._fire_melee(target)
        else:
            self._fire_support(target)

    def _fire_ranged(self, target: Entity):
        distance = self._calculate_distance(target)
        if distance <= self.range:
            damage = self.base_damage
            if self.is_charged:
                damage *= 1.5  # Charged shot bonus
            target.take_damage(damage)
            print(f"{self.name} (Ranged): Hit {target.name} for {damage} damage.")
        else:
            print(f"{self.name} (Ranged): Missed {target.name} - Out of Range.")

    def _fire_melee(self, target: Entity):
        distance = self._calculate_distance(target)
        if distance <= 1.0:  # Melee range is 1 unit
            damage = self.base_damage
            target.take_damage(damage)
            print(f"{self.name} (Melee): Hit {target.name} for {damage} damage.")
        else:
            print(f"{self.name} (Melee): Missed {target.name} - Too Far.")

    def _fire_support(self, target: Entity):
        # Support weapons might heal, shield, or otherwise assist
        bonus = self.base_damage
        if self.name == "Heal Module":
            target.health = min(target.health + bonus, 100.0)
            print(f"{self.name} (Support): Healed {target.name} for {bonus} health.")
        elif self.name == "Shield Module":
            target.shield = min(getattr(target, "shield", 0) + bonus, 50.0)
            print(f"{self.name} (Support): Shielded {target.name} with {bonus} energy.")

    def _calculate_distance(self, target: Entity) -> float:
        # Simple 3D distance formula
        dx = self.owner.position[0] - target.position[0]
        dy = self.owner.position[1] - target.position[1]
        dz = self.owner.position[2] - target.position[2]
        return (dx**2 + dy**2 + dz**2)**0.5

# === ARENA AND OBJECTIVES ===
class Objective:
    def __init__(self, obj_type: ObjectiveType, position: Point3D, team: Optional[Team] = None):
        self.type = obj_type
        self.position = position
        self.owner_team = team
        self.status = Status.INACTIVE

    def activate(self):
        self.status = Status.ACTIVE
        print(f"{self.type.value} Objective activated at {self.position}")

    def complete(self, team: Team):
        self.status = Status.INACTIVE
        self.owner_team = team
        print(f"{self.type.value} Objective completed by {team.value}")

class FlagObjective(Objective):
    def __init__(self, team: Team, home_position: Point3D, capture_position: Point3D):
        super().__init__(ObjectiveType.CAPTURE_FLAG, capture_position, team)
        self.home_position = home_position
        self.current_position = capture_position

    def move_to_home(self):
        self.current_position = self.home_position
        print(f"Flag returned to home position for {self.owner_team.value} team")

    def move_to_capture(self):
        self.current_position = self.position
        print(f"Flag moved to capture position for {self.owner_team.value} team")

class BaseObjective(Objective):
    def __init__(self, team: Team, position: Point3D, health: float = 200.0):
        super().__init__(ObjectiveType.DEFEND_BASE, position, team)
        self.health = health
        self.structures = []

    def add_structure(self, structure):
        self.structures.append(structure)

    def take_damage(self, amount: float):
        self.health -= amount
        if self.health <= 0:
            self.status = Status.ELIMINATED
            print(f"{self.owner_team.value} Base destroyed")

class PayloadObjective(Objective):
    def __init__(self, team: Team, start_position: Point3D, end_position: Point3D):
        super().__init__(ObjectiveType.ESCORT_PAYLOAD, start_position, team)
        self.start_position = start_position
        self.end_position = end_position
        self.current_position = start_position
        self.is_moving = False

    def move(self):
        self.is_moving = True
        print(f"Payload moving from {self.start_position} to {self.end_position}")

    def stop(self):
        self.is_moving = False
        print(f"Payload stopped at {self.current_position}")

# === DYNAMIC DIFFICULTY ===
class AdaptiveDifficulty:
    def __init__(self, base_difficulty: float = 1.0):
        self.base_difficulty = base_difficulty
        self.current_difficulty = base_difficulty
        self.robot_performance = {}

    def update_difficulty(self, performance_data: Dict):
        # This is a simplified example of difficulty adjustment
        if not performance_data:
            return

        total_score = sum(p["score"] for p in performance_data.values())
        avg_score = total_score / len(performance_data)

        if avg_score > 80:  # If robots are performing very well
            self.current_difficulty = min(3.0, self.current_difficulty * 1.2)
        elif avg_score < 40:  # If robots are struggling
            self.current_difficulty = max(0.5, self.current_difficulty * 0.8)
        else:
            self.current_difficulty = self.base_difficulty

        print(f"Adaptive Difficulty updated to: {self.current_difficulty:.2f}")

        # Update AI behavior based on difficulty
        for robot_id, data in self.robot_performance.items():
            robot = data["robot"]
            if self.current_difficulty > 1.5:
                if robot.role != Role.COMMANDER:
                    robot.assign_role(Role.COMMANDER)
            elif self.current_difficulty < 0.7:
                if robot.role != Role.SCOUT:
                    robot.assign_role(Role.SCOUT)

    def record_performance(self, robot: Robot, score: float):
        self.robot_performance[robot.name] = {
            "robot": robot,
            "score": score
        }

# === GAME MECHANICS ===
class GameEngine:
    def __init__(self, map_name: str, teams: List[Team]):
        self.map_name = map_name
        self.teams = teams
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[Dict] = []  # List of power-up dicts
        self.hazards: List[Dict] = []  # List of hazard dicts
        self.difficulty = AdaptiveDifficulty(base_difficulty=1.0)
        self.battle_log = []
        self.is_running = False
        self.game_timer = 0
        self.scoreboard: Dict[Team, int] = {team: 0 for team in teams}

    def add_robot(self, robot: Robot):
        self.robots.append(robot)
        self.difficulty.record_performance(robot, 0)  # Initial recording

    def add_objective(self, objective: Objective):
        self.objectives.append(objective)

    def add_power_up(self, power_up: PowerUpType, position: Point3D, duration: float = 10.0):
        self.power_ups.append({
            "type": power_up,
            "position": position,
            "duration": duration,
            "active": True,
            "activation_time": time.time()
        })

    def add_hazard(self, hazard: HazardType, position: Point3D, radius: float = 5.0):
        self.hazards.append({
            "type": hazard,
            "position": position,
            "radius": radius,
            "active": True
        })

    def start_game(self):
        self.is_running = True
        self.game_timer = 0
        for objective in self.objectives:
            objective.activate()

        # Start game loop in a separate thread
        game_thread = threading.Thread(target=self._game_loop)
        game_thread.start()

    def _game_loop(self):
        while self.is_running:
            self.game_timer += 1
            self.update_power_ups()
            self.update_hazards()
            self.update_objectives()
            self.update_difficulty()
            self.battle_tick()
            time.sleep(1)  # 1-second tick

    def battle_tick(self):
        for robot in self.robots:
            if robot.status == Status.ELIMINATED:
                continue

            # AI decision making (simplified)
            target = self._select_target(robot)
            if target:
                robot.attack(target)
                self._log_action(robot, "attack", target.name)
            else:
                # Move to a random position
                new_position = self._generate_random_position()
                robot.position = new_position

            # Check for power-ups
            self._check_for_power_up(robot)

    def _select_target(self, robot: Robot) -> Optional[Entity]:
        # Simple target selection logic
        enemies = [r for r in self.robots if r.team != robot.team and r.status == Status.ACTIVE]
        if enemies:
            return random.choice(enemies)
        return None

    def _generate_random_position(self) -> Point3D:
        # Generate a random position within the map bounds
        return (random.uniform(-50, 50), random.uniform(-50, 50), 0)

    def _log_action(self, robot: Robot, action: str, detail: str):
        self.battle_log.append({
            "time": time.time(),
            "robot": robot.name,
            "team": robot.team.value,
            "action": action,
            "detail": detail
        })

    def update_power_ups(self):
        for power_up in self.power_ups:
            if power_up["active"] and time.time() - power_up["activation_time"] > power_up["duration"]:
                power_up["active"] = False
                print(f"{power_up['type'].value} power-up expired at {power_up['position']}")

    def update_hazards(self):
        for hazard in self.hazards:
            if hazard["active"]:
                # Apply hazard effects to robots
                for robot in self.robots:
                    distance = self._calculate_distance(robot.position, hazard["position"])
                    if distance <= hazard["radius"]:
                        if hazard["type"] == HazardType.LAVA_ZONE:
                            robot.take_damage(5.0)
                            print(f"{robot.name} damaged by Lava Zone for 5.0 damage!")
                        elif hazard["type"] == HazardType.ELECTRIC_FIELD:
                            robot.take_damage(3.0)
                            print(f"{robot.name} damaged by Electric Field for 3.0 damage!")
                        elif hazard["type"] == HazardType.ICE_PATCH:
                            robot.status = Status.INACTIVE
                            print(f"{robot.name} immobilized by Ice Patch!")

    def update_objectives(self):
        for objective in self.objectives:
            if objective.type == ObjectiveType.CAPTURE_FLAG:
                flag_obj: FlagObjective = objective
                if flag_obj.status == Status.ACTIVE:
                    # Check if any robot is at the flag position
                    for robot in self.robots:
                        if robot.status != Status.ACTIVE:
                            continue
                        distance = self._calculate_distance(robot.position, flag_obj.current_position)
                        if distance <= 1.0:
                            # Flag is captured!
                            flag_obj.complete(robot.team)
                            self.scoreboard[robot.team] += 100
                            print(f"{robot.team.value} captured the flag! Score: {self.scoreboard[robot.team]}")
                            break
            elif objective.type == ObjectiveType.DEFEND_BASE:
                base_obj: BaseObjective = objective
                if base_obj.status == Status.ACTIVE:
                    # Check if base is being attacked
                    for robot in self.robots:
                        if robot.team != base_obj.owner_team and robot.status == Status.ACTIVE:
                            distance = self._calculate_distance(robot.position, base_obj.position)
                            if distance <= 5.0:
                                base_obj.take_damage(10.0)
                                print(f"{robot.team.value} is attacking {base_obj.owner_team.value} base!")
                                break
            elif objective.type == ObjectiveType.ESCORT_PAYLOAD:
                payload_obj: PayloadObjective = objective
                if payload_obj.status == Status.ACTIVE and payload_obj.is_moving:
                    distance = self._calculate_distance(payload_obj.current_position, payload_obj.end_position)
                    if distance <= 1.0:
                        payload_obj.complete(payload_obj.owner_team)
                        self.scoreboard[payload_obj.owner_team] += 100
                        print(f"{payload_obj.owner_team.value} completed the payload escort! Score: {self.scoreboard[payload_obj.owner_team]}")

    def update_difficulty(self):
        # Gather performance data for difficulty adjustment
        performance_data = {}
        for robot in self.robots:
            score = robot.experience * 2 + self._calculate_combat_effectiveness(robot)
            performance_data[robot.name] = {
                "score": score,
                "team": robot.team.value,
                "robot": robot
            }

        self.difficulty.update_difficulty(performance_data)

    def _calculate_combat_effectiveness(self, robot: Robot) -> float:
        # Simple measure of combat effectiveness
        return robot.health / 100.0 * 100  # Health percentage contribution

    def _calculate_distance(self, pos1: Point3D, pos2: Point3D) -> float:
        # Simple 3D distance formula
        dx = pos1[0] - pos2[0]
        dy = pos1[1] - pos2[1]
        dz = pos1[2] - pos2[2]
        return (dx**2 + dy**2 + dz**2)**0.5

    def _check_for_power_up(self, robot: Robot):
        for power_up in self.power_ups:
            if not power_up["active"]:
                continue
            distance = self._calculate_distance(robot.position, power_up["position"])
            if distance <= 2.0:
                self._apply_power_up(robot, power_up)
                power_up["active"] = False
                print(f"{robot.name} picked up {power_up['type'].value} power-up!")

    def _apply_power_up(self, robot: Robot, power_up: Dict):
        p_type = power_up["type"]
        if p_type == PowerUpType.SHIELD:
            robot.shield = min(getattr(robot, "shield", 0) + 50.0, 50.0)
            print(f"{robot.name} has been shielded for 50.0 energy!")
        elif p_type == PowerUpType.SPEED_BOOST:
            robot.speed = min(getattr(robot, "speed", 1.0) * 1.5, 3.0)
            print(f"{robot.name} speed increased to {robot.speed}!")
        elif p_type == PowerUpType.DAMAGE_AMPLIFIER:
            robot.weapon.base_damage = round(robot.weapon.base_damage * 1.5, 2)
            print(f"{robot.name}'s weapon damage increased to {robot.weapon.base_damage}!")

    def get_scoreboard(self):
        return self.scoreboard

    def end_game(self):
        self.is_running = False
        print("=== GAME OVER ===")
        print("Final Scoreboard:")
        for team, score in self.scoreboard.items():
            print(f"{team.value}: {score} points")

