class Player:
    def __init__(self, player_id: str, name: str, team: Team, health: int = 100, score: int = 0):
        self.player_id = player_id
        self.name = name
        self.team = team
        self.health = health
        self.score = score
        self.status = Status.ACTIVE

    def take_damage(self, amount: int):
        self.health -= amount
        if self.health <= 0:
            self.status = Status.ELIMINATED

    def add_score(self, amount: int):
        self.score += amount

    def reset(self):
        self.health = 100
        self.score = 0
        self.status = Status.ACTIVE

class Weapon:
    def __init__(self, weapon_id: str, name: str, weapon_type: WeaponType, damage: int, ammo: int = 60):
        self.weapon_id = weapon_id
        self.name = name
        self.weapon_type = weapon_type
        self.damage = damage
        self.ammo = ammo

    def is_ranged(self) -> bool:
        return self.weapon_type == WeaponType.RANGED

class Challenge:
    def __init__(self, challenge_id: str, name: str, challenge_type: ChallengeType, difficulty: int = 1, time_limit: int = 60):
        self.challenge_id = challenge_id
        self.name = name
        self.challenge_type = challenge_type
        self.difficulty = difficulty
        self.time_limit = time_limit
        self.status = Status.ACTIVE

    def start(self):
        self.status = Status.ACTIVE

    def complete(self):
        self.status = Status.INACTIVE

# === GAME ENGINE ===
class GameEngine:
    def __init__(self):
        self.players: Dict[str, Player] = {}
        self.weapons: Dict[str, Weapon] = {}
        self.challenges: Dict[str, Challenge] = {}
        self.current_challenge: Optional[Challenge] = None
        self.game_status = Status.ACTIVE

