        if player_id not in self.players:
            self.players[player_id] = Player(player_id, name, team)

    def add_weapon(self, weapon_id: str, name: str, weapon_type: WeaponType, damage: int, ammo: int):
        if weapon_id not in self.weapons:
            self.weapons[weapon_id] = Weapon(weapon_id, name, weapon_type, damage, ammo)

    def add_challenge(self, challenge_id: str, name: str, challenge_type: ChallengeType, difficulty: int, time_limit: int):
        if challenge_id not in self.challenges:
            self.challenges[challenge_id] = Challenge(challenge_id, name, challenge_type, difficulty, time_limit)

    def start_challenge(self, challenge_id: str):
        if challenge_id in self.challenges:
            self.current_challenge = self.challenges[challenge_id]
