def fetch_product_info(product_query, retailer):
    if (product_query, retailer) in product_cache:
        return product_cache[(product_query, retailer)]

    url = RETAILER_API_URLS[retailer].format(product_query)
    try:
        response = requests.get(url)
        if response.status_code == 200:
            data = response.json()
            result = {
                'retailer': retailer,
                'products': data.get('products', [])
            }
