    def fire_weapon(self, target: "Robot") -> bool:
        """Attempt to fire weapon at a target robot. Returns True if successful."""
        # Check if weapon is ready
        if time.time() - self.weapon.last_fired < self.weapon.cooldown:
            return False

        # Check if within range
        distance = math.sqrt((target.position.x - self.position.x)**2 + 
                             (target.position.y - self.position.y)**2)

        if distance > self.weapon.range:
            return False

        # Check if has enough energy
        if self.energy < self.weapon.energy_cost:
            return False

        # Fire the weapon
        self.weapon.last_fired = time.time()
        self.energy -= self.weapon.energy_cost
        target.health -= self.weapon.damage

        self.battle_log.append({
            "action": "fired",
            "target": target.id,
            "weapon": self.weapon.name,
            "damage": self.weapon.damage,
            "timestamp": time.time()
        })

        return True

    def apply_power_up(self, power_up: PowerUpType, duration: float):
        """Apply a power-up to the robot for a specified duration."""
        if power_up == PowerUpType.SHIELD:
            self.status_effects[PowerUpType.SHIELD] = time.time() + duration
        elif power_up == PowerUpType.ENERGIZE:
            self.status_effects[PowerUpType.ENERGIZE] = time.time() + duration
        elif power_up == PowerUpType.SPEED:
            self.status_effects[PowerUpType.SPEED] = time.time() + duration
        elif power_up == PowerUpType.HEAL:
            self.health = min(MAX_HEALTH, self.health + 30)

    def update(self, delta_time: float):
        """Update robot state based on active power-ups and elapsed time."""
        # Update position based on velocity
        self.position.x += self.velocity.x * delta_time
        self.position.y += self.velocity.y * delta_time

        # Check for power-up expiration
        expired_effects = []
        for effect, end_time in self.status_effects.items():
            if time.time() > end_time:
                expired_effects.append(effect)

        for effect in expired_effects:
            if effect == PowerUpType.SHIELD:
                del self.status_effects[PowerUpType.SHIELD]
            elif effect == PowerUpType.ENERGIZE:
                del self.status_effects[PowerUpType.ENERGIZE]
            elif effect == PowerUpType.SPEED:
                del self.status_effects[PowerUpType.SPEED]

        # Regenerate energy if energize power-up is active
        if PowerUpType.ENERGIZE in self.status_effects:
            energy_gain = 5 * delta_time
            self.energy = min(MAX_ENERGY, self.energy + energy_gain)

        # Regular energy regeneration
        self.energy = min(MAX_ENERGY, self.energy + 1 * delta_time)

        # Regular health regeneration if not in combat
        if time.time() - self.last_action > 5:
            self.health = min(MAX_HEALTH, self.health + 0.5 * delta_time)

