            'preferences': user.preferences,
            'lists': [list.name for list in user.shopping_lists]
        }

    def update_catalog(self, product_data: List[Dict[str, Any]]):
        for product in product_data:
            self.product_catalog[product['product_id']] = product

    def get_recommendations(self, user_id: str) -> List[str]:
        if user_id in self.recommendations_cache:
            return self.recommendations_cache[user_id][:MAX_RECOMMENDATIONS]

        user = self.user_data.get(user_id)
        if not user:
            return []

        # Generate recommendations based on preferences, shopping history, and group activities
        recommendations = []
        for product in self.product_catalog.values():
            if (product['category'] in user['preferences'] or product['name'] in user['lists']) and product['availability']:
                recommendations.append(product['name'])

        # Sort by rating and price
        recommendations.sort(key=lambda x: (self.product_catalog[x]['rating'], -self.product_catalog[x]['price']))

        self.recommendations_cache[user_id] = recommendations
        return recommendations[:MAX_RECOMMENDATIONS]

# Notification System
