    def __init__(self):
        self.subscriptions = {}

    def subscribe(self, user_id: str, list_id: str):
        if list_id not in self.subscriptions:
            self.subscriptions[list_id] = set()
        self.subscriptions[list_id].add(user_id)

    def notify(self, list_id: str, event: str):
