            'name': name,
            'category': category,
            'brand': brand,
            'price': price,
            'rating': rating,
            'availability': availability
        }

    def search(self, query: str, filter_by: Dict[str, Any] = {}) -> List[Dict[str, Any]]:
        results = []
        for product in self.product_index.values():
            if query.lower() in product['name'].lower() or query.lower() in product['category'].lower():
                match = True
                for key, value in filter_by.items():
                    if key == 'price' and product[key] > value:
                        match = False
                        break
                    elif key == 'rating' and product[key] < value:
                        match = False
                        break
                    elif key == 'availability' and product[key] != value:
                        match = False
                        break
                if match:
                    results.append(product)
        # Sort by rating (descending) and price (ascending)
        results.sort(key=lambda x: (-x['rating'], x['price']))
        return results[:MAX_SEARCH_RESULTS]

