class AdaptiveDifficulty:
    def __init__(self, arena: CyberArena):
        self.arena = arena
        self.difficulty_history: List[float] = []
        self.max_difficulty = 3.0
        self.min_difficulty = 0.5

    def update_difficulty(self) -> None:
        """Update the difficulty based on recent performance"""
        if len(self.arena.robots) == 0:
            return

        # Calculate average robot performance
        average_health = sum(robot.health for robot in self.arena.robots.values() 
                            if robot.is_active) / len(self.arena.robots)
        average_health_ratio = average_health / self.arena.robots[next(iter(self.arena.robots))].max_health

        # Calculate kill/death ratio (simplified)
        total_kills = sum(robot.score for robot in self.arena.robots.values())
        total_deaths = sum(1 for robot in self.arena.robots.values() if not robot.is_active)

        kd_ratio = total_kills / (total_deaths + 1)  # +1 to avoid division by zero

        # Calculate difficulty adjustment based on performance
        if average_health_ratio > 0.7 and kd_ratio > 2.0:
            # Robots are doing too well, increase difficulty
            new_difficulty = min(self.max_difficulty, self.arena.difficulty * 1.1)
        elif average_health_ratio < 0.3 and kd_ratio < 0.5:
            # Robots are struggling, decrease difficulty
            new_difficulty = max(self.min_difficulty, self.arena.difficulty * 0.9)
        else:
            # Keep difficulty stable
            new_difficulty = self.arena.difficulty

        # Apply the difficulty change
        if abs(new_difficulty - self.arena.difficulty) > 0.05:
            self.arena.update_difficulty(new_difficulty)
            self.difficulty_history.append(new_difficulty)

    def get_difficulty_trend(self) -> str:
        """Get a description of the difficulty trend over time"""
        if len(self.difficulty_history) < 3:
            return "Insufficient data to determine trend"

        recent_difficulties = self.difficulty_history[-3:]
        change = recent_difficulties[-1] - recent_difficulties[0]

        if change > 0.2:
            return "Difficulty is increasing rapidly"
        elif change < -0.2:
            return "Difficulty is decreasing rapidly"
        elif change > 0:
            return "Difficulty is gradually increasing"
        elif change < 0:
            return "Difficulty is gradually decreasing"
        else:
            return "Difficulty is stable"

