# Main implementation of the CyberArena multi-agent system

import random
import time
import threading
from dataclasses import dataclass
from enum import Enum


# -------------------
# Base Classes and Enums
# -------------------

class Team(Enum):
    BLUE = "Blue Team"
    RED = "Red Team"


class WeaponType(Enum):
    RANGED = "Ranged"
    MELEE = "Melee"
    SUPPORT = "Support"


class StatusEffect(Enum):
    STUN = "Stunned"
    SLOWED = "Slowed"
    BURNING = "Burning"
    HEALED = "Healed"


class Objective(Enum):
    CAPTURE_FLAG = "Capture the Enemy Flag"
    DEFEND_BASE = "Defend Your Base"
    ESCORT_PAYLOAD = "Escort the Payload to the Target Zone"


# -------------------
# Robot Class
# -------------------

@dataclass
class Position:
    x: float
    y: float
    z: float = 0.0


class Weapon:
    def __init__(self, name: str, weapon_type: WeaponType, damage: float, range: float, cooldown: float):
        self.name = name
        self.type = weapon_type
        self.damage = damage
        self.range = range
        self.cooldown = cooldown
        self.next_available = 0  # Time when the weapon is ready to be used again

    def is_ready(self, current_time: float) -> bool:
        return current_time >= self.next_available

    def use(self, current_time: float) -> None:
        self.next_available = current_time + self.cooldown


class PowerUp:
    def __init__(self, name: str, effect: StatusEffect, duration: float, activation_time: float):
        self.name = name
        self.effect = effect
        self.duration = duration
        self.activation_time = activation_time
        self.expires_at = 0

    def is_active(self, current_time: float) -> bool:
        return current_time < self.expires_at

    def activate(self, current_time: float) -> None:
        self.expires_at = current_time + self.duration


class Robot:
    def __init__(self, name: str, team: Team, position: Position):
        self.name = name
        self.team = team
        self.position = position
        self.health = 100.0
        self.max_health = 100.0
        self.speed = 5.0
        self.weapons = []  # List of weapons available to the robot
        self.power_ups = []  # List of power-ups available to the robot
        self.status_effects = {}  # Dictionary of active status effects (effect_type: remaining_time)
        self.objective = None  # Objective assigned to the robot
        self.role = None  # Role in the team (e.g., attacker, defender, healer)
        self.skills = []  # List of skills the robot has learned
        self.experience = 0  # Experience points for learning and adaptation

    def add_weapon(self, weapon: Weapon) -> None:
        self.weapons.append(weapon)

    def add_power_up(self, power_up: PowerUp) -> None:
        self.power_ups.append(power_up)

    def apply_status_effect(self, effect: StatusEffect, duration: float) -> None:
        self.status_effects[effect] = duration

    def update_status_effects(self, delta_time: float) -> None:
        """Update all active status effects by reducing their remaining time."""
        for effect, remaining in list(self.status_effects.items()):
            remaining -= delta_time
            if remaining <= 0:
                del self.status_effects[effect]
            else:
                self.status_effects[effect] = remaining

    def attack(self, target, current_time: float) -> None:
        """Handle attack logic, checking for weapon readiness and targeting."""
        for weapon in self.weapons:
            if weapon.is_ready(current_time):
                # Example attack logic
                distance = ((self.position.x - target.position.x)**2 + (self.position.y - target.position.y)**2)**0.5
                if distance <= weapon.range:
                    target.health -= weapon.damage
                    weapon.use(current_time)
                    print(f"{self.name} attacked {target.name} with {weapon.name}, dealing {weapon.damage} damage.")
                    break

    def move_towards(self, target_position: Position, delta_time: float) -> None:
        """Move the robot towards a target position."""
        dx = target_position.x - self.position.x
        dy = target_position.y - self.position.y
        distance = (dx**2 + dy**2)**0.5

        if distance > 0:
            self.position.x += dx / distance * self.speed * delta_time
            self.position.y += dy / distance * self.speed * delta_time

    def use_power_up(self, power_up_name: str, current_time: float) -> None:
        """Use a power-up if available."""
        for power_up in self.power_ups:
            if power_up.name == power_up_name:
                if not power_up.is_active(current_time):
                    power_up.activate(current_time)
                    print(f"{self.name} activated {power_up.name}.")
                break

    def learn_skill(self, skill_name: str) -> None:
        """Add a skill to the robot's skillset."""
        self.skills.append(skill_name)
        self.experience += 10  # Reward with experience for learning
        print(f"{self.name} learned a new skill: {skill_name}.")

    def update_learning(self) -> None:
        """Improve skills or adapt to new situations based on experience."""
        if self.experience >= 50:
            self.speed += 0.5
            self.max_health += 5.0
