class CombatSystem:
    def __init__(self, team_manager: TeamManager):
        self.team_manager = team_manager

    def update_combat(self, delta_time: float) -> None:
        """Handle real-time combat updates for all robots."""
        for team in [Team.BLUE, Team.RED]:
            for robot in self.team_manager.teams[team]:
                # Update status effects
                robot.update_status_effects(delta_time)

                # Update skills and learning
                robot.update_learning()

                # Find a target to attack (simple nearest enemy logic)
                nearest_enemy = self.find_nearest_enemy(robot)
