                    robot.move_towards(nearest_enemy.position, delta_time)
                    robot.attack(nearest_enemy, time.time())

    def find_nearest_enemy(self, robot: Robot) -> Robot:
        """Find the nearest enemy robot to the given robot."""
        nearest_distance = float('inf')
        nearest_robot = None
        for enemy in self.team_manager.get_opponents(robot.team):
            if enemy.health > 0:
                distance = ((robot.position.x - enemy.position.x)**2 + (robot.position.y - enemy.position.y)**2)**0.5
