# Class for managing the battle arena
class CyberArena:
    def __init__(self, width: int = 20, height: int = 20):
        self.width = width
        self.height = height
        self.teams = {}
        self.robots = []
        self.power_ups = []
        self.hazards = []
        self.round_time = 60  # seconds
        self.current_time = 0
        self.difficulty = 1.0  # Difficulty multiplier

    def add_team(self, team: Team):
        """Add a team to the arena"""
        self.teams[team.name] = team
        self.robots.extend(team.robots)
        return f"Added team {team.name} to the arena"

    def add_power_up(self, power_up):
        """Add a power-up to the arena"""
        self.power_ups.append(power_up)
        return f"Added power-up {power_up.name} to the arena"

    def add_hazard(self, hazard):
        """Add a hazard to the arena"""
        self.hazards.append(hazard)
        return f"Added hazard {hazard.name} to the arena"

    def check_power_ups(self):
        """Check if any robot is near a power-up and activate it"""
        for power_up in self.power_ups[:]:  # Use a slice to allow removal
            for robot in self.robots:
                if robot.distance_to(power_up) <= 1:
                    # Apply power-up effect
                    power_up.activate(robot)
                    self.power_ups.remove(power_up)
                    return f"{robot.name} activated {power_up.name} power-up!"
        return "No power-ups activated."

    def check_hazards(self):
        """Check if any robot is in a hazard and apply damage"""
        for hazard in self.hazards:
            for robot in self.robots:
                if robot.distance_to(hazard) <= hazard.range:
                    damage = hazard.damage * self.difficulty
                    robot.take_damage(damage)
                    return f"{robot.name} took {damage} damage from {hazard.name} hazard!"
        return "No robots in hazards."

    def check_objectives(self):
        """Check if any team has completed their objective"""
        for team in self.teams.values():
            if team.objective == "capture_flag":
                flag_position = (10, 10)
                for robot in team.robots:
                    if robot.is_alive and robot.position == flag_position:
                        team.update_score(100)
                        return f"Team {team.name} captured the flag! Score +100"
            elif team.objective == "defend_base":
                base_position = (0, 0)
                all_robots_back = all(robot.position == base_position for robot in team.robots if robot.is_alive)
                if all_robots_back:
                    team.update_score(50)
                    return f"Team {team.name} successfully defended the base! Score +50"
            elif team.objective == "escort_payload":
                payload_position = (5, 5)
                if any(robot.position == payload_position for robot in team.robots if robot.is_alive):
                    team.update_score(150)
                    return f"Team {team.name} escorted the payload! Score +150"
        return "No team has completed their objective yet."

    def update_difficulty(self):
        """Adjust difficulty based on battle progress"""
        alive_robots = sum(1 for robot in self.robots if robot.is_alive)
        if alive_robots == 0:
            return
        avg_health = sum(robot.health for robot in self.robots if robot.is_alive) / alive_robots
        if avg_health < 30:
            self.difficulty = min(1.5, self.difficulty + 0.1)
        elif avg_health > 70:
            self.difficulty = max(0.5, self.difficulty - 0.1)
        return f"Difficulty adjusted to {self.difficulty:.2f}"

    def simulate_round(self):
        """Simulate a round of battle"""
        self.current_time += 1
        if self.current_time >= self.round_time:
            return self.end_round()

        # Update all robots
        for robot in self.robots:
            if robot.is_alive:
                if random.random() < 0.5:
                    # Try to attack a random enemy
                    enemies = [r for r in self.robots if r.team != robot.team and r.is_alive]
                    if enemies:
