        print(self.check_hazards())

        # Check if any objective was completed
        print(self.check_objectives())

        # Update difficulty
        print(self.update_difficulty())

        return f"Round {self.current_time}/{self.round_time} completed"

    def end_round(self):
        """End the current round and evaluate results"""
        # Calculate winner
        winner_team = max(self.teams.values(), key=lambda team: team.score)
        loser_team = min(self.teams.values(), key=lambda team: team.score)

        # Generate game summary
        summary = {
            "duration": self.current_time,
            "winner": winner_team.name,
            "winner_score": winner_team.score,
            "loser": loser_team.name,
            "loser_score": loser_team.score,
            "top_performers": self.get_top_performers()
        }

        # Reset for next round
        self.__init__(self.width, self.height)
        self.add_team(winner_team)  # Winner carries over to next round
        # Create new team for the next round
        new_team = Team(name=f"Team {len(self.teams)+1}")
        for _ in range(len(winner_team.robots) // 2):  # Create new robots from winner's DNA
            new_robot = Robot(
