# Class for power-ups
class PowerUp:
    def __init__(self, name: str, position: tuple, duration: int = 10):
        self.name = name
        self.position = position
        self.duration = duration
        self.remaining = duration

    def activate(self, robot: Robot):
        """Apply the power-up effect to the robot"""
        if self.name == "Health Boost":
            robot.heal(30)
        elif self.name == "Speed Boost":
            robot.speed = min(10, robot.speed + 2)
        elif self.name == "Damage Boost":
            for weapon in robot.weapons:
                weapon.damage = int(weapon.damage * 1.5)
        return f"{robot.name} has been boosted by {self.name}!"

