    def can_fire(self, current_time: float) -> bool:
        """Check if the weapon is ready to fire."""
        return current_time - self.last_used >= self.cooldown and self.ammo > 0

    def fire(self, current_time: float):
        """Fire the weapon, updating ammo and cooldown."""
        if self.can_fire(current_time):
