class SupportRobot(Robot):
    """Concrete robot class for a support type robot that heals and assists teammates."""

    def __init__(self, name: str, team: Team, position: Position):
        # Initialize with healing abilities and support weapons
        super().__init__(name, team, position, health=150.0)
        self.movement_speed = 2.0
        self.weapons = [
