        ]

    def move(self, direction: Direction, environment: 'BattleEnvironment'):
        """Support robot movement logic - follows injured teammates."""
        self.direction = direction
        speed = self.movement_speed
        if self.speed_boost_active:
            speed *= 2.0

        if direction == Direction.UP:
            self.position.y += speed
        elif direction == Direction.DOWN:
            self.position.y -= speed
        elif direction == Direction.LEFT:
            self.position.x -= speed
        elif direction == Direction.RIGHT:
            self.position.x += speed

    def select_target(self, environment: 'BattleEnvironment') -> Optional['Robot']:
        """Support robot selects the most injured teammate as target."""
        most_injured_teammate = None
        lowest_health = self.max_health
        for robot in environment.robots:
            if robot.team == self.team and robot.health > 0 and robot.health < lowest_health:
                lowest_health = robot.health
                most_injured_teammate = robot
        return most_injured_teammate

