        elif self.role == Role.INVASION:
            return random.choice([WeaponType.SHIELD, WeaponType.BURST, WeaponType.SABER])
        elif self.role == Role.STRIKER:
            return random.choice([WeaponType.LAZER, WeaponType.BURST, WeaponType.SABER])
        elif self.role == Role.COMMANDER:
            return random.choice([WeaponType.PLASMA, WeaponType.SHIELD])
        else:
