class TeamManager:
    """Manages team composition and strategies."""
    def __init__(self, team: Team, robots: List[Robot]):
        self.team = team
        self.robots = robots
        self._validate_team()

    def _validate_team(self) -> None:
        """Ensures the team has a valid configuration."""
        if not (1 <= len(self.robots) <= MAX_TEAM_SIZE):
            raise ValueError(f"Team must have between 1 and {MAX_TEAM_SIZE} robots.")
        for robot in self.robots:
            if robot.team != self.team:
                raise ValueError("All robots in a team must belong to the same team.")

    def get_role_distribution(self) -> Dict[Role, int]:
        """Returns the distribution of roles in the team."""
        roles = {}
        for robot in self.robots:
            roles[robot.role] = roles.get(robot.role, 0) + 1
        return roles

    def assign_roles(self):
        """Assigns roles to robots for optimal team composition."""
        role_distribution = self.get_role_distribution()
        required_roles = {
            Role.SENTRY: 1,
            Role.INVASION: 1,
            Role.STRIKER: 1,
            Role.COMMANDER: 1
        }

        for role in required_roles:
            if role_distribution.get(role, 0) < required_roles[role]:
                for robot in self.robots:
                    if robot.role != role:
                        robot.role = role
                        break

    def adjust_difficulty(self, team_performance: float):
        """Adjusts the AI difficulty based on the team's performance."""
        if team_performance < 0.5:
            # Increase difficulty
            for robot in self.robots:
                robot.speed += 1.0
                robot.max_health += 10
        elif team_performance > 0.75:
            # Decrease difficulty
            for robot in self.robots:
                robot.speed = max(3.0, robot.speed - 1.0)
                robot.max_health = max(50, robot.max_health - 10)

class PowerUpSpawner:
    """Manages spawning and logic for power-ups in the arena."""
    def __init__(self, arena_size: Tuple[float, float]):
        self.arena_size = arena_size
