        """Spawns a power-up at a random location in the arena."""
        x = random.uniform(0, self.arena_size[0])
        y = random.uniform(0, self.arena_size[1])
        self.power_ups.append({
            "type": power_up_type,
            "position": Position(x, y),
            "duration": self._power_up_duration(power_up_type)
