        """Returns the duration power-up remains active in the arena."""
        return {
            PowerUpType.SHIELD: 30.0,
            PowerUpType.SPEED_BOOST: 20.0,
            PowerUpType.DAMAGE_BOOST: 25.0,
            PowerUpType.TEAM_SHIELD: 15.0,
            PowerUpType.HEAL: 10.0
        }[power_up_type]

    def update(self, delta_time: float) -> None:
        """Updates power-up states and removes expired ones."""
        for power in self.power_ups[:]:
            power["duration"] -= delta_time
            if power["duration"] <= 0:
                self.power_ups.remove(power)

    def get_power_ups_near(self, position: Position, radius: float = 100.0) -> List[Dict]:
        """Returns power-ups within a certain radius of a position."""
        return [
            power for power in self.power_ups
            if position.distance_to(power["position"]) <= radius
        ]

class BattleObjective:
    """Manages a battle objective (e.g., capture flag, escort payload)."""
    def __init__(self, objective_type: Objective, position: Position):
        self.objective_type = objective_type
        self.position = position
        self.status = "active"
        self.team_controlled = None

    def update(self, robots: List[Robot]) -> None:
        """Updates the objective's status based on robot proximity."""
        if self.status == "active":
            for robot in robots:
                if self.position.distance_to(robot.position) < 20.0:
                    if robot.team != self.team_controlled:
                        self.team_controlled = robot.team
                        self.status = "in_progress"
                        break
        elif self.status == "in_progress":
            if self.objective_type == Objective.CAPTURE_FLAG:
                self._check_flag_capture(robots)
            elif self.objective_type == Objective.ESCORT_PAYLOAD:
                self._check_payload_protection(robots)
            elif self.objective_type == Objective.DEFEND_BASE:
                self._check_base_integrity(robots)

    def _check_flag_capture(self, robots: List[Robot]) -> None:
        """Checks if the flag has been captured by a team."""
        if self.team_controlled:
            for robot in robots:
                if robot.team == self.team_controlled and robot.role == Role.INVASION:
                    robot.objective_progress += 1
                    if robot.objective_progress >= 10:
                        self.status = "completed"
                        self.team_controlled = None

    def _check_payload_protection(self, robots: List[Robot]) -> None:
        """Checks if the payload is being protected or captured."""
        if self.team_controlled:
            for robot in robots:
                if robot.team != self.team_controlled and robot.role == Role.INVASION:
                    robot.objective_progress += 1
                    if robot.objective_progress >= 10:
                        self.status = "completed"
                        self.team_controlled = None

    def _check_base_integrity(self, robots: List[Robot]) -> None:
        """Checks if the base remains intact or has been breached."""
        if self.team_controlled:
            for robot in robots:
                if robot.team != self.team_controlled and robot.role == Role.SENTRY:
                    robot.objective_progress += 1
                    if robot.objective_progress >= 10:
                        self.status = "completed"
                        self.team_controlled = None

    def is_complete(self) -> bool:
        """Returns True if the objective has been completed."""
        return self.status == "completed"

class ScoringSystem:
    """Calculates and tracks scores for the battle."""
    def __init__(self):
        self.scores = {Team.RED: 0, Team.BLUE: 0}

    def add_score(self, team: Team, amount: int) -> None:
        """Adds a score to the specified team."""
        self.scores[team] += amount

    def get_score(self, team: Team) -> int:
        """Returns the current score for a team."""
        return self.scores.get(team, 0)

    def reset_scores(self) -> None:
        """Resets all scores to zero."""
        self.scores = {Team.RED: 0, Team.BLUE: 0}

    def get_winner(self) -> Team:
        """Returns the team with the highest score."""
        return max(self.scores, key=self.scores.get)

    def report_scores(self) -> None:
        """Prints the current scores to the console."""
        print(f"RED Team Score: {self.scores.get(Team.RED, 0)}")
        print(f"BLUE Team Score: {self.scores.get(Team.BLUE, 0)}")

class CyberArena:
    """Main class for the CyberArena simulation."""
    def __init__(self):
        self.teams = []
        self.robots = []
        self.power_up_spawner = PowerUpSpawner((ARENA_WIDTH, ARENA_HEIGHT))
        self.battle_objective = BattleObjective(Objective.CAPTURE_FLAG, Position(500, 400))
        self.scoring_system = ScoringSystem()
        self.current_round = 0
        self.start_time = 0

    def add_team(self, team: TeamManager) -> None:
        """Adds a team to the arena."""
        self.teams.append(team)
        self.robots.extend(team.robots)

    def start_round(self) -> None:
        """Initializes and starts a new round of the battle."""
        self.current_round += 1
        for team in self.teams:
            team.assign_roles()
        self._initialize_robots()
        self.battle_objective = BattleObjective(
            Objective.CAPTURE_FLAG, 
            Position(500 + random.randint(-100, 100), 400 + random.randint(-100, 100))
        )
        self.power_up_spawner.power_ups.clear()
        self.power_up_spawner.spawn_power_up(PowerUpType.SHIELD)
        self.power_up_spawner.spawn_power_up(PowerUpType.SPEED_BOOST)
        self.power_up_spawner.spawn_power_up(PowerUpType.DAMAGE_BOOST)
        self.scoring_system.reset_scores()
        self.start_time = time.time()

    def _initialize_robots(self) -> None:
        """Resets all robots for a new round."""
        for robot in self.robots:
            robot.health = robot.max_health
            robot.is_active = True
            robot.damage_dealt = 0
            robot.objective_progress = 0
            robot.position = self._get_spawn_position(robot.team)

    def _get_spawn_position(self, team: Team) -> Position:
        """Generates a spawn position based on team."""
        if team == Team.RED:
            return Position(100 + random.randint(0, 200), 200 + random.randint(0, 400))
        else:  # Team.BLUE
            return Position(700 + random.randint(0, 200), 200 + random.randint(0, 400))

    def run_simulation(self, rounds: int = MAX_ROUNDS) -> None:
        """Runs the battle simulation for the specified number of rounds."""
        for _ in range(rounds):
            self.start_round()
            self._run_battle()
            self._process_results()
            self._adjust_difficulty()
            self._report_round_results()

    def _run_battle(self) -> None:
        """Simulates a single battle round until the objective is completed."""
        while not self.battle_objective.is_complete():
            delta_time = time.time() - self.start_time
            self.start_time = time.time()

            # Update and move all robots
            for robot in self.robots:
                robot.update(delta_time)

            # Update objectives
            self.battle_objective.update(self.robots)

            # Update power-ups
            self.power_up_spawner.update(delta_time)

            # AI behavior and movement
            self._handle_ai_actions(delta_time)

            # Collision and power-up collection
            self._check_power_up_collisions()

            time.sleep(ACTION_DELAY)

    def _handle_ai_actions(self, delta_time: float) -> None:
        """Handles AI actions such as targeting, movement, and attacking."""
        for robot in self.robots:
            if not robot.is_active:
                continue

            # Simple AI logic
            nearby_power_ups = self.power_up_spawner.get_power_ups_near(robot.position)
            if nearby_power_ups:
                power = nearby_power_ups[0]
                robot.move_towards(power["position"])
            else:
                # Targeting logic
                target = self._find_best_target(robot)
                if target and robot.position.distance_to(target.position) < 100:
                    robot.attack(target)
                else:
                    # Move toward objective
                    robot.move_towards(self.battle_objective.position)

    def _find_best_target(self, robot: Robot) -> Robot:
        """Finds the best target for a robot to attack."""
        best_target = None
        min_distance = float("inf")
        for other in self.robots:
            if other.team != robot.team and other.is_active:
                distance = robot.position.distance_to(other.position)
                if distance < min_distance and distance < 150:
                    min_distance = distance
                    best_target = other
        return best_target

    def _check_power_up_collisions(self) -> None:
        """Checks if robots have collided with power-ups and collects them."""
        for robot in self.robots:
            for power in self.power_up_spawner.power_ups:
                if robot.position.distance_to(power["position"]) < 20:
                    robot.collect_power_up(power["type"])
                    self.power_up_spawner.power_ups.remove(power)

    def _process_results(self) -> None:
        """Processes the results of the battle and updates the scoring system."""
        winner_team = self.battle_objective.team_controlled
        if winner_team:
            self.scoring_system.add_score(winner_team, 10)
        self._award_teamwork_bonus()

    def _award_teamwork_bonus(self) -> None:
        """Award bonus points for effective teamwork based on objective progress."""
        for robot in self.robots:
            if robot.objective_progress > 0:
                self.scoring_system.add_score(robot.team, robot.objective_progress // 2)

    def _adjust_difficulty(self) -> None:
        """Adjusts the difficulty for all teams based on performance."""
        for team in self.teams:
            team_performance = self._calculate_team_performance(team)
            team.adjust_difficulty(team_performance)

    def _calculate_team_performance(self, team: TeamManager) -> float:
        """Calculates a performance metric for a team."""
        total_damage = sum(robot.damage_dealt for robot in team.robots)
        total_health = sum(robot.health for robot in team.robots)
        return (total_damage + total_health) / (100 * len(team.robots))

    def _report_round_results(self) -> None:
        """Reports the results of the current round."""
        print(f"\n--- Round {self.current_round} Complete ---")
        self.scoring_system.report_scores()
        winner = self.scoring_system.get_winner()
        print(f"Winning Team: {winner.name}")
        for team in self.teams:
            for robot in team.robots:
                print(f"{robot.name}: Health={robot.health}, Damage={robot.damage_dealt}")
        print("------------------------------\n")

    def end_simulation(self) -> None:
        """Ends the simulation and reports final results."""
        print("\n--- Simulation Complete ---")
        self.scoring_system.report_scores()
        winner = self.scoring_system.get_winner()
        print(f"Overall Winner: {winner.name}")
        for team in self.teams:
            for robot in team.robots:
                print(f"{robot.name}: Experience={robot.experience}, Health={robot.health}")
        print("------------------------------\n")

# ------------------------------
# 4. Main Execution
# ------------------------------

def main():
    """Main function to set up and run the CyberArena simulation."""
    # Create teams and robots
    team_red_robots = [
        Robot("Red Sentry", Team.RED, Position(100, 200), Role.SENTRY),
        Robot("Red Invader", Team.RED, Position(150, 250), Role.INVASION),
        Robot("Red Striker", Team.RED, Position(120, 220), Role.STRIKER),
        Robot("Red Commander", Team.RED, Position(130, 240), Role.COMMANDER)
    ]

    team_blue_robots = [
