        Robot("Blue Invader", Team.BLUE, Position(850, 550), Role.INVASION),
        Robot("Blue Striker", Team.BLUE, Position(880, 580), Role.STRIKER),
        Robot("Blue Commander", Team.BLUE, Position(870, 570), Role.COMMANDER)
