# solution.py
import random
import time
from dataclasses import dataclass
from enum import Enum
from typing import Dict, List, Tuple, Optional

# ------------------------------
# 1. Core Application Constants
# ------------------------------

MAX_TEAM_SIZE = 4
TOTAL_TEAMS = 2
ACTION_DELAY = 0.1  # seconds between actions

# ------------------------------
# 2. Enumerations
# ------------------------------

class Team(Enum):
    """Enum for representing teams in the application."""
    RED = 1
    BLUE = 2

class Role(Enum):
    """Enum for roles within a team."""
    COACH = "COACH"
    PLAYER = "PLAYER"
    MANAGER = "MANAGER"

class TrainingType(Enum):
    """Enum for types of training sessions."""
    CARDIO = "CARDIO"
    STRENGTH = "STRENGTH"
    TACTICAL = "TACTICAL"
    CONDITIONING = "CONDITIONING"

class PerformanceMetric(Enum):
    """Enum for performance metrics tracked by the system."""
    SPEED = "SPEED"
    ENDURANCE = "ENDURANCE"
    ACCURACY = "ACCURACY"
    REACTION_TIME = "REACTION_TIME"
    TEAMWORK = "TEAMWORK"

# ------------------------------
# 3. Data Classes
# ------------------------------

@dataclass
class Athlete:
    name: str
    team: Team
    role: Role
    strength: float
    endurance: float
    speed: float
    performance: Dict[PerformanceMetric, float] = None

    def __post_init__(self):
        self.performance = {
            PerformanceMetric.SPEED: random.uniform(5.0, 10.0),
            PerformanceMetric.ENDURANCE: random.uniform(60.0, 90.0),
            PerformanceMetric.ACCURACY: random.uniform(70.0, 100.0),
            PerformanceMetric.REACTION_TIME: random.uniform(0.1, 0.5),
            PerformanceMetric.TEAMWORK: random.uniform(60.0, 95.0),
        }

@dataclass
class WorkoutPlan:
    name: str
    training_type: TrainingType
    duration: int  # in minutes
    intensity: str  # low, medium, high
    participants: List[Athlete] = None

    def __post_init__(self):
        self.participants = []

@dataclass
class GameStrategy:
    name: str
    description: str
    team: Team
    success_rate: float  # in percentage

@dataclass
class PerformanceRecord:
    athlete: Athlete
    metrics: Dict[PerformanceMetric, float]
    timestamp: float = None

    def __post_init__(self):
        self.timestamp = time.time()

# ------------------------------
# 4. Database Simulation
# ------------------------------

class SportTeamDatabase:
    def __init__(self):
        self.athletes: Dict[str, Athlete] = {}
        self.workout_plans: Dict[str, WorkoutPlan] = {}
        self.strategies: Dict[str, GameStrategy] = {}
        self.performance_records: List[PerformanceRecord] = []

    def add_athlete(self, athlete: Athlete):
        self.athletes[athlete.name] = athlete

    def create_workout_plan(self, plan: WorkoutPlan):
        self.workout_plans[plan.name] = plan

    def add_game_strategy(self, strategy: GameStrategy):
        self.strategies[strategy.name] = strategy

    def log_performance(self, record: PerformanceRecord):
        self.performance_records.append(record)

    def get_athlete_performance(self, athlete_name: str) -> List[PerformanceRecord]:
        return [record for record in self.performance_records if record.athlete.name == athlete_name]

# ------------------------------
# 5. Analytics Module
# ------------------------------

class PerformanceAnalytics:
    def __init__(self, db: SportTeamDatabase):
        self.db = db

    def analyze_team_performance(self, team: Team) -> Dict[str, float]:
        athletes = [athlete for athlete in self.db.athletes.values() if athlete.team == team]
        metrics = {metric: [] for metric in PerformanceMetric}
        for athlete in athletes:
            for metric in metrics:
                metrics[metric].append(athlete.performance[metric])
        return {
            metric.name: sum(values) / len(values)
            for metric, values in metrics.items()
            if values
        }

    def predict_performance_gain(self, workout_plan: WorkoutPlan) -> Dict[PerformanceMetric, float]:
        # Simulate performance gain based on training type and intensity
        gains = {
            PerformanceMetric.SPEED: 0,
            PerformanceMetric.ENDURANCE: 0,
            PerformanceMetric.ACCURACY: 0,
            PerformanceMetric.REACTION_TIME: 0,
            PerformanceMetric.TEAMWORK: 0
        }

        if workout_plan.training_type == TrainingType.CARDIO:
            gains[PerformanceMetric.ENDURANCE] += 5
            gains[PerformanceMetric.SPEED] += 3
        elif workout_plan.training_type == TrainingType.STRENGTH:
            gains[PerformanceMetric.ENDURANCE] += 3
            gains[PerformanceMetric.SPEED] += 2
        elif workout_plan.training_type == TrainingType.CONDITIONING:
            gains[PerformanceMetric.ENDURANCE] += 4
            gains[PerformanceMetric.REACTION_TIME] += 2
        elif workout_plan.training_type == TrainingType.TACTICAL:
            gains[PerformanceMetric.TEAMWORK] += 5
            gains[PerformanceMetric.ACCURACY] += 3

        if workout_plan.intensity == "high":
            for metric in gains:
                gains[metric] += 3
        elif workout_plan.intensity == "medium":
            for metric in gains:
                gains[metric] += 1

        return gains

# ------------------------------
# 6. Main Application Module
# ------------------------------

class Sport_Team_Coordinator:
    def __init__(self):
        self.db = SportTeamDatabase()
        self.analytics = PerformanceAnalytics(self.db)

    def setup_team(self):
        for team in Team:
            for i in range(MAX_TEAM_SIZE):
                name = f"{team.name}_Player_{i+1}"
                self.db.add_athlete(Athlete(name=name, team=team, role=Role.PLAYER))

    def assign_workouts(self):
        # Example workout plans
        cardio = WorkoutPlan(
            name="Morning Cardio",
            training_type=TrainingType.CARDIO,
            duration=45,
            intensity="high"
        )
        strength = WorkoutPlan(
            name="Strength and Conditioning",
            training_type=TrainingType.STRENGTH,
            duration=60,
            intensity="medium"
        )

        for plan in [cardio, strength]:
            for athlete in self.db.athletes.values():
                plan.participants.append(athlete)
            self.db.create_workout_plan(plan)

    def run_simulation(self, rounds: int = MAX_ROUNDS):
        for round_num in range(1, rounds + 1):
            print(f"--- Round {round_num} ---")
            for team in Team:
                # Simulate training and performance
                for athlete in self.db.athletes.values():
                    performance = {k: v + random.uniform(-1, 2) for k, v in athlete.performance.items()}
                    record = PerformanceRecord(athlete=athlete, metrics=performance)
                    self.db.log_performance(record)

            # Simulate game strategy
            for team in Team:
                strategy = GameStrategy(
                    name=f"{team.name} Strategy",
                    description="Aggressive offense and defensive coverage",
                    team=team,
                    success_rate=75.0
                )
                self.db.add_game_strategy(strategy)

            time.sleep(ACTION_DELAY)

    def display_team_performance(self):
        for team in Team:
            print(f"\n--- {team.name} Team Performance ---")
            avg_metrics = self.analytics.analyze_team_performance(team)
            for metric, value in avg_metrics.items():
                print(f"{metric}: {value:.2f}")

    def predict_performance_after_training(self, plan_name: str):
        plan = self.db.workout_plans.get(plan_name)
        if plan:
            gains = self.analytics.predict_performance_gain(plan)
            print(f"\nPredicted performance gain after '{plan.name}':")
            for metric, gain in gains.items():
                print(f"{metric.name}: +{gain:.2f}")
        else:
            print("Workout plan not found.")

# ------------------------------
# 7. Execution
# ------------------------------

if __name__ == "__main__":
    coordinator = Sport_Team_Coordinator()
    coordinator.setup_team()
    coordinator.assign_workouts()
    coordinator.run_simulation()
    coordinator.display_team_performance()
    coordinator.predict_performance_after_training("Morning Cardio")
```

