class Objective:
    def __init__(self, objective_type, team, position=None):
        self.type = objective_type
        self.team = team
        self.position = position
        self.progress = 0
        self.completed = False

        if objective_type == ObjectiveType.CTF:
            self.flag = Flag(team)
        elif objective_type == ObjectiveType.DEFEND_BASE:
            self.base = Base(team, position)
        elif objective_type == ObjectiveType.ESCORT_PAYLOAD:
            self.payload = Payload(team, position)

    def update(self):
        """Update objective state"""
        if self.type == ObjectiveType.CTF and self.flag:
            if self.flag.captured:
                # Update progress toward completing the objective
                self.progress = 100  # Objective complete
                self.completed = True
        elif self.type == ObjectiveType.DEFEND_BASE and self.base:
            if self.base.destroyed:
                self.progress = 0  # Objective failed
                self.completed = True
        elif self.type == ObjectiveType.ESCORT_PAYLOAD and self.payload:
            if self.payload.reached_destination:
                self.progress = 100  # Objective complete
                self.completed = True

