from enum import Enum
from typing import Dict, List, Tuple, Optional

class Direction(Enum):
    UP = 0
    DOWN = 1
    LEFT = 2
    RIGHT = 3

class WeaponType(Enum):
    PULSE_LASER = 0
    PLASMA_RIFLE = 1
    SHOCK_SWORD = 2
    ELECTRO_NET = 3

class ObjectiveType(Enum):
    CTF = 0       # Capture the flag
    DEFEND_BASE = 1
    ESCORT_PAYLOAD = 2

class RobotStatus(Enum):
    ALIVE = 0
    DEAD = 1
    DISABLED = 2

class PowerUpType(Enum):
    SHIELD = 0
    AMMO = 1
    SPEED_BOOST = 2
    DAMAGE_BOOST = 3

class HazardType(Enum):
    ELECTRIC_TESLA = 0
    FREEZE_ZONE = 1
    EXPLOSIVE_TRAP = 2

class Skill(Enum):
    REPAIR = 0
    HACK = 1
    JUMP = 2
    SHIELD = 3
    SPRINT = 4

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other):
        return math.hypot(self.x - other.x, self.y - other.y)

@dataclass
class Weapon:
    name: str
    damage: int
    range: float
    ammo: int
    fire_rate: float  # bullets per second
    is_ranged: bool
    cooldown: float

    def __post_init__(self):
        if self.range is None:
            self.range = 0
        if self.is_ranged is None:
            self.is_ranged = self.range > 0

class Robot:
    def __init__(self, team, name, position, health=100, speed=5, weapon=None):
        self.team = team
        self.name = name
        self.position = position
        self.health = health
        self.max_health = health
        self.speed = speed
        self.weapon = weapon or Weapon("Default Laser", 10, 20, 100, 10, True, 0.5)
        self.status = RobotStatus.ALIVE
        self.skills = {
            Skill.REPAIR: 30,       # health points to repair
            Skill.HACK: 10,          # seconds to disable enemy
            Skill.JUMP: 30,          # seconds of jump boost
            Skill.SHIELD: 50,        # damage reduction percentage
            Skill.SPRINT: 2,          # speed multiplier
        }
        self.inventory = {
            PowerUpType.SHIELD: 0,
            PowerUpType.AMMO: 50,
            PowerUpType.SPEED_BOOST: 0,
            PowerUpType.DAMAGE_BOOST: 0
        }
        self.active_effects = {}
        self.movement_direction = Direction.RIGHT
        self.last_shot_time = 0
        self.role = Role.SUPPORT  # default role

    def move(self, direction, arena):
        """Move robot in the specified direction"""
        if self.status != RobotStatus.ALIVE:
            return

        if direction == Direction.UP:
            self.position.y -= self.speed
        elif direction == Direction.DOWN:
            self.position.y += self.speed
        elif direction == Direction.LEFT:
            self.position.x -= self.speed
        elif direction == Direction.RIGHT:
            self.position.x += self.speed

        # Check boundary
        self.position.x = max(0, min(arena.width, self.position.x))
        self.position.y = max(0, min(arena.height, self.position.y))

        # Check for hazards
        for hazard in arena.hazards:
            if self.position.distance_to(hazard.position) < hazard.radius and hazard.active:
                self.take_damage(hazard.damage)

    def attack(self, target):
        """Attack a target if in range and weapon is ready"""
        if self.status != RobotStatus.ALIVE:
            return

        if self.position.distance_to(target.position) <= self.weapon.range and self.weapon.ammo > 0:
            if time.time() - self.last_shot_time >= 1/self.weapon.fire_rate:
                self.weapon.ammo -= 1
                self.last_shot_time = time.time()
                target.take_damage(self.weapon.damage)

    def take_damage(self, amount):
        """Apply damage to the robot"""
        if self.status != RobotStatus.ALIVE:
            return

        if PowerUpType.SHIELD in self.inventory and self.inventory[PowerUpType.SHIELD] > 0:
            shield_amount = min(self.inventory[PowerUpType.SHIELD], amount)
            self.inventory[PowerUpType.SHIELD] -= shield_amount
            amount -= shield_amount

        if amount > 0:
            self.health -= amount
            if self.health <= 0:
                self.status = RobotStatus.DEAD
                self.respawn_timer = time.time() + random.uniform(5, 10)  # Respawn after 5-10 seconds

    def activate_skill(self, skill: Skill):
        """Activate a special skill"""
        if self.status != RobotStatus.ALIVE:
            return False

        if skill not in self.skills:
            return False

        if skill == Skill.REPAIR:
            if self.health < self.max_health:
                self.health = min(self.max_health, self.health + self.skills[skill])
                return True
        elif skill == Skill.HACK:
            return False  # Would need enemy target implementation
        elif skill == Skill.JUMP:
            self.speed *= 1.5
            self.active_effects[skill] = time.time() + self.skills[skill]
            return True
        elif skill == Skill.SHIELD:
            if PowerUpType.SHIELD in self.inventory:
                self.inventory[PowerUpType.SHIELD] += 20
                return True
        elif skill == Skill.SPRINT:
            self.speed *= self.skills[skill]
            self.active_effects[skill] = time.time() + self.skills[skill]
            return True

        return False

    def update(self, arena):
        """Update robot state for each frame"""
        # Update effects
        expired_effects = []
        for effect, end_time in self.active_effects.items():
            if time.time() > end_time:
                if effect == Skill.JUMP:
                    self.speed /= 1.5
                elif effect == Skill.SPRINT:
                    self.speed /= self.skills[Skill.SPRINT]
                expired_effects.append(effect)

        for effect in expired_effects:
            del self.active_effects[effect]

        # Check for power-ups
        for power_up in arena.power_ups:
            if power_up.active and self.position.distance_to(power_up.position) < power_up.radius:
                self.collect_power_up(power_up)
                power_up.active = False

        # Check for hazards
        for hazard in arena.hazards:
            if hazard.active and self.position.distance_to(hazard.position) < hazard.radius:
                self.take_damage(hazard.damage)

    def collect_power_up(self, power_up):
        """Collect and apply a power-up"""
        if power_up.type in self.inventory:
            self.inventory[power_up.type] += power_up.amount
        elif power_up.type == PowerUpType.AMMO and self.weapon:
            self.weapon.ammo += power_up.amount
        else:
            # Apply instant effect
            if power_up.type == PowerUpType.SPEED_BOOST:
                self.speed *= 1.5
                self.active_effects[PowerUpType.SPEED_BOOST] = time.time() + 10
            elif power_up.type == PowerUpType.DAMAGE_BOOST:
                self.weapon.damage = int(self.weapon.damage * 1.5)
                self.active_effects[PowerUpType.DAMAGE_BOOST] = time.time() + 10

class Team:
    def __init__(self, name, color, role=None):
        self.name = name
        self.color = color
        self.members = []
        self.score = 0
        self.role = role  # Dynamic role for the team
        self.flag = None  # For CTF objectives
        self.base = None  # For base defense objectives

    def add_member(self, robot):
        self.members.append(robot)
        robot.team = self

    def update_score(self, points):
        self.score += points
        print(f"{self.name} team score: {self.score}")

    def get_objective_status(self, objective):
        """Return the current status of the team's objective"""
        if objective.type == ObjectiveType.CTF and self.flag:
            if self.flag.held_by == self:
                return "Holding flag"
            elif self.flag.captured:
                return "Flag captured"
            else:
                return "Flag at base"
        elif objective.type == ObjectiveType.DEFEND_BASE:
            if self.base.destroyed:
                return "Base destroyed"
            else:
                return f"Base intact ({self.base.health}/100)"
        elif objective.type == ObjectiveType.ESCORT_PAYLOAD:
            if self.payload.reached_destination:
                return "Payload delivered"
            else:
                return f"Payload at {self.payload.position.x:.2f}, {self.payload.position.y:.2f}"

    def assign_roles(self, arena):
        """Assign dynamic roles to team members"""
        if not self.members:
            return

        if self.role == Role.SUPPORT:
            # Make one robot a healer, one a hacker, one a scout
            healer = random.choice(self.members)
            healer.role = Role.HEALER

            hacker = random.choice([r for r in self.members if r != healer])
            hacker.role = Role.HACKER

            for robot in self.members:
                if robot.role not in [Role.HEALER, Role.HACKER]:
                    robot.role = Role.SCOUT
        elif self.role == Role.ASSAULT:
            # Make one robot a heavy, one a sniper, others as attackers
            heavy = random.choice(self.members)
            heavy.role = Role.HEAVY

            sniper = random.choice([r for r in self.members if r != heavy])
            sniper.role = Role.SNIPER

            for robot in self.members:
                if robot.role not in [Role.HEAVY, Role.SNIPER]:
                    robot.role = Role.ATTACKER
        elif self.role == Role.DEFENSE:
            # One robot as a commander, others as defenders
            commander = random.choice(self.members)
            commander.role = Role.COMMANDER

            for robot in self.members:
                if robot != commander:
                    robot.role = Role.DEFENDER
        elif self.role == Role.SECRET:
            # One robot as a stealth unit, others as standard
            stealth = random.choice(self.members)
            stealth.role = Role.STEALTH

            for robot in self.members:
                if robot != stealth:
                    robot.role = Role.SUPPORT

        print(f"{self.name} team roles assigned: {[r.role.name for r in self.members]}")

class PowerUp:
    def __init__(self, position, power_up_type, amount=10, radius=2):
        self.position = position
        self.type = power_up_type
        self.amount = amount
        self.radius = radius
        self.active = True

class Hazard:
    def __init__(self, position, hazard_type, damage=10, radius=3, duration=15):
        self.position = position
        self.type = hazard_type
        self.damage = damage
        self.radius = radius
        self.duration = duration
        self.active = True
        self.activation_time = time.time()

    def update(self):
        """Update hazard state"""
        if self.active and time.time() - self.activation_time > self.duration:
            self.active = False

class Objective:
    def __init__(self, objective_type, team, position=None):
        self.type = objective_type
        self.team = team
        self.position = position
        self.progress = 0
        self.completed = False

        if objective_type == ObjectiveType.CTF:
            self.flag = Flag(team)
        elif objective_type == ObjectiveType.DEFEND_BASE:
            self.base = Base(team, position)
        elif objective_type == ObjectiveType.ESCORT_PAYLOAD:
            self.payload = Payload(team, position)

    def update(self):
        """Update objective state"""
        if self.type == ObjectiveType.CTF and self.flag:
            if self.flag.captured:
                # Update progress toward completing the objective
                self.progress = 100  # Objective complete
                self.completed = True
        elif self.type == ObjectiveType.DEFEND_BASE and self.base:
            if self.base.destroyed:
                self.progress = 0  # Objective failed
                self.completed = True
        elif self.type == ObjectiveType.ESCORT_PAYLOAD and self.payload:
            if self.payload.reached_destination:
                self.progress = 100  # Objective complete
                self.completed = True

class Flag:
    def __init__(self, team):
        self.team = team
        self.position = Position(team.base_x, team.base_y)
        self.held_by = None
        self.captured = False

    def capture(self, capturing_team):
        if self.held_by is None and not self.captured:
            self.held_by = capturing_team
            print(f"Flag captured by {capturing_team.name} team")
            self.team.update_score(50)
            return True
        return False

    def return_to_base(self):
        self.held_by = None
        self.position = Position(self.team.base_x, self.team.base_y)
        print(f"Flag returned to {self.team.name} base")

class Base:
    def __init__(self, team, position):
        self.team = team
        self.position = position
        self.health = 100
        self.max_health = 100
        self.destroyed = False

    def take_damage(self, damage):
        if not self.destroyed:
            self.health -= damage
            if self.health <= 0:
                self.destroyed = True
                print(f"{self.team.name} base destroyed!")
                self.team.update_score(-100)

    def repair(self, amount):
        if not self.destroyed:
            self.health = min(self.max_health, self.health + amount)

class Payload:
    def __init__(self, team, position):
        self.team = team
        self.position = position
        self.destination = Position(team.base_x + 100, team.base_y)
        self.reached_destination = False

    def move_toward(self, direction, speed):
        """Move the payload in a specific direction"""
        if not self.reached_destination:
            if direction == Direction.UP:
                self.position.y -= speed
            elif direction == Direction.DOWN:
                self.position.y += speed
            elif direction == Direction.LEFT:
                self.position.x -= speed
            elif direction == Direction.RIGHT:
                self.position.x += speed

            # Check if reached destination
            if self.position.distance_to(self.destination) < 1:
                self.reach_destination()

    def reach_destination(self):
        self.reached_destination = True
        print(f"Payload delivered to {self.team.name} destination")
        self.team.update_score(150)

class Arena:
    def __init__(self, width=800, height=600, teams=None):
        self.width = width
        self.height = height
        self.teams = teams or []
        self.robots = []
        self.power_ups = []
        self.hazards = []
        self.objectives = []
        self.game_time = 0
        self.running = True
        self.difficulty = 1.0  # 1.0 is normal, can increase/decrease
        self.feedback_loop = {}

        # Create all robots
        for team in self.teams:
            for i in range(5):  # 5 robots per team
                robot = Robot(
                    team=team,
                    name=f"{team.name} Bot {i+1}",
                    position=Position(team.base_x + i*10, team.base_y),
                    weapon=Weapon(f"{team.name} Laser", 
                                  int(10 * self.difficulty),
                                  20 * self.difficulty,
                                  100,
                                  10 * self.difficulty,
                                  True,
                                  0.5)
                )
                team.add_member(robot)
                self.robots.append(robot)

        # Initialize objectives
        for team in self.teams:
            if len(self.teams) > 1:
                # Capture the flag objective
                self.objectives.append(Objective(ObjectiveType.CTF, team))
            else:
                # Single team objective (defense)
                self.objectives.append(Objective(ObjectiveType.DEFEND_BASE, team,
                                               Position(width/2, height/2)))

        # Set up initial power-ups
        for _ in range(5):
            self.spawn_power_up()

        # Set up initial hazards
        for _ in range(3):
            self.spawn_hazard()

    def spawn_power_up(self):
        """Spawn a random power-up at a random location"""
        power_up_type = random.choice(list(PowerUpType))
        position = Position(
            random.uniform(0, self.width),
            random.uniform(0, self.height)
        )
        amount = random.randint(10, 30) if power_up_type in [PowerUpType.AMMO] else 1
        self.power_ups.append(PowerUp(position, power_up_type, amount))

    def spawn_hazard(self):
        """Spawn a random hazard at a random location"""
        hazard_type = random.choice(list(HazardType))
        position = Position(
            random.uniform(0, self.width),
            random.uniform(0, self.height)
        )
        self.hazards.append(Hazard(position, hazard_type))

    def update(self):
        """Update the arena state"""
        self.game_time += 1/60  # 60 FPS

        # Update all hazards
        for hazard in self.hazards:
            hazard.update()

        # Update all robots
        for robot in self.robots:
            if robot.status == RobotStatus.ALIVE:
                robot.update(self)

                # AI decision making
                self.make_ai_decisions(robot)

        # Update all objectives
        for objective in self.objectives:
            objective.update()
            if objective.completed:
                self.check_victory()

        # Adaptive difficulty
        self.adjust_difficulty()

        # Power-up respawn
        if random.random() < 0.01:  # 1% chance per frame
            self.spawn_power_up()

        # Hazard reactivation
        if random.random() < 0.005:  # 0.5% chance per frame
            for hazard in self.hazards:
                if not hazard.active:
                    hazard.active = True
                    hazard.activation_time = time.time()

    def make_ai_decisions(self, robot):
        """Make AI decisions for a robot based on its role and current state"""
        if robot.status != RobotStatus.ALIVE:
            return

        # Basic movement
        if robot.role == Role.HEALER:
            # Find injured teammate
            injured_teammates = [r for r in robot.team.members if 
                                r.status == RobotStatus.ALIVE and r.health < r.max_health]
            if injured_teammates:
                target = random.choice(injured_teammates)
                self.move_toward(robot, target.position)
                if robot.position.distance_to(target.position) < 5:
                    robot.activate_skill(Skill.REPAIR)
        elif robot.role == Role.HACKER:
            # Find enemy
            enemies = [r for r in self.robots if r.team != robot.team and 
                      r.status == RobotStatus.ALIVE]
            if enemies:
                target = random.choice(enemies)
                self.move_toward(robot, target.position)
                if robot.position.distance_to(target.position) < 10:
                    robot.activate_skill(Skill.HACK)
        elif robot.role == Role.SCOUT:
            # Move toward random location
            self.move_toward(robot, Position(
                random.uniform(0, self.width),
                random.uniform(0, self.height)
            ))
        elif robot.role == Role.HEAVY:
            # Find closest enemy
            enemies = [r for r in self.robots if r.team != robot.team and 
                      r.status == RobotStatus.ALIVE]
            if enemies:
                closest = min(enemies, key=lambda x: robot.position.distance_to(x.position))
                self.move_toward(robot, closest.position)
                robot.attack(closest)
        elif robot.role == Role.SNIPER:
            # Find distant enemy
            enemies = [r for r in self.robots if r.team != robot.team and 
                      r.status == RobotStatus.ALIVE and 
                      robot.position.distance_to(r.position) < robot.weapon.range]
            if enemies:
                target = max(enemies, key=lambda x: robot.position.distance_to(x.position))
                self.move_toward(robot, target.position)
                robot.attack(target)
        elif robot.role == Role.DEFENDER:
            # Defend base position
            self.move_toward(robot, robot.team.base.position)
        elif robot.role == Role.COMMANDER:
            # Make strategic decisions
            self.evaluate_strategic_situation(robot)
        elif robot.role == Role.STEALTH:
            # Stay hidden
            pass  # Would implement hiding behavior in real game

    def move_toward(self, robot, target_position):
        """Move robot toward a target position"""
        dx = target_position.x - robot.position.x
        dy = target_position.y - robot.position.y
        distance = math.hypot(dx, dy)

        if distance > 0:
            robot.movement_direction = self.get_direction(dx, dy)
            robot.move(robot.movement_direction, self)

    def get_direction(self, dx, dy):
        """Determine direction based on movement vector"""
        if abs(dx) > abs(dy):
            return Direction.RIGHT if dx > 0 else Direction.LEFT
        else:
            return Direction.DOWN if dy > 0 else Direction.UP

    def evaluate_strategic_situation(self, robot):
        """Evaluate the current strategic situation for a commander"""
        # Count team members
        alive_teammates = sum(1 for r in robot.team.members if r.status == RobotStatus.ALIVE)
        dead_teammates = len(robot.team.members) - alive_teammates

        # Count enemy members
        enemies = [r for r in self.robots if r.team != robot.team]
        alive_enemies = sum(1 for r in enemies if r.status == RobotStatus.ALIVE)
        dead_enemies = len(enemies) - alive_enemies

        # Adjust team role based on situation
        if alive_teammates > alive_enemies and dead_enemies > dead_teammates:
            # We're winning, focus on defense
            robot.team.role = Role.DEFENSE
        elif alive_teammates < alive_enemies and dead_teammates > dead_enemies:
            # We're losing, focus on offense
            robot.team.role = Role.ASSAULT
        else:
            # Balanced situation, focus on support
            robot.team.role = Role.SUPPORT

        # Reassign roles based on new team role
        robot.team.assign_roles(self)

    def adjust_difficulty(self):
        """Adjust game difficulty based on team performance"""
        # Calculate team scores
        team_scores = {team.name: team.score for team in self.teams}

        # If one team is significantly ahead, increase difficulty for them
        if max(team_scores.values()) - min(team_scores.values()) > 200:
            # Increase difficulty
            self.difficulty = min(1.5, self.difficulty + 0.01)

            # Make enemies more aggressive
            for robot in self.robots:
                if robot.team.name == max(team_scores, key=team_scores.get):
                    robot.weapon.damage += 1
                    robot.weapon.fire_rate += 0.1
                    robot.speed += 0.5
        else:
            # Balance difficulty
            self.difficulty = 1.0

    def check_victory(self):
        """Check if any team has won the game"""
        completed_objectives = sum(1 for obj in self.objectives if obj.completed)
        total_objectives = len(self.objectives)

        if completed_objectives == total_objectives:
            # Game over
            self.running = False

            # Determine winner
            winning_teams = [team for team in self.teams if team.score > 0]
            if len(winning_teams) == 1:
                print(f"{winning_teams[0].name} team wins!")
            else:
                print("Draw!")

    def run_game(self, duration=300):
        """Run the game for a specified duration"""
        game_thread = threading.Thread(target=self._game_loop, args=(duration,))
        game_thread.start()

        return game_thread

    def _game_loop(self, duration):
        """Main game loop"""
        start_time = time.time()

        while self.running and (time.time() - start_time) < duration:
            self.update()
            time.sleep(1/60)  # 60 FPS

        print("Game ended!")
        self.print_game_statistics()

    def print_game_statistics(self):
        """Print game statistics"""
        print("\n=== Game Statistics ===")

        # Print team scores
        print("\nTeam Scores:")
        for team in self.teams:
            print(f"{team.name} team: {team.score} points")

        # Print objective status
        print("\nObjective Status:")
        for objective in self.objectives:
            print(f"- {objective.type.name}: {objective.get_objective_status()}")

        # Print robot performance
        print("\nRobot Performance:")
        for robot in self.robots:
            print(f"{robot.name} ({robot.team.name} team):")
            print(f"  - Health: {robot.health}/{robot.max_health}")
            print(f"  - Score contribution: {robot.team.score / len(robot.team.members):.2f} points")
            print(f"  - Role: {robot.role.name}")
            print(f"  - Weapon: {robot.weapon.name} ({robot.weapon.damage} damage, {robot.weapon.range} range)")
            print(f"  - Ammo: {robot.weapon.ammo}")
            print(f"  - Power-ups: {', '.join(f'{pu}: {robot.inventory[pu]}' for pu in robot.inventory if robot.inventory[pu] > 0) or 'None'}")

class Role(Enum):
    HEALER = 0
    HACKER = 1
    SCOUT = 2
    HEAVY = 3
    SNIPER = 4
    ATTACKER = 5
    DEFENDER = 6
    COMMANDER = 7
    STEALTH = 8
    SUPPORT = 9
    ASSAULT = 10
    DEFENSE = 11
    SECRET = 12

class CyberArena:
    def __init__(self):
        # Create teams
        red_team = Team("Red", "red", Role.ASSAULT)
        blue_team = Team("Blue", "blue", Role.DEFENSE)

        # Set team base positions
        red_team.base_x = 100
        red_team.base_y = 100
        blue_team.base_x = 700
        blue_team.base_y = 500

        # Create arena
        self.arena = Arena(width=800, height=600, teams=[red_team, blue_team])

        # Assign roles
        for team in self.arena.teams:
            team.assign_roles(self.arena)

    def start_game(self, duration=300):
        """Start the game for a specified duration in seconds"""
        print("Starting CyberArena battle!")
        print(f"Duration: {duration} seconds")
        print(f"Teams: {[team.name for team in self.arena.teams]}")
        print(f"Number of robots: {len(self.arena.robots)}")

