        self.active_effects = {}
        self.movement_direction = Direction.RIGHT
        self.last_shot_time = 0
        self.role = Role.SUPPORT  # default role

    def move(self, direction, arena):
        """Move robot in the specified direction"""
        if self.status != RobotStatus.ALIVE:
            return

        if direction == Direction.UP:
            self.position.y -= self.speed
        elif direction == Direction.DOWN:
            self.position.y += self.speed
        elif direction == Direction.LEFT:
            self.position.x -= self.speed
        elif direction == Direction.RIGHT:
            self.position.x += self.speed

        # Check boundary
        self.position.x = max(0, min(arena.width, self.position.x))
        self.position.y = max(0, min(arena.height, self.position.y))

        # Check for hazards
        for hazard in arena.hazards:
            if self.position.distance_to(hazard.position) < hazard.radius and hazard.active:
                self.take_damage(hazard.damage)

    def attack(self, target):
        """Attack a target if in range and weapon is ready"""
        if self.status != RobotStatus.ALIVE:
            return

        if self.position.distance_to(target.position) <= self.weapon.range and self.weapon.ammo > 0:
            if time.time() - self.last_shot_time >= 1/self.weapon.fire_rate:
                self.weapon.ammo -= 1
                self.last_shot_time = time.time()
                target.take_damage(self.weapon.damage)

    def take_damage(self, amount):
        """Apply damage to the robot"""
        if self.status != RobotStatus.ALIVE:
            return

        if PowerUpType.SHIELD in self.inventory and self.inventory[PowerUpType.SHIELD] > 0:
            shield_amount = min(self.inventory[PowerUpType.SHIELD], amount)
            self.inventory[PowerUpType.SHIELD] -= shield_amount
            amount -= shield_amount

        if amount > 0:
            self.health -= amount
            if self.health <= 0:
                self.status = RobotStatus.DEAD
                self.respawn_timer = time.time() + random.uniform(5, 10)  # Respawn after 5-10 seconds

