        if skill not in self.skills:
            return False

        if skill == Skill.REPAIR:
            if self.health < self.max_health:
                self.health = min(self.max_health, self.health + self.skills[skill])
                return True
        elif skill == Skill.HACK:        if skill == Skill.HACK:
