                target.status = RobotStatus.DISABLED
                target.hack_end_time = time.time() + hack_duration
                print(f"{self.name} hacked {target.name} for {hack_duration} seconds!")
                return True
            else:
                return False        elif skill == Skill.SHIELD:
            if PowerUpType.SHIELD in self.inventory:
                self.inventory[PowerUpType.SHIELD] += 20
                return True
        elif skill == Skill.SPRINT:
            self.speed *= self.skills[skill]
            self.active_effects[skill] = time.time() + self.skills[skill]
            return True

        return False

    def update(self, arena):
        """Update robot state for each frame"""
        # Update effects
        expired_effects = []
        for effect, end_time in self.active_effects.items():
            if time.time() > end_time:
                if effect == Skill.JUMP:
                    self.speed /= 1.5
                elif effect == Skill.SPRINT:
                    self.speed /= self.skills[Skill.SPRINT]
                expired_effects.append(effect)

        for effect in expired_effects:
            del self.active_effects[effect]

        # Check for power-ups
        for power_up in arena.power_ups:
            if power_up.active and self.position.distance_to(power_up.position) < power_up.radius:
                self.collect_power_up(power_up)
                power_up.active = False

        # Check for hazards
        for hazard in arena.hazards:
            if hazard.active and self.position.distance_to(hazard.position) < hazard.radius:
                self.take_damage(hazard.damage)

    def collect_power_up(self, power_up):
        """Collect and apply a power-up"""
        if power_up.type in self.inventory:
            self.inventory[power_up.type] += power_up.amount
        elif power_up.type == PowerUpType.AMMO and self.weapon:
            self.weapon.ammo += power_up.amount
        else:
            # Apply instant effect
            if power_up.type == PowerUpType.SPEED_BOOST:
                self.speed *= 1.5
                self.active_effects[PowerUpType.SPEED_BOOST] = time.time() + 10
            elif power_up.type == PowerUpType.DAMAGE_BOOST:
                self.weapon.damage = int(self.weapon.damage * 1.5)
                self.active_effects[PowerUpType.DAMAGE_BOOST] = time.time() + 10

