    def move_toward(self, robot, target_position):
        """Move robot toward a target position"""
        dx = target_position.x - robot.position.x
        dy = target_position.y - robot.position.y
        distance = math.hypot(dx, dy)

        if distance > 0:
            robot.movement_direction = self.get_direction(dx, dy)
            robot.move(robot.movement_direction, self)

    def get_direction(self, dx, dy):
        """Determine direction based on movement vector"""
        if abs(dx) > abs(dy):
            return Direction.RIGHT if dx > 0 else Direction.LEFT
        else:
            return Direction.DOWN if dy > 0 else Direction.UP

    def evaluate_strategic_situation(self, robot):
        """Evaluate the current strategic situation for a commander"""
        # Count team members
        alive_teammates = sum(1 for r in robot.team.members if r.status == RobotStatus.ALIVE)
        dead_teammates = len(robot.team.members) - alive_teammates

        # Count enemy members
        enemies = [r for r in self.robots if r.team != robot.team]
        alive_enemies = sum(1 for r in enemies if r.status == RobotStatus.ALIVE)
        dead_enemies = len(enemies) - alive_enemies

        # Adjust team role based on situation
        if alive_teammates > alive_enemies and dead_enemies > dead_teammates:
            # We're winning, focus on defense
            robot.team.role = Role.DEFENSE
        elif alive_teammates < alive_enemies and dead_teammates > dead_enemies:
            # We're losing, focus on offense
            robot.team.role = Role.ASSAULT
        else:
            # Balanced situation, focus on support
            robot.team.role = Role.SUPPORT

        # Reassign roles based on new team role
        robot.team.assign_roles(self)

    def adjust_difficulty(self):
        """Adjust game difficulty based on team performance"""
        # Calculate team scores
