        dz = target.z - self.z
        distance = ((dx**2) + (dy**2) + (dz**2)) ** 0.5
        if distance > 0:
            self.x += (dx / distance) * speed
            self.y += (dy / distance) * speed
            self.z += (dz / distance) * speed

