        if data.validate_format():
            self.data.append(data)
            return data.process_data()
        else:
            return "Invalid data format"

    def analyze_match(self, user):
        if user.can_perform_action('analyze_data'):
            return self.metrics.calculate_performance(self.data[-1].content)
        return "Access denied"

    def generate_and_share_report(self, user):
        if user.can_perform_action('generate_report'):
            return self.metrics.generate_report()
        return "Access denied"

