                         self.position[1] + dy + random.uniform(-0.1, 0.1))

    def attack(self, target):
        """Attack the specified target with the current weapon"""
        if self.weapon and self.status == RobotStatus.ACTIVE:
            self.weapon.use(self, target)
            self.use_power_ups(PowerUp.DAMAGE_AMPLIFIER)

    def use_power_ups(self, power_up_type):
        """Use any active power-ups of the specified type"""
        for power_up in self.power_ups:
            if power_up.type == power_up_type and power_up.is_active():
                power_up.use(self)

    def take_damage(self, amount):
        """Apply damage to the robot's health"""
        if self.status == RobotStatus.ACTIVE:
            self.health -= amount
            if self.health <= 0:
                self.status = RobotStatus.DEAD
                self.die()

    def heal(self, amount):
        """Heal the robot's health"""
        if self.status == RobotStatus.ACTIVE:
            self.health = min(self.max_health, self.health + amount)

    def die(self):
        """Handle robot death"""
        self.status = RobotStatus.DEAD
        self.reset_position()
        self.respawn_timer = time.time() + 5  # 5 seconds before respawn

    def reset_position(self):
        """Reset the robot to its starting position"""
        # This would be implemented with specific start positions for each team
        self.position = (0, 0)

    def update(self, arena):
        """Update robot state each frame"""
        if self.status == RobotStatus.DEAD:
            self.check_respawn()
            return

        # Update AI based on current strategy
        if self.strategy:
            self.strategy.execute(self, arena)

        # Update power-ups
        active_power_ups = []
        for power_up in self.power_ups:
            if power_up.update():
                active_power_ups.append(power_up)
        self.power_ups = active_power_ups

    def check_respawn(self):
        """Check if the robot should respawn"""
        if self.status == RobotStatus.DEAD and time.time() >= self.respawn_timer:
            self.status = RobotStatus.ACTIVE
            self.health = self.max_health // 2  # Half health on respawn
            self.reset_position()

    def learn(self, battle_results):
        """Learn from the battle results to improve future performance"""
        # Update strategy based on battle results
        self.experience += len(battle_results)
        self.strategy.update(battle_results)

        # Adjust difficulty based on performance
        if sum(result["success"] for result in battle_results) / len(battle_results) > 0.8:
            self.difficulty = min(Difficulty.HARD, self.difficulty.value + 1)
        elif sum(result["success"] for result in battle_results) / len(battle_results) < 0.4:
            self.difficulty = max(Difficulty.EASY, self.difficulty.value - 1)

