    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.robots = []
        self.objective_manager = ObjectiveManager(self)
        self.power_up_manager = PowerUpManager(self)
        self.environment = Environment(width, height)
        self.scoreboard = {}
        self.difficulty_manager = DifficultyManager()
        self.combat_log = deque(maxlen=100)  # Store last 100 combat events

    def add_robot(self, robot):
        self.robots.append(robot)
        self.scoreboard[robot.name] = 0
        self.difficulty_manager.register_robot(robot)

    def start(self):
        """Start the CyberArena simulation"""
        self.objective_manager.start_new_objective()
        self.spawn_power_ups()
        self.spawn_hazards()
        self.start_render_thread()
        self.run_simulation()

    def run_simulation(self):
        """Main simulation loop"""
        last_time = time.time()
        while True:
            current_time = time.time()
            delta_time = current_time - last_time
            last_time = current_time

            self.update(delta_time)
            time.sleep(0.01)  # Limit to 100 FPS

    def update(self, delta_time):
        """Update the entire arena state"""
        for robot in self.robots:
            robot.update(self)

        self.objective_manager.update()
        self.power_up_manager.update()
        self.environment.update()

        # Check for collisions and interactions
        self.check_collisions()
        self.process_combat()

    def check_collisions(self):
        """Check for collisions between robots and other entities"""
        for robot in self.robots:
            # Check for collisions with other robots
            for other in self.robots:
                if robot != other and self.is_colliding(robot, other):
                    self.handle_robot_collision(robot, other)

            # Check for collisions with power-ups
            for power_up in self.power_up_manager.power_ups:
                if self.is_colliding(robot, power_up):
                    self.handle_power_up_pickup(robot, power_up)

            # Check for collisions with environment hazards
            for hazard in self.environment.hazards:
                if self.is_colliding(robot, hazard):
                    self.handle_hazard_collision(robot, hazard)

    def is_colliding(self, entity1, entity2):
        """Check if two entities are colliding"""
        # Simple distance-based collision check for demonstration
        distance = math.sqrt((entity1.position[0] - entity2.position[0])**2 + 
                            (entity1.position[1] - entity2.position[1])**2)
        return distance < 0.5  # 0.5 units distance for collision

    def handle_robot_collision(self, robot1, robot2):
        """Handle a collision between two robots"""
        # Determine if a melee attack should occur
        if robot1.weapon and robot1.weapon.weapon_type == WeaponType.MELEE:
            robot1.attack(robot2)
        elif robot2.weapon and robot2.weapon.weapon_type == WeaponType.MELEE:
            robot2.attack(robot1)

    def handle_power_up_pickup(self, robot, power_up):
        """Handle a robot picking up a power-up"""
        robot.power_ups.append(power_up)
        self.power_up_manager.power_ups.remove(power_up)
        robot.score += 10  # Award points for picking up power-ups

    def handle_hazard_collision(self, robot, hazard):
        """Handle a robot colliding with an environmental hazard"""
        robot.take_damage(hazard.damage)
        self.combat_log.append({
            "type": "hazard",
            "robot": robot.name,
            "hazard": hazard.name,
            "damage": hazard.damage
        })

    def process_combat(self):
        """Process all combat actions from the combat log"""
        for combat_event in self.combat_log:
            if combat_event["type"] == "attack":
                attacker = next((r for r in self.robots if r.name == combat_event["attacker"]), None)
                defender = next((r for r in self.robots if r.name == combat_event["defender"]), None)
                if attacker and defender:
                    defender.take_damage(combat_event["damage"])
                    attacker.score += combat_event["damage"]  # Award points for damage dealt

    def spawn_power_ups(self):
        """Spawn initial power-ups in the arena"""
        power_up_types = [PowerUp.SHIELD, PowerUp.SPEED_BOOST, 
                         PowerUp.DAMAGE_AMPLIFIER, PowerUp.TEAM_HEAL]

        # Spawn 3-5 power-ups at random positions
        for _ in range(random.randint(3, 5)):
            power_up_type = random.choice(power_up_types)
