    def __init__(self):
        self.robots = []
        self.difficulty_adjustment_interval = 60  # seconds
        self.last_adjustment = time.time()

    def register_robot(self, robot):
        self.robots.append(robot)

    def update_difficulty(self):
        """Update the difficulty for all robots based on their performance"""
        if time.time() - self.last_adjustment >= self.difficulty_adjustment_interval:
            for robot in self.robots:
                # Adjust difficulty based on win/loss ratio
                win_ratio = robot.score / max(1, robot.experience) if robot.experience > 0 else 0.5
                if win_ratio > 0.8:
                    robot.difficulty = min(Difficulty.HARD, robot.difficulty.value + 1)
                elif win_ratio < 0.4:
                    robot.difficulty = max(Difficulty.EASY, robot.difficulty.value - 1)
            self.last_adjustment = time.time()

class AICombatStrategy:
    def __init__(self, robot):
        self.robot = robot

    def execute(self, robot, arena):
        """Execute the combat strategy for this robot"""
        # Basic AI: find nearest enemy and attack
        enemies = [r for r in arena.robots if r.team != robot.team and r.status == RobotStatus.ACTIVE]
        if enemies:
            nearest_enemy = min(enemies, key=lambda e: self.distance_to(robot, e))
            if self.distance_to(robot, nearest_enemy) < 1.0:
                robot.attack(nearest_enemy)
            else:
                direction = self.get_direction_to(robot, nearest_enemy)
                robot.move(direction)

    def distance_to(self, robot1, robot2):
        """Calculate distance between two robots"""
        return math.sqrt((robot1.position[0] - robot2.position[0])**2 + 
                        (robot1.position[1] - robot2.position[1])**2)

    def get_direction_to(self, robot1, robot2):
        """Get the direction to move toward another robot"""
        if robot1.position[0] < robot2.position[0]:
            return Direction.RIGHT
        elif robot1.position[0] > robot2.position[0]:
            return Direction.LEFT
        elif robot1.position[1] < robot2.position[1]:
            return Direction.UP
        else:
            return Direction.DOWN

