        """Aggressive attack strategy for attackers."""
        if situation == "enemy_in_range":
            robot.perform_action(robot.find_closest_opponent())
        elif situation == "free_roam":
            robot.move_towards(robot.find_closest_objective())

    def defensive_defend_strategy(self, robot: Robot, situation: str):
        """Defensive strategy for defenders."""
        if situation == "enemy_threat":
            robot.perform_action(robot.find_closest_opponent())
        elif situation == "guard_position":
            robot.move_towards(robot.team.objective_position)

