        """Support strategy for support robots."""
        if situation == "ally_needs_help":
            ally = robot.find_injured_ally()
            if ally:
                robot.move_towards(ally.position)
        elif situation == "provide_backup":
            robot.move_towards(robot.find_closest_objective())

