from typing import List, Dict, Tuple, Optional


class Task:
    """Represents a task to be executed by an agent."""

    def __init__(self, name: str, description: str, priority: int, required_resources: List[str]):
        self.name = name
        self.description = description
        self.priority = priority
        self.required_resources = required_resources
        self.status = 'pending'
        self.start_time = None
        self.end_time = None
        self.assigned_agent = None
        self.notes = []

    def start(self, agent):
        self.status = 'in progress'
        self.start_time = time.time()
        self.assigned_agent = agent

    def complete(self, feedback: str = None):
        self.status = 'completed'
        self.end_time = time.time()
        if feedback:
            self.notes.append(feedback)

    def update_status(self, status, feedback: str = None):
        self.status = status
        if feedback:
            self.notes.append(feedback)

    def is_complete(self) -> bool:
        return self.status == 'completed'

    def get_estimated_time_remaining(self) -> float:
        if self.status != 'in progress':
            return float('inf')
        return random.uniform(10, 60)  # Simulate estimated time remaining


class Agent:
    """Represents an agent capable of performing tasks."""

    def __init__(self, agent_id: str, skills: List[str]):
        self.agent_id = agent_id
        self.skills = skills
        self.current_task = None
        self.available = True
        self.status_updates = []

    def assign_task(self, task: Task):
        if self.available and all(skill in self.skills for skill in task.required_resources):
            self.current_task = task
            task.start(self.agent_id)
            self.available = False
            self.status_updates.append(f"Assigned task {task.name} to Agent {self.agent_id}")
        else:
            self.status_updates.append(f"Agent {self.agent_id} cannot be assigned task {task.name}")

    def complete_task(self):
        if self.current_task:
            self.current_task.complete()
            self.available = True
            self.status_updates.append(f"Completed task {self.current_task.name} by Agent {self.agent_id}")
            self.current_task = None

    def update_status(self, status, feedback: str = None):
        if self.current_task:
            self.current_task.update_status(status, feedback)


class TaskScheduler:
    """Main class for managing tasks and agents."""

    def __init__(self):
        self.tasks: List[Task] = []
        self.agents: List[Agent] = []
        self.task_history: List[Task] = []
        self.chat_log: List[Tuple[str, str]] = []

    def add_task(self, task: Task):
        self.tasks.append(task)

    def add_agent(self, agent: Agent):
        self.agents.append(agent)

    def assign_tasks(self):
        # Sort tasks by priority
        sorted_tasks = sorted(self.tasks, key=lambda t: t.priority, reverse=True)
        for task in sorted_tasks:
            for agent in self.agents:
                if agent.available and all(skill in agent.skills for skill in task.required_resources):
                    agent.assign_task(task)
                    break

    def reassign_tasks(self):
        # Reassign tasks if agents are no longer available or tasks need to be re-prioritized
        completed_tasks = [task for task in self.tasks if task.is_complete()]
        for task in completed_tasks:
            self.task_history.append(task)
            self.tasks.remove(task)

        # Reassign remaining tasks
        self.assign_tasks()

    def update_task_status(self, task_name: str, status: str, feedback: str = None):
        for task in self.tasks:
            if task.name == task_name:
                task.update_status(status, feedback)
                break

    def get_task_status(self, task_name: str) -> dict:
        for task in self.tasks:
            if task.name == task_name:
                return {
                    'name': task.name,
                    'description': task.description,
                    'priority': task.priority,
                    'status': task.status,
                    'assigned_agent': task.assigned_agent,
                    'estimated_time_remaining': task.get_estimated_time_remaining()
                }
        return None

    def log_message(self, sender: str, message: str):
        self.chat_log.append((sender, message))

    def get_chat_log(self):
        return self.chat_log

    def get_task_progress(self):
        return {
            'total_tasks': len(self.tasks),
            'completed_tasks': sum(1 for task in self.tasks if task.is_complete()),
            'in_progress_tasks': sum(1 for task in self.tasks if task.status == 'in progress'),
            'pending_tasks': sum(1 for task in self.tasks if task.status == 'pending')
        }

    def get_agent_performance(self):
        performance = []
        for agent in self.agents:
            completed_tasks = sum(1 for task in self.task_history if task.assigned_agent == agent.agent_id and task.is_complete())
            performance.append({
                'agent_id': agent.agent_id,
                'completed_tasks': completed_tasks,
                'status_updates': agent.status_updates
            })
        return performance

    def get_task_history(self):
        return self.task_history


def run_scheduler():
    # Example usage of the MultiAgentTaskScheduler
    scheduler = TaskScheduler()

    # Create some tasks
    task1 = Task('Task1', 'Setup environment', 2, ['setup', 'environment'])
    task2 = Task('Task2', 'Write code', 1, ['python', 'coding'])
    task3 = Task('Task3', 'Run tests', 3, ['testing', 'automation'])

    # Create some agents
    agent1 = Agent('A1', ['setup', 'python'])
    agent2 = Agent('A2', ['python', 'testing'])

    # Add to scheduler
    scheduler.add_task(task1)
    scheduler.add_task(task2)
    scheduler.add_task(task3)

    scheduler.add_agent(agent1)
    scheduler.add_agent(agent2)

    # Assign tasks and monitor progress
    scheduler.assign_tasks()

    # Simulate task execution
    for agent in scheduler.agents:
        if agent.current_task:
            print(f"Agent {agent.agent_id} is executing task {agent.current_task.name}")
            time.sleep(agent.current_task.get_estimated_time_remaining())
            agent.complete_task()

    # Reassign tasks after some are completed
    scheduler.reassign_tasks()

    # Log a message
    scheduler.log_message('A1', 'Task1 completed successfully.')
    scheduler.log_message('A2', 'Task2 had some issues, but resolved.')

    # Get status
    print("\nTask Status:")
    for task in scheduler.tasks:
        print(scheduler.get_task_status(task.name))

    print("\nAgent Performance:")
    for performance in scheduler.get_agent_performance():
        print(performance)

    print("\nChat Log:")
    for sender, message in scheduler.get_chat_log():
        print(f"{sender}: {message}")

    print("\nTask History:")
    for task in scheduler.get_task_history():
        print(task.name, task.start_time, task.end_time, task.assigned_agent)


if __name__ == "__main__":
    run_scheduler()"
