# ProjectOrganizer - A Project Management Tool for Task and Resource Management

from enum import Enum
from dataclasses import dataclass
import datetime
from typing import List, Dict, Optional
import threading
import time
import json

# --- Enums ---

class Priority(Enum):
    """Priority levels for tasks"""
    LOW = 1
    MEDIUM = 2
    HIGH = 3

# --- Data Models ---

@dataclass
class TeamMember:
    name: str
    role: str
    available_hours: int

@dataclass
class Task:
    id: int
    description: str
    due_date: datetime.date
    priority: Priority
    assigned_to: List[TeamMember]
    status: str  # 'Pending', 'In Progress', 'Completed'
    dependencies: List[int]  # IDs of tasks this task depends on

@dataclass
class Resource:
    name: str
    type: str
    available: bool
    allocated_tasks: List[int]

# --- Task Management Module ---

class TaskManager:
    def __init__(self):
        self.tasks: List[Task] = []
        self.next_task_id = 1

    def create_task(self, description: str, due_date: datetime.date, priority: Priority, assigned_to: List[TeamMember], dependencies: List[int]) -> Task:
        task = Task(
            id=self.next_task_id,
            description=description,
            due_date=due_date,
            priority=priority,
            assigned_to=assigned_to,
            status='Pending',
            dependencies=dependencies
        )
        self.tasks.append(task)
        self.next_task_id += 1
        return task

    def edit_task(self, task_id: int, description: Optional[str] = None, due_date: Optional[datetime.date] = None,
                  priority: Optional[Priority] = None, assigned_to: Optional[List[TeamMember]] = None, dependencies: Optional[List[int]] = None):
        for task in self.tasks:
            if task.id == task_id:
                if description:
                    task.description = description
                if due_date:
                    task.due_date = due_date
                if priority:
                    task.priority = priority
                if assigned_to:
                    task.assigned_to = assigned_to
                if dependencies:
                    task.dependencies = dependencies
                break

    def delete_task(self, task_id: int):
        for i, task in enumerate(self.tasks):
            if task.id == task_id:
                del self.tasks[i]
                break

    def get_task(self, task_id: int) -> Optional[Task]:
        for task in self.tasks:
            if task.id == task_id:
                return task
        return None

    def get_all_tasks(self) -> List[Task]:
        return self.tasks

# --- Task Scheduling Module ---

class TaskScheduler:
    def __init__(self, task_manager: TaskManager):
        self.task_manager = task_manager

    def schedule_tasks(self):
        tasks = self.task_manager.get_all_tasks()
        # Sort tasks by priority and due date
        tasks.sort(key=lambda t: (t.priority.value, t.due_date))
        for task in tasks:
            for dep_id in task.dependencies:
                dep_task = self.task_manager.get_task(dep_id)
                if dep_task and dep_task.status != 'Completed':
                    print(f"Error: Task {task.id} has a dependency on incomplete task {dep_id}")

    def update_schedule_on_completion(self, task_id: int):
        task = self.task_manager.get_task(task_id)
        if task:
            task.status = 'Completed'
            print(f"Task {task_id} completed. Schedule updated.")

