class Arena:
    """Main class for the CyberArena simulation."""
    def __init__(self, size: Tuple[float, float] = (100, 100)):
        self.size = size  # width and height of the arena
        self.robots: List[Robot] = []
        self.power_ups: List[PowerUp] = []
        self.environmental_effects: List[EnvironmentalEffect] = []
        self.objectives: List[Objective] = []
        self.teams: Dict[Team, List[Robot]] = {
            Team.RED: [],
            Team.BLUE: [],
            Team.NEUTRAL: []
        }
        self.enemies: Dict[Team, List[Robot]] = {
            Team.RED: [],
            Team.BLUE: [],
            Team.NEUTRAL: []
        }
        self.current_time = 0.0
        self.delta_time = 0.01  # 100 updates per second
        self.round_time = 300.0  # 5 minutes per round
        self.total_rounds = 3
        self.current_round = 1
        self.spectators: List[str] = []

    def add_robot(self, robot: Robot) -> None:
        """Add a robot to the arena."""
        self.robots.append(robot)
        self.teams[robot.team].append(robot)
        self._update_enemies()

    def remove_robot(self, robot: Robot) -> None:
        """Remove a robot from the arena."""
        self.robots.remove(robot)
        self.teams[robot.team].remove(robot)
        self._update_enemies()

    def _update_enemies(self) -> None:
        """Update the enemies for each team."""
        self.enemies = {
            Team.RED: [robot for robot in self.robots if robot.team != Team.RED],
            Team.BLUE: [robot for robot in self.robots if robot.team != Team.BLUE],
            Team.NEUTRAL: [robot for robot in self.robots if robot.team != Team.NEUTRAL]
        }

    def add_power_up(self, power_up: PowerUp) -> None:
        """Add a power-up to the arena."""
        self.power_ups.append(power_up)

    def add_environmental_effect(self, effect: EnvironmentalEffect) -> None:
        """Add an environmental effect to the arena."""
        self.environmental_effects.append(effect)

    def add_objective(self, objective: Objective) -> None:
        """Add an objective to the arena."""
        self.objectives.append(objective)

    def update(self) -> None:
        """Update the state of the arena."""
        # Update current time
        self.current_time += self.delta_time

        # Update all robots
        for robot in self.robots:
            robot.update(self.delta_time, self)

        # Check for power-up pickups
        for robot in self.robots:
            for power_up in self.power_ups[:]:  # Use a copy to avoid modifying during iteration
                if robot.position.distance_to(power_up.position) < 2.0:
                    power_up.activate(robot)
                    self.power_ups.remove(power_up)

        # Apply environmental effects
        for effect in self.environmental_effects:
            for robot in self.robots:
                if robot.position.distance_to(effect.position) <= effect.radius:
                    effect.apply_effect(robot, self)

        # Update objectives
        for objective in self.objectives:
            objective.update(self)
            if objective.is_complete():
                self.handle_objective_completion(objective)

        # Check for round completion
        if self.current_time >= self.round_time:
            self.end_round()

        # Adaptive difficulty adjustment
        self.adjust_difficulty()

