    def adjust_difficulty(self) -> None:
        """Adjust the difficulty based on the performance of the robots."""
        # This is a simplified example of difficulty adjustment
        team_performance = {
            "red": self._calculate_team_performance(Team.RED),
            "blue": self._calculate_team_performance(Team.BLUE)
        }

        if team_performance["red"] > team_performance["blue"]:
            # Make blue team stronger
            for robot in self.teams[Team.BLUE]:
                robot.speed *= 1.1
                robot.weapon.damage *= 1.1
                robot.health = min(GameConstants.MAX_HEALTH, robot.health * 1.1)
        else:
            # Make red team stronger
            for robot in self.teams[Team.RED]:
                robot.speed *= 1.1
                robot.weapon.damage *= 1.1
                robot.health = min(GameConstants.MAX_HEALTH, robot.health * 1.1)

        # Reset the adjustments after a few rounds to prevent runaway difficulty
        if self.current_round > 3:
            for robot in self.robots:
                robot.speed = GameConstants.MOVE_SPEED
                robot.weapon.damage = robot.weapon.damage / 1.1
                robot.health = GameConstants.MAX_HEALTH

    def _calculate_team_performance(self, team: Team) -> float:
        """Calculate the performance of a team based on various factors."""
        performance = 0
        for robot in self.teams[team]:
            # This is a simplified performance calculation
            performance += robot.score
            performance += robot.health
            performance += robot.objective_progress * 10
        return performance

