        """Calculate the Euclidean distance between two positions."""
        return ((self.x - other.x)**2 + (self.y - other.y)**2)**0.5

    def move_towards(self, target: "Position", speed: float, delta_time: float) -> "Position":
        """Move towards a target position at a given speed."""
        distance = self.distance_to(target)
        if distance <= 0:
            return self  # Already at target position
        move_vector = Position(
            (target.x - self.x) / distance,
            (target.y - self.y) / distance
        )
        new_position = Position(
            self.x + move_vector.x * speed * delta_time,
            self.y + move_vector.y * speed * delta_time
        )
        return new_position

