# ProjectOrganizer - A Project Management Tool for Task and Resource Management

from abc import ABC, abstractmethod
from enum import Enum
from typing import List, Dict, Optional
import uuid
import datetime

# Enums and Constants
class Priority(Enum):
    """Enumeration for task priority levels."""
    LOW = 'low'
    MEDIUM = 'medium'
    HIGH = 'high'

class TaskStatus(Enum):
    """Enumeration for task statuses."""
    PENDING = 'pending'
    IN_PROGRESS = 'in_progress'
    COMPLETED = 'completed'

class ResourceType(Enum):
    """Enumeration for types of resources."""
    PERSONNEL = 'personnel'
    EQUIPMENT = 'equipment'
    BUDGET = 'budget'

# Task Management Module
class Task:
    """Represents a project task with details and status."""
    def __init__(self, description: str, due_date: datetime.date, priority: Priority, assigned_members: List[str]):
        self.task_id = str(uuid.uuid4())
        self.description = description
        self.due_date = due_date
        self.priority = priority
        self.assigned_members = assigned_members
        self.status = TaskStatus.PENDING
        self.dependencies: List[str] = []

    def mark_as_complete(self):
        self.status = TaskStatus.COMPLETED

    def __repr__(self):
        return f"Task(id={self.task_id}, description='{self.description}', due_date='{self.due_date}', priority={self.priority.value}, status={self.status.value})"

class TaskManager:
    """Manages the creation, deletion, and editing of tasks."""
    def __init__(self):
        self.tasks: Dict[str, Task] = {}

    def create_task(self, description: str, due_date: datetime.date, priority: Priority, assigned_members: List[str]):
        task = Task(description, due_date, priority, assigned_members)
        self.tasks[task.task_id] = task
        return task

    def delete_task(self, task_id: str):
        if task_id in self.tasks:
            del self.tasks[task_id]

    def edit_task(self, task_id: str, description: Optional[str] = None, due_date: Optional[datetime.date] = None, priority: Optional[Priority] = None):
        if task_id in self.tasks:
            task = self.tasks[task_id]
            if description:
                task.description = description
            if due_date:
                task.due_date = due_date
            if priority:
                task.priority = priority

# Task Scheduling Module
class TaskScheduler:
    """Automatically schedules tasks based on dependencies and priority."""
    def __init__(self, task_manager: TaskManager):
        self.task_manager = task_manager

    def schedule_tasks(self):
        tasks = self.task_manager.tasks.values()
        # Sort by priority and due date
        sorted_tasks = sorted(tasks, key=lambda task: (task.priority.value, task.due_date))
        print("Tasks scheduled successfully:")
        for task in sorted_tasks:
            print(task)

    def update_schedule(self, completed_task_id: str):
        if completed_task_id in self.task_manager.tasks:
            print(f"Task {completed_task_id} completed. Re-scheduling tasks...")
            self.schedule_tasks()

