class Location:
    def __init__(self, name: str, coordinates: Tuple[float, float]):
        self.name = name
        self.coordinates = coordinates

class Route:
    def __init__(self, path: List[Location], transport_mode: TransportMode, estimated_time: float, cost: float, eco_score: int = 0):
