        self.user_routes = {}  # user_id -> Route
        self.shared_travel_plans = {}  # group_id -> List[user_ids]
        self.traffic_updates = {}  # location -> TrafficCondition
        self.user_feedback = {}  # route_id -> List[Feedback]

    def update_traffic(self, location: Location, condition: TrafficCondition):
        self.traffic_updates[location.coordinates] = condition

    def get_traffic_condition(self, location: Location) -> TrafficCondition:
        return self.traffic_updates.get(location.coordinates, TrafficCondition.CLEAR)

