    def plan_multiple_routes(self, start: Location, destination: Location, preferences: UserPreferences) -> List[Route]:
        fastest = self._find_route(start, destination, TransportMode.PRIVATE_VEHICLE, "fastest")
        cheapest = self._find_route(start, destination, TransportMode.PUBLIC_TRANSPORT, "cheapest")
        eco_friendly = self._find_route(start, destination, TransportMode.BIKE, "eco_friendly")
        return [fastest, cheapest, eco_friendly]

    def _find_route(self, start: Location, destination: Location, mode: TransportMode, strategy: str) -> Route:
        # Simplified route finding using Dijkstra's algorithm
        def get_cost(src, dest):
            base_time = self.map_data[src.coordinates][dest.coordinates]
            traffic = self.get_traffic_condition(dest)
            if traffic == TrafficCondition.CONGESTED:
                base_time *= 1.5
            elif traffic == TrafficCondition.ACCIDENT:
                base_time *= 3.0
            elif traffic == TrafficCondition.ROAD_CLOSED:
                return float('inf')
            return base_time

        # Build a list of reachable locations (simplified for demo)
