        graph = {}
        for loc in reachable:
            graph[loc.coordinates] = {}
        for loc in reachable:
            for other in reachable:
                if loc != other:
                    graph[loc.coordinates][other.coordinates] = get_cost(loc, other)

        # Dijkstra's algorithm
        def dijkstra(start_coords, end_coords):
            distances = {node: float('inf') for node in graph}
            distances[start_coords] = 0
            priority_queue = [(0, start_coords)]
            while priority_queue:
                current_dist, current = heapq.heappop(priority_queue)
                if current == end_coords:
                    break
                if current_dist > distances[current]:
                    continue
                for neighbor, weight in graph[current].items():
                    distance = current_dist + weight
                    if distance < distances[neighbor]:
                        distances[neighbor] = distance
                        heapq.heappush(priority_queue, (distance, neighbor))
            return distances[end_coords]

        time_estimate = dijkstra(start.coordinates, destination.coordinates)

        cost = 0
        if mode == TransportMode.PRIVATE_VEHICLE:
