class ItineraryGenerator:
    def __init__(self):
        self.activities = {
            "Beach": {"preferences": [TravelPreference.RELAXATION, TravelPreference.FOOD], "cost": 100},
            "Museum": {"preferences": [TravelPreference.CULTURE], "cost": 50},
            "Hiking": {"preferences": [TravelPreference.ADVENTURE], "cost": 75},
            "Shopping": {"preferences": [TravelPreference.SHOPPING], "cost": 90},
            "City Tour": {"preferences": [TravelPreference.CULTURE, TravelPreference.FOOD], "cost": 60}
        }

    def generate_individual_itinerary(self, user: User) -> dict:
        # Match user preferences with activities
        user_activities = []
        for activity_name, activity_info in self.activities.items():
            matching_preferences = [p for p in activity_info["preferences"] if user.preferences.get(p, 0) > 0]
            if matching_preferences:
                user_activities.append({
                    "name": activity_name,
                    "cost": activity_info["cost"],
                    "preferences": [p.value for p in matching_preferences]
                })
        return {
            "user_id": user.user_id,
            "itinerary": user_activities
        }

    def integrate_itineraries(self, itineraries: List[dict]) -> dict:
        # Combine all activities into a group itinerary
        group_activities = {}
        for itinerary in itineraries:
            for activity in itinerary["itinerary"]:
                activity_name = activity["name"]
                if activity_name not in group_activities:
                    group_activities[activity_name] = {
                        "name": activity_name,
                        "cost": activity["cost"],
                        "users_interested": [itinerary["user_id"]]
                    }
                else:
                    group_activities[activity_name]["users_interested"].append(itinerary["user_id"])

        # Sort by number of interested users
        sorted_activities = sorted(group_activities.values(), key=lambda x: len(x["users_interested"]), reverse=True)

        return {
            "group_itinerary": sorted_activities
        }

