class ConflictResolver:
    def resolve_conflicts(self, group_itinerary: dict, user_budgets: Dict[str, int], total_budget: int):
        # Ensure group itinerary is within budget and feasible
        total_cost = sum(activity["cost"] for activity in group_itinerary["group_itinerary"])
        if total_cost > total_budget:
            # Remove most expensive items first
            group_itinerary["group_itinerary"] = sorted(group_itinerary["group_itinerary"], key=lambda x: x["cost"], reverse=False)
            while total_cost > total_budget and group_itinerary["group_itinerary"]:
                removed_activity = group_itinerary["group_itinerary"].pop()
                total_cost -= removed_activity["cost"]

