        self.position = (0, 0)
        self.weapon = random.choice(list(WeaponType))
        self.role = random.choice([Role.SOLDIER, Role.SUPPORT, Role.TANK])
        self.experience = 0
        self.skills = self._initialize_skills()
        self.last_action = None
