        # Adaptive learning parameters
        self.action_success = {}  # Tracks success of different actions
        self.weapon_effectiveness = {}  # Tracks effectiveness of different weapons
        self.teamwork_score = 0  # Tracks effectiveness of teamwork

    def _initialize_skills(self) -> Dict[ActionType, float]:
        """Initialize base skill levels for different actions"""
        return {
            ActionType.ATTACK: random.uniform(0.6, 0.8),
            ActionType.DEFEND: random.uniform(0.5, 0.7),
            ActionType.MOVE: random.uniform(0.7, 0.9),
            ActionType.USE_ABILITY: random.uniform(0.4, 0.6),
            ActionType.RETREAT: random.uniform(0.7, 0.9)
        }

    def take_damage(self, amount: float):
        """Process damage taken by the robot"""
        self.health -= amount
        self.energy -= min(amount, 10)
        if self.health <= 0:
            self.die()

    def die(self):
        """Handle robot death event"""
        print(f"{self.name} has been destroyed!")
        self.health = 0
        self.energy = 0
        # Reset position to respawn point
        self.position = self._get_respawn_position()

    def _get_respawn_position(self) -> Tuple[float, float]:
        """Determine respawn position based on team"""
        if self.team == Team.RED:
            return (10, 10)
        elif self.team == Team.BLUE:
            return (90, 90)
        else:
            return (50, 50)

    def select_action(self, environment_state: Dict) -> ActionType:
        """
        Select the most appropriate action based on current state and learned experience
        """
        # Update action probabilities based on past success
        action_probabilities = self._calculate_action_probabilities()

        # Select action based on probabilities and current situation
        best_action = max(action_probabilities, key=action_probabilities.get)

        # Make sure the robot doesn't repeat the same action too often
        if self.last_action == best_action:
            other_actions = [a for a in action_probabilities if a != best_action]
            if other_actions:
                best_action = random.choice(other_actions)

        self.last_action = best_action
        return best_action

    def _calculate_action_probabilities(self) -> Dict[ActionType, float]:
        """
        Calculate action probabilities based on skills and past success
        """
        base_probabilities = {action: skill for action, skill in self.skills.items()}

        # Adjust probabilities based on past success
        for action, probability in base_probabilities.items():
            if action in self.action_success:
                base_probabilities[action] *= self.action_success[action]

        # Normalize probabilities
        total = sum(base_probabilities.values())
        if total > 0:
            for action in base_probabilities:
                base_probabilities[action] /= total

        return base_probabilities

    def update_experience(self, action: ActionType, success: bool, value: float):
        """
        Update the robot's experience and learning from an action
        """
        # Update action success tracking
        if action not in self.action_success:
            self.action_success[action] = 0.5
        if success:
            self.action_success[action] = min(1.0, self.action_success[action] + 0.1)
        else:
            self.action_success[action] = max(0.2, self.action_success[action] - 0.1)

        # Update weapon effectiveness tracking
