            else:
                self.weapon_effectiveness[self.weapon] = max(
                    0.2, self.weapon_effectiveness[self.weapon] - 0.1)

        # Update experience and score
        self.experience += value
        self.score += value * 0.1  # Small portion of experience contributes to score

