                    # Payload moves with the escort team
                    self.payload_position = robot.position
                    break

        if self.payload_position == self.target_position:
            self.completed = True
            return {"status": "payload_delivered", "victor": self.escort_team.name}

        # Check if payload is destroyed
        if self.payload_health <= 0:
            self.completed = True
            return {"status": "payload_destroyed", "victor": "attackers"}

        # Check if payload is under attack
        attackers = [robot for robot in robots if 
                    robot.position[0] > self.payload_position[0] - 10 and 
                    robot.position[0] < self.payload_position[0] + 10 and
                    robot.position[1] > self.payload_position[1] - 10 and
                    robot.position[1] < self.payload_position[1] + 10 and
                    robot.team != self.escort_team]

        if len(attackers) > 0:
            self.payload_health -= len(attackers) * 1
            return {"status": "payload_under_attack", "attackers": len(attackers), "health": self.payload_health}

        return {"status": "in_progress"}

class Arena:
    """Main class for the CyberArena simulation"""
    def __init__(self, width: int, height: int):
        self.width = width
        self.height = height
        self.robots = []
        self.power_ups = []
        self.hazards = []
        self.objectives = []
        self.round_time = 0
        self.start_time = 0
        self.difficulty_level = 1
        self.team_scores = {Team.RED: 0, Team.BLUE: 0, Team.NEUTRAL: 0}
        self.environment_effects = []

    def add_robot(self, robot: Robot):
        """Add a robot to the arena"""
        self.robots.append(robot)
        self._initialize_robot_position(robot)

    def _initialize_robot_position(self, robot: Robot):
        """Initialize robot position based on team"""
        if robot.team == Team.RED:
            robot.position = (10, 10)
        elif robot.team == Team.BLUE:
            robot.position = (90, 90)
        else:
            robot.position = (50, 50)

    def add_power_up(self, power_up: PowerUp):
        """Add a power-up to the arena"""
        self.power_ups.append(power_up)

    def add_hazard(self, hazard: Hazard):
        """Add a hazard to the arena"""
        self.hazards.append(hazard)

    def add_objective(self, objective: Objective):
        """Add an objective to the arena"""
        self.objectives.append(objective)

    def start_round(self):
        """Start a new round in the arena"""
        self.start_time = time.time()
        print(f"Round {self.round_time + 1} started!")
        self._initialize_arena()

    def _initialize_arena(self):
        """Initialize arena state for a new round"""
        # Reset robot positions
        for robot in self.robots:
            self._initialize_robot_position(robot)
            robot.health = 100
            robot.energy = 100
            robot.last_action = None

        # Reset power-ups
        for power_up in self.power_ups:
            power_up.active = True

        # Reset hazards
        for hazard in self.hazards:
            hazard.active = True

        # Reset objectives
        for objective in self.objectives:
            objective.completed = False

    def run_simulation(self, duration: float):
        """Run the simulation for a specified duration"""
        end_time = time.time() + duration
        while time.time() < end_time and not self._check_objective_completion():
            self.update_simulation()
            time.sleep(0.1)  # Simulate real-time updates

        self._display_results()
        self._adjust_difficulty()
        self.round_time += 1

    def update_simulation(self):
        """Update the simulation state"""
        # Check for collisions with hazards
        for hazard in self.hazards:
            for robot in self.robots:
                if hazard.check_collision(robot):
                    print(f"{robot.name} was hit by a {hazard.hazard_type} hazard!")

        # Check for robot actions
        for robot in self.robots:
            if robot.health <= 0:
                continue  # Skip dead robots

            # Select action based on current state
            action = robot.select_action(self._get_environment_state(robot))

            if action == ActionType.ATTACK:
                self._handle_attack(robot)
            elif action == ActionType.DEFEND:
                self._handle_defend(robot)
            elif action == ActionType.MOVE:
                self._handle_move(robot)
            elif action == ActionType.USE_ABILITY:
                robot.use_ability(self._get_environment_state(robot))
            elif action == ActionType.RETREAT:
                self._handle_retreat(robot)

            # Check for power-up pickup
            self._check_power_ups(robot)

        # Check objectives progress
        for objective in self.objectives:
            progress = objective.check_progress(self.robots)
            if progress.get("victor"):
                self._award_objective_completion(objective, progress["victor"])

        # Update adaptive difficulty
        self._update_adaptive_difficulty()

    def _get_environment_state(self, robot: Robot) -> Dict:
        """Get a snapshot of the environment state for a robot's decision making"""
        enemies = [r for r in self.robots if r.team != robot.team and r.health > 0]
        allies = [r for r in self.robots if r.team == robot.team and r.health > 0]

        return {
            "enemies": enemies,
            "allies": allies,
            "power_ups": [p for p in self.power_ups if p.active],
            "hazards": [h for h in self.hazards if h.active],
            "objectives": self.objectives,
            "current_time": time.time() - self.start_time
        }

    def _handle_attack(self, robot: Robot):
        """Handle attack action for a robot"""
        enemies = [r for r in self.robots if r.team != robot.team and r.health > 0]
        if enemies:
            target = random.choice(enemies)
            damage = self._calculate_damage(robot, target)
            target.take_damage(damage)
            print(f"{robot.name} attacked {target.name} for {damage} damage!")
            robot.update_experience(ActionType.ATTACK, True, damage / 10)
        else:
            robot.update_experience(ActionType.ATTACK, False, 1)

    def _calculate_damage(self, attacker: Robot, defender: Robot) -> float:
        """Calculate damage from an attack"""
        base_damage = 10  # Base damage value
        weapon_multiplier = 1.0

        if attacker.weapon in attacker.weapon_effectiveness:
            weapon_multiplier = attacker.weapon_effectiveness[attacker.weapon]

        # Calculate defense effectiveness
        defense_multiplier = defender.skills.get(ActionType.DEFEND, 0.5)

        # Final damage calculation
        damage = base_damage * weapon_multiplier * (1 - defense_multiplier)
        return max(1, damage)  # Ensure minimum damage of 1

    def _handle_defend(self, robot: Robot):
        """Handle defend action for a robot"""
        # Increase defense effectiveness temporarily
        robot.skills[ActionType.DEFEND] *= 1.2
        print(f"{robot.name} is defending!")
        robot.update_experience(ActionType.DEFEND, True, 5)

    def _handle_move(self, robot: Robot):
        """Handle move action for a robot"""
        # Calculate new position based on direction and terrain
        direction = random.choice([(1, 0), (-1, 0), (0, 1), (0, -1)])
        new_x = robot.position[0] + direction[0] * robot.skills[ActionType.MOVE]
        new_y = robot.position[1] + direction[1] * robot.skills[ActionType.MOVE]

        # Ensure position stays within arena boundaries
        new_x = max(0, min(new_x, self.width))
        new_y = max(0, min(new_y, self.height))

        robot.position = (new_x, new_y)
        print(f"{robot.name} moved to {robot.position}")
        robot.update_experience(ActionType.MOVE, True, 2)

    def _handle_retreat(self, robot: Robot):
        """Handle retreat action for a robot"""
        # Move away from enemies
        enemies = [r for r in self.robots if r.team != robot.team and r.health > 0]
        if enemies:
            enemy_avg_x = sum(r.position[0] for r in enemies) / len(enemies)
            enemy_avg_y = sum(r.position[1] for r in enemies) / len(enemies)

            direction_x = 1 if robot.position[0] < enemy_avg_x else -1
            direction_y = 1 if robot.position[1] < enemy_avg_y else -1

            new_x = robot.position[0] + direction_x * robot.skills[ActionType.MOVE]
            new_y = robot.position[1] + direction_y * robot.skills[ActionType.MOVE]

            # Ensure position stays within arena boundaries
            new_x = max(0, min(new_x, self.width))
            new_y = max(0, min(new_y, self.height))

            robot.position = (new_x, new_y)
            print(f"{robot.name} retreated to {robot.position}")
        robot.update_experience(ActionType.RETREAT, True, 3)

    def _check_power_ups(self, robot: Robot):
        """Check if the robot can pick up a power-up"""
        for power_up in self.power_ups:
            if power_up.active and power_up.position == robot.position:
                power_up.apply_effect(robot)
                print(f"{robot.name} picked up a {power_up.power_type} power-up!")
                robot.update_experience(ActionType.USE_ABILITY, True, 5)
                break

    def _check_objective_completion(self) -> bool:
        """Check if any objective has been completed"""
        for objective in self.objectives:
            if objective.is_complete():
                return True
        return False

    def _award_objective_completion(self, objective: Objective, victor: str):
        """Award points for completing an objective"""
        if victor == "attackers":
            victor_team = Team.RED if objective.defending_team == Team.BLUE else Team.BLUE
        else:
            victor_team = Team[victor]

        # Award points to the victor team
        points = 50  # Base points for completing an objective
        self.team_scores[victor_team] += points

        # Award bonus points based on time
        time_bonus = max(0, 60 - (time.time() - self.start_time)) // 10
        self.team_scores[victor_team] += time_bonus

        print(f"Objective completed! {victor_team.name} team gets {points + time_bonus} points!")

    def _update_adaptive_difficulty(self):
        """Adjust difficulty based on current game state"""
        # Calculate team performance
        red_performance = sum(r.health for r in self.robots if r.team == Team.RED)
        blue_performance = sum(r.health for r in self.robots if r.team == Team.BLUE)

        # Adjust difficulty level based on performance
        if red_performance > blue_performance * 1.5:
            self.difficulty_level += 1
            print("Increasing difficulty level to", self.difficulty_level)
        elif blue_performance > red_performance * 1.5:
            self.difficulty_level += 1
            print("Increasing difficulty level to", self.difficulty_level)
        elif self.difficulty_level > 1 and red_performance < blue_performance and blue_performance < red_performance:
            self.difficulty_level -= 1
            print("Decreasing difficulty level to", self.difficulty_level)

        # Apply difficulty adjustments
        self._adjust_ai_parameters()
        self._adjust_environment()

    def _adjust_ai_parameters(self):
        """Adjust AI parameters based on difficulty level"""
        for robot in self.robots:
            if self.difficulty_level > 1:
                # Higher difficulty: increase enemy AI effectiveness
                if robot.team != Team.NEUTRAL:
                    robot.skills[ActionType.ATTACK] *= 1.1
                    robot.skills[ActionType.DEFEND] *= 1.1
                    robot.skills[ActionType.MOVE] *= 1.05
            else:
                # Lower difficulty: decrease enemy AI effectiveness
                if robot.team != Team.NEUTRAL:
                    robot.skills[ActionType.ATTACK] *= 0.9
                    robot.skills[ActionType.DEFEND] *= 0.9
                    robot.skills[ActionType.MOVE] *= 0.95

    def _adjust_environment(self):
        """Adjust environment based on difficulty level"""
        if self.difficulty_level > 2:
