class CyberArenaGame:
    """Main class for the CyberArena game"""
    def __init__(self, arena_width: int = 100, arena_height: int = 100):
        self.arena = Arena(arena_width, arena_height)
        self.is_running = False
        self.robots = []
        self.objectives = []
        self.spectator_view = None

    def create_robots(self, num_robots: int, teams: List[Team]):
        """Create and add robots to the arena"""
        robot_names = ["Nova", "Vex", "Syn", "Blitz", "Aegis", "Zeta", "Kryo", "Pyra", "Cryo", "Vortex"]

        for i in range(num_robots):
            if i < len(teams):
                team = teams[i]
            else:
                # Round-robin team assignment
                team = teams[i % len(teams)]

            robot_name = robot_names[i % len(robot_names)] + str(i // len(robot_names))
            robot = Robot(robot_name, team)
            self.arena.add_robot(robot)
            self.robots.append(robot)

    def create_objectives(self, objective_types: List[str]):
        """Create and add objectives to the arena"""
        for objective_type in objective_types:
            if objective_type == "flag_capture":
                # Create a flag capture objective
                self.arena.add_objective(FlagCaptureObjective((50, 50)))
            elif objective_type == "base_defense":
                # Create a base defense objective for each team
                self.arena.add_objective(BaseDefenseObjective((10, 10)))
                self.arena.add_objective(BaseDefenseObjective((90, 90)))
            elif objective_type == "payload_escort":
                # Create a payload escort objective
                self.arena.add_objective(PayloadEscortObjective((10, 10), (90, 90)))

    def create_power_ups(self, num_power_ups: int):
        """Create and add power-ups to the arena"""
        power_up_types = ["health", "energy", "speed", "damage", "defense"]

        for _ in range(num_power_ups):
            position = (random.randint(10, 90), random.randint(10, 90))
            power_up_type = random.choice(power_up_types)
            self.arena.add_power_up(PowerUp(position, power_up_type))

    def create_hazards(self, num_hazards: int):
        """Create and add hazards to the arena"""
        hazard_types = ["laser_grid", "electro_pad", "gravity_well"]

        for _ in range(num_hazards):
            position = (random.randint(10, 90), random.randint(10, 90))
            hazard_type = random.choice(hazard_types)
            self.arena.add_hazard(Hazard(position, hazard_type))

    def start_game(self, num_rounds: int, round_duration: float):
        """Start the CyberArena game"""
        self.is_running = True
        print("CyberArena game started!")

        for round_num in range(num_rounds):
            print(f"\n=== ROUND {round_num + 1} ===")
            self.arena.start_round()
            self.arena.run_simulation(round_duration)

            # Reset scores for next round
            self.arena.team_scores = {Team.RED: 0, Team.BLUE: 0, Team.NEUTRAL: 0}

            if not self.is_running:
                break

        self.end_game()

    def end_game(self):
        """End the CyberArena game"""
        print("\nCyberArena game completed!")
        self.is_running = False
        self._display_final_results()

    def _display_final_results(self):
        """Display final game results"""
        print("\nFinal Results:")
        print(f"Red team total score: {self.arena.team_scores[Team.RED]}")
        print(f"Blue team total score: {self.arena.team_scores[Team.BLUE]}")
        print(f"Neutral score: {self.arena.team_scores[Team.NEUTRAL]}")

        # Display overall top performing robots
        print("\nOverall Top Performing Robots:")
        sorted_robots = sorted(self.robots, key=lambda r: r.score, reverse=True)
        for i, robot in enumerate(sorted_robots[:5], 1):
            print(f"{i}. {robot.name} ({robot.team.name}): {robot.score:.2f} points")

        # Display most improved robots
        print("\nMost Improved Robots:")
        sorted_robots = sorted(self.robots, key=lambda r: r.experience, reverse=True)
        for i, robot in enumerate(sorted_robots[:5], 1):
            print(f"{i}. {robot.name} ({robot.team.name}): {robot.experience:.2f} experience points")

    def set_spectator_view(self, robot_name: str):
        """Set the spectator view to follow a specific robot"""
        for robot in self.robots:
            if robot.name == robot_name:
                self.spectator_view = robot
                print(f"Spectator view set to {robot_name}")
                return
        print(f"Robot {robot_name} not found")

    def get_spectator_view(self) -> dict:
        """Get the current spectator view information"""
        if self.spectator_view:
            return {
                "name": self.spectator_view.name,
                "team": self.spectator_view.team.name,
                "position": self.spectator_view.position,
                "health": self.spectator_view.health,
                "energy": self.spectator_view.energy,
                "weapon": self.spectator_view.weapon.name,
                "role": self.spectator_view.role.name,
                "score": self.spectator_view.score,
                "experience": self.spectator_view.experience,
                "last_action": self.spectator_view.last_action.name if self.spectator_view.last_action else None
            }
        return None

    def get_team_status(self, team: Team) -> dict:
        """Get the status of a specific team"""
        team_robots = [robot for robot in self.robots if robot.team == team]
        return {
            "team": team.name,
            "score": self.arena.team_scores[team],
            "alive_robots": [robot.name for robot in team_robots if robot.health > 0],
            "dead_robots": [robot.name for robot in team_robots if robot.health <= 0],
            "average_health": sum(robot.health for robot in team_robots if robot.health > 0) / max(1, len(team_robots)),
            "total_experience": sum(robot.experience for robot in team_robots)
        }

    def get_game_status(self) -> dict:
        """Get the current status of the game"""
        return {
            "round_time": self.arena.round_time,
            "is_running": self.is_running,
            "team_scores": self.arena.team_scores,
            "difficulty_level": self.arena.difficulty_level,
            "spectator_view": self.get_spectator_view(),
            "objectives": [objective.objective_type for objective in self.arena.objectives],
            "num_power_ups": len(self.arena.power_ups),
            "num_hazards": len(self.arena.hazards)
        }

    def update_game(self):
        """Update the game state"""
        self.arena.update_simulation()

    def run_game_loop(self, duration: float, update_interval: float = 0.1):
        """Run the game loop for a specified duration"""
        end_time = time.time() + duration
        while time.time() < end_time and self.is_running:
            self.update_game()
            time.sleep(update_interval)

    def stop_game(self):
        """Stop the game"""
        self.is_running = False

