        for spawner in self.power_up_spawners:
            print(f"  Spawner at ({spawner.position.x}, {spawner.position.y}): {len(spawner.power_ups)} power-ups")

    def get_winner(self):
        """Determine the winner based on objectives and scores"""
        completed_objectives = [obj for obj in self.objectives if obj.check_completion()]

        if completed_objectives:
            winning_teams = [obj.team for obj in completed_objectives]
            most_wins = max(set(winning_teams), key=winning_teams.count)
            return f"Team {most_wins.name} wins with {winning_teams.count(most_wins)} completed objectives!"

