@dataclass
class Position:
    """Represents a 2D position in the arena."""
    x: float
    y: float

    def distance_to(self, other: "Position") -> float:
        """Calculate the Euclidean distance to another position."""
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5


class Weapon:
    """Base class for weapons used by robots."""
    def __init__(self, name: str, damage: int, range: float, cool_down: float):
        self.name = name
        self.damage = damage
        self.range = range  # Maximum range of the weapon
        self.cool_down = cool_down  # Time between shots
        self.last_used = 0  # Timestamp of the last time this weapon was used

    def is_ready(self, current_time: float) -> bool:
        """Check if the weapon is ready to be used."""
        return current_time - self.last_used >= self.cool_down

    def use(self, current_time: float):
        """Mark the weapon as used and record the timestamp."""
        self.last_used = current_time


