class PowerUp:
    """Power-ups that can enhance robot abilities temporarily."""
    def __init__(self, name: str, effect: Dict, duration: float):
        self.name = name
        self.effect = effect  # Dictionary with effect details (e.g., {"speed": 1.5})
        self.duration = duration  # Duration of the power-up effect in seconds
        self.expires = 0  # Timestamp when the power-up expires

    def is_active(self, current_time: float) -> bool:
        """Check if the power-up is still active."""
        return current_time < self.expires

    def apply(self, robot: "Robot", current_time: float):
        """Apply the power-up effect to the robot."""
        self.expires = current_time + self.duration
        for attr, value in self.effect.items():
            if hasattr(robot, attr):
                original_value = getattr(robot, attr)
                setattr(robot, f"original_{attr}", original_value)
                setattr(robot, attr, original_value * value)

    def remove(self, robot: "Robot"):
        """Remove the power-up effect from the robot."""
        for attr in self.effect.keys():
            original_value = getattr(robot, f"original_{attr}")
            setattr(robot, attr, original_value)


