import json
import threading
from abc import ABC, abstractmethod
from enum import Enum
from typing import List, Dict, Tuple, Optional

# Define User Roles

class UserRole(Enum):
    EDITOR = "EDITOR"
    REVIEWER = "REVIEWER"
    OWNER = "OWNER"

# Define Video Format Support

class VideoFormat(Enum):
    MP4 = "MP4"
    AVI = "AVI"
    MOV = "MOV"
    MKV = "MKV"

# Position class for handling video timeline

class Position:
    def __init__(self, start: float, end: float):
        self.start = start
        self.end = end

    def duration(self) -> float:
        return self.end - self.start

# Base class for all video editing operations

class VideoOperation(ABC):
    @abstractmethod
    def execute(self):
        pass

    @abstractmethod
    def undo(self):
        pass

    @abstractmethod
    def redo(self):
        pass

# Example of a cutting operation

class CutOperation(VideoOperation):
    def __init__(self, video, start: float, end: float):
        self.video = video
        self.start = start
        self.end = end
        self.original_segments = video.active_segments.copy()

    def execute(self):
        self.video.active_segments = [s for s in self.video.active_segments if not 
                                      (s.start >= self.start and s.end <= self.end)]

    def undo(self):
        self.video.active_segments = self.original_segments

    def redo(self):
        self.execute()

# Undo/Redo Manager

class UndoRedoManager:
    def __init__(self):
        self.undo_stack = []
        self.redo_stack = []

    def do_operation(self, operation: VideoOperation):
        operation.execute()
        self.undo_stack.append(operation)
        self.redo_stack.clear()

    def undo(self):
        if self.undo_stack:
            operation = self.undo_stack.pop()
            operation.undo()
            self.redo_stack.append(operation)

    def redo(self):
        if self.redo_stack:
            operation = self.redo_stack.pop()
            operation.redo()
            self.undo_stack.append(operation)

# Feedback Mechanism

class Comment:
    def __init__(self, user: str, timestamp: float, message: str, suggestion: Optional[VideoOperation] = None):
        self.user = user
        self.timestamp = timestamp
        self.message = message
        self.suggestion = suggestion

# Real-time Sync Mechanism using Observer Pattern

class RealTimeSync:
    def __init__(self):
        self.subscribers = []

    def subscribe(self, subscriber):
        self.subscribers.append(subscriber)

    def notify(self, event: str, data: Dict):
        for subscriber in self.subscribers:
            subscriber.update(event, data)

# Video class representing the video being edited

class Video:
    def __init__(self, title: str, path: str, resolution: Tuple[int, int], format: VideoFormat):
        self.title = title
        self.path = path
        self.resolution = resolution
        self.format = format
        self.active_segments = []  # List of segments currently in the video
        self.comments = []  # List of comments and suggestions
        self.undo_redo_manager = UndoRedoManager()
        self.change_history = []  # History of all edits

    def add_comment(self, user: str, message: str, suggestion: Optional[VideoOperation] = None):
        comment = Comment(user, time.time(), message, suggestion)
        self.comments.append(comment)

    def apply_comment_suggestion(self, comment_index: int):
        comment = self.comments[comment_index]
        if comment.suggestion:
            self.undo_redo_manager.do_operation(comment.suggestion)

    def add_segment(self, segment: Position):
        self.active_segments.append(segment)
        self.change_history.append(f"Added segment from {segment.start} to {segment.end}")

    def cut(self, start: float, end: float):
        cut_op = CutOperation(self, start, end)
        self.undo_redo_manager.do_operation(cut_op)
        self.change_history.append(f"Cut from {start} to {end}")

