    def can_edit(self):
        return self.role in [UserRole.EDITOR, UserRole.OWNER]

    def can_review(self):
        return self.role in [UserRole.REVIEWER, UserRole.OWNER]

# Main Collaborative Video Editing System

class VideoCollabEditor:
    def __init__(self):
        self.current_video = None
        self.users = []  # List of connected users
        self.real_time_sync = RealTimeSync()

    def set_video(self, video: Video):
        self.current_video = video

    def connect_user(self, user: User):
        self.users.append(user)
        self.real_time_sync.subscribe(user)

    def disconnect_user(self, user: User):
        if user in self.users:
            self.users.remove(user)

    def apply_edit(self, user: User, operation: VideoOperation):
        if user.can_edit():
            self.current_video.undo_redo_manager.do_operation(operation)
            self.real_time_sync.notify("edit_applied", {
                "user": user.name,
                "operation": type(operation).__name__
            })
        else:
            print(f"{user.name} does not have permission to edit.")

